/// Saves the bytes as a file. Uses file_picker's save dialog, which works on
/// Android, iOS, desktop and web (no web-only imports, so Android builds).
Future<String?> _downloadInBrowser(
    Uint8List bytes, String fileName, String contentType) async {
  try {
    final path = await FilePicker.platform
        .saveFile(dialogTitle: 'Save file', fileName: fileName, bytes: bytes);
    // On Windows / macOS / Linux the picker only returns the chosen path and
    // does not always write the bytes, so write the file here.
    if (path != null &&
        !kIsWeb &&
        (Platform.isWindows || Platform.isMacOS || Platform.isLinux)) {
      await File(path).writeAsBytes(bytes, flush: true);
    }
    return path;
  } catch (e) {
    debugPrint('Save failed: $e');
    rethrow;
  }
}

class ExamRecord {
  final String subject;
  final String form;
  final bool received;
  final DateTime? receivedAt;
  final bool hasFile;
  final String? fileName;
  final String footer; // auto-generated: subject | form | teacher
  final String teacherName;
  final String marks; // optional override of the general marks
  final String allowedTime; // optional override of the general time

  const ExamRecord({
    required this.subject,
    required this.form,
    this.received = false,
    this.receivedAt,
    this.hasFile = false,
    this.fileName,
    this.footer = '',
    this.teacherName = '',
    this.marks = '',
    this.allowedTime = '',
  });

  static String idFor(String subject, String form) => '${subject}_$form';

  factory ExamRecord.empty(String subject, String form) =>
      ExamRecord(subject: subject, form: form);

  factory ExamRecord.fromMap(Map<String, dynamic> m) => ExamRecord(
    subject: m['subject'] ?? '',
    form: m['form'] ?? '',
    received: m['status'] == 'received',
    receivedAt: (m['receivedAt'] as Timestamp?)?.toDate(),
    hasFile: m['hasFile'] == true,
    fileName: m['fileName'],
    footer: m['footer'] ?? '',
    teacherName: m['teacherName'] ?? '',
    marks: m['marks'] ?? '',
    allowedTime: m['allowedTime'] ?? '',
  );
}

/// General exam-heading information (same for every exam, set once).
/// Form and subject are NOT stored here: they come from the button.
class ExamHeading {
  final String examName; // e.g. FINAL EXAM
  final String academicYear; // e.g. 2025-2026
  final String month; // e.g. June
  final String year; // e.g. 2026
  final String marks; // default marks, e.g. 30
  final String allowedTime; // default time, e.g. ONE-HOUR PLUS 20 MINUTES
  // Arabic and Somali versions (used automatically for the Arabic / Somali
  // subject buttons).
  final String examNameAr;
  final String allowedTimeAr;
  // Islamic subject: its own Arabic heading, separate from the Arabic subject.
  final String examNameIs;
  final String allowedTimeIs;
  final String examNameSo;
  final String allowedTimeSo;

  const ExamHeading({
    this.examName = 'FINAL EXAM',
    this.academicYear = '2025-2026',
    this.month = 'June',
    this.year = '2026',
    this.marks = '30',
    this.allowedTime = 'ONE-HOUR PLUS 20 MINUTES',
    this.examNameAr = 'امتحان نهائي',
    this.allowedTimeAr = 'ساعتان وعشر دقائق لقراءة ورقة الامتحان',
    this.examNameIs = 'امتحان نهائي',
    this.allowedTimeIs = 'ساعتان وعشر دقائق لقراءة ورقة الامتحان',
    this.examNameSo = 'IMTIXAANKA UGU HORREEYA',
    this.allowedTimeSo = 'HAL SAAC IYO 20 DAQIIQO OO AKHRIS AH',
  });

  static const _d = ExamHeading();

  factory ExamHeading.fromMap(Map<String, dynamic> m) {
    String s(String k, String d) {
      final v = m[k];
      return v is String && v.trim().isNotEmpty ? v.trim() : d;
    }

    return ExamHeading(
      examName: s('examName', _d.examName),
      academicYear: s('academicYear', _d.academicYear),
      month: s('examMonth', _d.month),
      year: s('examYear', _d.year),
      marks: s('defaultMarks', _d.marks),
      allowedTime: s('allowedTime', _d.allowedTime),
      examNameAr: s('examNameAr', _d.examNameAr),
      allowedTimeAr: s('allowedTimeAr', _d.allowedTimeAr),
      examNameIs: s('examNameIs', _d.examNameIs),
      allowedTimeIs: s('allowedTimeIs', _d.allowedTimeIs),
      examNameSo: s('examNameSo', _d.examNameSo),
      allowedTimeSo: s('allowedTimeSo', _d.allowedTimeSo),
    );
  }

  Map<String, dynamic> toMap() => {
    'examName': examName.trim(),
    'academicYear': academicYear.trim(),
    'examMonth': month.trim(),
    'examYear': year.trim(),
    'defaultMarks': marks.trim(),
    'allowedTime': allowedTime.trim(),
    'examNameAr': examNameAr.trim(),
    'allowedTimeAr': allowedTimeAr.trim(),
    'examNameIs': examNameIs.trim(),
    'allowedTimeIs': allowedTimeIs.trim(),
    'examNameSo': examNameSo.trim(),
    'allowedTimeSo': allowedTimeSo.trim(),
  };

  /// 'ar' for the Arabic subject, 'so' for the Somali subject, else 'en'.
  static String langFor(String subject) {
    switch (subject.trim().toLowerCase()) {
      case 'arabic':
      case 'islamic':
        return 'ar';
      case 'somali':
        return 'so';
      default:
        return 'en';
    }
  }

  /// The general allowed time that applies to this subject's language.
  String defaultTimeFor(String subject) {
    if (subject.trim().toLowerCase() == 'islamic') return allowedTimeIs;
    switch (langFor(subject)) {
      case 'ar':
        return allowedTimeAr;
      case 'so':
        return allowedTimeSo;
      default:
        return allowedTime;
    }
  }

  static int? _formNo(String form) =>
      int.tryParse(form.replaceAll(RegExp(r'[^0-9]'), ''));

  static String _formWord(String form) {
    final n = _formNo(form);
    const words = {1: 'ONE', 2: 'TWO', 3: 'THREE', 4: 'FOUR', 5: 'FIVE', 6: 'SIX'};
    return words[n] ?? form.toUpperCase();
  }

  static String _formWordAr(String form) {
    const words = {
      1: 'الأول', 2: 'الثاني', 3: 'الثالث', 4: 'الرابع', 5: 'الخامس', 6: 'السادس',
    };
    return words[_formNo(form)] ?? form;
  }

  static String _formWordSo(String form) {
    const words = {
      1: 'KOOWAAD', 2: 'LABAAD', 3: 'SADDEXAAD', 4: 'AFRAAD', 5: 'SHANAAD', 6: 'LIXAAD',
    };
    return words[_formNo(form)] ?? form.toUpperCase();
  }

  /// 20 -> ٢٠
  static String _arabicDigits(String s) {
    const d = '٠١٢٣٤٥٦٧٨٩';
    return s.replaceAllMapped(RegExp(r'[0-9]'), (m) => d[int.parse(m[0]!)]);
  }

  /// Builds the final text lines for one exam. Subject and form come from the
  /// button; [marks] / [time] (if not empty) override the general values.
  /// The Arabic and Somali subjects get a heading in their own language.
  ExamHeadingText build(String subject, String form,
      {String? marks, String? time}) {
    final m = (marks ?? '').trim().isEmpty ? this.marks : marks!.trim();
    final lang = langFor(subject);
    final t = (time ?? '').trim().isEmpty ? defaultTimeFor(subject) : time!.trim();
    final isIslamic = subject.trim().toLowerCase() == 'islamic';
    final mo = month.trim();
    final yr = year.trim();
    final ay = academicYear.trim();
    switch (lang) {
      case 'ar':
        return ExamHeadingText(
          lang: lang,
          title: '${(isIslamic ? examNameIs : examNameAr).trim()} العام الدراسي $ay',
          formLine: 'الفصل ${_formWordAr(form)} – ${_arabicDigits(m)} درجة',
          subjectLine: isIslamic
              ? 'امتحان التربية الإسلامية'
              : 'امتحان اللغة العربية',
          monthLine: '${mo.toUpperCase()} $yr',
          timeLine: 'الزمن: $t',
          month: mo,
          year: yr,
        );
      case 'so':
        return ExamHeadingText(
          lang: lang,
          title: '${examNameSo.trim().toUpperCase()} EE SANNAD DUGSIYEEDKA $ay',
          formLine: 'FASALKA ${_formWordSo(form).toUpperCase()} – $m DARAJO',
          subjectLine: 'IMTIXAANKA SOOMAALIGA',
          monthLine: '${mo.toUpperCase()} $yr',
          timeLine: 'WAKHTIGA LA OGOL YAHAY: ${t.toUpperCase()}',
          month: mo,
          year: yr,
        );
      default:
        return ExamHeadingText(
          lang: lang,
          title: '${examName.trim().toUpperCase()} FOR ACADEMIC YEAR $ay',
          formLine: 'FORM ${_formWord(form)} – $m MARKS',
          subjectLine: '${subject.toUpperCase()} EXAMINATION',
          monthLine: '${mo.toUpperCase()} $yr',
          timeLine: 'ALLOWED TIME: ${t.toUpperCase()}',
          month: mo,
          year: yr,
        );
    }
  }
}

/// The ready-to-print lines of the heading table.
class ExamHeadingText {
  final String lang; // 'en' | 'ar' | 'so'
  final String title, formLine, subjectLine, monthLine, timeLine;
  final String month, year;
  const ExamHeadingText({
    this.lang = 'en',
    required this.title,
    required this.formLine,
    required this.subjectLine,
    required this.monthLine,
    required this.timeLine,
    required this.month,
    required this.year,
  });

  /// Arabic is written right-to-left.
  bool get rtl => lang == 'ar';

  /// Name / Class / Date line, with [dot] as the fill character.
  String nameLine(String dot) {
    switch (lang) {
      case 'ar':
        return 'اسم: ${dot * 26} الفصل: ${dot * 8} تاريخ: ${dot * 8}/$month/$year';
      case 'so':
        return 'Magac: ${dot * 26} Fasal: ${dot * 8} Taariikh: ${dot * 8}/$month/$year';
      default:
        return 'Name: ${dot * 26} Class: ${dot * 8} Date: ${dot * 8}/$month/$year';
    }
  }

  List<String> get centeredLines => [formLine, subjectLine, monthLine, timeLine];
}

/// Grey heading box shown in the dialogs (same look as the printed table).
Widget _headingPreview(ExamHeadingText p, {double pad = 6}) {
  const bold = TextStyle(fontSize: 11, fontWeight: FontWeight.bold);
  return Directionality(
    textDirection: p.rtl ? ui.TextDirection.rtl : ui.TextDirection.ltr,
    child: Container(
      width: double.infinity,
      padding: EdgeInsets.all(pad),
      color: const Color(0xFFD9D9D9),
      child: Column(children: [
        Align(
          alignment: AlignmentDirectional.centerStart,
          child: Text(p.nameLine('.'),
              style: const TextStyle(fontSize: 10, fontWeight: FontWeight.bold)),
        ),
        Container(
          width: double.infinity,
          margin: const EdgeInsets.symmetric(vertical: 2),
          padding: const EdgeInsets.symmetric(vertical: 2),
          decoration: BoxDecoration(border: Border.all(color: Colors.black)),
          child: Text(p.title, textAlign: TextAlign.center, style: bold),
        ),
        for (final l in p.centeredLines)
          Text(l, textAlign: TextAlign.center, style: bold),
      ]),
    ),
  );
}

