class ExamService {
  static const subjects = [
    'English', 'Somali', 'Arabic', 'Islamic', 'Maths',
    'Chemistry', 'Biology', 'Physics', 'History', 'Geography',
  ];
  static const forms = ['Form1', 'Form2', 'Form3', 'Form4'];

  final _db = FirebaseFirestore.instance;
  CollectionReference<Map<String, dynamic>> get _files => _db.collection('files');

  static const maxFileBytes = 700 * 1024; // Firestore doc limit is 1 MiB

  CollectionReference<Map<String, dynamic>> get _col => _db.collection('exams');

  /// Live map of docId -> record. Missing docs mean "Pending".
  Stream<Map<String, ExamRecord>> watchAll() => _col.snapshots().map((s) => {
    for (final d in s.docs) d.id: ExamRecord.fromMap(d.data()),
  });

  // ---------------- General school letterhead (one for all) ----------------
  DocumentReference<Map<String, dynamic>> get _settings =>
      _db.collection('settings').doc('general');

  /// Live letterhead image bytes (null = not registered yet).
  Stream<Uint8List?> watchLetterhead() => _settings.snapshots().map((d) {
    final b64 = d.data()?['letterheadBase64'] as String?;
    return b64 == null ? null : base64Decode(b64);
  });

  Future<Uint8List?> getLetterhead() async {
    final b64 = (await _settings.get()).data()?['letterheadBase64'] as String?;
    return b64 == null ? null : base64Decode(b64);
  }

  // ---------------- General exam heading ----------------
  Future<ExamHeading> getHeading() async =>
      ExamHeading.fromMap((await _settings.get()).data() ?? {});

  Future<void> saveHeading(ExamHeading h) => _settings.set({
    ...h.toMap(),
    'updatedBy': FirebaseAuth.instance.currentUser?.uid,
    'updatedAt': FieldValue.serverTimestamp(),
  }, SetOptions(merge: true));

  /// Stored inside Firestore (a document may be up to ~1 MB), so keep it small.
  Future<void> saveLetterhead(Uint8List bytes) {
    if (bytes.length > 700 * 1024) {
      throw Exception('Letterhead is too large. Please use an image under 700 KB.');
    }
    return _validateAndSaveLetterhead(bytes);
  }

  Future<void> _validateAndSaveLetterhead(Uint8List bytes) async {
    try {
      await _toPng(bytes); // make sure it is a readable image
    } catch (_) {
      throw Exception(
          'This letterhead file is not a readable image. Please save it as PNG or JPG and try again.');
    }
    return _settings.set({
      'letterheadBase64': base64Encode(bytes),
      'updatedBy': FirebaseAuth.instance.currentUser?.uid,
      'updatedAt': FieldValue.serverTimestamp(),
    }, SetOptions(merge: true));
  }

  // ---------------- Image helpers ----------------
  /// Decodes ANY image the platform understands (PNG, JPG, WebP, GIF, BMP...)
  /// and re-encodes it as a clean PNG that the PDF library can embed.
  Future<Uint8List> _toPng(Uint8List bytes) async => (await _toPngInfo(bytes)).png;

  Future<({Uint8List png, int w, int h})> _toPngInfo(Uint8List bytes) async {
    final codec = await ui.instantiateImageCodec(bytes);
    final frame = await codec.getNextFrame();
    final data = await frame.image.toByteData(format: ui.ImageByteFormat.png);
    if (data == null) throw Exception('Could not convert image.');
    return (
    png: data.buffer.asUint8List(),
    w: frame.image.width,
    h: frame.image.height
    );
  }

  /// Detects PNG / JPEG by their first bytes (null = another format).
  String? _sniff(Uint8List b) {
    if (b.length > 4 && b[0] == 0x89 && b[1] == 0x50 && b[2] == 0x4E && b[3] == 0x47) {
      return 'png';
    }
    if (b.length > 3 && b[0] == 0xFF && b[1] == 0xD8 && b[2] == 0xFF) return 'jpeg';
    return null;
  }

  /// Image width/height without re-encoding it.
  Future<({int w, int h})> _imageSize(Uint8List bytes) async {
    final codec = await ui.instantiateImageCodec(bytes);
    final frame = await codec.getNextFrame();
    return (w: frame.image.width, h: frame.image.height);
  }

  static String _stripFontOverrides(String xml) => xml
      .replaceAll(RegExp(r'<w:rFonts\b[^>]*?(/>|>\s*</w:rFonts>)'), '')
      .replaceAll(RegExp(r'<w:sz\b[^>]*/>'), '')
      .replaceAll(RegExp(r'<w:szCs\b[^>]*/>'), '');

  /// Makes Times New Roman 12 pt the default of the whole document.
  static String _forceTimes12(String? styles) {
    const header = '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>';
    const wns = 'http://schemas.openxmlformats.org/wordprocessingml/2006/main';
    final lang =
        RegExp(r'<w:lang\b[^>]*/>').firstMatch(styles ?? '')?.group(0) ?? '';
    final defaults = '<w:docDefaults><w:rPrDefault><w:rPr>'
        '<w:rFonts w:ascii="Times New Roman" w:hAnsi="Times New Roman" '
        'w:eastAsia="Times New Roman" w:cs="Times New Roman"/>'
        '<w:sz w:val="24"/><w:szCs w:val="24"/>$lang'
        '</w:rPr></w:rPrDefault></w:docDefaults>';
    if (styles == null || !styles.contains('<w:styles')) {
      return '$header<w:styles xmlns:w="$wns">$defaults</w:styles>';
    }
    var x = _stripFontOverrides(styles);
    x = x.replaceAll(
        RegExp(r'<w:docDefaults>.*?</w:docDefaults>', dotAll: true), '');
    x = x.replaceAll(RegExp(r'<w:docDefaults\s*/>'), '');
    return x.replaceFirstMapped(
        RegExp(r'<w:styles\b[^>]*>'), (m) => '${m[0]}$defaults');
  }

  static String _xml(String t) => t
      .replaceAll('&', '&amp;')
      .replaceAll('<', '&lt;')
      .replaceAll('>', '&gt;')
      .replaceAll('"', '&quot;');

  /// Word table placed above the first line of the document.
  static String _headingTableXml(ExamHeadingText h) {
    final rtl = h.rtl;
    // In a right-to-left paragraph Word's "left" means the start (right side).
    String para(String t, {bool left = false}) =>
        '<w:p><w:pPr>${rtl ? '<w:bidi/>' : ''}'
            '<w:spacing w:before="20" w:after="20" w:line="240" w:lineRule="auto"/>'
            '<w:jc w:val="${left ? 'left' : 'center'}"/></w:pPr>'
            '<w:r><w:rPr><w:b/><w:bCs/>${rtl ? '<w:rtl/>' : ''}</w:rPr>'
            '<w:t xml:space="preserve">${_xml(t)}</w:t></w:r></w:p>';
    const shade = '<w:shd w:val="clear" w:color="auto" w:fill="D9D9D9"/>';
    const edge = 'w:val="single" w:sz="12" w:space="0" w:color="000000"';
    const box = '<w:tcBorders><w:top $edge/><w:left $edge/><w:bottom $edge/>'
        '<w:right $edge/></w:tcBorders>';
    String row(String inner, {bool boxed = false}) =>
        '<w:tr><w:tc><w:tcPr><w:tcW w:w="5000" w:type="pct"/>'
            '${boxed ? box : ''}$shade</w:tcPr>$inner</w:tc></w:tr>';

    final rows = StringBuffer()
      ..write(row(para(h.nameLine('…'), left: true)))
      ..write(row(para(h.title), boxed: true));
    for (final l in h.centeredLines) {
      rows.write(row(para(l)));
    }
    return '<w:tbl><w:tblPr><w:tblW w:w="5000" w:type="pct"/><w:jc w:val="center"/></w:tblPr>'
        '<w:tblGrid><w:gridCol w:w="9000"/></w:tblGrid>$rows</w:tbl>'
    // empty paragraph so the table never merges with the next one
        '<w:p><w:pPr><w:spacing w:before="0" w:after="120"/></w:pPr></w:p>';
  }

  /// Same table for PDF / image uploads (first page only).
  static pw.Widget _pdfHeading(ExamHeadingText h, [pw.Font? arabicFont]) {
    String a(String s) => s.replaceAll('–', '-'); // built-in PDF font = Latin-1
    final rtl = h.rtl && arabicFont != null;
    final style = pw.TextStyle(
        font: rtl ? arabicFont : pw.Font.timesBold(), fontSize: 10.5);
    final dir = rtl ? pw.TextDirection.rtl : pw.TextDirection.ltr;
    const grey = PdfColor(0.85, 0.85, 0.85);
    pw.Widget bar(pw.Widget child) => pw.Container(
      width: double.infinity,
      color: grey,
      padding: const pw.EdgeInsets.symmetric(vertical: 2, horizontal: 4),
      child: child,
    );
    pw.Widget txt(String t) =>
        pw.Text(a(t), style: style, textDirection: dir);
    return pw.Column(mainAxisSize: pw.MainAxisSize.min, children: [
      bar(pw.Align(
        alignment: rtl ? pw.Alignment.centerRight : pw.Alignment.centerLeft,
        child: txt(h.nameLine('.')),
      )),
      bar(pw.Container(
        alignment: pw.Alignment.center,
        padding: const pw.EdgeInsets.symmetric(vertical: 2),
        decoration: pw.BoxDecoration(border: pw.Border.all(width: 1)),
        child: txt(h.title),
      )),
      for (final l in h.centeredLines) bar(pw.Center(child: txt(l))),
    ]);
  }

  /// Arabic needs a real font in PDFs (the built-in ones are Latin only).
  static Future<pw.Font?> _arabicFont(ExamHeadingText? h) async =>
      (h != null && h.rtl) ? await PdfGoogleFonts.notoNaskhArabicBold() : null;

  // ---------------- Word (.docx) stamping ----------------
  static const _docxMime =
      'application/vnd.openxmlformats-officedocument.wordprocessingml.document';

  /// Puts the school letterhead in the page header and the footer text in the
  /// page footer of every section of a .docx file. The document's own
  /// content and formatting stay untouched (still editable in Word).
  Future<Uint8List> stampDocx({
    required Uint8List docx,
    required Uint8List letterhead,
    required String footer,
    ExamHeadingText? heading,
    bool autoFormat = false,
    bool numberQuestions = true,
  }) async {
    // Keep the original PNG/JPEG bytes (fast + small); convert other formats.
    final ({Uint8List data, int w, int h, String kind}) img;
    try {
      final kind = _sniff(letterhead);
      if (kind != null) {
        final size = await _imageSize(letterhead);
        img = (data: letterhead, w: size.w, h: size.h, kind: kind);
      } else {
        final p = await _toPngInfo(letterhead);
        img = (data: p.png, w: p.w, h: p.h, kind: 'png');
      }
    } catch (_) {
      throw Exception(
          'The saved school letterhead cannot be read. Tap the image icon and upload it again as PNG or JPG.');
    }

    final files = <String, List<int>>{};
    try {
      for (final f in zip.ZipDecoder().decodeBytes(docx).files) {
        if (f.isFile) files[f.name] = List<int>.from(f.content as List<int>);
      }
    } catch (_) {
      throw Exception(
          'This is not a valid .docx file. Open it in Word and use Save As → Word Document (.docx).');
    }
    if (!files.containsKey('word/document.xml')) {
      throw Exception('This is not a valid .docx file (document.xml missing).');
    }

    const ns =
        'xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main" '
        'xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships" '
        'xmlns:wp="http://schemas.openxmlformats.org/drawingml/2006/wordprocessingDrawing" '
        'xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main" '
        'xmlns:pic="http://schemas.openxmlformats.org/drawingml/2006/picture"';
    const relBase =
        'http://schemas.openxmlformats.org/officeDocument/2006/relationships';

    // Image size in EMU (914400 per inch): max 6 in wide, 1.4 in tall.
    final ratio = img.h / img.w;
    var cx = 5486400;
    var cy = (cx * ratio).round();
    const maxCy = 1280160;
    if (cy > maxCy) {
      cy = maxCy;
      cx = (cy / ratio).round();
    }

    // 1) header + footer parts
    files['word/media/school_letterhead.${img.kind}'] = img.data;
    if (schoolLogo.value.uses(LogoPlace.exam)) {
      files['word/media/school_logo.png'] = schoolLogo.value.bytes!;
    }
    files['word/_rels/header_school.xml.rels'] = utf8.encode(
        '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
            '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'
            '<Relationship Id="rId1" Type="$relBase/image" Target="media/school_letterhead.${img.kind}"/>'
            '${docxLogoRel(LogoPlace.exam, 'rId2')}'
            '${docxWmRel(LogoPlace.exam, 'rId3')}'
            '</Relationships>');
    files['word/header_school.xml'] = utf8.encode(
        '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
            '<w:hdr $ns>${docxLogoPara(LogoPlace.exam, rid: 'rId2', docPrId: 9101)}'
            '${docxWatermarkPara(LogoPlace.exam, rid: 'rId3', docPrId: 9301)}'
            '<w:p><w:pPr><w:jc w:val="center"/></w:pPr><w:r><w:drawing>'
            '<wp:inline distT="0" distB="0" distL="0" distR="0">'
            '<wp:extent cx="$cx" cy="$cy"/><wp:docPr id="9001" name="School letterhead"/>'
            '<a:graphic><a:graphicData uri="http://schemas.openxmlformats.org/drawingml/2006/picture">'
            '<pic:pic><pic:nvPicPr><pic:cNvPr id="0" name="school_letterhead.png"/><pic:cNvPicPr/></pic:nvPicPr>'
            '<pic:blipFill><a:blip r:embed="rId1"/><a:stretch><a:fillRect/></a:stretch></pic:blipFill>'
            '<pic:spPr><a:xfrm><a:off x="0" y="0"/><a:ext cx="$cx" cy="$cy"/></a:xfrm>'
            '<a:prstGeom prst="rect"><a:avLst/></a:prstGeom></pic:spPr></pic:pic>'
            '</a:graphicData></a:graphic></wp:inline></w:drawing></w:r></w:p></w:hdr>');
    const fRun = '<w:rPr><w:rFonts w:ascii="Times New Roman" w:hAnsi="Times New Roman" '
        'w:eastAsia="Times New Roman" w:cs="Times New Roman"/><w:b/><w:bCs/><w:sz w:val="24"/><w:szCs w:val="24"/></w:rPr>';
    String fld(String code) =>
        '<w:r>$fRun<w:fldChar w:fldCharType="begin"/></w:r>'
            '<w:r>$fRun<w:instrText xml:space="preserve"> $code </w:instrText></w:r>'
            '<w:r>$fRun<w:fldChar w:fldCharType="separate"/></w:r>'
            '<w:r>$fRun<w:t>1</w:t></w:r>'
            '<w:r>$fRun<w:fldChar w:fldCharType="end"/></w:r>';
    String txt(String t) =>
        '<w:r>$fRun<w:t xml:space="preserve">${_xml(t)}</w:t></w:r>';
    files['word/media/footer_stamp.png'] = base64Decode(_footerStampBase64);
    files['word/_rels/footer_school.xml.rels'] = utf8.encode(
        '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
            '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'
            '<Relationship Id="rId1" Type="$relBase/image" Target="media/footer_stamp.png"/>'
            '</Relationships>');
    files['word/footer_school.xml'] = utf8.encode(
        '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
            '<w:ftr $ns><w:p><w:pPr><w:pBdr><w:top w:val="single" w:sz="4" w:space="4" w:color="999999"/></w:pBdr>'
            '<w:jc w:val="center"/></w:pPr>'
            '${txt('$footer | Page ')}${fld('PAGE')}${txt(' of ')}${fld('NUMPAGES')}'
            '</w:p>'
            '<w:p><w:pPr><w:jc w:val="center"/></w:pPr><w:r><w:drawing>'
            '<wp:inline distT="0" distB="0" distL="0" distR="0">'
            '<wp:extent cx="1371600" cy="651917"/><wp:docPr id="9002" name="Footer stamp"/>'
            '<a:graphic><a:graphicData uri="http://schemas.openxmlformats.org/drawingml/2006/picture">'
            '<pic:pic><pic:nvPicPr><pic:cNvPr id="0" name="footer_stamp.png"/><pic:cNvPicPr/></pic:nvPicPr>'
            '<pic:blipFill><a:blip r:embed="rId1"/><a:stretch><a:fillRect/></a:stretch></pic:blipFill>'
            '<pic:spPr><a:xfrm><a:off x="0" y="0"/><a:ext cx="1371600" cy="651917"/></a:xfrm>'
            '<a:prstGeom prst="rect"><a:avLst/></a:prstGeom></pic:spPr></pic:pic>'
            '</a:graphicData></a:graphic></wp:inline></w:drawing></w:r></w:p>'
            '</w:ftr>');

    // 2) relationships of the main document
    var rels = files.containsKey('word/_rels/document.xml.rels')
        ? utf8.decode(files['word/_rels/document.xml.rels']!)
        : '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
        '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"></Relationships>';
    rels = rels.replaceAll(
        RegExp(r'<Relationship\b[^>]*Id="rIdSchool(Hdr|Ftr)"[^>]*/>'), '');
    rels = rels.replaceFirst(
        '</Relationships>',
        '<Relationship Id="rIdSchoolHdr" Type="$relBase/header" Target="header_school.xml"/>'
            '<Relationship Id="rIdSchoolFtr" Type="$relBase/footer" Target="footer_school.xml"/>'
            '</Relationships>');
    files['word/_rels/document.xml.rels'] = utf8.encode(rels);

    // 3) content types
    var ct = utf8.decode(files['[Content_Types].xml'] ?? const <int>[]);
    if (ct.isEmpty) {
      throw Exception('This is not a valid .docx file ([Content_Types].xml missing).');
    }
    if (!RegExp('Extension="${img.kind}"', caseSensitive: false).hasMatch(ct)) {
      ct = ct.replaceFirst('</Types>',
          '<Default Extension="${img.kind}" ContentType="image/${img.kind}"/></Types>');
    }
    if (!RegExp('Extension="png"', caseSensitive: false).hasMatch(ct)) {
      ct = ct.replaceFirst('</Types>',
          '<Default Extension="png" ContentType="image/png"/></Types>');
    }
    ct = ct.replaceAll(
        RegExp(r'<Override\b[^>]*PartName="/word/(header|footer)_school\.xml"[^>]*/>'),
        '');
    ct = ct.replaceFirst(
        '</Types>',
        '<Override PartName="/word/header_school.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.header+xml"/>'
            '<Override PartName="/word/footer_school.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.footer+xml"/>'
            '</Types>');
    files['[Content_Types].xml'] = utf8.encode(ct);

    // 4) point every section of the document to the new header/footer
    var doc = utf8.decode(files['word/document.xml']!);
    if (!doc.contains('xmlns:r=')) {
      doc = doc.replaceFirst('<w:document',
          '<w:document xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"');
    }
    const refs = '<w:headerReference w:type="default" r:id="rIdSchoolHdr"/>'
        '<w:footerReference w:type="default" r:id="rIdSchoolFtr"/>';
    doc = doc.replaceAllMapped(RegExp(r'<w:sectPr(\s[^>]*?)?/>'),
            (m) => '<w:sectPr${m[1] ?? ''}></w:sectPr>');
    doc = doc.replaceAll(RegExp(r'<w:(header|footer)Reference\b[^>]*/>'), '');
    doc = doc.replaceAll(RegExp(r'<w:titlePg\b[^>]*/>'), '');
    final sect = RegExp(r'<w:sectPr(\s[^>]*)?>');
    if (sect.hasMatch(doc)) {
      doc = doc.replaceAllMapped(sect, (m) => '${m[0]}$refs');
    } else {
      doc = doc.replaceFirst('</w:body>', '<w:sectPr>$refs</w:sectPr></w:body>');
    }
    // Page border: hatched "dash-dot stroked" line, 24 pt in from the page edge.
    const edge = 'w:val="dashDotStroked" w:sz="12" w:space="24" w:color="000000"';
    const border = '<w:pgBorders w:offsetFrom="page">'
        '<w:top $edge/><w:left $edge/><w:bottom $edge/><w:right $edge/>'
        '</w:pgBorders>';
    doc = doc.replaceAllMapped(
        RegExp(r'<w:sectPr\b[^>]*>(.*?)</w:sectPr>', dotAll: true), (m) {
      var inner = m[1]!
          .replaceAll(RegExp(r'<w:pgBorders\b[^>]*/>'), '')
          .replaceAll(
          RegExp(r'<w:pgBorders\b.*?</w:pgBorders>', dotAll: true), '');
      // pgBorders must come right after pgSz / pgMar in a section.
      final anchor = RegExp(r'<w:pgMar\b[^>]*/>').firstMatch(inner) ??
          RegExp(r'<w:pgSz\b[^>]*/>').firstMatch(inner);
      inner = anchor != null
          ? inner.replaceRange(anchor.end, anchor.end, border)
          : inner.replaceFirst(refs, '$refs$border');
      final open = m[0]!.substring(0, m[0]!.indexOf('>') + 1);
      return '$open$inner</w:sectPr>';
    });

    // Force Times New Roman 12 pt: drop direct font/size overrides in the body...
    doc = _stripFontOverrides(doc);
    if (autoFormat) {
      final numXml = files.containsKey('word/numbering.xml')
          ? utf8.decode(files['word/numbering.xml']!, allowMalformed: true)
          : null;
      doc = _autoFormatDoc(doc, numXml, number: numberQuestions);
    }
    // Exam heading table: first thing in the body, below the page header.
    if (heading != null) {
      final table = _headingTableXml(heading);
      doc = doc.replaceFirstMapped(
          RegExp(r'<w:body\b[^>]*>'), (m) => '${m[0]}$table');
    }
    files['word/document.xml'] = utf8.encode(doc);

    // ...and in every style, then set the document defaults.
    final stylesXml = files.containsKey('word/styles.xml')
        ? utf8.decode(files['word/styles.xml']!)
        : null;
    files['word/styles.xml'] = utf8.encode(_forceTimes12(stylesXml));
    if (stylesXml == null) {
      var r2 = utf8.decode(files['word/_rels/document.xml.rels']!);
      r2 = r2.replaceFirst('</Relationships>',
          '<Relationship Id="rIdSchoolStyles" Type="$relBase/styles" Target="styles.xml"/></Relationships>');
      files['word/_rels/document.xml.rels'] = utf8.encode(r2);
      var c2 = utf8.decode(files['[Content_Types].xml']!);
      c2 = c2.replaceFirst('</Types>',
          '<Override PartName="/word/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.styles+xml"/></Types>');
      files['[Content_Types].xml'] = utf8.encode(c2);
    }

    // 5) zip it again
    final out = zip.Archive();
    files.forEach(
            (name, data) => out.addFile(zip.ArchiveFile(name, data.length, data)));
    final bytes = zip.ZipEncoder().encode(out);
    return Uint8List.fromList(bytes!);
  }

  // ---------------- Stamping the letterhead on a document ----------------
  /// Returns a new PDF in which every page has the school letterhead on top,
  /// the original page in the middle and the footer text at the bottom.
  Future<Uint8List> stampDocument({
    required PlatformFile file,
    required Uint8List letterhead,
    required String footer,
    ExamHeadingText? heading,
  }) async {
    final bytes = file.bytes;
    if (bytes == null) throw Exception('Could not read file bytes.');
    final ext = (file.extension ?? '').toLowerCase();
    if (!const ['pdf', 'png', 'jpg', 'jpeg'].contains(ext)) {
      throw Exception(
          '"${file.name}" is not supported. Use a Word (.docx), PDF, PNG or JPG file.');
    }

    // Turn the source into a list of page images (all converted to clean PNG).
    final pages = <Uint8List>[];
    try {
      if (ext == 'pdf') {
        await for (final page in Printing.raster(bytes, dpi: 150)) {
          pages.add(await _toPng(await page.toPng()));
        }
      } else {
        pages.add(await _toPng(bytes)); // png / jpg / webp ...
      }
    } catch (e) {
      throw Exception(
          'Could not read the selected file "${file.name}". Make sure it is a valid PDF, PNG or JPG. ($e)');
    }
    if (pages.isEmpty) throw Exception('The selected file has no pages.');

    final Uint8List headerPng;
    try {
      headerPng = _sniff(letterhead) != null ? letterhead : await _toPng(letterhead);
    } catch (_) {
      throw Exception(
          'The saved school letterhead cannot be read. Tap the image icon and upload it again as PNG or JPG.');
    }
    final headerImg = pw.MemoryImage(headerPng);
    final stampImg = pw.MemoryImage(base64Decode(_footerStampBase64));
    final logoImg = pdfLogoImage(LogoPlace.exam);
    final wmBg = pdfWatermark(LogoPlace.exam);
    final arFont = await _arabicFont(heading);
    final out = pw.Document();
    for (var i = 0; i < pages.length; i++) {
      final p = pages[i];
      final img = pw.MemoryImage(p);
      out.addPage(pw.Page(
        pageTheme: pdfPageTheme(
            const pw.EdgeInsets.symmetric(horizontal: 12, vertical: 24),
            background: wmBg),
        build: (_) => pw.Column(
          crossAxisAlignment: pw.CrossAxisAlignment.stretch,
          children: [
            if (logoImg != null) pdfLogoBlock(logoImg),
            pw.Image(headerImg, width: double.infinity, fit: pw.BoxFit.fitWidth),
            pw.SizedBox(height: 8),
            if (i == 0 && heading != null) ...[
              _pdfHeading(heading, arFont),
              pw.SizedBox(height: 6),
            ],
            pw.Expanded(
              child: pw.Center(child: pw.Image(img, fit: pw.BoxFit.contain)),
            ),
            pw.SizedBox(height: 6),
            pw.Divider(thickness: 0.5),
            pw.Text('$footer | Page ${i + 1} of ${pages.length}',
                textAlign: pw.TextAlign.center,
                style: pw.TextStyle(
                    fontSize: 10, fontWeight: pw.FontWeight.bold)),
            pw.SizedBox(height: 4),
            pw.Center(
              child: pw.Image(stampImg, height: 45, fit: pw.BoxFit.contain),
            ),
          ],
        ),
      ));
    }
    return out.save();
  }

  // ---------------- Result report (PDF) ----------------
  /// A landscape PDF with one ranked table per group (a class, a form ...).
  /// The header is the school letterhead (and logo) saved in Settings, the
  /// footer is the footer text and the Exam Committee stamp, like the exams.
  Future<Uint8List> buildResultReportPdf({
    required String exam,
    required List<ResultReportGroup> groups,
  }) async {
    final usable = [for (final g in groups) if (g.students.isNotEmpty) g];
    if (usable.isEmpty) {
      throw Exception('There are no students to put in the report.');
    }

    // Header: the saved school letterhead (the report still works without it).
    pw.MemoryImage? headerImg;
    final letterhead = await getLetterhead();
    if (letterhead != null) {
      try {
        headerImg = pw.MemoryImage(
            _sniff(letterhead) != null ? letterhead : await _toPng(letterhead));
      } catch (_) {}
    }
    final topImg = headerImg; // final copy, so it can be used in the builders
    final stampImg = pw.MemoryImage(base64Decode(_footerStampBase64));
    final logoImg = pdfLogoImage(LogoPlace.result);
    final wmBg = pdfWatermark(LogoPlace.result);
    final heading = await getHeading();
    final st = appSettings.value;

    // The built-in PDF font is Latin-1 only.
    String safe(String t) => String.fromCharCodes([
      for (final r in t.runes)
        r == 0x2018 || r == 0x2019
            ? 0x27
            : r == 0x2013 || r == 0x2014
            ? 0x2D
            : r > 255
            ? 0x3F
            : r
    ]);
    const grey = PdfColor(0.85, 0.85, 0.85);
    const zebra = PdfColor(0.96, 0.96, 0.96);
    PdfColor gradeColor(String g) => g == 'A' || g == 'B'
        ? PdfColors.green800
        : g == 'C' || g == 'D'
        ? PdfColors.orange800
        : PdfColors.red800;
    pw.Widget bar(String t, {bool boxed = false, double size = 11}) =>
        pw.Container(
          width: double.infinity,
          alignment: pw.Alignment.center,
          padding: const pw.EdgeInsets.symmetric(vertical: 2, horizontal: 4),
          decoration: pw.BoxDecoration(
              color: grey, border: boxed ? pw.Border.all(width: 1) : null),
          child: pw.Text(safe(t),
              style: pw.TextStyle(fontSize: size, fontWeight: pw.FontWeight.bold)),
        );

    final theme = pw.ThemeData.withFont(
        base: pw.Font.times(), bold: pw.Font.timesBold());
    final doc = pw.Document();

    for (final g in usable) {
      final multi =
          {for (final x in g.students) g.sectionLabels[x.id] ?? ''}.length > 1;
      final subjects = [
        for (final sub in ExamService.subjects)
          if (g.students
              .any((x) => g.results[x.id]?.marks.containsKey(sub) ?? false))
            sub
      ];

      int byName(StudentInfo a, StudentInfo b) =>
          a.name.toLowerCase().compareTo(b.name.toLowerCase());
      final scored = [
        for (final x in g.students)
          if (g.results[x.id]?.average != null) x
      ]..sort((a, b) {
        final c = g.results[b.id]!.average!.compareTo(g.results[a.id]!.average!);
        return c != 0 ? c : byName(a, b);
      });
      final rank = <String, int>{};
      for (var i = 0; i < scored.length; i++) {
        final same = i > 0 &&
            g.results[scored[i].id]!.average ==
                g.results[scored[i - 1].id]!.average;
        rank[scored[i].id] = same ? rank[scored[i - 1].id]! : i + 1;
      }
      final unscored = [
        for (final x in g.students)
          if (g.results[x.id]?.average == null) x
      ]..sort(byName);
      final ordered = [...scored, ...unscored];

      final groupAvg = scored.isEmpty
          ? null
          : scored.fold(0.0, (a, x) => a + g.results[x.id]!.average!) /
          scored.length;
      final gradeCount = <String, int>{};
      for (final x in scored) {
        final gr = _gradeOf(g.results[x.id]!.average!);
        gradeCount[gr] = (gradeCount[gr] ?? 0) + 1;
      }

      final fs = subjects.length > 7 ? 8.0 : 9.0;
      pw.Widget cell(String t,
          {bool bold = false, bool left = false, PdfColor? color}) =>
          pw.Padding(
            padding: const pw.EdgeInsets.symmetric(vertical: 3, horizontal: 3),
            child: pw.Align(
              alignment:
              left ? pw.Alignment.centerLeft : pw.Alignment.center,
              child: pw.Text(safe(t),
                  style: pw.TextStyle(
                      fontSize: fs,
                      color: color,
                      fontWeight:
                      bold ? pw.FontWeight.bold : pw.FontWeight.normal)),
            ),
          );

      final widths = <int, pw.TableColumnWidth>{
        0: const pw.FixedColumnWidth(28),
        1: const pw.FlexColumnWidth(4.2),
      };
      var col = 2;
      if (multi) widths[col++] = const pw.FixedColumnWidth(38);
      for (final _ in subjects) {
        widths[col++] = const pw.FlexColumnWidth(1.25);
      }
      widths[col++] = const pw.FlexColumnWidth(1.3);
      widths[col++] = const pw.FlexColumnWidth(1.2);
      widths[col++] = const pw.FixedColumnWidth(36);

      final rows = <pw.TableRow>[
        pw.TableRow(
          repeat: true, // the heading row is repeated on every page
          decoration: const pw.BoxDecoration(color: grey),
          children: [
            cell('Pos', bold: true),
            cell('Student name', bold: true, left: true),
            if (multi) cell('Class', bold: true),
            for (final sub in subjects) cell(sub, bold: true),
            cell('Total', bold: true),
            cell('Average', bold: true),
            cell('Grade', bold: true),
          ],
        ),
        for (var i = 0; i < ordered.length; i++)
          pw.TableRow(
            decoration: i.isOdd ? const pw.BoxDecoration(color: zebra) : null,
            children: () {
              final x = ordered[i];
              final r = g.results[x.id];
              final avg = r?.average;
              final gr = avg == null ? null : _gradeOf(avg);
              return [
                cell(rank[x.id]?.toString() ?? '-'),
                cell(x.name, left: true),
                if (multi) cell(g.sectionLabels[x.id] ?? ''),
                for (final sub in subjects)
                  cell(r?.marks.containsKey(sub) ?? false
                      ? _fmtMark(r!.marks[sub]!)
                      : '-'),
                cell(r == null || avg == null ? '-' : _fmtMark(r.total),
                    bold: true),
                cell(
                    avg == null
                        ? '-'
                        : _fmtMark(double.parse(avg.toStringAsFixed(1))),
                    bold: true),
                cell(gr ?? '-',
                    bold: true, color: gr == null ? null : gradeColor(gr)),
              ];
            }(),
          ),
      ];

      final stats = '${g.students.length} students | ${scored.length} with '
          'results${groupAvg == null ? '' : ' | class average ${_fmtMark(double.parse(groupAvg.toStringAsFixed(1)))}'}';
      final key = [
        for (var i = 0; i < AppSettings.gradeLetters.length; i++)
          '${AppSettings.gradeLetters[i]} >= ${_fmtMark(st.grades[i])}',
        'F below ${_fmtMark(st.grades.last)}',
      ].join('   ');
      final counts = [
        for (final l in [...AppSettings.gradeLetters, 'F'])
          if ((gradeCount[l] ?? 0) > 0) '$l: ${gradeCount[l]}'
      ].join('   ');

      doc.addPage(pw.MultiPage(
        pageTheme: pw.PageTheme(
          pageFormat: PdfPageFormat.a4.landscape,
          margin: const pw.EdgeInsets.fromLTRB(28, 20, 28, 20),
          theme: theme,
          buildBackground: wmBg,
        ),
        footer: (ctx) => pw.Column(
          mainAxisSize: pw.MainAxisSize.min,
          children: [
            pw.Divider(thickness: 0.5),
            pw.Text(
                safe('Result report | ${g.title} | $exam | '
                    'Page ${ctx.pageNumber} of ${ctx.pagesCount}'),
                textAlign: pw.TextAlign.center,
                style:
                pw.TextStyle(fontSize: 10, fontWeight: pw.FontWeight.bold)),
            pw.SizedBox(height: 3),
            pw.Center(
                child: pw.Image(stampImg, height: 36, fit: pw.BoxFit.contain)),
          ],
        ),
        build: (ctx) => [
          if (logoImg != null) pdfLogoBlock(logoImg),
          if (topImg != null)
            pw.Image(topImg,
                width: double.infinity, height: 80, fit: pw.BoxFit.contain),
          pw.SizedBox(height: 6),
          bar('${exam.toUpperCase()} - RESULTS', boxed: true, size: 13),
          bar(g.title.toUpperCase(), size: 15),
          bar('ACADEMIC YEAR ${heading.academicYear}   |   $stats', size: 10),
          pw.SizedBox(height: 8),
          pw.Table(
            border: pw.TableBorder.all(width: 0.5),
            columnWidths: widths,
            children: rows,
          ),
          pw.SizedBox(height: 8),
          if (counts.isNotEmpty)
            pw.Text(safe('Grades: $counts'),
                style:
                pw.TextStyle(fontSize: 9, fontWeight: pw.FontWeight.bold)),
          pw.Text(safe('Grading (average mark): $key'),
              style: const pw.TextStyle(fontSize: 8.5)),
        ],
      ));
    }
    return doc.save();
  }

  // ---------------- Result report (Excel and Word) ----------------
  /// Same ranking as the PDF: best average first, equal averages share a
  /// position, students without marks come last (A-Z).
  static ({
  List<String> subjects,
  List<StudentInfo> ordered,
  Map<String, int> rank,
  double? groupAvg,
  int scoredCount,
  Map<String, int> gradeCount,
  bool multi,
  }) _rankResultGroup(ResultReportGroup g) {
    final multi =
        {for (final x in g.students) g.sectionLabels[x.id] ?? ''}.length > 1;
    final subjects = [
      for (final sub in ExamService.subjects)
        if (g.students
            .any((x) => g.results[x.id]?.marks.containsKey(sub) ?? false))
          sub
    ];
    int byName(StudentInfo a, StudentInfo b) =>
        a.name.toLowerCase().compareTo(b.name.toLowerCase());
    final scored = [
      for (final x in g.students)
        if (g.results[x.id]?.average != null) x
    ]..sort((a, b) {
      final c = g.results[b.id]!.average!.compareTo(g.results[a.id]!.average!);
      return c != 0 ? c : byName(a, b);
    });
    final rank = <String, int>{};
    for (var i = 0; i < scored.length; i++) {
      final same = i > 0 &&
          g.results[scored[i].id]!.average ==
              g.results[scored[i - 1].id]!.average;
      rank[scored[i].id] = same ? rank[scored[i - 1].id]! : i + 1;
    }
    final unscored = [
      for (final x in g.students)
        if (g.results[x.id]?.average == null) x
    ]..sort(byName);
    final groupAvg = scored.isEmpty
        ? null
        : scored.fold(0.0, (a, x) => a + g.results[x.id]!.average!) /
        scored.length;
    final gradeCount = <String, int>{};
    for (final x in scored) {
      final gr = _gradeOf(g.results[x.id]!.average!);
      gradeCount[gr] = (gradeCount[gr] ?? 0) + 1;
    }
    return (
    subjects: subjects,
    ordered: [...scored, ...unscored],
    rank: rank,
    groupAvg: groupAvg,
    scoredCount: scored.length,
    gradeCount: gradeCount,
    multi: multi,
    );
  }

  static String _resultStats(
      ResultReportGroup g, int scoredCount, double? groupAvg) =>
      '${g.students.length} students | $scoredCount with results'
          '${groupAvg == null ? '' : ' | class average ${_fmtMark(double.parse(groupAvg.toStringAsFixed(1)))}'}';

  static String _resultGradeCounts(Map<String, int> gradeCount) => [
    for (final l in [...AppSettings.gradeLetters, 'F'])
      if ((gradeCount[l] ?? 0) > 0) '$l: ${gradeCount[l]}'
  ].join('   ');

  static String _resultGradeKey() {
    final st = appSettings.value;
    return [
      for (var i = 0; i < AppSettings.gradeLetters.length; i++)
        '${AppSettings.gradeLetters[i]} >= ${_fmtMark(st.grades[i])}',
      'F below ${_fmtMark(st.grades.last)}',
    ].join('   ');
  }

  /// The result report as an Excel (.xlsx) file: one sheet per group, with the
  /// same columns, ranking and grades as the PDF. Marks are real numbers, so
  /// the sheet can be sorted, filtered or calculated on in Excel.
  Future<Uint8List> buildResultReportXlsx({
    required String exam,
    required List<ResultReportGroup> groups,
  }) async {
    final usable = [for (final g in groups) if (g.students.isNotEmpty) g];
    if (usable.isEmpty) {
      throw Exception('There are no students to put in the report.');
    }
    final heading = await getHeading();
    String colName(int i) {
      var n = i + 1;
      var s = '';
      while (n > 0) {
        final m = (n - 1) % 26;
        s = String.fromCharCode(65 + m) + s;
        n = (n - 1) ~/ 26;
      }
      return s;
    }

    String sc(int c, int r, String t, int style) =>
        '<c r="${colName(c)}$r" s="$style" t="inlineStr"><is>'
            '<t xml:space="preserve">${_xml(t.replaceAll('–', '-'))}</t></is></c>';
    String nc(int c, int r, num v, int style) =>
        '<c r="${colName(c)}$r" s="$style"><v>$v</v></c>';
    String ec(int c, int r, int style) => '<c r="${colName(c)}$r" s="$style"/>';

    final usedNames = <String>{};
    String sheetName(String t) {
      var n = t.replaceAll(RegExp(r'[\[\]:*?/\\]'), '-').trim();
      if (n.isEmpty) n = 'Results';
      if (n.length > 31) n = n.substring(0, 31);
      var u = n;
      var k = 2;
      while (!usedNames.add(u.toLowerCase())) {
        final suffix = ' ($k)';
        u = n.substring(0, (n.length.clamp(0, 31 - suffix.length)).toInt()) + suffix;
        k++;
      }
      return u;
    }

    const xmlHead = '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>';
    final sheets = <String>[];
    final names = <String>[];

    for (final g in usable) {
      final d = _rankResultGroup(g);
      final cols = 2 + (d.multi ? 1 : 0) + d.subjects.length + 3;
      final rows = StringBuffer();
      final merges = <String>[];

      String bandRow(int r, String text, int style) {
        merges.add('A$r:${colName(cols - 1)}$r');
        final b = StringBuffer('<row r="$r"${style == 5 ? ' ht="24" customHeight="1"' : ''}>');
        b.write(sc(0, r, text, style));
        for (var c = 1; c < cols; c++) {
          b.write(ec(c, r, style));
        }
        b.write('</row>');
        return b.toString();
      }

      rows.write(bandRow(1, '${exam.toUpperCase()} - RESULTS', 5));
      rows.write(bandRow(2, g.title.toUpperCase(), 5));
      rows.write(bandRow(
          3,
          'ACADEMIC YEAR ${heading.academicYear}   |   '
              '${_resultStats(g, d.scoredCount, d.groupAvg)}',
          10));

      // header row (row 5)
      final head = StringBuffer('<row r="5" ht="30" customHeight="1">');
      var c = 0;
      head.write(sc(c++, 5, 'Pos', 1));
      head.write(sc(c++, 5, 'Student name', 1));
      if (d.multi) head.write(sc(c++, 5, 'Class', 1));
      for (final sub in d.subjects) {
        head.write(sc(c++, 5, sub, 1));
      }
      head.write(sc(c++, 5, 'Total', 1));
      head.write(sc(c++, 5, 'Average', 1));
      head.write(sc(c++, 5, 'Grade', 1));
      head.write('</row>');
      rows.write(head);

      var r = 6;
      for (final x in d.ordered) {
        final res = g.results[x.id];
        final avg = res?.average;
        final gr = avg == null ? null : _gradeOf(avg);
        final line = StringBuffer('<row r="$r">');
        var k = 0;
        line.write(d.rank[x.id] == null
            ? sc(k++, r, '-', 2)
            : nc(k++, r, d.rank[x.id]!, 2));
        line.write(sc(k++, r, x.name, 3));
        if (d.multi) line.write(sc(k++, r, g.sectionLabels[x.id] ?? '', 2));
        for (final sub in d.subjects) {
          final m = res?.marks[sub];
          line.write(m == null ? sc(k++, r, '-', 2) : nc(k++, r, m, 2));
        }
        line.write(res == null || avg == null
            ? sc(k++, r, '-', 4)
            : nc(k++, r, res.total, 4));
        line.write(avg == null
            ? sc(k++, r, '-', 4)
            : nc(k++, r, double.parse(avg.toStringAsFixed(1)), 4));
        line.write(gr == null
            ? sc(k++, r, '-', 4)
            : sc(k++, r, gr,
            gr == 'A' || gr == 'B' ? 7 : (gr == 'C' || gr == 'D' ? 8 : 9)));
        line.write('</row>');
        rows.write(line);
        r++;
      }
      r++;
      final counts = _resultGradeCounts(d.gradeCount);
      if (counts.isNotEmpty) {
        rows.write('<row r="$r">${sc(0, r, 'Grades: $counts', 6)}</row>');
        r++;
      }
      rows.write(
          '<row r="$r">${sc(0, r, 'Grading (average mark): ${_resultGradeKey()}', 11)}</row>');

      final colsXml = StringBuffer('<cols>');
      var ci = 1;
      colsXml.write('<col min="$ci" max="$ci" width="6" customWidth="1"/>');
      ci++;
      final longest = g.students.fold<int>(
          12, (m, s) => s.name.length > m ? s.name.length : m);
      colsXml.write(
          '<col min="$ci" max="$ci" width="${(longest + 4).clamp(24, 50)}" customWidth="1"/>');
      ci++;
      if (d.multi) {
        colsXml.write('<col min="$ci" max="$ci" width="9" customWidth="1"/>');
        ci++;
      }
      for (final sub in d.subjects) {
        colsXml.write(
            '<col min="$ci" max="$ci" width="${(sub.length + 3).clamp(11, 22)}" customWidth="1"/>');
        ci++;
      }
      colsXml.write('<col min="$ci" max="${ci + 2}" width="10" customWidth="1"/>');
      colsXml.write('</cols>');

      sheets.add('$xmlHead<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main">'
          '<sheetPr><pageSetUpPr fitToPage="1"/></sheetPr>'
          '<sheetViews><sheetView workbookViewId="0">'
          '<pane ySplit="5" topLeftCell="A6" activePane="bottomLeft" state="frozen"/>'
          '</sheetView></sheetViews>'
          '<sheetFormatPr defaultRowHeight="16"/>'
          '$colsXml<sheetData>$rows</sheetData>'
          '<mergeCells count="${merges.length}">'
          '${merges.map((m) => '<mergeCell ref="$m"/>').join()}</mergeCells>'
          '<pageMargins left="0.4" right="0.4" top="0.5" bottom="0.5" header="0.3" footer="0.3"/>'
          '<pageSetup paperSize="9" orientation="landscape" fitToWidth="1" fitToHeight="0"/>'
          '</worksheet>');
      names.add(sheetName(g.title));
    }

    const rel =
        'http://schemas.openxmlformats.org/officeDocument/2006/relationships';
    const b1 =
        '<border><left style="thin"><color auto="1"/></left><right style="thin"><color auto="1"/></right>'
        '<top style="thin"><color auto="1"/></top><bottom style="thin"><color auto="1"/></bottom><diagonal/></border>';
    String xf(int font, int fill, int border, String h, {bool wrap = false}) =>
        '<xf numFmtId="0" fontId="$font" fillId="$fill" borderId="$border" xfId="0" '
            'applyFont="1" applyFill="1" applyBorder="1" applyAlignment="1">'
            '<alignment horizontal="$h" vertical="center"${wrap ? ' wrapText="1"' : ''}/></xf>';
    String font(String extra, {int sz = 11, String? color}) =>
        '<font>$extra<sz val="$sz"/>${color == null ? '' : '<color rgb="$color"/>'}'
            '<name val="Times New Roman"/></font>';

    final stylesXml = '$xmlHead<styleSheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main">'
        '<fonts count="6">${font('')}${font('<b/>')}${font('<b/>', sz: 14)}'
        '${font('<b/>', color: 'FF2E7D32')}${font('<b/>', color: 'FFEF6C00')}'
        '${font('<b/>', color: 'FFC62828')}</fonts>'
        '<fills count="3"><fill><patternFill patternType="none"/></fill>'
        '<fill><patternFill patternType="gray125"/></fill>'
        '<fill><patternFill patternType="solid"><fgColor rgb="FFD9D9D9"/><bgColor indexed="64"/></patternFill></fill></fills>'
        '<borders count="2"><border><left/><right/><top/><bottom/><diagonal/></border>$b1</borders>'
        '<cellStyleXfs count="1"><xf numFmtId="0" fontId="0" fillId="0" borderId="0"/></cellStyleXfs>'
        '<cellXfs count="12">'
        '${xf(0, 0, 0, 'general')}' // 0 default
        '${xf(1, 2, 1, 'center', wrap: true)}' // 1 header
        '${xf(0, 0, 1, 'center')}' // 2 body centre
        '${xf(0, 0, 1, 'left')}' // 3 body left
        '${xf(1, 0, 1, 'center')}' // 4 bold centre
        '${xf(2, 2, 1, 'center')}' // 5 title
        '${xf(1, 0, 0, 'left')}' // 6 bold note
        '${xf(3, 0, 1, 'center')}' // 7 grade A/B
        '${xf(4, 0, 1, 'center')}' // 8 grade C/D
        '${xf(5, 0, 1, 'center')}' // 9 grade E/F
        '${xf(1, 2, 1, 'center')}' // 10 sub title
        '${xf(0, 0, 0, 'left')}' // 11 plain note
        '</cellXfs>'
        '<cellStyles count="1"><cellStyle name="Normal" xfId="0" builtinId="0"/></cellStyles>'
        '</styleSheet>';

    final files = <String, List<int>>{
      '[Content_Types].xml': utf8.encode(
          '$xmlHead<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">'
              '<Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/>'
              '<Default Extension="xml" ContentType="application/xml"/>'
              '<Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/>'
              '<Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/>'
              '${[for (var i = 0; i < sheets.length; i++) '<Override PartName="/xl/worksheets/sheet${i + 1}.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>'].join()}'
              '</Types>'),
      '_rels/.rels': utf8.encode(
          '$xmlHead<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'
              '<Relationship Id="rId1" Type="$rel/officeDocument" Target="xl/workbook.xml"/>'
              '</Relationships>'),
      'xl/workbook.xml': utf8.encode(
          '$xmlHead<workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" '
              'xmlns:r="$rel"><sheets>'
              '${[for (var i = 0; i < names.length; i++) '<sheet name="${_xml(names[i])}" sheetId="${i + 1}" r:id="rId${i + 1}"/>'].join()}'
              '</sheets></workbook>'),
      'xl/_rels/workbook.xml.rels': utf8.encode(
          '$xmlHead<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'
              '${[for (var i = 0; i < sheets.length; i++) '<Relationship Id="rId${i + 1}" Type="$rel/worksheet" Target="worksheets/sheet${i + 1}.xml"/>'].join()}'
              '<Relationship Id="rId${sheets.length + 1}" Type="$rel/styles" Target="styles.xml"/>'
              '</Relationships>'),
      'xl/styles.xml': utf8.encode(stylesXml),
      for (var i = 0; i < sheets.length; i++)
        'xl/worksheets/sheet${i + 1}.xml': utf8.encode(sheets[i]),
    };
    final out = zip.Archive();
    files.forEach(
            (name, data) => out.addFile(zip.ArchiveFile(name, data.length, data)));
    final bytes = zip.ZipEncoder().encode(out);
    if (bytes == null) throw Exception('Could not create the Excel file.');
    return Uint8List.fromList(bytes);
  }

  /// The result report as an editable Word (.docx) file: landscape A4, one
  /// ranked table per group (each group starts on a new page), with the school
  /// logo / watermark saved in Settings for the Result report.
  Future<Uint8List> buildResultReportDocx({
    required String exam,
    required List<ResultReportGroup> groups,
  }) async {
    final usable = [for (final g in groups) if (g.students.isNotEmpty) g];
    if (usable.isEmpty) {
      throw Exception('There are no students to put in the report.');
    }
    final heading = await getHeading();
    String x(String t) => _xml(t.replaceAll('–', '-'));

    const ns =
        'xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main" '
        'xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships" '
        'xmlns:wp="http://schemas.openxmlformats.org/drawingml/2006/wordprocessingDrawing" '
        'xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main" '
        'xmlns:pic="http://schemas.openxmlformats.org/drawingml/2006/picture"';
    const relBase =
        'http://schemas.openxmlformats.org/officeDocument/2006/relationships';
    const shade = '<w:shd w:val="clear" w:color="auto" w:fill="D9D9D9"/>';
    const zebra = '<w:shd w:val="clear" w:color="auto" w:fill="F5F5F5"/>';
    const edge = 'w:val="single" w:sz="6" w:space="0" w:color="000000"';
    const tblBorders = '<w:tblBorders><w:top $edge/><w:left $edge/>'
        '<w:bottom $edge/><w:right $edge/><w:insideH $edge/>'
        '<w:insideV $edge/></w:tblBorders>';
    const pageW = 15038; // landscape A4 minus 900 twips margins

    String run(String t, {bool b = false, int sz = 20, String? color}) =>
        '<w:r><w:rPr>${b ? '<w:b/><w:bCs/>' : ''}'
            '${color == null ? '' : '<w:color w:val="$color"/>'}'
            '<w:sz w:val="$sz"/><w:szCs w:val="$sz"/></w:rPr>'
            '<w:t xml:space="preserve">${x(t)}</w:t></w:r>';
    String para(String t,
        {bool b = true,
          String jc = 'center',
          bool pageBreak = false,
          int sz = 20,
          int sp = 20,
          String? color}) =>
        '<w:p><w:pPr>${pageBreak ? '<w:pageBreakBefore/>' : ''}'
            '<w:spacing w:before="$sp" w:after="$sp"/><w:jc w:val="$jc"/>'
            '<w:rPr><w:sz w:val="$sz"/><w:szCs w:val="$sz"/></w:rPr></w:pPr>'
            '${t.isEmpty ? '' : run(t, b: b, sz: sz, color: color)}</w:p>';
    String bar(String t, {bool boxed = false, int sz = 22}) =>
        '<w:tr><w:tc><w:tcPr><w:tcW w:w="$pageW" w:type="dxa"/>'
            '${boxed ? '<w:tcBorders><w:top $edge/><w:left $edge/><w:bottom $edge/><w:right $edge/></w:tcBorders>' : ''}'
            '$shade</w:tcPr>${para(t, sz: sz, sp: sz > 22 ? 40 : 20)}</w:tc></w:tr>';
    String tc(int w, String t,
        {bool head = false,
          String jc = 'center',
          int sz = 20,
          bool b = false,
          bool zebraRow = false,
          String? color}) =>
        '<w:tc><w:tcPr><w:tcW w:w="$w" w:type="dxa"/>'
            '${head ? shade : (zebraRow ? zebra : '')}<w:vAlign w:val="center"/></w:tcPr>'
            '${para(t, b: head || b, jc: jc, sz: sz, sp: 30, color: color)}</w:tc>';
    String tr(List<String> cells, {bool head = false}) =>
        '<w:tr><w:trPr><w:cantSplit/>${head ? '<w:tblHeader/>' : ''}'
            '<w:trHeight w:val="360" w:hRule="atLeast"/></w:trPr>${cells.join()}</w:tr>';
    String table(String grid, String rows) =>
        '<w:tbl><w:tblPr><w:tblW w:w="$pageW" w:type="dxa"/>$tblBorders'
            '<w:tblLayout w:type="fixed"/></w:tblPr><w:tblGrid>$grid</w:tblGrid>$rows</w:tbl>';

    final body = StringBuffer();
    for (var gi = 0; gi < usable.length; gi++) {
      final g = usable[gi];
      final d = _rankResultGroup(g);

      // column widths (twips) that always add up to the page width
      const posW = 650, totW = 1100, avgW = 1100, gradeW = 850, clsW = 900;
      final fixed = posW + totW + avgW + gradeW + (d.multi ? clsW : 0);
      var nameW = 3800;
      var subW = 0;
      if (d.subjects.isEmpty) {
        nameW = pageW - fixed;
      } else {
        subW = ((pageW - fixed - nameW) / d.subjects.length).floor();
        if (subW < 850) {
          subW = 850;
          nameW = pageW - fixed - subW * d.subjects.length;
        }
        nameW = pageW - fixed - subW * d.subjects.length; // absorb the rounding
      }
      final sz = d.subjects.length > 7 ? 16 : 18;
      final widths = <int>[
        posW,
        nameW,
        if (d.multi) clsW,
        for (final _ in d.subjects) subW,
        totW,
        avgW,
        gradeW,
      ];
      final grid = widths.map((w) => '<w:gridCol w:w="$w"/>').join();

      if (gi > 0) body.write(para('', b: false, pageBreak: true, sz: 2, sp: 0));
      body.write(docxLogoPara(LogoPlace.result,
          rid: 'rIdSchoolLogo', docPrId: 9400 + gi));
      body.write(table(
        '<w:gridCol w:w="$pageW"/>',
        bar('${exam.toUpperCase()} - RESULTS', boxed: true, sz: 26) +
            bar(g.title.toUpperCase(), sz: 30) +
            bar('ACADEMIC YEAR ${heading.academicYear}   |   '
                '${_resultStats(g, d.scoredCount, d.groupAvg)}'),
      ));
      body.write(para('', b: false, sz: 12, sp: 0));

      final rows = StringBuffer(tr([
        tc(widths[0], 'Pos', head: true, sz: sz),
        tc(widths[1], 'Student name', head: true, jc: 'left', sz: sz),
        if (d.multi) tc(clsW, 'Class', head: true, sz: sz),
        for (final sub in d.subjects) tc(subW, sub, head: true, sz: sz),
        tc(totW, 'Total', head: true, sz: sz),
        tc(avgW, 'Average', head: true, sz: sz),
        tc(gradeW, 'Grade', head: true, sz: sz),
      ], head: true));
      for (var i = 0; i < d.ordered.length; i++) {
        final s = d.ordered[i];
        final res = g.results[s.id];
        final avg = res?.average;
        final gr = avg == null ? null : _gradeOf(avg);
        final z = i.isOdd;
        rows.write(tr([
          tc(posW, d.rank[s.id]?.toString() ?? '-', sz: sz, zebraRow: z),
          tc(nameW, s.name, jc: 'left', sz: sz, zebraRow: z),
          if (d.multi)
            tc(clsW, g.sectionLabels[s.id] ?? '', sz: sz, zebraRow: z),
          for (final sub in d.subjects)
            tc(subW,
                res?.marks.containsKey(sub) ?? false
                    ? _fmtMark(res!.marks[sub]!)
                    : '-',
                sz: sz,
                zebraRow: z),
          tc(totW, res == null || avg == null ? '-' : _fmtMark(res.total),
              sz: sz, b: true, zebraRow: z),
          tc(
              avgW,
              avg == null
                  ? '-'
                  : _fmtMark(double.parse(avg.toStringAsFixed(1))),
              sz: sz,
              b: true,
              zebraRow: z),
          tc(gradeW, gr ?? '-',
              sz: sz,
              b: true,
              zebraRow: z,
              color: gr == null
                  ? null
                  : (gr == 'A' || gr == 'B'
                  ? '2E7D32'
                  : (gr == 'C' || gr == 'D' ? 'EF6C00' : 'C62828'))),
        ]));
      }
      body.write(table(grid, rows.toString()));

      body.write(para('', b: false, sz: 12, sp: 0));
      final counts = _resultGradeCounts(d.gradeCount);
      if (counts.isNotEmpty) {
        body.write(para('Grades: $counts', jc: 'left', sz: 18, sp: 10));
      }
      body.write(para('Grading (average mark): ${_resultGradeKey()}',
          b: false, jc: 'left', sz: 17, sp: 10));
    }

    const xmlHead = '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>';
    final documentXml = '$xmlHead<w:document $ns><w:body>$body'
        '<w:sectPr>${docxWmSectRef(LogoPlace.result)}'
        '<w:pgSz w:w="16838" w:h="11906" w:orient="landscape"/>'
        '<w:pgMar w:top="720" w:right="900" w:bottom="720" w:left="900" '
        'w:header="400" w:footer="400" w:gutter="0"/>'
        '</w:sectPr></w:body></w:document>';
    const stylesXml = '$xmlHead<w:styles xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main">'
        '<w:docDefaults><w:rPrDefault><w:rPr>'
        '<w:rFonts w:ascii="Times New Roman" w:hAnsi="Times New Roman" w:eastAsia="Times New Roman" w:cs="Times New Roman"/>'
        '<w:sz w:val="20"/><w:szCs w:val="20"/></w:rPr></w:rPrDefault>'
        '<w:pPrDefault><w:pPr><w:spacing w:after="0" w:line="240" w:lineRule="auto"/></w:pPr></w:pPrDefault>'
        '</w:docDefaults></w:styles>';

    final files = <String, List<int>>{
      '[Content_Types].xml': utf8.encode(
          '$xmlHead<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">'
              '<Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/>'
              '<Default Extension="xml" ContentType="application/xml"/>'
              '<Default Extension="png" ContentType="image/png"/>'
              '<Default Extension="jpeg" ContentType="image/jpeg"/>'
              '<Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/>'
              '<Override PartName="/word/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.styles+xml"/>'
              '${docxWmHeaderOverride(LogoPlace.result)}'
              '</Types>'),
      '_rels/.rels': utf8.encode(
          '$xmlHead<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'
              '<Relationship Id="rId1" Type="$relBase/officeDocument" Target="word/document.xml"/>'
              '</Relationships>'),
      'word/_rels/document.xml.rels': utf8.encode(
          '$xmlHead<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'
              '<Relationship Id="rIdStyles" Type="$relBase/styles" Target="styles.xml"/>'
              '${docxLogoRel(LogoPlace.result, 'rIdSchoolLogo')}'
              '${docxWmHeaderRel(LogoPlace.result)}'
              '</Relationships>'),
      'word/document.xml': utf8.encode(documentXml),
      'word/styles.xml': utf8.encode(stylesXml),
      if (schoolLogo.value.uses(LogoPlace.result))
        'word/media/school_logo.png': schoolLogo.value.bytes!,
      ...docxWatermarkFiles(LogoPlace.result),
    };
    final out = zip.Archive();
    files.forEach(
            (name, data) => out.addFile(zip.ArchiveFile(name, data.length, data)));
    final bytes = zip.ZipEncoder().encode(out);
    if (bytes == null) throw Exception('Could not create the Word file.');
    return Uint8List.fromList(bytes);
  }

  // ---------------- Preview (nothing is saved) ----------------
  /// Builds the finished document exactly as Upload would, but only returns
  /// it. With no file selected it returns a sample page showing the letterhead,
  /// heading table and footer.
  Future<({Uint8List bytes, bool isDocx, String name})> buildPreview({
    required ExamRecord current,
    PlatformFile? file,
    required String footer,
    String marks = '',
    String allowedTime = '',
    bool addHeading = true,
    bool autoFormat = true,
    bool numberQuestions = true,
  }) async {
    footer = footer.replaceAll('Teacher: ', '').replaceAll('Teacher:', '');
    final letterhead = await getLetterhead();
    if (letterhead == null) {
      throw Exception(
          'No school letterhead yet. Tap the image icon at the top to upload it first.');
    }
    final heading = addHeading
        ? (await getHeading())
        .build(current.subject, current.form, marks: marks, time: allowedTime)
        : null;

    if (file == null) {
      final Uint8List headerPng;
      try {
        headerPng = _sniff(letterhead) != null ? letterhead : await _toPng(letterhead);
      } catch (_) {
        throw Exception('The saved school letterhead cannot be read.');
      }
      final headerImg = pw.MemoryImage(headerPng);
      final stampImg = pw.MemoryImage(base64Decode(_footerStampBase64));
      final logoImg = pdfLogoImage(LogoPlace.exam);
      final wmBg = pdfWatermark(LogoPlace.exam);
      final arFont = await _arabicFont(heading);
      final out = pw.Document();
      out.addPage(pw.Page(
        pageTheme: pdfPageTheme(
            const pw.EdgeInsets.symmetric(horizontal: 12, vertical: 24),
            background: wmBg),
        build: (_) => pw.Column(
          crossAxisAlignment: pw.CrossAxisAlignment.stretch,
          children: [
            if (logoImg != null) pdfLogoBlock(logoImg),
            pw.Image(headerImg, width: double.infinity, fit: pw.BoxFit.fitWidth),
            pw.SizedBox(height: 8),
            if (heading != null) ...[
              _pdfHeading(heading, arFont),
              pw.SizedBox(height: 6),
            ],
            pw.Expanded(
              child: pw.Center(
                child: pw.Text('(Exam questions appear here)',
                    style: const pw.TextStyle(fontSize: 12, color: PdfColors.grey600)),
              ),
            ),
            pw.SizedBox(height: 6),
            pw.Divider(thickness: 0.5),
            pw.Text('$footer | Page 1 of 1',
                textAlign: pw.TextAlign.center,
                style: pw.TextStyle(fontSize: 10, fontWeight: pw.FontWeight.bold)),
            pw.SizedBox(height: 4),
            pw.Center(child: pw.Image(stampImg, height: 45, fit: pw.BoxFit.contain)),
          ],
        ),
      ));
      return (bytes: await out.save(), isDocx: false, name: 'preview.pdf');
    }

    final bytes = file.bytes;
    if (bytes == null) throw Exception('Could not read file bytes.');
    final isDocx = (file.extension ?? '').toLowerCase() == 'docx';
    final stamped = isDocx
        ? await stampDocx(
        docx: bytes,
        letterhead: letterhead,
        footer: footer,
        heading: heading,
        autoFormat: autoFormat,
        numberQuestions: numberQuestions)
        : await stampDocument(
        file: file, letterhead: letterhead, footer: footer, heading: heading);
    return (
    bytes: stamped,
    isDocx: isDocx,
    name: isDocx ? 'Preview-${current.form}-${current.subject}.docx' : 'preview.pdf',
    );
  }

  // ---------------- Per-button details ----------------
  /// Saves only the teacher name + generated footer (no file needed).
  Future<void> saveDetails(
      String subject, String form, String footer, String teacher,
      {String marks = '', String allowedTime = ''}) {
    return _col.doc(ExamRecord.idFor(subject, form)).set({
      'subject': subject,
      'form': form,
      'footer': footer.replaceAll('Teacher: ', '').replaceAll('Teacher:', ''),
      'teacherName': teacher,
      'marks': marks,
      'allowedTime': allowedTime,
      'updatedBy': FirebaseAuth.instance.currentUser?.uid,
      'updatedAt': FieldValue.serverTimestamp(),
    }, SetOptions(merge: true));
  }

  /// Stamps the general letterhead + footer on the file, uploads it and
  /// marks the cell as Received.
  Future<void> upload({
    required ExamRecord current,
    required PlatformFile file,
    required String footer,
    required String teacher,
    String marks = '',
    String allowedTime = '',
    bool addHeading = true,
    bool autoFormat = true,
    bool numberQuestions = true,
    void Function(double progress)? onProgress,
    void Function(String status)? onStatus,
  }) async {
    footer = footer.replaceAll('Teacher: ', '').replaceAll('Teacher:', '');
    final letterhead = await getLetterhead();
    if (letterhead == null) {
      throw Exception(
          'No school letterhead yet. Tap the image icon at the top to upload it first.');
    }

    final bytes = file.bytes;
    if (bytes == null) throw Exception('Could not read file bytes.');
    final isDocx = (file.extension ?? '').toLowerCase() == 'docx';

    onStatus?.call('Adding letterhead, exam heading and footer...');
    final ExamHeadingText? heading = addHeading
        ? (await getHeading())
        .build(current.subject, current.form, marks: marks, time: allowedTime)
        : null;
    final Uint8List stamped = isDocx
        ? await stampDocx(
        docx: bytes,
        letterhead: letterhead,
        footer: footer,
        heading: heading,
        autoFormat: autoFormat,
        numberQuestions: numberQuestions)
        : await stampDocument(
        file: file, letterhead: letterhead, footer: footer, heading: heading);

    final baseName = file.name.replaceAll(RegExp(r'\.[^.]+$'), '');
    final fileName = isDocx ? file.name : '$baseName.pdf';
    final kb = (stamped.length / 1024).round();
    if (stamped.length > maxFileBytes) {
      throw Exception(
          'File is too large ($kb KB after adding the letterhead). The limit is 700 KB. '
              'Please compress the file or use a smaller letterhead image.');
    }

    onStatus?.call('Saving $kb KB...');
    final id = ExamRecord.idFor(current.subject, current.form);
    await _files.doc(id).set({
      'fileName': fileName,
      'contentType': isDocx ? _docxMime : 'application/pdf',
      'dataBase64': base64Encode(stamped),
      'size': stamped.length,
      'updatedBy': FirebaseAuth.instance.currentUser?.uid,
      'updatedAt': FieldValue.serverTimestamp(),
    }).timeout(const Duration(seconds: 40), onTimeout: () {
      throw Exception(
          'Saving timed out. Check the internet connection and the Firestore rules (collection "files").');
    });
    onProgress?.call(1);

    await _col.doc(id).set({
      'subject': current.subject,
      'form': current.form,
      'status': 'received',
      'receivedAt': FieldValue.serverTimestamp(),
      'hasFile': true,
      'fileName': fileName,
      'footer': footer,
      'teacherName': teacher,
      'marks': marks,
      'allowedTime': allowedTime,
      'updatedBy': FirebaseAuth.instance.currentUser?.uid,
      'updatedAt': FieldValue.serverTimestamp(),
    }, SetOptions(merge: true));
  }

  // ---------------- In-app editing of a stored .docx ----------------
  static final _paraRe =
  RegExp(r'<w:p(?:\s[^>]*?)?(?<!/)>(.*?)</w:p>', dotAll: true);
  static final _textRe = RegExp(r'<w:t(?:\s[^>]*)?>(.*?)</w:t>', dotAll: true);
  static final _runRe = RegExp(r'<w:r(?:\s[^>]*)?>(.*?)</w:r>', dotAll: true);
  static final _runPartRe =
  RegExp(r'<w:t(?:\s[^>]*)?>(.*?)</w:t>|<w:tab\s*/>', dotAll: true);
  // Paragraphs holding pictures, fields, links, breaks, tracked changes...
  // are shown read-only so nothing in them can be damaged.
  static final _lockRe = RegExp(
      r'<w:(drawing|pict|object|txbxContent|fldChar|fldSimple|hyperlink|sdt|ins|del|br|footnoteReference|endnoteReference|commentReference|moveFrom|moveTo)\b');

  static String _unxml(String t) => t
      .replaceAllMapped(RegExp(r'&#(x?)([0-9A-Fa-f]+);'), (m) {
    final c = int.tryParse(m[2]!, radix: m[1] == 'x' ? 16 : 10);
    return c == null ? m[0]! : String.fromCharCode(c);
  })
      .replaceAll('&lt;', '<')
      .replaceAll('&gt;', '>')
      .replaceAll('&quot;', '"')
      .replaceAll('&apos;', "'")
      .replaceAll('&amp;', '&');

  /// Loads the stored .docx of a received exam (throws for PDF / missing).
  Future<Uint8List> loadStoredDocx(ExamRecord r) async {
    final snap = await _files.doc(ExamRecord.idFor(r.subject, r.form)).get();
    final d = snap.data();
    if (d == null || d['dataBase64'] == null) {
      throw Exception('The file was not found.');
    }
    final name = ((d['fileName'] as String?) ?? '').toLowerCase();
    if (!name.endsWith('.docx')) {
      throw Exception('Only Word (.docx) files can be edited inside the app.');
    }
    return base64Decode(d['dataBase64'] as String);
  }

  static Map<String, List<int>> _unzip(Uint8List docx) {
    final files = <String, List<int>>{};
    try {
      for (final f in zip.ZipDecoder().decodeBytes(docx).files) {
        if (f.isFile) files[f.name] = List<int>.from(f.content as List<int>);
      }
    } catch (_) {
      throw Exception('This is not a valid .docx file.');
    }
    if (!files.containsKey('word/document.xml')) {
      throw Exception('This is not a valid .docx file (document.xml missing).');
    }
    return files;
  }

  static bool _flag(String rPr, String tag) {
    final m = RegExp('<w:$tag\\b([^>]*)/>').firstMatch(rPr);
    if (m == null) return false;
    final v = RegExp(r'w:val="([^"]*)"').firstMatch(m[1]!)?.group(1);
    return v == null || !const ['0', 'false', 'off', 'none'].contains(v);
  }

  static DocxFmt _fmtOf(String rPr) {
    if (rPr.isEmpty) return const DocxFmt();
    final font = RegExp(r'<w:rFonts\b[^>]*?w:(?:ascii|hAnsi|cs)="([^"]*)"')
        .firstMatch(rPr)
        ?.group(1);
    final sz = RegExp(r'<w:sz\b[^>]*w:val="(\d+)"').firstMatch(rPr)?.group(1);
    final col = RegExp(r'<w:color\b[^>]*w:val="([0-9A-Fa-f]{6})"')
        .firstMatch(rPr)
        ?.group(1);
    return DocxFmt(
      b: _flag(rPr, 'b'),
      i: _flag(rPr, 'i'),
      u: _flag(rPr, 'u'),
      s: _flag(rPr, 'strike'),
      size: sz == null ? null : int.parse(sz) / 2,
      font: font,
      color: col == null ? null : int.parse(col, radix: 16),
    );
  }

  static List<DocxPara> _parseParas(String xml) {
    final cells = [
      for (final c in RegExp(r'<w:tc>.*?</w:tc>', dotAll: true).allMatches(xml))
        (c.start, c.end)
    ];
    final out = <DocxPara>[];
    var k = 0;
    for (final m in _paraRe.allMatches(xml)) {
      final whole = m[0]!, inner = m[1]!;
      final open = whole.substring(0, whole.indexOf('>') + 1);
      final pPr = RegExp(r'<w:pPr>.*?</w:pPr>', dotAll: true)
          .firstMatch(inner)
          ?.group(0) ??
          '';
      final body = pPr.isEmpty ? inner : inner.replaceFirst(pPr, '');
      final locked = _lockRe.hasMatch(body);
      final text = StringBuffer();
      final fmts = <DocxFmt>[];
      if (locked) {
        for (final t in _textRe.allMatches(body)) {
          text.write(_unxml(t[1]!));
        }
        fmts.addAll(List<DocxFmt>.filled(text.length, const DocxFmt()));
      } else {
        for (final r in _runRe.allMatches(body)) {
          final run = r[1]!;
          final f = _fmtOf(RegExp(r'<w:rPr>.*?</w:rPr>', dotAll: true)
              .firstMatch(run)
              ?.group(0) ??
              '');
          for (final part in _runPartRe.allMatches(run)) {
            final t = part[1] == null ? '\t' : _unxml(part[1]!);
            text.write(t);
            fmts.addAll(List<DocxFmt>.filled(t.length, f));
          }
        }
      }
      final jc = RegExp(r'<w:jc\b[^>]*w:val="(\w+)"').firstMatch(pPr)?.group(1);
      final align = switch (jc) {
        'center' => DocxAlign.center,
        'right' || 'end' => DocxAlign.end,
        'both' || 'distribute' || 'thaiDistribute' => DocxAlign.justify,
        _ => DocxAlign.start,
      };
      final bm = RegExp(r'<w:bidi\b([^>]*)/>').firstMatch(pPr);
      final rtl = bm != null && !RegExp(r'w:val="(0|false|off)"').hasMatch(bm[1]!);
      var note = '';
      if (locked && text.isEmpty) {
        note = RegExp(r'<w:(drawing|pict|object)\b').hasMatch(body)
            ? '[picture]'
            : '';
      }
      out.add(DocxPara(
        orig: k++,
        text: text.toString(),
        fmts: fmts,
        align: align,
        rtl: rtl,
        locked: locked,
        cell: cells.indexWhere((c) => m.start >= c.$1 && m.start < c.$2),
        note: note,
        pPr: pPr,
        open: open,
      ));
    }
    return out;
  }

  /// The paragraphs of a stored .docx (text + formatting), in order.
  static List<DocxPara> docxParagraphs(Uint8List docx) => _parseParas(
      utf8.decode(_unzip(docx)['word/document.xml']!, allowMalformed: true));

  static bool _sameContent(DocxPara a, DocxPara b) {
    if (a.text != b.text ||
        a.align != b.align ||
        a.fmts.length != b.fmts.length) {
      return false;
    }
    for (var i = 0; i < a.fmts.length; i++) {
      if (a.fmts[i] != b.fmts[i]) return false;
    }
    return true;
  }

  static bool docxParasSame(List<DocxPara> a, List<DocxPara> b) {
    if (a.length != b.length) return false;
    for (var i = 0; i < a.length; i++) {
      if (a[i].orig != b[i].orig || !_sameContent(a[i], b[i])) return false;
    }
    return true;
  }

  static String _setJc(String pPr, DocxAlign a) {
    final v = switch (a) {
      DocxAlign.start => 'left',
      DocxAlign.center => 'center',
      DocxAlign.end => 'right',
      DocxAlign.justify => 'both',
    };
    final jc = '<w:jc w:val="$v"/>';
    if (pPr.isEmpty) return '<w:pPr>$jc</w:pPr>';
    final x = pPr.replaceAll(RegExp(r'<w:jc\b[^>]*/>'), '');
    final at = RegExp(
        r'<w:(textDirection|textAlignment|textboxTightWrap|outlineLvl|divId|cnfStyle|rPr|sectPr|pPrChange)\b')
        .firstMatch(x);
    if (at != null) return x.replaceRange(at.start, at.start, jc);
    return x.replaceFirst('</w:pPr>', '$jc</w:pPr>');
  }

  static String _rPrXml(DocxFmt f, bool rtl) {
    final b = StringBuffer();
    if (f.font != null) {
      final n = _xml(f.font!);
      b.write('<w:rFonts w:ascii="$n" w:hAnsi="$n" w:eastAsia="$n" w:cs="$n"/>');
    }
    if (f.b) b.write('<w:b/><w:bCs/>');
    if (f.i) b.write('<w:i/><w:iCs/>');
    if (f.s) b.write('<w:strike/>');
    if (f.color != null) {
      b.write(
          '<w:color w:val="${f.color!.toRadixString(16).padLeft(6, '0').toUpperCase()}"/>');
    }
    if (f.size != null) {
      final h = (f.size! * 2).round();
      b.write('<w:sz w:val="$h"/><w:szCs w:val="$h"/>');
    }
    if (f.u) b.write('<w:u w:val="single"/>');
    if (rtl) b.write('<w:rtl/>');
    final s = b.toString();
    return s.isEmpty ? '' : '<w:rPr>$s</w:rPr>';
  }

  static String _runsXml(String text, List<DocxFmt> fm) {
    if (text.isEmpty) return '';
    final fmts =
    fm.length == text.length ? fm : List<DocxFmt>.filled(text.length, const DocxFmt());
    final arabic = RegExp(r'[\u0600-\u06FF]');
    final out = StringBuffer();
    var s = 0;
    for (var k = 1; k <= text.length; k++) {
      if (k == text.length || fmts[k] != fmts[s]) {
        final seg = text.substring(s, k);
        out.write('<w:r>${_rPrXml(fmts[s], arabic.hasMatch(seg))}');
        final parts = seg.split('\t');
        for (var q = 0; q < parts.length; q++) {
          if (q > 0) out.write('<w:tab/>');
          if (parts[q].isNotEmpty) {
            out.write('<w:t xml:space="preserve">${_xml(parts[q])}</w:t>');
          }
        }
        out.write('</w:r>');
        s = k;
      }
    }
    return out.toString();
  }

  static String _newParaXml(DocxPara n, DocxPara anchor) {
    final pPr = _setJc(
        anchor.pPr
            .replaceAll(RegExp(r'<w:sectPr\b.*?</w:sectPr>', dotAll: true), ''),
        n.align);
    return '<w:p>$pPr${_runsXml(n.text, n.fmts)}</w:p>';
  }

  /// Writes the edited paragraphs back into the .docx. Paragraphs that were
  /// not touched are kept byte-for-byte; edited ones are rebuilt from the
  /// text, character formatting and alignment; new ones are inserted.
  static Uint8List applyDocxParas(Uint8List docx, List<DocxPara> edited) {
    final files = _unzip(docx);
    final xml0 = utf8.decode(files['word/document.xml']!, allowMalformed: true);
    final origs = _parseParas(xml0);
    if (origs.isEmpty) return docx;

    final byOrig = <int, DocxPara>{};
    final after = <int, List<DocxPara>>{};
    var anchor = -1;
    for (final p in edited) {
      if (p.orig >= 0) {
        byOrig[p.orig] = p;
        anchor = p.orig;
      } else {
        after.putIfAbsent(anchor, () => []).add(p);
      }
    }

    var idx = -1;
    final xml = xml0.replaceAllMapped(_paraRe, (m) {
      idx++;
      final o = origs[idx];
      final buf = StringBuffer();
      if (idx == 0) {
        for (final n in after[-1] ?? const <DocxPara>[]) {
          buf.write(_newParaXml(n, o));
        }
      }
      final e = byOrig[idx];
      if (e == null) {
        if (o.locked) buf.write(m[0]!); // removed in the editor: drop it
      } else if (o.locked || _sameContent(o, e)) {
        buf.write(m[0]!);
      } else {
        final pPr = e.align != o.align ? _setJc(o.pPr, e.align) : o.pPr;
        buf.write('${o.open}$pPr${_runsXml(e.text, e.fmts)}</w:p>');
      }
      for (final n in after[idx] ?? const <DocxPara>[]) {
        buf.write(_newParaXml(n, o));
      }
      return buf.toString();
    });

    files['word/document.xml'] = utf8.encode(xml);
    final out = zip.Archive();
    files.forEach(
            (name, data) => out.addFile(zip.ArchiveFile(name, data.length, data)));
    return Uint8List.fromList(zip.ZipEncoder().encode(out)!);
  }

  // ---------------- Auto-format: titles / questions bold, options regular ----------------
  static final _optLowerRe = RegExp(r'^\(?\s*[a-h]\s*[\)\.]');
  static final _optUpperRe = RegExp(r'^\(?\s*[A-H]\s*\)');
  static final _optArabicRe = RegExp(r'^\(?\s*[أبجد]\s*[\)\.\-]');
  static final _questionRe = RegExp(
      r'^\(?\s*(?:\d{1,3}|[٠-٩]{1,3})\s*[\)\.\-–:](?!\d)|^(?:q|question|su.?aal|سؤال|السؤال)\s*\(?\d',
      caseSensitive: false);
  static final _sectionRe = RegExp(
      r'^(?:section|part|chapter|unit|exercise|questions?|qaybta|qeybta|su.?aalaha|القسم|الجزء|الأسئلة|السؤال)\b',
      caseSensitive: false);
  static final _upperLetterDotRe = RegExp(r'^[A-H]\s*\.');

  /// Decides what a line of an exam is: a title, a numbered question, an
  /// a/b/c/d option, or something else (left untouched).
  static LineKind classifyLine(String raw, {bool centered = false}) {
    final t = raw.trim();
    if (t.isEmpty) return LineKind.other;
    if (_questionRe.hasMatch(t)) return LineKind.question;
    if (_optLowerRe.hasMatch(t) ||
        _optUpperRe.hasMatch(t) ||
        _optArabicRe.hasMatch(t)) {
      return LineKind.option;
    }
    if (_sectionRe.hasMatch(t) || _upperLetterDotRe.hasMatch(t)) {
      return LineKind.title;
    }
    if (centered && t.length <= 100) return LineKind.title;
    final letters = t.replaceAll(RegExp(r'[^A-Za-z]'), '');
    if (letters.length >= 3 && t == t.toUpperCase() && t.length <= 90) {
      return LineKind.title;
    }
    if ((t.endsWith(':') || t.endsWith('：')) && t.length <= 110) {
      return LineKind.title;
    }
    return LineKind.other;
  }

  /// "numId:level" -> number format (decimal, lowerLetter...) from numbering.xml.
  static Map<String, String> _numFormats(String? numbering) {
    final out = <String, String>{};
    if (numbering == null) return out;
    final abstracts = <String, Map<String, String>>{};
    for (final a in RegExp(
        r'<w:abstractNum\b[^>]*w:abstractNumId="(\d+)"[^>]*>(.*?)</w:abstractNum>',
        dotAll: true)
        .allMatches(numbering)) {
      final lv = <String, String>{};
      for (final l in RegExp(r'<w:lvl\b[^>]*w:ilvl="(\d+)"[^>]*>(.*?)</w:lvl>',
          dotAll: true)
          .allMatches(a[2]!)) {
        final f = RegExp(r'<w:numFmt\b[^>]*w:val="(\w+)"').firstMatch(l[2]!)?.group(1);
        if (f != null) lv[l[1]!] = f;
      }
      abstracts[a[1]!] = lv;
    }
    for (final n in RegExp(
        r'<w:num\b[^>]*w:numId="(\d+)"[^>]*>(.*?)</w:num>',
        dotAll: true)
        .allMatches(numbering)) {
      final aid = RegExp(r'<w:abstractNumId\b[^>]*w:val="(\d+)"')
          .firstMatch(n[2]!)
          ?.group(1);
      final lv = aid == null ? null : abstracts[aid];
      if (lv == null) continue;
      lv.forEach((lvl, f) => out['${n[1]}:$lvl'] = f);
    }
    return out;
  }

  static String _boldRun(String run, bool on) {
    final b = on ? '<w:b/><w:bCs/>' : '<w:b w:val="0"/><w:bCs w:val="0"/>';
    final rp = RegExp(r'<w:rPr>(.*?)</w:rPr>', dotAll: true).firstMatch(run);
    if (rp == null) {
      return run.replaceFirstMapped(
          RegExp(r'^<w:r(?:\s[^>]*)?>'), (m) => '${m[0]}<w:rPr>$b</w:rPr>');
    }
    var inner = rp[1]!.replaceAll(RegExp(r'<w:b(?:Cs)?\b[^>]*/>'), '');
    final at = RegExp(r'^(?:<w:rStyle\b[^>]*/>)?(?:<w:rFonts\b[^>]*/>)?')
        .firstMatch(inner)!
        .end;
    inner = inner.replaceRange(at, at, b);
    return run.replaceRange(rp.start, rp.end, '<w:rPr>$inner</w:rPr>');
  }

  static final _numPrefixRe = RegExp(
      r'^\s*(?:(?:q|question|su.?aal|سؤال|السؤال)\s*\(?\d{1,3}\s*[\)\.\-–:]?|\(?(?:\d{1,3}|[٠-٩]{1,3})\s*[\)\.\-–:](?!\d))\s*',
      caseSensitive: false);
  static final _blankRe = RegExp(r'_{3,}|\.{4,}|…{2,}');
  static final _wordRe = RegExp(r'[A-Za-z\u0600-\u06FF]{3,}');

  /// Length of an existing question number at the start of [text] ("2)", "3-").
  static int numPrefixEnd(String text) => _numPrefixRe.firstMatch(text)?.end ?? 0;

  /// Works out, for a list of exam lines, what each one is and which question
  /// number it gets (numbering restarts after every title / part).
  /// [wordKinds] = what Word's own automatic numbering says (or other).
  static ({List<LineKind> kinds, List<int> numbers}) planLines(
      List<String> texts, List<bool> centered, List<LineKind> wordKinds) {
    final n = texts.length;
    final kinds = List<LineKind>.filled(n, LineKind.other);
    final wordNumbered = List<bool>.filled(n, false);
    for (var i = 0; i < n; i++) {
      var k = classifyLine(texts[i], centered: centered[i]);
      if (k == LineKind.other && wordKinds[i] != LineKind.other) {
        k = wordKinds[i];
        wordNumbered[i] = k == LineKind.question;
      }
      kinds[i] = k;
    }
    // questions without a number: end with "?", are followed by options,
    // or are a sentence with a blank to fill in
    for (var i = 0; i < n; i++) {
      if (kinds[i] != LineKind.other) continue;
      final t = texts[i].trim();
      if (!_wordRe.hasMatch(t)) continue;
      var q = t.endsWith('?') || t.endsWith('؟');
      if (!q) {
        for (var j = i + 1; j < n; j++) {
          if (texts[j].trim().isEmpty) continue;
          q = kinds[j] == LineKind.option;
          break;
        }
      }
      if (!q && _blankRe.hasMatch(t)) q = true;
      if (q) kinds[i] = LineKind.question;
    }
    final numbers = List<int>.filled(n, 0);
    var c = 0;
    for (var i = 0; i < n; i++) {
      if (kinds[i] == LineKind.title) {
        c = 0;
      } else if (kinds[i] == LineKind.question && !wordNumbered[i]) {
        numbers[i] = ++c;
      }
    }
    return (kinds: kinds, numbers: numbers);
  }

  /// Writes "N. " at the start of a paragraph (replacing an old "2)" number).
  static String _numberPara(String whole, int number) {
    final text = _textRe.allMatches(whole).map((t) => _unxml(t[1]!)).join();
    var strip = numPrefixEnd(text);
    var first = true;
    return whole.replaceAllMapped(_textRe, (t) {
      var s = _unxml(t[1]!);
      if (strip > 0) {
        final k = strip < s.length ? strip : s.length;
        s = s.substring(k);
        strip -= k;
      }
      if (first) {
        first = false;
        s = '$number. $s';
      }
      return '<w:t xml:space="preserve">${_xml(s)}</w:t>';
    });
  }

  static LineKind _wordKind(String pPr, Map<String, String> nums) {
    final nid = RegExp(r'<w:numId\b[^>]*w:val="(\d+)"').firstMatch(pPr)?.group(1);
    if (nid == null) return LineKind.other;
    final lvl =
        RegExp(r'<w:ilvl\b[^>]*w:val="(\d+)"').firstMatch(pPr)?.group(1) ?? '0';
    final f = nums['$nid:$lvl'] ?? '';
    if (f.startsWith('decimal')) return LineKind.question;
    if (f.contains('Letter') || f == 'arabicAbjad' || f == 'arabicAlpha') {
      return LineKind.option;
    }
    return LineKind.other;
  }

  /// Titles and questions -> bold. a), b), c), d) options -> regular.
  /// Questions get "1.", "2." numbers (restarting in every part).
  /// Other paragraphs (answer lines, passages...) stay as they are.
  static String _autoFormatDoc(String xml, String? numbering,
      {bool number = true}) {
    final nums = _numFormats(numbering);
    final texts = <String>[];
    final centered = <bool>[];
    final wordKinds = <LineKind>[];
    for (final m in _paraRe.allMatches(xml)) {
      final inner = m[1]!;
      texts.add(_textRe.allMatches(inner).map((t) => _unxml(t[1]!)).join());
      final pPr = RegExp(r'<w:pPr>.*?</w:pPr>', dotAll: true)
          .firstMatch(inner)
          ?.group(0) ??
          '';
      centered.add(RegExp(r'<w:jc\b[^>]*w:val="center"').hasMatch(pPr));
      wordKinds.add(_wordKind(pPr, nums));
    }
    final plan = planLines(texts, centered, wordKinds);
    var i = -1;
    return xml.replaceAllMapped(_paraRe, (m) {
      i++;
      final k = plan.kinds[i];
      if (k == LineKind.other) return m[0]!;
      var whole = m[0]!.replaceAllMapped(
          _runRe, (r) => _boldRun(r[0]!, k != LineKind.option));
      if (number && plan.numbers[i] > 0) {
        whole = _numberPara(whole, plan.numbers[i]);
      }
      return whole;
    });
  }

  /// Saves an edited .docx over the stored one (status stays Received).
  Future<void> saveEditedDocx(ExamRecord r, Uint8List edited) async {
    if (edited.length > maxFileBytes) {
      throw Exception(
          'File is too large (${(edited.length / 1024).round()} KB). The limit is 700 KB.');
    }
    await _files.doc(ExamRecord.idFor(r.subject, r.form)).set({
      'dataBase64': base64Encode(edited),
      'size': edited.length,
      'updatedBy': FirebaseAuth.instance.currentUser?.uid,
      'updatedAt': FieldValue.serverTimestamp(),
    }, SetOptions(merge: true)).timeout(const Duration(seconds: 40),
        onTimeout: () {
          throw Exception('Saving timed out. Check the internet connection.');
        });
  }

  /// Downloads the stored file to the user's device.
  Future<void> openFile(ExamRecord r) async {
    final snap = await _files.doc(ExamRecord.idFor(r.subject, r.form)).get();
    final d = snap.data();
    if (d == null || d['dataBase64'] == null) {
      throw Exception('The file was not found.');
    }
    // Name: form-subject-month-year, e.g. Form2-English-October-2026.docx
    final stored = (d['fileName'] as String?) ?? 'exam.docx';
    final dot = stored.lastIndexOf('.');
    final ext = dot >= 0 ? stored.substring(dot) : '';
    String clean(String v) =>
        v.trim().replaceAll(RegExp(r'[\\/:*?"<>|]'), '').replaceAll(RegExp(r'\s+'), '_');
    final monthYear = DateFormat('MMMM-yyyy').format(DateTime.now());
    final downloadName = '${clean(r.form)}-${clean(r.subject)}-$monthYear$ext';
    _downloadInBrowser(
      base64Decode(d['dataBase64'] as String),
      downloadName,
      (d['contentType'] as String?) ?? 'application/octet-stream',
    );
  }

  /// Downloads EVERY uploaded exam as one ZIP:
  /// <year>/<Subject>/<Form>-<Subject>-<Month>-<Year>.<ext>
  /// Returns how many files were put in the ZIP.
  Future<int> downloadAll() async {
    String clean(String v) => v
        .trim()
        .replaceAll(RegExp(r'[\\/:*?"<>|]'), '')
        .replaceAll(RegExp(r'\s+'), '_');
    final now = DateTime.now();
    final year = '${now.year}';
    final monthYear = DateFormat('MMMM-yyyy').format(now);

    final exams = await _col.get();
    final received = exams.docs
        .map((d) => ExamRecord.fromMap(d.data()))
        .where((r) =>
    r.received &&
        r.hasFile &&
        teacherScope.value.allows(r.subject, r.form))
        .toList();
    if (received.isEmpty) {
      throw Exception('There are no uploaded exams to download yet.');
    }

    final archive = zip.Archive();
    var count = 0;
    final docs = await Future.wait(
        received.map((r) => _files.doc(ExamRecord.idFor(r.subject, r.form)).get()));
    for (var i = 0; i < received.length; i++) {
      final r = received[i];
      final d = docs[i].data();
      if (d == null || d['dataBase64'] == null) continue;
      final stored = (d['fileName'] as String?) ?? 'exam.docx';
      final dot = stored.lastIndexOf('.');
      final ext = dot >= 0 ? stored.substring(dot) : '';
      final bytes = base64Decode(d['dataBase64'] as String);
      final path = '$year/${clean(r.subject)}/'
          '${clean(r.form)}-${clean(r.subject)}-$monthYear$ext';
      archive.addFile(zip.ArchiveFile(path, bytes.length, bytes));
      count++;
    }
    if (count == 0) throw Exception('The uploaded files could not be read.');
    final out = zip.ZipEncoder().encode(archive);
    if (out == null) throw Exception('Could not create the ZIP file.');
    _downloadInBrowser(Uint8List.fromList(out), '$year.zip', 'application/zip');
    return count;
  }

  // ---------------- Re-upload ALL exams from a ZIP ----------------

  static String _cleanName(String v) => v
      .trim()
      .replaceAll(RegExp(r'[\\/:*?"<>|]'), '')
      .replaceAll(RegExp(r'\s+'), '_');

  /// Reads a ZIP made by "Download all" and works out which exam
  /// (subject + form) every file belongs to. Nothing is saved yet.
  /// Files are matched by their name: <Form>-<Subject>-<Month>-<Year>.<ext>
  /// (the subject folder is used as a backup).
  ZipImportPlan planZipImport(Uint8List zipBytes) {
    final archive = () {
      try {
        return zip.ZipDecoder().decodeBytes(zipBytes);
      } catch (_) {
        throw Exception('This is not a valid ZIP file.');
      }
    }();
    final scope = teacherScope.value;
    final items = <String, ZipImportItem>{};
    final skipped = <String>[];

    for (final f in archive.files) {
      if (!f.isFile) continue;
      final path = f.name.replaceAll('\\', '/');
      if (path.startsWith('__MACOSX/') || path.split('/').last.startsWith('.')) {
        continue;
      }
      final parts = path.split('/');
      final base = parts.last;
      final lower = base.toLowerCase();
      final dot = base.lastIndexOf('.');
      final ext = dot >= 0 ? lower.substring(dot + 1) : '';
      if (ext != 'docx' && ext != 'pdf') {
        skipped.add('$base (only .docx and .pdf are accepted)');
        continue;
      }

      String? form, subject;
      for (final fo in forms) {
        for (final su in subjects) {
          if (lower.startsWith('${_cleanName(fo)}-${_cleanName(su)}-'.toLowerCase())) {
            form = fo;
            subject = su;
          }
        }
      }
      if (form == null && parts.length >= 2) {
        // backup: subject from the folder, form from the start of the name
        final folder = parts[parts.length - 2].toLowerCase();
        for (final su in subjects) {
          if (_cleanName(su).toLowerCase() == folder) subject = su;
        }
        for (final fo in forms) {
          if (lower.startsWith(_cleanName(fo).toLowerCase())) form = fo;
        }
      }
      if (form == null || subject == null) {
        skipped.add('$base (could not tell which subject / form it is)');
        continue;
      }
      if (!scope.allowsSubject(subject) || !scope.allowsForm(form)) {
        skipped.add('$base (you do not have access to $subject $form)');
        continue;
      }
      final bytes = Uint8List.fromList(List<int>.from(f.content as List<int>));
      if (bytes.length > maxFileBytes) {
        skipped.add('$base (too large: ${(bytes.length / 1024).round()} KB, limit is 700 KB)');
        continue;
      }
      final id = ExamRecord.idFor(subject, form);
      if (items.containsKey(id)) {
        skipped.add('${items[id]!.fileName} (duplicate of $base for $subject $form)');
      }
      items[id] = ZipImportItem(
        subject: subject,
        form: form,
        fileName: base,
        contentType: ext == 'docx' ? _docxMime : 'application/pdf',
        bytes: bytes,
      );
    }
    final list = items.values.toList()
      ..sort((a, b) {
        final c = subjects.indexOf(a.subject).compareTo(subjects.indexOf(b.subject));
        return c != 0 ? c : forms.indexOf(a.form).compareTo(forms.indexOf(b.form));
      });
    return ZipImportPlan(items: list, skipped: skipped);
  }

  /// Saves every file of the plan over the stored exams (they were already
  /// stamped with the letterhead when first uploaded, so they are stored as-is)
  /// and marks each cell Received. Returns how many saved and which failed.
  Future<({int saved, List<String> failed})> applyZipImport(
      ZipImportPlan plan, {
        void Function(int done, int total)? onProgress,
      }) async {
    var saved = 0;
    final failed = <String>[];
    final uid = FirebaseAuth.instance.currentUser?.uid;
    final total = plan.items.length;
    for (final it in plan.items) {
      try {
        final id = ExamRecord.idFor(it.subject, it.form);
        await _files.doc(id).set({
          'fileName': it.fileName,
          'contentType': it.contentType,
          'dataBase64': base64Encode(it.bytes),
          'size': it.bytes.length,
          'updatedBy': uid,
          'updatedAt': FieldValue.serverTimestamp(),
        }).timeout(const Duration(seconds: 40));
        await _col.doc(id).set({
          'subject': it.subject,
          'form': it.form,
          'status': 'received',
          'receivedAt': FieldValue.serverTimestamp(),
          'hasFile': true,
          'fileName': it.fileName,
          'updatedBy': uid,
          'updatedAt': FieldValue.serverTimestamp(),
        }, SetOptions(merge: true));
        saved++;
      } catch (e) {
        failed.add('${it.subject} ${it.form}');
      }
      onProgress?.call(saved + failed.length, total);
    }
    return (saved: saved, failed: failed);
  }

  /// Deletes the uploaded file and sets the cell back to Pending.
  Future<void> markPending(ExamRecord r) async {
    try {
      await _files.doc(ExamRecord.idFor(r.subject, r.form)).delete();
    } catch (_) {}
    await _col.doc(ExamRecord.idFor(r.subject, r.form)).set({
      'status': 'pending',
      'receivedAt': FieldValue.delete(),
      'hasFile': FieldValue.delete(),
      'fileName': FieldValue.delete(),
    }, SetOptions(merge: true));
  }
}

/// Opened by every Pending / Received button.
/// Contains: header manager, footer manager and the file upload.
class UploadDialog extends StatefulWidget {
  final ExamRecord record;
  final ExamService service;
  const UploadDialog({super.key, required this.record, required this.service});

  @override
  State<UploadDialog> createState() => _UploadDialogState();
}

class _UploadDialogState extends State<UploadDialog> {
  late final _footer = TextEditingController(
      text: widget.record.footer.replaceAll('Teacher: ', '').replaceAll('Teacher:', ''));
  late final _teacher = TextEditingController(text: widget.record.teacherName);

  /// Footer is generated automatically from subject, form and teacher name.
  String _buildFooter(String teacher) {
    final t = teacher.trim();
    if (t.isEmpty) return '';
    return '${widget.record.subject} | ${widget.record.form} | $t';
  }
  late final _marks = TextEditingController(text: widget.record.marks);
  late final _time = TextEditingController(text: widget.record.allowedTime);
  // The starting ticks come from Settings > Exam upload.
  bool _addHeading = appSettings.value.uploadHeading;
  bool _autoFormat = appSettings.value.uploadAutoFormat;
  bool _numberQuestions = appSettings.value.uploadNumber;
  static const _docxMimeType = ExamService._docxMime;
  ExamHeading? _heading; // general heading, loaded from Firestore

  @override
  void initState() {
    super.initState();
    widget.service.getHeading().then((h) {
      if (mounted) setState(() => _heading = h);
    }).catchError((_) {});
  }

  PlatformFile? _file;
  double? _progress;
  String? _status;
  bool _busy = false;

  @override
  void dispose() {
    _footer.dispose();
    _teacher.dispose();
    _marks.dispose();
    _time.dispose();
    super.dispose();
  }

  Future<void> _pick() async {
    final res = await FilePicker.platform.pickFiles(
      withData: true, // needed so bytes are available on every platform
      type: FileType.custom,
      allowedExtensions: ['docx', 'pdf', 'png', 'jpg', 'jpeg'],
    );
    if (res != null && res.files.isNotEmpty) {
      final f = res.files.first;
      final ext = (f.extension ?? '').toLowerCase();
      if (!const ['docx', 'pdf', 'png', 'jpg', 'jpeg'].contains(ext)) {
        // The Windows file dialog lets users switch to "All files".
        ScaffoldMessenger.of(context).showSnackBar(SnackBar(
          duration: const Duration(seconds: 6),
          content: Text(
              '"${f.name}" cannot be used. Use a Word (.docx) file. For .doc or .odt '
                  'files, open them in Word and use Save As → Word Document (.docx).'),
        ));
        return;
      }
      setState(() => _file = f);
    }
  }

  /// Asks for confirmation, then deletes the uploaded file (cell goes back to Pending).
  Future<void> _confirmDelete() async {
    final ok = await showDialog<bool>(
      context: context,
      builder: (ctx) => AlertDialog(
        title: const Text('Delete file?'),
        content: Text(
            'Delete "${widget.record.fileName ?? 'the uploaded file'}"? '
                'This cannot be undone and the exam will be marked as Pending.'),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(ctx, false),
            child: const Text('Cancel'),
          ),
          FilledButton(
            onPressed: () => Navigator.pop(ctx, true),
            child: const Text('Delete'),
          ),
        ],
      ),
    );
    if (ok != true || !mounted) return;
    await _run(() => widget.service.markPending(widget.record), 'File deleted');
  }

  /// Shows the finished document without saving anything.
  Future<void> _preview() async {
    setState(() {
      _busy = true;
      _status = 'Building preview...';
    });
    final messenger = ScaffoldMessenger.of(context);
    try {
      final p = await widget.service.buildPreview(
        current: widget.record,
        file: _file,
        footer: _footer.text.trim(),
        marks: _marks.text.trim(),
        allowedTime: _time.text.trim(),
        addHeading: _addHeading,
        autoFormat: _autoFormat,
        numberQuestions: _numberQuestions,
      );
      if (!mounted) return;
      if (p.isDocx) {
        // Word files cannot be drawn inside the app: download a copy to check.
        _downloadInBrowser(p.bytes, p.name, _docxMimeType);
        messenger.showSnackBar(const SnackBar(
          duration: Duration(seconds: 6),
          content: Text('Preview downloaded. Open it in Word to check, '
              'then press Upload if it is correct.'),
        ));
      } else {
        await showDialog(
          context: context,
          builder: (_) => PreviewDialog(bytes: p.bytes),
        );
      }
    } catch (e) {
      messenger.showSnackBar(SnackBar(content: Text('Preview failed: $e')));
    } finally {
      if (mounted) {
        setState(() {
          _busy = false;
          _status = null;
        });
      }
    }
  }

  Future<void> _run(Future<void> Function() action, String okMsg) async {
    setState(() => _busy = true);
    final messenger = ScaffoldMessenger.of(context);
    final nav = Navigator.of(context);
    try {
      await action();
      nav.pop();
      messenger.showSnackBar(SnackBar(content: Text(okMsg)));
    } catch (e) {
      if (mounted) setState(() => _busy = false);
      messenger.showSnackBar(SnackBar(content: Text('Failed: $e')));
    }
  }

  @override
  Widget build(BuildContext context) {
    final r = widget.record;
    final preview = _heading?.build(r.subject, r.form,
        marks: _marks.text, time: _time.text);
    return AlertDialog(
      title: Text('${r.subject} · ${r.form}'),
      content: SizedBox(
        width: 420,
        child: SingleChildScrollView(
          child: Column(mainAxisSize: MainAxisSize.min, children: [
            TextField(
              controller: _teacher,
              textCapitalization: TextCapitalization.words,
              onChanged: (v) => setState(() => _footer.text = _buildFooter(v)),
              decoration: const InputDecoration(
                labelText: "Teacher's name",
                prefixIcon: Icon(Icons.person),
                border: OutlineInputBorder(),
              ),
            ),
            const SizedBox(height: 12),
            TextField(
              controller: _footer,
              readOnly: true,
              maxLines: 2,
              decoration: const InputDecoration(
                labelText: 'Footer (auto-generated)',
                helperText: 'Built from subject, form and teacher name',
                filled: true,
                border: OutlineInputBorder(),
              ),
            ),
            const SizedBox(height: 12),
            Row(children: [
              Expanded(
                child: TextField(
                  controller: _marks,
                  onChanged: (_) => setState(() {}),
                  decoration: InputDecoration(
                    labelText: 'Marks',
                    hintText: _heading?.marks,
                    border: const OutlineInputBorder(),
                  ),
                ),
              ),
              const SizedBox(width: 12),
              Expanded(
                flex: 2,
                child: TextField(
                  controller: _time,
                  onChanged: (_) => setState(() {}),
                  decoration: InputDecoration(
                    labelText: 'Allowed time',
                    hintText: _heading?.defaultTimeFor(r.subject),
                    border: const OutlineInputBorder(),
                  ),
                ),
              ),
            ]),
            const Padding(
              padding: EdgeInsets.only(top: 4),
              child: Align(
                alignment: Alignment.centerLeft,
                child: Text(
                  'Leave Marks / Allowed time empty to use the general values.',
                  style: TextStyle(fontSize: 11, color: Colors.black54),
                ),
              ),
            ),
            CheckboxListTile(
              dense: true,
              contentPadding: EdgeInsets.zero,
              controlAffinity: ListTileControlAffinity.leading,
              value: _addHeading,
              onChanged: _busy
                  ? null
                  : (v) => setState(() => _addHeading = v ?? true),
              title: const Text('Add exam heading table on the first page'),
            ),
            CheckboxListTile(
              dense: true,
              contentPadding: EdgeInsets.zero,
              controlAffinity: ListTileControlAffinity.leading,
              value: _autoFormat,
              onChanged: _busy
                  ? null
                  : (v) => setState(() => _autoFormat = v ?? true),
              title: const Text('Titles and questions bold, options (a, b, c, d) regular'),
            ),
            CheckboxListTile(
              dense: true,
              contentPadding: EdgeInsets.zero,
              controlAffinity: ListTileControlAffinity.leading,
              value: _numberQuestions,
              onChanged: (_busy || !_autoFormat)
                  ? null
                  : (v) => setState(() => _numberQuestions = v ?? true),
              title: const Text('Number the questions 1. 2. 3. in each part'),
            ),
            if (_addHeading && preview != null) _headingPreview(preview),
            const SizedBox(height: 16),
            if (r.received && r.fileName != null)
              ListTile(
                dense: true,
                contentPadding: EdgeInsets.zero,
                leading: const Icon(Icons.description),
                title: Text(r.fileName!, overflow: TextOverflow.ellipsis),
                subtitle: const Text('Currently uploaded'),
                trailing: Row(
                  mainAxisSize: MainAxisSize.min,
                  children: [
                    if (r.fileName?.toLowerCase().endsWith('.docx') == true)
                      IconButton(
                        icon: const Icon(Icons.edit),
                        tooltip: 'Open and edit document',
                        onPressed: _busy
                            ? null
                            : () => showDialog(
                          context: context,
                          barrierDismissible: false,
                          builder: (_) => DocxTextEditorDialog(
                              record: r, service: widget.service),
                        ),
                      ),
                    IconButton(
                      icon: const Icon(Icons.download),
                      tooltip: 'Download',
                      onPressed: _busy
                          ? null
                          : () async {
                        try {
                          await widget.service.openFile(r);
                        } catch (e) {
                          if (!mounted) return;
                          ScaffoldMessenger.of(context)
                              .showSnackBar(SnackBar(content: Text('$e')));
                        }
                      },
                    ),
                    IconButton(
                      icon: const Icon(Icons.delete_outline),
                      tooltip: 'Delete file',
                      color: Theme.of(context).colorScheme.error,
                      onPressed: _busy ? null : _confirmDelete,
                    ),
                  ],
                ),
              ),
            Row(
              mainAxisSize: MainAxisSize.min,
              children: [
                Flexible(
                  child: OutlinedButton.icon(
                    onPressed: _busy ? null : _pick,
                    icon: const Icon(Icons.attach_file),
                    label: Text(
                      _file?.name ??
                          (r.received ? 'Choose replacement file' : 'Choose file'),
                      overflow: TextOverflow.ellipsis,
                    ),
                  ),
                ),
                if (_file != null)
                  IconButton(
                    icon: const Icon(Icons.close),
                    tooltip: 'Remove selected file',
                    onPressed: _busy ? null : () => setState(() => _file = null),
                  ),
              ],
            ),
            const SizedBox(height: 6),
            const Text(
              'Word (.docx) recommended; PDF and images also work. The school '
                  'letterhead and the footer are added automatically to every page.',
              style: TextStyle(fontSize: 12, color: Colors.black54),
            ),
            if (_status != null) ...[
              const SizedBox(height: 10),
              Text(_status!, style: const TextStyle(fontSize: 12)),
            ],
            if (_busy) ...[
              const SizedBox(height: 6),
              LinearProgressIndicator(value: _progress),
            ],
          ]),
        ),
      ),
      actions: [
        if (r.received)
          TextButton(
            onPressed: _busy
                ? null
                : () => _run(() => widget.service.markPending(r),
                'Marked as pending'),
            child: const Text('Mark pending'),
          ),
        TextButton(
          onPressed: _busy ? null : () => Navigator.pop(context),
          child: const Text('Cancel'),
        ),
        TextButton(
          onPressed: _busy
              ? null
              : () => _run(
                () => widget.service.saveDetails(
                r.subject, r.form, _footer.text.trim(),
                _teacher.text.trim(),
                marks: _marks.text.trim(),
                allowedTime: _time.text.trim()),
            'Saved',
          ),
          child: const Text('Save details'),
        ),
        OutlinedButton.icon(
          onPressed: _busy ? null : _preview,
          icon: const Icon(Icons.visibility),
          label: const Text('Preview'),
        ),
        FilledButton.icon(
          onPressed: (_busy || _file == null)
              ? null
              : () => _run(
                () => widget.service.upload(
              current: r,
              file: _file!,
              footer: _footer.text.trim(),
              teacher: _teacher.text.trim(),
              marks: _marks.text.trim(),
              allowedTime: _time.text.trim(),
              addHeading: _addHeading,
              autoFormat: _autoFormat,
              numberQuestions: _numberQuestions,
              onProgress: (p) {
                if (mounted) setState(() => _progress = p);
              },
              onStatus: (t) {
                if (mounted) setState(() => _status = t);
              },
            ),
            'Uploaded — marked as Received',
          ),
          icon: const Icon(Icons.cloud_upload),
          label: const Text('Upload'),
        ),
      ],
    );
  }
}

enum LineKind { title, question, option, other }

enum DocxAlign { start, center, end, justify }

/// Character formatting of the Word editor.
class DocxFmt {
  final bool b, i, u, s;
  final double? size; // points
  final String? font;
  final int? color; // 0xRRGGBB
  const DocxFmt(
      {this.b = false,
        this.i = false,
        this.u = false,
        this.s = false,
        this.size,
        this.font,
        this.color});

  DocxFmt copyWith(
      {bool? b, bool? i, bool? u, bool? s, double? size, String? font, int? color}) =>
      DocxFmt(
        b: b ?? this.b,
        i: i ?? this.i,
        u: u ?? this.u,
        s: s ?? this.s,
        size: size ?? this.size,
        font: font ?? this.font,
        color: color ?? this.color,
      );

  @override
  bool operator ==(Object o) =>
      o is DocxFmt &&
          o.b == b &&
          o.i == i &&
          o.u == u &&
          o.s == s &&
          o.size == size &&
          o.font == font &&
          o.color == color;

  @override
  int get hashCode => Object.hash(b, i, u, s, size, font, color);
}

/// One paragraph of a Word file: text + per-character formatting.
class DocxPara {
  final int orig; // index in the stored file, -1 = new paragraph
  final String text;
  final List<DocxFmt> fmts; // one per UTF-16 unit of [text]
  final DocxAlign align;
  final bool rtl, locked;
  final int cell; // table cell number, -1 = not in a table
  final String note, pPr, open;
  const DocxPara({
    required this.orig,
    required this.text,
    required this.fmts,
    required this.align,
    required this.rtl,
    required this.locked,
    required this.cell,
    required this.note,
    required this.pPr,
    required this.open,
  });
}

/// A text controller that keeps a format for every character.
class _RichController extends TextEditingController {
  _RichController(String text, List<DocxFmt> f)
      : fmts = List<DocxFmt>.of(f),
        super(text: text);

  List<DocxFmt> fmts;
  DocxFmt? typing; // format chosen with the toolbar for the next typed text
  DocxFmt base = const DocxFmt(); // format of an empty paragraph

  static TextStyle styleOf(DocxFmt f) => TextStyle(
    fontWeight: f.b ? FontWeight.bold : FontWeight.normal,
    fontStyle: f.i ? FontStyle.italic : FontStyle.normal,
    decoration: TextDecoration.combine([
      if (f.u) TextDecoration.underline,
      if (f.s) TextDecoration.lineThrough,
    ]),
    fontSize: (f.size ?? 12) * 4 / 3,
    fontFamily: f.font ?? 'Times New Roman',
    fontFamilyFallback: const ['Liberation Serif', 'serif'],
    color: f.color != null ? Color(0xFF000000 | f.color!) : null,
  );

  /// Replaces the whole content (not treated as a user edit).
  void reset(String t, List<DocxFmt> f, {int? cursor}) {
    fmts = List<DocxFmt>.of(f);
    typing = null;
    final c = cursor == null ? t.length : (cursor > t.length ? t.length : cursor);
    super.value = TextEditingValue(
        text: t, selection: TextSelection.collapsed(offset: c));
  }

  @override
  set value(TextEditingValue v) {
    if (v.text != text) {
      _edit(v);
    } else if (v.selection != value.selection) {
      typing = null;
    }
    super.value = v;
  }

  void _edit(TextEditingValue v) {
    final old = text, nw = v.text;
    if (fmts.length != old.length) {
      fmts = List<DocxFmt>.filled(old.length, fmts.isEmpty ? base : fmts.first);
    }
    if (fmts.isNotEmpty) base = fmts.first;
    var s = 0;
    final lim = old.length < nw.length ? old.length : nw.length;
    while (s < lim && old.codeUnitAt(s) == nw.codeUnitAt(s)) {
      s++;
    }
    var oe = old.length, ne = nw.length;
    while (oe > s && ne > s && old.codeUnitAt(oe - 1) == nw.codeUnitAt(ne - 1)) {
      oe--;
      ne--;
    }
    if (oe == s && v.selection.isCollapsed) {
      // pure insertion: trust the cursor position
      final n = ne - s, st = v.selection.baseOffset - n;
      if (n > 0 &&
          st >= 0 &&
          st + n <= nw.length &&
          old == nw.substring(0, st) + nw.substring(st + n)) {
        s = st;
        ne = st + n;
        oe = st;
      }
    }
    final inherit = typing ?? (s > 0 ? fmts[s - 1] : (fmts.isNotEmpty ? fmts.first : base));
    fmts.replaceRange(s, oe, List<DocxFmt>.filled(ne - s, inherit));
  }

  /// Format at the cursor (or of the selection's first character).
  DocxFmt get current {
    if (typing != null) return typing!;
    if (fmts.isEmpty || fmts.length != text.length) return base;
    final sel = selection;
    if (!sel.isValid) return fmts.first;
    if (sel.isCollapsed) return sel.start > 0 ? fmts[sel.start - 1] : fmts.first;
    return fmts[sel.start];
  }

  bool allHave(bool Function(DocxFmt) test) {
    final sel = selection;
    if (!sel.isValid ||
        sel.isCollapsed ||
        fmts.length != text.length ||
        fmts.isEmpty) {
      return test(current);
    }
    for (var k = sel.start; k < sel.end; k++) {
      if (!test(fmts[k])) return false;
    }
    return true;
  }

  /// Puts "N. " at the start (replacing an old number like "2)").
  void setNumber(int n) {
    final k = ExamService.numPrefixEnd(text);
    final len = text.length;
    final src = fmts.length == len ? fmts : List<DocxFmt>.filled(len, base);
    final rest = src.sublist(k);
    final lead = rest.isNotEmpty ? rest.first : (src.isNotEmpty ? src.first : base);
    final prefix = '$n. ';
    reset(prefix + text.substring(k),
        [...List<DocxFmt>.filled(prefix.length, lead), ...rest]);
  }

  /// Makes the whole paragraph bold (or regular).
  void setAllBold(bool on) {
    if (fmts.length == text.length) {
      fmts = [for (final f in fmts) f.copyWith(b: on)];
    }
    base = base.copyWith(b: on);
    typing = null;
    notifyListeners();
  }

  /// Applies a format change to the selection (or to the next typed text).
  void apply(DocxFmt Function(DocxFmt) change) {
    final sel = selection;
    if (!sel.isValid ||
        sel.isCollapsed ||
        fmts.length != text.length ||
        fmts.isEmpty) {
      typing = change(current);
    } else {
      for (var k = sel.start; k < sel.end; k++) {
        fmts[k] = change(fmts[k]);
      }
    }
    notifyListeners();
  }

  @override
  TextSpan buildTextSpan(
      {required BuildContext context,
        TextStyle? style,
        required bool withComposing}) {
    if (text.isEmpty) {
      return TextSpan(
          style: style?.merge(styleOf(typing ?? base)) ?? styleOf(typing ?? base),
          text: '');
    }
    if (fmts.length != text.length) return TextSpan(style: style, text: text);
    final kids = <TextSpan>[];
    var s = 0;
    for (var k = 1; k <= text.length; k++) {
      if (k == text.length || fmts[k] != fmts[s]) {
        kids.add(TextSpan(text: text.substring(s, k), style: styleOf(fmts[s])));
        s = k;
      }
    }
    return TextSpan(style: style, children: kids);
  }
}

class _Row {
  final int orig;
  final bool locked, rtl;
  final int cell;
  final String note, pPr, open;
  DocxAlign align;
  final _RichController c;
  final FocusNode focus = FocusNode();
  bool splitQueued = false;

  _Row(DocxPara p)
      : orig = p.orig,
        locked = p.locked,
        rtl = p.rtl,
        cell = p.cell,
        note = p.note,
        pPr = p.pPr,
        open = p.open,
        align = p.align,
        c = _RichController(p.text, p.fmts);
}

/// Opens an uploaded Word file as an editable page inside the app, with a
/// Word-style Font / Paragraph toolbar (no download / re-upload).
class DocxTextEditorDialog extends StatefulWidget {
  final ExamRecord record;
  final ExamService service;
  const DocxTextEditorDialog(
      {super.key, required this.record, required this.service});

  @override
  State<DocxTextEditorDialog> createState() => _DocxTextEditorDialogState();
}

class _DocxTextEditorDialogState extends State<DocxTextEditorDialog> {
  static const _fonts = [
    'Times New Roman',
    'Arial',
    'Calibri',
    'Cambria',
    'Georgia',
    'Verdana',
    'Tahoma',
    'Courier New',
    'Traditional Arabic',
    'Simplified Arabic',
  ];
  static const _sizes = <double>[8, 9, 10, 11, 12, 14, 16, 18, 20, 24, 28, 36, 48];
  static const _colors = <String, int>{
    'Black': 0x000000,
    'Red': 0xC00000,
    'Orange': 0xED7D31,
    'Green': 0x00B050,
    'Blue': 0x0070C0,
    'Purple': 0x7030A0,
    'Grey': 0x7F7F7F,
  };

  final _tick = ValueNotifier<int>(0);
  List<_Row> _rows = [];
  List<DocxPara> _orig = const [];
  Uint8List? _docx;
  _Row? _active;
  bool _loading = true;
  bool _saving = false;
  String? _error;

  @override
  void initState() {
    super.initState();
    _load();
  }

  _Row _makeRow(DocxPara p) {
    final r = _Row(p);
    r.c.addListener(() => _onCtrl(r));
    r.focus.addListener(() {
      if (r.focus.hasFocus) {
        _active = r;
        _tick.value++;
      }
    });
    return r;
  }

  Future<void> _load() async {
    try {
      final bytes = await widget.service.loadStoredDocx(widget.record);
      final paras = ExamService.docxParagraphs(bytes);
      if (!mounted) return;
      setState(() {
        _docx = bytes;
        _orig = paras;
        _rows = [for (final p in paras) _makeRow(p)];
        _loading = false;
      });
    } catch (e) {
      if (mounted) {
        setState(() {
          _error = '$e'.replaceFirst('Exception: ', '');
          _loading = false;
        });
      }
    }
  }

  @override
  void dispose() {
    for (final r in _rows) {
      r.c.dispose();
      r.focus.dispose();
    }
    _tick.dispose();
    super.dispose();
  }

  // ---------- paragraphs: Enter splits, Backspace / Delete join ----------
  void _onCtrl(_Row r) {
    if (identical(_active, r)) _tick.value++;
    if (!r.splitQueued && r.c.text.contains('\n')) {
      r.splitQueued = true;
      WidgetsBinding.instance.addPostFrameCallback((_) => _split(r));
      WidgetsBinding.instance.scheduleFrame();
    }
  }

  void _focusAt(_Row r, int offset) {
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (!mounted || !_rows.contains(r)) return;
      r.focus.requestFocus();
      final o = offset > r.c.text.length ? r.c.text.length : offset;
      r.c.selection = TextSelection.collapsed(offset: o);
    });
  }

  void _split(_Row r) {
    r.splitQueued = false;
    if (!mounted) return;
    final i = _rows.indexOf(r);
    final text = r.c.text;
    if (i < 0 || !text.contains('\n')) return;
    final fm = r.c.fmts.length == text.length
        ? r.c.fmts
        : List<DocxFmt>.filled(text.length, r.c.base);
    final carry = r.c.current;
    final parts = <String>[];
    final pf = <List<DocxFmt>>[];
    var s = 0;
    for (var k = 0; k <= text.length; k++) {
      if (k == text.length || text.codeUnitAt(k) == 10) {
        parts.add(text.substring(s, k));
        pf.add(fm.sublist(s, k));
        s = k + 1;
      }
    }
    r.c.base = carry;
    r.c.reset(parts[0], pf[0]);
    final added = <_Row>[];
    for (var k = 1; k < parts.length; k++) {
      final nr = _makeRow(DocxPara(
        orig: -1,
        text: parts[k],
        fmts: pf[k],
        align: r.align,
        rtl: r.rtl,
        locked: false,
        cell: r.cell,
        note: '',
        pPr: '',
        open: '<w:p>',
      ));
      nr.c.base = carry;
      added.add(nr);
    }
    setState(() => _rows.insertAll(i + 1, added));
    _focusAt(added.last, parts.length == 2 ? 0 : parts.last.length);
  }

  bool _canMerge(int i) =>
      i > 0 &&
          i < _rows.length &&
          !_rows[i - 1].locked &&
          !_rows[i].locked &&
          _rows[i - 1].cell == _rows[i].cell;

  /// Joins paragraph [i] onto the end of the one before it.
  void _mergeUp(int i) {
    if (!_canMerge(i)) return;
    final a = _rows[i - 1], b = _rows[i];
    final at = a.c.text.length;
    final fa = a.c.fmts.length == at ? a.c.fmts : List<DocxFmt>.filled(at, a.c.base);
    final fb = b.c.fmts.length == b.c.text.length
        ? b.c.fmts
        : List<DocxFmt>.filled(b.c.text.length, b.c.base);
    a.c.reset(a.c.text + b.c.text, [...fa, ...fb], cursor: at);
    setState(() => _rows.removeAt(i));
    if (identical(_active, b)) _active = a;
    WidgetsBinding.instance.addPostFrameCallback((_) {
      b.c.dispose();
      b.focus.dispose();
    });
    _focusAt(a, at);
  }

  KeyEventResult _onKey(_Row r, KeyEvent e) {
    if (e is! KeyDownEvent && e is! KeyRepeatEvent) return KeyEventResult.ignored;
    final sel = r.c.selection;
    if (!sel.isValid || !sel.isCollapsed) return KeyEventResult.ignored;
    final i = _rows.indexOf(r);
    if (e.logicalKey == LogicalKeyboardKey.backspace &&
        sel.baseOffset == 0 &&
        i > 0) {
      _mergeUp(i);
      return KeyEventResult.handled;
    }
    if (e.logicalKey == LogicalKeyboardKey.delete &&
        sel.baseOffset == r.c.text.length &&
        i >= 0 &&
        i < _rows.length - 1) {
      _mergeUp(i + 1);
      return KeyEventResult.handled;
    }
    return KeyEventResult.ignored;
  }

  // ---------- toolbar actions ----------
  void _fmt(DocxFmt Function(DocxFmt) change) {
    final a = _active;
    if (a == null) return;
    a.c.apply(change);
    a.focus.requestFocus();
  }

  /// Titles and questions bold, a/b/c/d options regular, questions numbered
  /// 1. 2. 3. in every part (whole document).
  void _autoFormat() {
    final texts = [for (final r in _rows) r.locked ? '' : r.c.text];
    final centered = [for (final r in _rows) r.align == DocxAlign.center];
    final plan = ExamService.planLines(
        texts, centered, List<LineKind>.filled(_rows.length, LineKind.other));
    var n = 0;
    for (var i = 0; i < _rows.length; i++) {
      final r = _rows[i];
      final k = plan.kinds[i];
      if (r.locked || k == LineKind.other) continue;
      r.c.setAllBold(k != LineKind.option);
      if (plan.numbers[i] > 0) r.c.setNumber(plan.numbers[i]);
      n++;
    }
    _tick.value++;
    ScaffoldMessenger.of(context).showSnackBar(SnackBar(
        content: Text(n == 0
            ? 'No titles, questions or options were found.'
            : 'Formatted $n lines. Press Save to keep the changes.')));
  }

  void _setAlign(DocxAlign al) {
    final a = _active;
    if (a == null) return;
    setState(() => a.align = al);
    _tick.value++;
    a.focus.requestFocus();
  }

  // ---------- save / close ----------
  List<DocxPara> _snapshot() => [
    for (final r in _rows)
      DocxPara(
        orig: r.orig,
        text: r.c.text,
        fmts: List<DocxFmt>.of(r.c.fmts),
        align: r.align,
        rtl: r.rtl,
        locked: r.locked,
        cell: r.cell,
        note: r.note,
        pPr: r.pPr,
        open: r.open,
      ),
  ];

  bool get _changed => !ExamService.docxParasSame(_orig, _snapshot());

  Future<void> _cancel() async {
    if (_changed) {
      final discard = await showDialog<bool>(
        context: context,
        builder: (ctx) => AlertDialog(
          title: const Text('Discard changes?'),
          content: const Text('Your edits have not been saved.'),
          actions: [
            TextButton(
                onPressed: () => Navigator.pop(ctx, false),
                child: const Text('Keep editing')),
            FilledButton(
                onPressed: () => Navigator.pop(ctx, true),
                child: const Text('Discard')),
          ],
        ),
      );
      if (discard != true || !mounted) return;
    }
    Navigator.pop(context, false);
  }

  Future<void> _save() async {
    final edited = _snapshot();
    if (ExamService.docxParasSame(_orig, edited)) {
      Navigator.pop(context, false);
      return;
    }
    setState(() => _saving = true);
    final nav = Navigator.of(context);
    final messenger = ScaffoldMessenger.of(context);
    try {
      final out = ExamService.applyDocxParas(_docx!, edited);
      await widget.service.saveEditedDocx(widget.record, out);
      nav.pop(true);
      messenger.showSnackBar(const SnackBar(content: Text('Document updated')));
    } catch (e) {
      if (mounted) setState(() => _saving = false);
      messenger.showSnackBar(SnackBar(content: Text('Save failed: $e')));
    }
  }

  // ---------- UI ----------
  Widget _tb(IconData icon, String tip, bool active, VoidCallback? onTap) =>
      Tooltip(
        message: tip,
        child: InkWell(
          canRequestFocus: false,
          borderRadius: BorderRadius.circular(4),
          onTap: onTap,
          child: Container(
            width: 32,
            height: 32,
            decoration: BoxDecoration(
              color: active ? const Color(0xFFD3D3D3) : null,
              borderRadius: BorderRadius.circular(4),
            ),
            child: Icon(icon,
                size: 20, color: onTap == null ? Colors.black26 : Colors.black87),
          ),
        ),
      );

  Widget _group(String name, List<Widget> kids) => Column(
    mainAxisSize: MainAxisSize.min,
    children: [
      SizedBox(
        height: 36,
        child: Row(mainAxisSize: MainAxisSize.min, children: kids),
      ),
      Text(name, style: const TextStyle(fontSize: 11, color: Colors.black54)),
    ],
  );

  Widget _toolbar() => Material(
    color: Colors.white,
    elevation: 1,
    child: ValueListenableBuilder<int>(
      valueListenable: _tick,
      builder: (context, _, __) {
        final a = _active;
        final c = a?.c;
        final f = c?.current ?? const DocxFmt();
        final can = c != null && !_saving;
        bool has(bool Function(DocxFmt) t) => c != null && c.allHave(t);
        final size = f.size ?? 12;
        final fontName = f.font ?? 'Times New Roman';
        final rtl = a?.rtl ?? false;
        String sz(double v) =>
            v == v.roundToDouble() ? v.round().toString() : v.toString();
        return SingleChildScrollView(
          scrollDirection: Axis.horizontal,
          padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 4),
          child: Row(crossAxisAlignment: CrossAxisAlignment.start, children: [
            _group('Font', [
              SizedBox(
                width: 170,
                child: DropdownButtonHideUnderline(
                  child: DropdownButton<String>(
                    isExpanded: true,
                    isDense: true,
                    value: _fonts.contains(fontName) ? fontName : null,
                    hint: Text(fontName, style: const TextStyle(fontSize: 14)),
                    items: [
                      for (final n in _fonts)
                        DropdownMenuItem(
                          value: n,
                          child: Text(n,
                              style: TextStyle(fontFamily: n, fontSize: 14)),
                        ),
                    ],
                    onChanged: can
                        ? (v) {
                      if (v != null) _fmt((x) => x.copyWith(font: v));
                    }
                        : null,
                  ),
                ),
              ),
              const SizedBox(width: 8),
              SizedBox(
                width: 56,
                child: DropdownButtonHideUnderline(
                  child: DropdownButton<double>(
                    isExpanded: true,
                    isDense: true,
                    value: _sizes.contains(size) ? size : null,
                    hint: Text(sz(size), style: const TextStyle(fontSize: 14)),
                    items: [
                      for (final v in _sizes)
                        DropdownMenuItem(
                          value: v,
                          child: Text(sz(v), style: const TextStyle(fontSize: 14)),
                        ),
                    ],
                    onChanged: can
                        ? (v) {
                      if (v != null) _fmt((x) => x.copyWith(size: v));
                    }
                        : null,
                  ),
                ),
              ),
              _tb(Icons.text_increase, 'Grow font', false, can
                  ? () {
                final n = _sizes.firstWhere((s) => s > size,
                    orElse: () => _sizes.last);
                _fmt((x) => x.copyWith(size: n));
              }
                  : null),
              _tb(Icons.text_decrease, 'Shrink font', false, can
                  ? () {
                final n = _sizes.lastWhere((s) => s < size,
                    orElse: () => _sizes.first);
                _fmt((x) => x.copyWith(size: n));
              }
                  : null),
              const SizedBox(width: 6),
              _tb(Icons.format_bold, 'Bold', has((x) => x.b), can
                  ? () {
                final v = !has((x) => x.b);
                _fmt((x) => x.copyWith(b: v));
              }
                  : null),
              _tb(Icons.format_italic, 'Italic', has((x) => x.i), can
                  ? () {
                final v = !has((x) => x.i);
                _fmt((x) => x.copyWith(i: v));
              }
                  : null),
              _tb(Icons.format_underlined, 'Underline', has((x) => x.u), can
                  ? () {
                final v = !has((x) => x.u);
                _fmt((x) => x.copyWith(u: v));
              }
                  : null),
              _tb(Icons.strikethrough_s, 'Strikethrough', has((x) => x.s), can
                  ? () {
                final v = !has((x) => x.s);
                _fmt((x) => x.copyWith(s: v));
              }
                  : null),
              PopupMenuButton<int>(
                enabled: can,
                tooltip: 'Font color',
                padding: EdgeInsets.zero,
                onSelected: (v) => _fmt((x) => x.copyWith(color: v)),
                itemBuilder: (_) => [
                  for (final e in _colors.entries)
                    PopupMenuItem(
                      value: e.value,
                      child: Row(children: [
                        Container(
                          width: 16,
                          height: 16,
                          decoration: BoxDecoration(
                            color: Color(0xFF000000 | e.value),
                            shape: BoxShape.circle,
                          ),
                        ),
                        const SizedBox(width: 10),
                        Text(e.key),
                      ]),
                    ),
                ],
                child: SizedBox(
                  width: 32,
                  height: 32,
                  child: Column(
                    mainAxisAlignment: MainAxisAlignment.center,
                    children: [
                      Icon(Icons.format_color_text,
                          size: 18,
                          color: can ? Colors.black87 : Colors.black26),
                      Container(
                        width: 18,
                        height: 4,
                        color: Color(0xFF000000 | (f.color ?? 0xC00000)),
                      ),
                    ],
                  ),
                ),
              ),
            ]),
            Container(
              width: 1,
              height: 52,
              margin: const EdgeInsets.symmetric(horizontal: 12),
              color: const Color(0xFFDDDDDD),
            ),
            _group('Paragraph', [
              _tb(
                  Icons.format_align_left,
                  'Align left',
                  a != null && a.align == (rtl ? DocxAlign.end : DocxAlign.start),
                  can ? () => _setAlign(rtl ? DocxAlign.end : DocxAlign.start) : null),
              _tb(Icons.format_align_center, 'Center',
                  a != null && a.align == DocxAlign.center,
                  can ? () => _setAlign(DocxAlign.center) : null),
              _tb(
                  Icons.format_align_right,
                  'Align right',
                  a != null && a.align == (rtl ? DocxAlign.start : DocxAlign.end),
                  can ? () => _setAlign(rtl ? DocxAlign.start : DocxAlign.end) : null),
              _tb(Icons.format_align_justify, 'Justify',
                  a != null && a.align == DocxAlign.justify,
                  can ? () => _setAlign(DocxAlign.justify) : null),
            ]),
            Container(
              width: 1,
              height: 52,
              margin: const EdgeInsets.symmetric(horizontal: 12),
              color: const Color(0xFFDDDDDD),
            ),
            _group('Exam', [
              _tb(
                  Icons.auto_fix_high,
                  'Auto-format: bold titles and questions, regular options, numbered questions',
                  false,
                  _saving ? null : _autoFormat),
            ]),
          ]),
        );
      },
    ),
  );

  Widget _rowWidget(_Row r) {
    const base = TextStyle(
      fontFamily: 'Times New Roman',
      fontFamilyFallback: ['Liberation Serif', 'serif'],
      fontSize: 16,
      height: 1.3,
      color: Colors.black,
    );
    final align = switch (r.align) {
      DocxAlign.start => TextAlign.start,
      DocxAlign.center => TextAlign.center,
      DocxAlign.end => TextAlign.end,
      DocxAlign.justify => TextAlign.justify,
    };
    final dir = r.rtl ? ui.TextDirection.rtl : ui.TextDirection.ltr;
    final Widget child;
    if (r.locked) {
      final t = r.c.text.isNotEmpty ? r.c.text : r.note;
      child = Text(t,
          textAlign: align,
          textDirection: dir,
          style: base.copyWith(color: Colors.black45));
    } else {
      child = Focus(
        skipTraversal: true,
        onKeyEvent: (_, e) => _onKey(r, e),
        child: TextField(
          controller: r.c,
          focusNode: r.focus,
          enabled: !_saving,
          maxLines: null,
          keyboardType: TextInputType.multiline,
          textAlign: align,
          textDirection: dir,
          style: base,
          onTapOutside: (_) {},
          decoration: const InputDecoration(
            border: InputBorder.none,
            enabledBorder: InputBorder.none,
            focusedBorder: InputBorder.none,
            disabledBorder: InputBorder.none,
            filled: false,
            isCollapsed: true,
          ),
        ),
      );
    }
    return Container(
      key: ObjectKey(r),
      color: r.cell >= 0 ? const Color(0xFFF4F4F4) : null,
      padding: EdgeInsets.symmetric(vertical: 1, horizontal: r.cell >= 0 ? 6 : 0),
      child: child,
    );
  }

  @override
  Widget build(BuildContext context) {
    final r = widget.record;
    final Widget body;
    if (_loading) {
      body = const Center(child: CircularProgressIndicator());
    } else if (_error != null) {
      body = Center(
          child: Padding(
            padding: const EdgeInsets.all(24),
            child: Text(_error!, style: const TextStyle(color: Colors.red)),
          ));
    } else if (_rows.isEmpty) {
      body = const Center(child: Text('No editable text was found in this document.'));
    } else {
      body = Column(children: [
        _toolbar(),
        Expanded(
          child: LayoutBuilder(builder: (context, c) {
            final pad = c.maxWidth < 700 ? 20.0 : 64.0;
            return SingleChildScrollView(
              padding: EdgeInsets.symmetric(
                  horizontal: c.maxWidth < 700 ? 8 : 24, vertical: 20),
              child: Center(
                child: ConstrainedBox(
                  constraints: const BoxConstraints(maxWidth: 794),
                  child: Container(
                    width: double.infinity,
                    constraints: const BoxConstraints(minHeight: 900),
                    padding: EdgeInsets.symmetric(horizontal: pad, vertical: 48),
                    decoration: const BoxDecoration(
                      color: Colors.white,
                      boxShadow: [
                        BoxShadow(
                            color: Colors.black26,
                            blurRadius: 8,
                            offset: Offset(0, 2)),
                      ],
                    ),
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.stretch,
                      children: [for (final row in _rows) _rowWidget(row)],
                    ),
                  ),
                ),
              ),
            );
          }),
        ),
      ]);
    }
    return Dialog.fullscreen(
      child: Scaffold(
        backgroundColor: const Color(0xFFE3E3E3),
        appBar: AppBar(
          leading: IconButton(
            icon: const Icon(Icons.close),
            tooltip: 'Close',
            onPressed: _saving ? null : _cancel,
          ),
          title: Text('${r.subject} · ${r.form}', overflow: TextOverflow.ellipsis),
          actions: [
            FilledButton.icon(
              onPressed: (_saving || _loading || _error != null || _rows.isEmpty)
                  ? null
                  : _save,
              icon: _saving
                  ? const SizedBox(
                  height: 16,
                  width: 16,
                  child: CircularProgressIndicator(strokeWidth: 2))
                  : const Icon(Icons.save),
              label: const Text('Save'),
            ),
            const SizedBox(width: 12),
          ],
        ),
        body: body,
      ),
    );
  }
}

/// One general school letterhead, used on every uploaded document.
class LetterheadDialog extends StatefulWidget {
  final ExamService service;
  const LetterheadDialog({super.key, required this.service});

  @override
  State<LetterheadDialog> createState() => _LetterheadDialogState();
}

class _LetterheadDialogState extends State<LetterheadDialog> {
  bool _busy = false;

  Future<void> _upload() async {
    final res = await FilePicker.platform.pickFiles(
      withData: true,
      type: FileType.custom,
      allowedExtensions: ['png', 'jpg', 'jpeg'],
    );
    if (res == null || res.files.isEmpty || res.files.first.bytes == null) return;
    setState(() => _busy = true);
    final messenger = ScaffoldMessenger.of(context);
    try {
      await widget.service.saveLetterhead(res.files.first.bytes!);
      messenger.showSnackBar(const SnackBar(content: Text('Letterhead saved')));
    } catch (e) {
      messenger.showSnackBar(SnackBar(content: Text('Failed: $e')));
    } finally {
      if (mounted) setState(() => _busy = false);
    }
  }

  @override
  Widget build(BuildContext context) {
    return AlertDialog(
      title: const Text('School letterhead (general header)'),
      content: SizedBox(
        width: 460,
        child: StreamBuilder<Uint8List?>(
          stream: widget.service.watchLetterhead(),
          builder: (context, snap) {
            final bytes = snap.data;
            return Column(mainAxisSize: MainAxisSize.min, children: [
              Container(
                width: double.infinity,
                constraints: const BoxConstraints(minHeight: 90),
                decoration: BoxDecoration(
                  border: Border.all(color: Colors.black26),
                  borderRadius: BorderRadius.circular(6),
                ),
                child: bytes == null
                    ? const Padding(
                  padding: EdgeInsets.all(24),
                  child: Center(child: Text('No letterhead uploaded yet')),
                )
                    : Image.memory(bytes, fit: BoxFit.contain),
              ),
              const SizedBox(height: 12),
              const Text(
                'Upload your school letterhead once (PNG or JPG, under 700 KB). '
                    'It is placed at the top of every document uploaded from any button.',
                style: TextStyle(fontSize: 12, color: Colors.black54),
              ),
              if (_busy) ...[
                const SizedBox(height: 10),
                const LinearProgressIndicator(),
              ],
            ]);
          },
        ),
      ),
      actions: [
        TextButton(
          onPressed: _busy ? null : () => Navigator.pop(context),
          child: const Text('Close'),
        ),
        FilledButton.icon(
          onPressed: _busy ? null : _upload,
          icon: const Icon(Icons.upload),
          label: const Text('Upload / replace'),
        ),
      ],
    );
  }
}

/// Upload / remove the school logo and choose where it is shown.
class LogoDialog extends StatefulWidget {
  const LogoDialog({super.key});

  @override
  State<LogoDialog> createState() => _LogoDialogState();
}

class _LogoDialogState extends State<LogoDialog> {
  bool _busy = false;

  Future<void> _run(Future<void> Function() job, [String? okMsg]) async {
    final messenger = ScaffoldMessenger.of(context);
    setState(() => _busy = true);
    try {
      await job();
      if (okMsg != null) {
        messenger.showSnackBar(SnackBar(content: Text(okMsg)));
      }
    } catch (e) {
      messenger.showSnackBar(SnackBar(
          content: Text('Failed: ${'$e'.replaceFirst('Exception: ', '')}')));
    } finally {
      if (mounted) setState(() => _busy = false);
    }
  }

  Future<void> _upload() async {
    final res = await FilePicker.platform.pickFiles(
      withData: true,
      type: FileType.custom,
      allowedExtensions: ['png', 'jpg', 'jpeg'],
    );
    if (res == null || res.files.isEmpty || res.files.first.bytes == null) {
      return;
    }
    await _run(() => schoolLogo.setImage(res.files.first.bytes!), 'Logo saved');
  }

  void _toggleWm(SchoolLogo l, String place, bool on) {
    final next = [
      for (final p in LogoPlace.documents)
        if (p == place ? on : l.watermarkPlaces.contains(p)) p,
    ];
    _run(() => schoolLogo.update({'watermarkPlaces': next}));
  }

  void _togglePlace(SchoolLogo l, String place, bool on) {
    final next = [
      for (final p in LogoPlace.all)
        if (p == place ? on : l.places.contains(p)) p,
    ];
    _run(() => schoolLogo.update({'places': next}));
  }

  @override
  Widget build(BuildContext context) {
    return AlertDialog(
      title: const Text('School logo'),
      content: SizedBox(
        width: 460,
        child: ValueListenableBuilder<SchoolLogo>(
          valueListenable: schoolLogo,
          builder: (context, l, _) {
            final hasLogo = l.bytes != null;
            return SingleChildScrollView(
              child: Column(
                mainAxisSize: MainAxisSize.min,
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Container(
                    width: double.infinity,
                    constraints: const BoxConstraints(minHeight: 110),
                    padding: const EdgeInsets.all(10),
                    decoration: BoxDecoration(
                      color: Colors.white,
                      border: Border.all(color: Colors.black26),
                      borderRadius: BorderRadius.circular(6),
                    ),
                    child: hasLogo
                        ? Image.memory(l.bytes!, height: 120, fit: BoxFit.contain)
                        : const Center(child: Text('No logo uploaded yet')),
                  ),
                  const SizedBox(height: 8),
                  const Text(
                    'PNG or JPG (a PNG with a transparent background looks best). '
                        'The logo is saved once and used everywhere you tick below.',
                    style: TextStyle(fontSize: 12, color: Colors.black54),
                  ),
                  if (hasLogo) ...[
                    const Divider(height: 24),
                    const Text('Show the logo on',
                        style: TextStyle(fontWeight: FontWeight.w600)),
                    for (final p in LogoPlace.all)
                      CheckboxListTile(
                        contentPadding: EdgeInsets.zero,
                        dense: true,
                        controlAffinity: ListTileControlAffinity.leading,
                        value: l.places.contains(p),
                        onChanged:
                        _busy ? null : (v) => _togglePlace(l, p, v ?? false),
                        title: Text(LogoPlace.labels[p]!),
                      ),
                    const Divider(height: 24),
                    const Text('On printed documents',
                        style: TextStyle(fontWeight: FontWeight.w600)),
                    const SizedBox(height: 8),
                    Row(children: [
                      const Expanded(child: Text('Position')),
                      SegmentedButton<String>(
                        showSelectedIcon: false,
                        segments: const [
                          ButtonSegment(value: 'left', label: Text('Left')),
                          ButtonSegment(value: 'center', label: Text('Center')),
                          ButtonSegment(value: 'right', label: Text('Right')),
                        ],
                        selected: {l.align},
                        onSelectionChanged: _busy
                            ? null
                            : (v) => _run(
                                () => schoolLogo.update({'align': v.first})),
                      ),
                    ]),
                    const SizedBox(height: 8),
                    Row(children: [
                      const Text('Size'),
                      Expanded(
                        child: Slider(
                          min: 30,
                          max: 120,
                          divisions: 9,
                          value: l.height.clamp(30.0, 120.0).toDouble(),
                          label: '${l.height.round()}',
                          onChanged: _busy
                              ? null
                              : (v) => _run(
                                  () => schoolLogo.update({'height': v})),
                        ),
                      ),
                    ]),
                    const Text(
                      'Position and size apply to exam papers, section lists and '
                          'the attendance report. The logo is placed above the '
                          'letterhead / title.',
                      style: TextStyle(fontSize: 12, color: Colors.black54),
                    ),
                    const Divider(height: 24),
                    const Text('Watermark (faded logo behind the text)',
                        style: TextStyle(fontWeight: FontWeight.w600)),
                    for (final p in LogoPlace.documents)
                      CheckboxListTile(
                        contentPadding: EdgeInsets.zero,
                        dense: true,
                        controlAffinity: ListTileControlAffinity.leading,
                        value: l.watermarkPlaces.contains(p),
                        onChanged:
                        _busy ? null : (v) => _toggleWm(l, p, v ?? false),
                        title: Text(LogoPlace.labels[p]!),
                      ),
                    Row(children: [
                      const SizedBox(width: 64, child: Text('Strength')),
                      Expanded(
                        child: Slider(
                          min: 0.05,
                          max: 0.4,
                          divisions: 7,
                          value: l.wmOpacity.clamp(0.05, 0.4).toDouble(),
                          label: '${(l.wmOpacity * 100).round()}%',
                          onChanged: _busy
                              ? null
                              : (v) => _run(
                                  () => schoolLogo.update({'wmOpacity': v})),
                        ),
                      ),
                    ]),
                    Row(children: [
                      const SizedBox(width: 64, child: Text('Size')),
                      Expanded(
                        child: Slider(
                          min: 0.3,
                          max: 0.9,
                          divisions: 6,
                          value: l.wmSize.clamp(0.3, 0.9).toDouble(),
                          label: '${(l.wmSize * 100).round()}%',
                          onChanged: _busy
                              ? null
                              : (v) => _run(
                                  () => schoolLogo.update({'wmSize': v})),
                        ),
                      ),
                    ]),
                    const Text(
                      'The watermark is centred on every page. Strength is how '
                          'visible it is; size is its width compared with the page.',
                      style: TextStyle(fontSize: 12, color: Colors.black54),
                    ),
                  ],
                  if (_busy) ...[
                    const SizedBox(height: 10),
                    const LinearProgressIndicator(),
                  ],
                ],
              ),
            );
          },
        ),
      ),
      actions: [
        if (schoolLogo.value.bytes != null)
          TextButton(
            onPressed:
            _busy ? null : () => _run(schoolLogo.removeImage, 'Logo removed'),
            child: const Text('Remove'),
          ),
        TextButton(
          onPressed: _busy ? null : () => Navigator.pop(context),
          child: const Text('Close'),
        ),
        FilledButton.icon(
          onPressed: _busy ? null : _upload,
          icon: const Icon(Icons.upload),
          label: const Text('Upload / replace'),
        ),
      ],
    );
  }
}

/// Sets the GENERAL exam heading information once (same for every exam).
/// Form and subject are taken from the button that was pressed.
class ExamHeadingDialog extends StatefulWidget {
  final ExamService service;
  const ExamHeadingDialog({super.key, required this.service});

  @override
  State<ExamHeadingDialog> createState() => _ExamHeadingDialogState();
}

class _ExamHeadingDialogState extends State<ExamHeadingDialog> {
  final _examName = TextEditingController();
  final _academicYear = TextEditingController();
  final _month = TextEditingController();
  final _year = TextEditingController();
  final _marks = TextEditingController();
  final _time = TextEditingController();
  final _examNameAr = TextEditingController();
  final _timeAr = TextEditingController();
  final _examNameIs = TextEditingController();
  final _timeIs = TextEditingController();
  final _examNameSo = TextEditingController();
  final _timeSo = TextEditingController();
  bool _loading = true;
  bool _busy = false;

  @override
  void initState() {
    super.initState();
    _load();
  }

  Future<void> _load() async {
    try {
      final h = await widget.service.getHeading();
      _examName.text = h.examName;
      _academicYear.text = h.academicYear;
      _month.text = h.month;
      _year.text = h.year;
      _marks.text = h.marks;
      _time.text = h.allowedTime;
      _examNameAr.text = h.examNameAr;
      _timeAr.text = h.allowedTimeAr;
      _examNameIs.text = h.examNameIs;
      _timeIs.text = h.allowedTimeIs;
      _examNameSo.text = h.examNameSo;
      _timeSo.text = h.allowedTimeSo;
    } catch (_) {}
    if (mounted) setState(() => _loading = false);
  }

  @override
  void dispose() {
    for (final c in [
      _examName, _academicYear, _month, _year, _marks, _time,
      _examNameAr, _timeAr, _examNameIs, _timeIs, _examNameSo, _timeSo,
    ]) {
      c.dispose();
    }
    super.dispose();
  }

  ExamHeading get _current => ExamHeading(
    examName: _examName.text,
    academicYear: _academicYear.text,
    month: _month.text,
    year: _year.text,
    marks: _marks.text,
    allowedTime: _time.text,
    examNameAr: _examNameAr.text,
    allowedTimeAr: _timeAr.text,
    examNameIs: _examNameIs.text,
    allowedTimeIs: _timeIs.text,
    examNameSo: _examNameSo.text,
    allowedTimeSo: _timeSo.text,
  );

  Future<void> _save() async {
    setState(() => _busy = true);
    final messenger = ScaffoldMessenger.of(context);
    final nav = Navigator.of(context);
    try {
      await widget.service.saveHeading(_current);
      nav.pop();
      messenger.showSnackBar(const SnackBar(content: Text('Exam heading saved')));
    } catch (e) {
      if (mounted) setState(() => _busy = false);
      messenger.showSnackBar(SnackBar(content: Text('Failed: $e')));
    }
  }

  Widget _field(String label, TextEditingController c, {String? hint}) => Padding(
    padding: const EdgeInsets.only(bottom: 10),
    child: TextField(
      controller: c,
      onChanged: (_) => setState(() {}),
      decoration: InputDecoration(
        labelText: label,
        hintText: hint,
        border: const OutlineInputBorder(),
      ),
    ),
  );

  @override
  Widget build(BuildContext context) {
    final p = _current.build('Biology', 'Form1');
    final pAr = _current.build('Arabic', 'Form1');
    final pIs = _current.build('Islamic', 'Form1');
    final pSo = _current.build('Somali', 'Form1');
    return AlertDialog(
      title: const Text('Exam heading (general)'),
      content: SizedBox(
        width: 460,
        child: _loading
            ? const Padding(
          padding: EdgeInsets.all(24),
          child: Center(child: CircularProgressIndicator()),
        )
            : SingleChildScrollView(
          child: Column(mainAxisSize: MainAxisSize.min, children: [
            _field('Exam name', _examName, hint: 'FINAL EXAM'),
            Row(children: [
              Expanded(
                  child: _field('Academic year', _academicYear,
                      hint: '2025-2026')),
              const SizedBox(width: 10),
              Expanded(child: _field('Month', _month, hint: 'June')),
              const SizedBox(width: 10),
              Expanded(child: _field('Year', _year, hint: '2026')),
            ]),
            Row(children: [
              Expanded(
                  child: _field('Default marks', _marks, hint: '30')),
              const SizedBox(width: 10),
              Expanded(
                  flex: 2,
                  child: _field('Allowed time', _time,
                      hint: 'ONE-HOUR PLUS 20 MINUTES')),
            ]),
            const Divider(),
            const Align(
              alignment: Alignment.centerLeft,
              child: Text('Arabic exam (used for the Arabic subject)',
                  style: TextStyle(fontWeight: FontWeight.bold)),
            ),
            const SizedBox(height: 8),
            Directionality(
              textDirection: ui.TextDirection.rtl,
