const kBlue = Color(0xFF3498DB);
const kGreen = Color(0xFF2ECC71);
const kRed = Color(0xFFE74C3C);

/// App-bar button: downloads all uploaded exams as <year>.zip
/// (year folder > subject folders > exam files).
class _DownloadAllButton extends StatefulWidget {
  final ExamService service;
  const _DownloadAllButton({required this.service});

  @override
  State<_DownloadAllButton> createState() => _DownloadAllButtonState();
}

class _DownloadAllButtonState extends State<_DownloadAllButton> {
  bool _busy = false;

  Future<void> _run() async {
    setState(() => _busy = true);
    final messenger = ScaffoldMessenger.of(context);
    try {
      final n = await widget.service.downloadAll();
      messenger.showSnackBar(
          SnackBar(content: Text('Downloaded $n exam files in ${DateTime.now().year}.zip')));
    } catch (e) {
      messenger.showSnackBar(SnackBar(content: Text('$e')));
    } finally {
      if (mounted) setState(() => _busy = false);
    }
  }

  @override
  Widget build(BuildContext context) {
    if (_busy) {
      return const Padding(
        padding: EdgeInsets.symmetric(horizontal: 12),
        child: Center(
          child: SizedBox(
              width: 20, height: 20, child: CircularProgressIndicator(strokeWidth: 2)),
        ),
      );
    }
    return IconButton(
      tooltip: 'Download all exams (ZIP)',
      icon: const Icon(Icons.folder_zip),
      onPressed: _run,
    );
  }
}

/// App-bar button: re-uploads a ZIP made by "Download all exams".
/// Every file goes back into its own Subject / Form cell in one go.
class _UploadAllButton extends StatefulWidget {
  final ExamService service;
  const _UploadAllButton({required this.service});

  @override
  State<_UploadAllButton> createState() => _UploadAllButtonState();
}

class _UploadAllButtonState extends State<_UploadAllButton> {
  bool _busy = false;
  String? _progress;

  Future<void> _run() async {
    final messenger = ScaffoldMessenger.of(context);
    try {
      final res = await FilePicker.platform.pickFiles(
        withData: true,
        type: FileType.custom,
        allowedExtensions: ['zip'],
      );
      if (res == null || res.files.isEmpty) return;
      final bytes = res.files.first.bytes;
      if (bytes == null) throw Exception('Could not read the ZIP file.');

      setState(() {
        _busy = true;
        _progress = 'Reading...';
      });
      final plan = widget.service.planZipImport(bytes);
      if (!mounted) return;
      setState(() => _busy = false);

      if (plan.items.isEmpty) {
        throw Exception('No exam files were found in this ZIP.'
            '${plan.skipped.isEmpty ? '' : '\n${plan.skipped.take(3).join('\n')}'}');
      }
      final ok = await showDialog<bool>(
        context: context,
        builder: (ctx) => AlertDialog(
          title: const Text('Re-upload all exams'),
          content: SizedBox(
            width: 420,
            child: SingleChildScrollView(
              child: Column(
                mainAxisSize: MainAxisSize.min,
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Text('${plan.items.length} file(s) will be saved and will '
                      'REPLACE the current files in these cells:'),
                  const SizedBox(height: 8),
                  for (final it in plan.items)
                    Text('• ${it.subject} – ${it.form}   (${it.fileName})',
                        style: const TextStyle(fontSize: 12)),
                  if (plan.skipped.isNotEmpty) ...[
                    const SizedBox(height: 12),
                    Text('${plan.skipped.length} file(s) skipped:',
                        style: const TextStyle(
                            fontWeight: FontWeight.bold, color: kRed)),
                    for (final s in plan.skipped)
                      Text('• $s', style: const TextStyle(fontSize: 12)),
                  ],
                ],
              ),
            ),
          ),
          actions: [
            TextButton(
                onPressed: () => Navigator.pop(ctx, false),
                child: const Text('Cancel')),
            FilledButton(
                onPressed: () => Navigator.pop(ctx, true),
                child: const Text('Upload all')),
          ],
        ),
      );
      if (ok != true || !mounted) return;

      setState(() {
        _busy = true;
        _progress = '0/${plan.items.length}';
      });
      final r = await widget.service.applyZipImport(plan, onProgress: (d, t) {
        if (mounted) setState(() => _progress = '$d/$t');
      });
      messenger.showSnackBar(SnackBar(
        content: Text(r.failed.isEmpty
            ? 'Uploaded ${r.saved} exam file(s).'
            : 'Uploaded ${r.saved}. Failed: ${r.failed.join(', ')}'),
      ));
    } catch (e) {
      messenger.showSnackBar(
          SnackBar(content: Text('$e'.replaceFirst('Exception: ', ''))));
    } finally {
      if (mounted) setState(() => _busy = false);
    }
  }

  @override
  Widget build(BuildContext context) {
    if (_busy) {
      return Padding(
        padding: const EdgeInsets.symmetric(horizontal: 12),
        child: Center(
          child: Row(mainAxisSize: MainAxisSize.min, children: [
            const SizedBox(
                width: 20,
                height: 20,
                child: CircularProgressIndicator(strokeWidth: 2)),
            if (_progress != null) ...[
              const SizedBox(width: 6),
              Text(_progress!, style: const TextStyle(fontSize: 12)),
            ],
          ]),
        ),
      );
    }
    return IconButton(
      tooltip: 'Re-upload all exams (ZIP)',
      icon: const Icon(Icons.drive_folder_upload),
      onPressed: _run,
    );
  }
}

