// ======================= ASSIGNMENTS =======================
//
// Works like the Exam tab (subject rows x form columns, one button per
// cell, school letterhead + footer added to every uploaded file), but each
// button holds ANY NUMBER of assignments instead of one file.
// Firestore: assignments/{id} (details) and assignmentFiles/{id} (the file).

class AssignmentRecord {
  final String id, subject, form, title, teacherName, fileName;
  final int size;
  final DateTime? createdAt;
  const AssignmentRecord({
    required this.id,
    required this.subject,
    required this.form,
    required this.title,
    this.teacherName = '',
    this.fileName = '',
    this.size = 0,
    this.createdAt,
  });

  static String keyFor(String subject, String form) => '${subject}_$form';

  factory AssignmentRecord.fromDoc(
      QueryDocumentSnapshot<Map<String, dynamic>> d) {
    final m = d.data();
    return AssignmentRecord(
      id: d.id,
      subject: '${m['subject'] ?? ''}',
      form: '${m['form'] ?? ''}',
      title: '${m['title'] ?? ''}',
      teacherName: '${m['teacherName'] ?? ''}',
      fileName: '${m['fileName'] ?? ''}',
      size: (m['size'] as num?)?.toInt() ?? 0,
      createdAt: (m['createdAt'] as Timestamp?)?.toDate(),
    );
  }
}

/// Teacher, marks and allowed time saved for one subject + form button
/// (same details the Exam tab keeps per button).
class AssignmentDetails {
  final String teacherName, marks, allowedTime;
  const AssignmentDetails(
      {this.teacherName = '', this.marks = '', this.allowedTime = ''});

  factory AssignmentDetails.fromMap(Map<String, dynamic> m) =>
      AssignmentDetails(
        teacherName: '${m['teacherName'] ?? ''}',
        marks: '${m['marks'] ?? ''}',
        allowedTime: '${m['allowedTime'] ?? ''}',
      );
}

class AssignmentService {
  final _db = FirebaseFirestore.instance;

  /// Reused for the school letterhead, the stamping of the files and the
  /// preview, so assignments look exactly like the exam papers.
  final ExamService exams = ExamService();

  CollectionReference<Map<String, dynamic>> get _meta =>
      _db.collection('assignments');
  CollectionReference<Map<String, dynamic>> get _files =>
      _db.collection('assignmentFiles');

  static void _sortOldestFirst(List<AssignmentRecord> l) {
    final far = DateTime.now().add(const Duration(days: 1));
    l.sort((a, b) => (a.createdAt ?? far).compareTo(b.createdAt ?? far));
  }

  /// All assignments, grouped by "subject_form" (oldest first).
  Stream<Map<String, List<AssignmentRecord>>> watchAll() =>
      _meta.snapshots().map((s) {
        final out = <String, List<AssignmentRecord>>{};
        for (final d in s.docs) {
          final r = AssignmentRecord.fromDoc(d);
          (out[AssignmentRecord.keyFor(r.subject, r.form)] ??= []).add(r);
        }
        for (final l in out.values) {
          _sortOldestFirst(l);
        }
        return out;
      });

  /// The assignments of one subject + form button (oldest first).
  Stream<List<AssignmentRecord>> watchFor(String subject, String form) =>
      _meta.where('subject', isEqualTo: subject).snapshots().map((s) {
        final l = [
          for (final d in s.docs)
            if ('${d.data()['form']}' == form) AssignmentRecord.fromDoc(d),
        ];
        _sortOldestFirst(l);
        return l;
      });

  /// Same footer as the exams: Subject | Form | Teacher.
  static String footerFor(String subject, String form, String teacher) {
    final t = teacher.replaceAll('Teacher: ', '').replaceAll('Teacher:', '').trim();
    return t.isEmpty ? '' : '$subject | $form | $t';
  }

  static String _clean(String v) => v
      .trim()
      .replaceAll(RegExp(r'[\\/:*?"<>|]'), '')
      .replaceAll(RegExp(r'\s+'), '_');

  static String _extOf(String name) {
    final dot = name.lastIndexOf('.');
    return dot >= 0 ? name.substring(dot) : '';
  }

  // ---------------- Per-button details ----------------
  DocumentReference<Map<String, dynamic>> get _details =>
      _db.collection('settings').doc('assignmentDetails');

  /// Live map "subject_form" -> saved teacher / marks / time.
  Stream<Map<String, AssignmentDetails>> watchDetails() =>
      _details.snapshots().map((d) {
        final m = d.data() ?? {};
        return {
          for (final e in m.entries)
            if (e.value is Map)
              e.key: AssignmentDetails.fromMap(
                  Map<String, dynamic>.from(e.value as Map)),
        };
      });

  Future<AssignmentDetails> getDetails(String subject, String form) async {
    final v = (await _details.get()).data()?[AssignmentRecord.keyFor(subject, form)];
    return v is Map
        ? AssignmentDetails.fromMap(Map<String, dynamic>.from(v))
        : const AssignmentDetails();
  }

  /// Saves only the teacher name, footer, marks and time (no file needed).
  Future<void> saveDetails(String subject, String form,
      {required String teacher, String marks = '', String allowedTime = ''}) {
    return _details.set({
      AssignmentRecord.keyFor(subject, form): {
        'teacherName': teacher,
        'footer': footerFor(subject, form, teacher),
        'marks': marks,
        'allowedTime': allowedTime,
      },
    }, SetOptions(merge: true));
  }

  /// Deletes every assignment of one button (it goes back to Pending).
  Future<void> deleteAll(String subject, String form) async {
    final snap = await _meta.where('subject', isEqualTo: subject).get();
    for (final d in snap.docs) {
      if ('${d.data()['form']}' != form) continue;
      try {
        await _files.doc(d.id).delete();
      } catch (_) {}
      await d.reference.delete();
    }
  }

  /// Stamps the general letterhead + footer on the file and saves it as one
  /// more assignment of this subject and form.
  Future<void> upload({
    required String subject,
    required String form,
    required String title,
    required String teacher,
    required PlatformFile file,
    String marks = '',
    String allowedTime = '',
    bool addHeading = true,
    bool autoFormat = true,
    bool numberQuestions = true,
    void Function(String status)? onStatus,
  }) async {
    final letterhead = await exams.getLetterhead();
    if (letterhead == null) {
      throw Exception(
          'No school letterhead yet. Tap the image icon at the top to upload it first.');
    }
    final bytes = file.bytes;
    if (bytes == null) throw Exception('Could not read file bytes.');
    final isDocx = (file.extension ?? '').toLowerCase() == 'docx';
    final footer = footerFor(subject, form, teacher);

    onStatus?.call('Adding letterhead, heading and footer...');
    final ExamHeadingText? heading = addHeading
        ? (await exams.getHeading())
        .build(subject, form, marks: marks, time: allowedTime)
        : null;
    final Uint8List stamped = isDocx
        ? await exams.stampDocx(
        docx: bytes,
        letterhead: letterhead,
        footer: footer,
        heading: heading,
        autoFormat: autoFormat,
        numberQuestions: numberQuestions)
        : await exams.stampDocument(
        file: file,
        letterhead: letterhead,
        footer: footer,
        heading: heading);

    final baseName = file.name.replaceAll(RegExp(r'\.[^.]+$'), '');
    final fileName = isDocx ? file.name : '$baseName.pdf';
    final kb = (stamped.length / 1024).round();
    if (stamped.length > ExamService.maxFileBytes) {
      throw Exception(
          'File is too large ($kb KB after adding the letterhead). The limit is 700 KB. '
              'Please compress the file or use a smaller letterhead image.');
    }

    onStatus?.call('Saving $kb KB...');
    final uid = FirebaseAuth.instance.currentUser?.uid;
    final ref = _meta.doc();
    await _files.doc(ref.id).set({
      'fileName': fileName,
      'contentType': isDocx ? ExamService._docxMime : 'application/pdf',
      'dataBase64': base64Encode(stamped),
      'size': stamped.length,
      'updatedBy': uid,
      'updatedAt': FieldValue.serverTimestamp(),
    }).timeout(const Duration(seconds: 40), onTimeout: () {
      throw Exception(
          'Saving timed out. Check the internet connection and the Firestore rules '
              '(collection "assignmentFiles").');
    });
    await ref.set({
      'subject': subject,
      'form': form,
      'title': title,
      'teacherName': teacher,
      'footer': footer,
      'marks': marks,
      'allowedTime': allowedTime,
      'fileName': fileName,
      'size': stamped.length,
      'createdBy': uid,
      'createdAt': FieldValue.serverTimestamp(),
    });
    // Remember the teacher / marks / time for this button (like the exams).
    try {
      await saveDetails(subject, form,
          teacher: teacher, marks: marks, allowedTime: allowedTime);
    } catch (_) {}
  }

  /// Downloads one assignment to the user's device.
  Future<void> download(AssignmentRecord r) async {
    final d = (await _files.doc(r.id).get()).data();
    if (d == null || d['dataBase64'] == null) {
      throw Exception('The file was not found.');
    }
    final stored = (d['fileName'] as String?) ?? r.fileName;
    final name = '${_clean(r.form)}-${_clean(r.subject)}-'
        '${_clean(r.title.isEmpty ? 'Assignment' : r.title)}${_extOf(stored)}';
    await _downloadInBrowser(
      base64Decode(d['dataBase64'] as String),
      name,
      (d['contentType'] as String?) ?? 'application/octet-stream',
    );
  }

  Future<void> delete(AssignmentRecord r) async {
    try {
      await _files.doc(r.id).delete();
    } catch (_) {}
    await _meta.doc(r.id).delete();
  }

  /// Every assignment this person may see, as one ZIP:
  /// <year>/<Subject>/<Form>-<Subject>-<Title>.<ext>
  Future<int> downloadAll() async {
    final snap = await _meta.get();
    final list = [
      for (final d in snap.docs) AssignmentRecord.fromDoc(d),
    ].where((r) =>
        teacherScope.value.allows(r.subject, r.form)).toList();
    if (list.isEmpty) {
      throw Exception('There are no uploaded assignments to download yet.');
    }
    final year = '${DateTime.now().year}';
    final docs = await Future.wait(list.map((r) => _files.doc(r.id).get()));
    final archive = zip.Archive();
    final used = <String>{};
    var count = 0;
    for (var i = 0; i < list.length; i++) {
      final r = list[i];
      final d = docs[i].data();
      if (d == null || d['dataBase64'] == null) continue;
      final bytes = base64Decode(d['dataBase64'] as String);
      final ext = _extOf((d['fileName'] as String?) ?? r.fileName);
      final stem = '$year/${_clean(r.subject)}/${_clean(r.form)}-'
          '${_clean(r.subject)}-${_clean(r.title.isEmpty ? 'Assignment' : r.title)}';
      var path = '$stem$ext';
      for (var n = 2; !used.add(path); n++) {
        path = '$stem-$n$ext';
      }
      archive.addFile(zip.ArchiveFile(path, bytes.length, bytes));
      count++;
    }
    if (count == 0) throw Exception('The uploaded files could not be read.');
    final out = zip.ZipEncoder().encode(archive);
    if (out == null) throw Exception('Could not create the ZIP file.');
    await _downloadInBrowser(
        Uint8List.fromList(out), 'Assignments-$year.zip', 'application/zip');
    return count;
  }
}

class _AssignmentDownloadAll extends StatefulWidget {
  final AssignmentService service;
  const _AssignmentDownloadAll({required this.service});

  @override
  State<_AssignmentDownloadAll> createState() => _AssignmentDownloadAllState();
}

class _AssignmentDownloadAllState extends State<_AssignmentDownloadAll> {
  bool _busy = false;

  Future<void> _run() async {
    setState(() => _busy = true);
    final messenger = ScaffoldMessenger.of(context);
    try {
      final n = await widget.service.downloadAll();
      messenger.showSnackBar(SnackBar(
          content: Text('Downloaded $n assignment files in '
              'Assignments-${DateTime.now().year}.zip')));
    } catch (e) {
      messenger.showSnackBar(SnackBar(
          content: Text('$e'.replaceFirst('Exception: ', ''))));
    } finally {
      if (mounted) setState(() => _busy = false);
    }
  }

  @override
  Widget build(BuildContext context) {
    if (_busy) {
      return const Padding(
        padding: EdgeInsets.symmetric(horizontal: 12),
        child: Center(
          child: SizedBox(
              width: 20,
              height: 20,
              child: CircularProgressIndicator(strokeWidth: 2)),
        ),
      );
    }
    return IconButton(
      tooltip: 'Download all assignments (ZIP)',
      icon: const Icon(Icons.folder_zip),
      onPressed: _run,
    );
  }
}

class AssignmentScreen extends StatefulWidget {
  const AssignmentScreen({super.key});

  @override
  State<AssignmentScreen> createState() => _AssignmentScreenState();
}

class _AssignmentScreenState extends State<AssignmentScreen> {
  final _service = AssignmentService();
  late final Stream<Map<String, List<AssignmentRecord>>> _stream =
  _service.watchAll();
  late final Stream<Map<String, AssignmentDetails>> _detailsStream =
  _service.watchDetails();
  Map<String, AssignmentDetails> _details = const {};

  static const _headStyle =
  TextStyle(color: Colors.white, fontWeight: FontWeight.bold, fontSize: 16);

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: const Text('Assignments'),
        actions: [
          _AssignmentDownloadAll(service: _service),
          IconButton(
            tooltip: 'Exam heading (general)',
            icon: const Icon(Icons.edit_note),
            onPressed: () => showDialog(
              context: context,
              builder: (_) => ExamHeadingDialog(service: _service.exams),
            ),
          ),
          IconButton(
            tooltip: 'School letterhead (general header)',
            icon: const Icon(Icons.image),
            onPressed: () => showDialog(
              context: context,
              builder: (_) => LetterheadDialog(service: _service.exams),
            ),
          ),
          const SizedBox(width: 8),
        ],
      ),
      body: StreamBuilder<Map<String, AssignmentDetails>>(
        stream: _detailsStream,
        builder: (context, dsnap) {
          _details = dsnap.data ?? const {};
          return StreamBuilder<Map<String, List<AssignmentRecord>>>(
            stream: _stream,
            builder: (context, snap) {
              if (snap.hasError) {
                return Center(child: Text('Error: ${snap.error}'));
              }
              if (!snap.hasData) {
                return const Center(child: CircularProgressIndicator());
              }
              final data = snap.data!;
              return ValueListenableBuilder<TeacherScope>(
                valueListenable: teacherScope,
                builder: (context, sc, _) {
                  if (sc.subjectList.isEmpty || sc.formList.isEmpty) {
                    return const Center(
                      child: Padding(
                        padding: EdgeInsets.all(24),
                        child: Text(
                            'No subjects or forms are set on your account.\n'
                                'Ask the administrator to add them in Teachers.',
                            textAlign: TextAlign.center),
                      ),
                    );
                  }
                  return SingleChildScrollView(
                    padding: const EdgeInsets.all(16),
                    child: SingleChildScrollView(
                      scrollDirection: Axis.horizontal,
                      child: Card(
                        clipBehavior: Clip.antiAlias,
                        child: _table(data, sc),
                      ),
                    ),
                  );
                },
              );
            },
          );
        },
      ),
    );
  }

  Widget _table(Map<String, List<AssignmentRecord>> data, TeacherScope sc) {
    const subjectWidth = 130.0;
    const cellWidth = 250.0;
    final header = Container(
      color: kBlue,
      padding: const EdgeInsets.symmetric(vertical: 16),
      child: Row(children: [
        const SizedBox(
          width: subjectWidth,
          child: Padding(
            padding: EdgeInsets.only(left: 12),
            child: Text('Subject', style: _headStyle),
          ),
        ),
        for (final f in sc.formList)
          SizedBox(
            width: cellWidth,
            child: Padding(
              padding: const EdgeInsets.only(left: 12),
              child: Text(f, style: _headStyle),
            ),
          ),
      ]),
    );
    final rows = [
      for (final s in sc.subjectList)
        Container(
          decoration: const BoxDecoration(
            border: Border(bottom: BorderSide(color: Color(0xFFE0E0E0))),
          ),
          padding: const EdgeInsets.symmetric(vertical: 10),
          child: Row(children: [
            SizedBox(
              width: subjectWidth,
              child: Padding(
                padding: const EdgeInsets.only(left: 12),
                child: Text(s, style: const TextStyle(fontSize: 16)),
              ),
            ),
            for (final f in sc.formList)
              SizedBox(
                width: cellWidth,
                child: !sc.allows(s, f)
                    ? const Center(
                    child: Text('—',
                        style: TextStyle(color: Colors.black26, fontSize: 18)))
                    : _AssignmentCell(
                  subject: s,
                  form: f,
                  items: data[AssignmentRecord.keyFor(s, f)] ?? const [],
                  details: _details[AssignmentRecord.keyFor(s, f)],
                  service: _service,
                ),
              ),
          ]),
        ),
    ];
    return Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [header, ...rows]);
  }
}

class _AssignmentCell extends StatelessWidget {
  final String subject, form;
  final List<AssignmentRecord> items;
  final AssignmentDetails? details;
  final AssignmentService service;
  const _AssignmentCell({
    required this.subject,
    required this.form,
    required this.items,
    required this.details,
    required this.service,
  });

  @override
  Widget build(BuildContext context) {
    final has = items.isNotEmpty;
    final last = has ? items.last.createdAt : null;
    var teacher = details?.teacherName ?? '';
    if (teacher.isEmpty && has) {
      teacher = items.reversed
          .map((a) => a.teacherName)
          .firstWhere((n) => n.isNotEmpty, orElse: () => '');
    }
    final row = Row(
      mainAxisAlignment: MainAxisAlignment.center,
      children: [
        if (last != null)
          Padding(
            padding: const EdgeInsets.only(right: 6),
            child: Text(
              DateFormat('MM/dd/yyyy').format(last),
              style: const TextStyle(fontSize: 12, color: Colors.black54),
            ),
          ),
        // The button IS the upload button; it opens the list of assignments.
        ElevatedButton.icon(
          onPressed: () => showDialog(
            context: context,
            builder: (_) => AssignmentDialog(
                subject: subject, form: form, service: service),
          ),
          icon: Icon(has ? Icons.check : Icons.upload_file, size: 16),
          label: Text(has
              ? '${items.length} assignment${items.length == 1 ? '' : 's'}'
              : 'Pending'),
          style: ElevatedButton.styleFrom(
            backgroundColor: has ? kGreen : kRed,
            foregroundColor: Colors.white,
            padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 8),
            minimumSize: const Size(0, 34),
            shape:
            RoundedRectangleBorder(borderRadius: BorderRadius.circular(4)),
          ),
        ),
      ],
    );
    if (teacher.isEmpty) return row;
    return Column(mainAxisSize: MainAxisSize.min, children: [
      row,
      const SizedBox(height: 2),
      Text(teacher,
          style: const TextStyle(fontSize: 11, color: Colors.black54)),
    ]);
  }
}

/// Opened by every button. Same details as the exam dialog (teacher, footer,
/// marks, allowed time, heading table, formatting) plus the list of the
/// assignments already uploaded and a form to add one more.
class AssignmentDialog extends StatefulWidget {
  final String subject, form;
  final AssignmentService service;
  const AssignmentDialog({
    super.key,
    required this.subject,
    required this.form,
    required this.service,
  });

  @override
  State<AssignmentDialog> createState() => _AssignmentDialogState();
}

class _AssignmentDialogState extends State<AssignmentDialog> {
  final _title = TextEditingController();
  final _teacher = TextEditingController();
  final _footer = TextEditingController();
  final _marks = TextEditingController();
  final _time = TextEditingController();
  late final Stream<List<AssignmentRecord>> _stream =
  widget.service.watchFor(widget.subject, widget.form);
  // The starting ticks come from Settings > Exam upload.
  bool _addHeading = appSettings.value.uploadHeading;
  bool _autoFormat = appSettings.value.uploadAutoFormat;
  bool _numberQuestions = appSettings.value.uploadNumber;
  ExamHeading? _heading; // general heading, loaded from Firestore
  PlatformFile? _file;
  bool _busy = false;
  String? _status;
  List<AssignmentRecord> _items = const [];
  int _count = 0; // assignments already uploaded (for "Assignment N")

  String get _suggestedTitle => 'Assignment ${_count + 1}';
  String get _titleOrSuggested =>
      _title.text.trim().isEmpty ? _suggestedTitle : _title.text.trim();

  @override
  void initState() {
    super.initState();
    widget.service.exams.getHeading().then((h) {
      if (mounted) setState(() => _heading = h);
    }).catchError((_) {});
    _loadDetails();
  }

  /// Teacher, marks and time saved for this button (or, if nothing was
  /// saved yet, the teacher of the last assignment).
  Future<void> _loadDetails() async {
    try {
      final d = await widget.service.getDetails(widget.subject, widget.form);
      var t = d.teacherName;
      if (t.isEmpty) {
        final l =
        await widget.service.watchFor(widget.subject, widget.form).first;
        t = l.reversed
            .map((a) => a.teacherName)
            .firstWhere((n) => n.isNotEmpty, orElse: () => '');
      }
      if (!mounted) return;
      setState(() {
        if (_teacher.text.isEmpty) {
          _teacher.text = t;
          _footer.text = AssignmentService.footerFor(
              widget.subject, widget.form, t);
        }
        if (_marks.text.isEmpty) _marks.text = d.marks;
        if (_time.text.isEmpty) _time.text = d.allowedTime;
      });
    } catch (_) {}
  }

  @override
  void dispose() {
    _title.dispose();
    _teacher.dispose();
    _footer.dispose();
    _marks.dispose();
    _time.dispose();
    super.dispose();
  }

  void _toast(String m, {int seconds = 4}) {
    if (!mounted) return;
    ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(duration: Duration(seconds: seconds), content: Text(m)));
  }

  String _err(Object e) => '$e'.replaceFirst('Exception: ', '');

  Future<void> _pick() async {
    final res = await FilePicker.platform.pickFiles(
      withData: true,
      type: FileType.custom,
      allowedExtensions: ['docx', 'pdf', 'png', 'jpg', 'jpeg'],
    );
    if (res == null || res.files.isEmpty) return;
    final f = res.files.first;
    final ext = (f.extension ?? '').toLowerCase();
    if (!const ['docx', 'pdf', 'png', 'jpg', 'jpeg'].contains(ext)) {
      _toast(
          '"${f.name}" cannot be used. Use a Word (.docx) file. For .doc or '
              '.odt files, open them in Word and use Save As → Word Document (.docx).',
          seconds: 6);
      return;
    }
    setState(() => _file = f);
  }

  Future<void> _saveDetails() async {
    setState(() => _busy = true);
    final messenger = ScaffoldMessenger.of(context);
    final nav = Navigator.of(context);
    try {
      await widget.service.saveDetails(widget.subject, widget.form,
          teacher: _teacher.text.trim(),
          marks: _marks.text.trim(),
          allowedTime: _time.text.trim());
      nav.pop();
      messenger.showSnackBar(const SnackBar(content: Text('Saved')));
    } catch (e) {
      if (mounted) setState(() => _busy = false);
      messenger.showSnackBar(SnackBar(content: Text('Failed: ${_err(e)}')));
    }
  }

  Future<void> _markPending() async {
    final ok = await showDialog<bool>(
      context: context,
      builder: (ctx) => AlertDialog(
        title: const Text('Delete all assignments?'),
        content: Text(
            'Delete all ${_items.length} assignment${_items.length == 1 ? '' : 's'} '
                'of ${widget.subject} · ${widget.form}? This cannot be undone and '
                'the button will be marked as Pending.'),
        actions: [
          TextButton(
              onPressed: () => Navigator.pop(ctx, false),
              child: const Text('Cancel')),
          FilledButton(
              onPressed: () => Navigator.pop(ctx, true),
              child: const Text('Delete')),
        ],
      ),
    );
    if (ok != true || !mounted) return;
    setState(() => _busy = true);
    final messenger = ScaffoldMessenger.of(context);
    final nav = Navigator.of(context);
    try {
      await widget.service.deleteAll(widget.subject, widget.form);
      nav.pop();
      messenger.showSnackBar(const SnackBar(content: Text('Marked as pending')));
    } catch (e) {
      if (mounted) setState(() => _busy = false);
      messenger.showSnackBar(SnackBar(content: Text('Failed: ${_err(e)}')));
    }
  }

  /// Shows the finished document without saving anything.
  Future<void> _preview() async {
    final f = _file;
    if (f == null) return;
    setState(() {
      _busy = true;
      _status = 'Building preview...';
    });
    try {
      final p = await widget.service.exams.buildPreview(
        current: ExamRecord.empty(widget.subject, widget.form),
        file: f,
        footer: _footer.text.trim(),
        marks: _marks.text.trim(),
        allowedTime: _time.text.trim(),
        addHeading: _addHeading,
        autoFormat: _autoFormat,
        numberQuestions: _numberQuestions,
      );
      if (!mounted) return;
      if (p.isDocx) {
        // Word files cannot be drawn inside the app: download a copy to check.
        await _downloadInBrowser(p.bytes, p.name, ExamService._docxMime);
        _toast(
            'Preview downloaded. Open it in Word to check, then press Upload '
                'if it is correct.',
            seconds: 6);
      } else {
        await showDialog(
          context: context,
          builder: (_) => PreviewDialog(bytes: p.bytes),
        );
      }
    } catch (e) {
      _toast('Preview failed: ${_err(e)}');
    } finally {
      if (mounted) {
        setState(() {
          _busy = false;
          _status = null;
        });
      }
    }
  }

  Future<void> _upload() async {
    final f = _file;
    if (f == null) return;
    final title = _titleOrSuggested;
    setState(() {
      _busy = true;
      _status = 'Preparing...';
    });
    try {
      await widget.service.upload(
        subject: widget.subject,
        form: widget.form,
        title: title,
        teacher: _teacher.text.trim(),
        file: f,
        marks: _marks.text.trim(),
        allowedTime: _time.text.trim(),
        addHeading: _addHeading,
        autoFormat: _autoFormat,
        numberQuestions: _numberQuestions,
        onStatus: (t) {
          if (mounted) setState(() => _status = t);
        },
      );
      if (!mounted) return;
      setState(() {
        _file = null;
        _title.clear();
      });
      _toast('"$title" uploaded. You can add another one.');
    } catch (e) {
      _toast('Failed: ${_err(e)}', seconds: 6);
    } finally {
      if (mounted) {
        setState(() {
          _busy = false;
          _status = null;
        });
      }
    }
  }

  Future<void> _download(AssignmentRecord r) async {
    try {
      await widget.service.download(r);
    } catch (e) {
      _toast(_err(e));
    }
  }

  Future<void> _delete(AssignmentRecord r) async {
    final ok = await showDialog<bool>(
      context: context,
      builder: (ctx) => AlertDialog(
        title: const Text('Delete assignment?'),
        content: Text('Delete "${r.title}"? This cannot be undone.'),
        actions: [
          TextButton(
              onPressed: () => Navigator.pop(ctx, false),
              child: const Text('Cancel')),
          FilledButton(
              onPressed: () => Navigator.pop(ctx, true),
              child: const Text('Delete')),
        ],
      ),
    );
    if (ok != true || !mounted) return;
    try {
      await widget.service.delete(r);
      _toast('Deleted "${r.title}"');
    } catch (e) {
      _toast('Failed: ${_err(e)}');
    }
  }

  Widget _existing(List<AssignmentRecord> items) {
    return Column(children: [
      for (final r in items)
        ListTile(
          dense: true,
          contentPadding: EdgeInsets.zero,
          leading: const Icon(Icons.description),
          title: Text(r.title.isEmpty ? r.fileName : r.title,
              overflow: TextOverflow.ellipsis),
          subtitle: Text(
              [
                if (r.createdAt != null)
                  DateFormat('MM/dd/yyyy').format(r.createdAt!),
                '${(r.size / 1024).round()} KB',
              ].join(' · '),
              overflow: TextOverflow.ellipsis),
          trailing: Row(mainAxisSize: MainAxisSize.min, children: [
            IconButton(
              tooltip: 'Download',
              icon: const Icon(Icons.download),
              onPressed: _busy ? null : () => _download(r),
            ),
            IconButton(
              tooltip: 'Delete assignment',
              icon: const Icon(Icons.delete_outline),
              color: Theme.of(context).colorScheme.error,
              onPressed: _busy ? null : () => _delete(r),
            ),
          ]),
        ),
    ]);
  }

  @override
  Widget build(BuildContext context) {
    final preview = _heading?.build(widget.subject, widget.form,
        marks: _marks.text, time: _time.text);
    return AlertDialog(
      title: Text('${widget.subject} · ${widget.form}'),
      content: SizedBox(
        width: 420,
        child: SingleChildScrollView(
          child: Column(mainAxisSize: MainAxisSize.min, children: [
            TextField(
              controller: _teacher,
              textCapitalization: TextCapitalization.words,
              onChanged: (v) => setState(() => _footer.text =
                  AssignmentService.footerFor(widget.subject, widget.form, v)),
              decoration: const InputDecoration(
                labelText: "Teacher's name",
                prefixIcon: Icon(Icons.person),
                border: OutlineInputBorder(),
              ),
            ),
            const SizedBox(height: 12),
            TextField(
              controller: _footer,
              readOnly: true,
              maxLines: 2,
              decoration: const InputDecoration(
                labelText: 'Footer (auto-generated)',
                helperText: 'Built from subject, form and teacher name',
                filled: true,
                border: OutlineInputBorder(),
              ),
            ),
            const SizedBox(height: 12),
            Row(children: [
              Expanded(
                child: TextField(
                  controller: _marks,
                  onChanged: (_) => setState(() {}),
                  decoration: InputDecoration(
                    labelText: 'Marks',
                    hintText: _heading?.marks,
                    border: const OutlineInputBorder(),
                  ),
                ),
              ),
              const SizedBox(width: 12),
              Expanded(
                flex: 2,
                child: TextField(
                  controller: _time,
                  onChanged: (_) => setState(() {}),
                  decoration: InputDecoration(
                    labelText: 'Allowed time',
                    hintText: _heading?.defaultTimeFor(widget.subject),
                    border: const OutlineInputBorder(),
                  ),
                ),
              ),
            ]),
            const Padding(
              padding: EdgeInsets.only(top: 4),
              child: Align(
                alignment: Alignment.centerLeft,
                child: Text(
                  'Leave Marks / Allowed time empty to use the general values.',
                  style: TextStyle(fontSize: 11, color: Colors.black54),
                ),
              ),
            ),
            CheckboxListTile(
              dense: true,
              contentPadding: EdgeInsets.zero,
              controlAffinity: ListTileControlAffinity.leading,
              value: _addHeading,
              onChanged: _busy
                  ? null
                  : (v) => setState(() => _addHeading = v ?? true),
              title: const Text('Add exam heading table on the first page'),
            ),
            CheckboxListTile(
              dense: true,
              contentPadding: EdgeInsets.zero,
              controlAffinity: ListTileControlAffinity.leading,
              value: _autoFormat,
              onChanged: _busy
                  ? null
                  : (v) => setState(() => _autoFormat = v ?? true),
              title: const Text(
                  'Titles and questions bold, options (a, b, c, d) regular'),
            ),
            CheckboxListTile(
              dense: true,
              contentPadding: EdgeInsets.zero,
              controlAffinity: ListTileControlAffinity.leading,
              value: _numberQuestions,
              onChanged: (_busy || !_autoFormat)
                  ? null
                  : (v) => setState(() => _numberQuestions = v ?? true),
              title: const Text('Number the questions 1. 2. 3. in each part'),
            ),
            if (_addHeading && preview != null) _headingPreview(preview),
            const SizedBox(height: 16),
            // The assignments already uploaded for this button.
            StreamBuilder<List<AssignmentRecord>>(
              stream: _stream,
              builder: (context, snap) {
                if (snap.hasError) return Text('Error: ${snap.error}');
                if (!snap.hasData) {
                  return const Padding(
                    padding: EdgeInsets.all(12),
                    child: Center(child: CircularProgressIndicator()),
                  );
                }
                final items = snap.data!;
                _items = items;
                if (_count != items.length) {
                  // The hint "Assignment N" follows the number uploaded.
                  WidgetsBinding.instance.addPostFrameCallback((_) {
                    if (mounted) setState(() => _count = items.length);
                  });
                }
                if (items.isEmpty) return const SizedBox.shrink();
                return Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Text(
                          'Uploaded (${items.length})',
                          style: const TextStyle(fontWeight: FontWeight.w700)),
                      _existing(items),
                      const SizedBox(height: 8),
                    ]);
              },
            ),
            TextField(
              controller: _title,
              textCapitalization: TextCapitalization.sentences,
              onChanged: (_) => setState(() {}),
              decoration: InputDecoration(
                labelText: 'Assignment title',
                hintText: _suggestedTitle,
                prefixIcon: const Icon(Icons.title),
                border: const OutlineInputBorder(),
              ),
            ),
            const SizedBox(height: 10),
            Row(
              mainAxisSize: MainAxisSize.min,
              children: [
                Flexible(
                  child: OutlinedButton.icon(
                    onPressed: _busy ? null : _pick,
                    icon: const Icon(Icons.attach_file),
                    label: Text(
                      _file?.name ??
                          (_items.isNotEmpty
                              ? 'Choose another file'
                              : 'Choose file'),
                      overflow: TextOverflow.ellipsis,
                    ),
                  ),
                ),
                if (_file != null)
                  IconButton(
                    icon: const Icon(Icons.close),
                    tooltip: 'Remove selected file',
                    onPressed: _busy ? null : () => setState(() => _file = null),
                  ),
              ],
            ),
            const SizedBox(height: 6),
            const Text(
              'Word (.docx) recommended; PDF and images also work. The school '
                  'letterhead and the footer are added automatically to every '
                  'page. You can upload as many assignments as you need.',
              style: TextStyle(fontSize: 12, color: Colors.black54),
            ),
            if (_status != null) ...[
              const SizedBox(height: 10),
              Text(_status!, style: const TextStyle(fontSize: 12)),
            ],
            if (_busy) ...[
              const SizedBox(height: 6),
              const LinearProgressIndicator(),
            ],
          ]),
        ),
      ),
      actions: [
        if (_items.isNotEmpty)
          TextButton(
            onPressed: _busy ? null : _markPending,
            child: const Text('Mark pending'),
          ),
        TextButton(
          onPressed: _busy ? null : () => Navigator.pop(context),
          child: const Text('Cancel'),
        ),
        TextButton(
          onPressed: _busy ? null : _saveDetails,
          child: const Text('Save details'),
        ),
        OutlinedButton.icon(
          onPressed: (_busy || _file == null) ? null : _preview,
          icon: const Icon(Icons.visibility),
          label: const Text('Preview'),
        ),
        FilledButton.icon(
          onPressed: (_busy || _file == null) ? null : _upload,
          icon: const Icon(Icons.cloud_upload),
          label: const Text('Upload'),
        ),
      ],
    );
  }
}

