/// Goes back to the home route first (so no pushed screen stays on top of the
/// login page) and then signs out.
Future<void> _signOut(BuildContext context) async {
  Navigator.of(context).popUntil((r) => r.isFirst);
  await FirebaseAuth.instance.signOut();
}

/// The pages of the app that can be allowed or hidden for each user.
/// The keys are saved in Firestore, so do not rename them.
class AppPages {
  static const exam = 'exam';
  static const assignments = 'assignments';
  static const sections = 'sections';
  static const students = 'students';
  static const attendance = 'attendance';
  static const result = 'result';
  static const teachers = 'teachers';
  static const settings = 'settings';

  static const all = [
    exam,
    assignments,
    sections,
    students,
    attendance,
    result,
    teachers,
    settings,
  ];
  static const labels = {
    exam: 'Exam',
    assignments: 'Assignments',
    sections: 'Sections',
    students: 'Students',
    attendance: 'Attendance',
    result: 'Result',
    teachers: 'Teachers',
    settings: 'Settings',
  };
}

/// Who the signed-in person is and which pages they may open
/// (Firestore: users/{uid}).
///  - role 'admin'   : sees every page and manages the permissions.
///  - role 'teacher' / 'student': sees the pages in `access`; when `access`
///    is not set, the default of that role (Settings > Users & permissions).
///  - no profile document: an account made before permissions existed. It
///    keeps full access, as an administrator.
class UserProfile {
  final String uid, role, name, email;
  final String phone; // students: the first phone number (their username)
  final String studentId; // student accounts: the registered student record
  final List<String>? access;
  final bool legacy;

  /// Added in the Teachers tab; has not signed in for the first time yet.
  final bool pending;
  const UserProfile({
    required this.uid,
    required this.role,
    this.name = '',
    this.email = '',
    this.phone = '',
    this.studentId = '',
    this.access,
    this.legacy = false,
    this.pending = false,
  });

  static const roles = ['admin', 'teacher', 'student'];
  static String roleLabel(String r) =>
      r.isEmpty ? r : r[0].toUpperCase() + r.substring(1);

  bool get isAdmin => role == 'admin';

  List<String> effectiveAccess(AppSettings st) {
    if (isAdmin) return AppPages.all;
    final a = access;
    if (a != null) return a;
    return role == 'student' ? st.studentAccess : st.teacherAccess;
  }

  factory UserProfile.fromDoc(DocumentSnapshot<Map<String, dynamic>> d) {
    final m = d.data();
    if (m == null) return UserProfile(uid: d.id, role: 'admin', legacy: true);
    final r = '${m['role'] ?? 'teacher'}';
    final a = m['access'];
    return UserProfile(
      uid: d.id,
      role: roles.contains(r) ? r : 'teacher',
      name: '${m['name'] ?? ''}',
      email: '${m['email'] ?? ''}',
      phone: '${m['phone'] ?? ''}',
      studentId: '${m['studentId'] ?? ''}',
      pending: m['pendingLogin'] == true,
      access: a is List
          ? [
        for (final e in a)
          if (e is String && AppPages.all.contains(e)) e
      ]
          : null,
    );
  }

  /// The profile of the signed-in person, live.
  static Stream<UserProfile> watchMine() {
    final uid = FirebaseAuth.instance.currentUser?.uid ?? '';
    return FirebaseFirestore.instance
        .collection('users')
        .doc(uid)
        .snapshots()
        .map(UserProfile.fromDoc);
  }
}

final _profilesEnsured = <String>{};

/// Every account must be a user in the list (Firestore: users/{uid}).
/// Accounts made before permissions existed have no profile yet, so one is
/// created the first time they open the app:
///  - when there is no administrator yet, that account becomes the
///    administrator (the owner of the app);
///  - every other old account becomes a Teacher with the default access.
/// The administrator can change roles and access in Settings.
Future<void> ensureUserProfile(User user) async {
  if (!_profilesEnsured.add(user.uid)) return; // once per account and session
  try {
    final users = FirebaseFirestore.instance.collection('users');
    final mine = users.doc(user.uid);
    if ((await mine.get()).exists) return;
    final admins = await users.where('role', isEqualTo: 'admin').limit(1).get();
    final email = user.email ?? '';
    await mine.set({
      'role': admins.docs.isEmpty ? 'admin' : 'teacher',
      'name': email.contains('@') ? email.split('@').first : email,
      'email': email,
      'createdAt': FieldValue.serverTimestamp(),
    });
  } catch (e) {
    debugPrint('User profile could not be created: $e');
  }
}

/// subject -> forms taught, read from a teacher document. Records saved
/// before per-subject forms existed only have the two lists `subjects` and
/// `forms`: every subject then applies to every form of the teacher.
Map<String, List<String>> parseTeacherAssignments(Map? m) {
  final out = <String, List<String>>{};
  final a = m?['assignments'];
  if (a is Map) {
    for (final s in ExamService.subjects) {
      final v = a[s];
      if (v is List) {
        final fs = [
          for (final f in ExamService.forms)
            if (v.contains(f)) f
        ];
        if (fs.isNotEmpty) out[s] = fs;
      }
    }
    if (out.isNotEmpty) return out;
  }
  List<String> list(String k) {
    final v = m?[k];
    return v is List ? [for (final e in v) if (e is String) e] : <String>[];
  }

  final subs = list('subjects'), forms = list('forms');
  if (subs.isNotEmpty && forms.isNotEmpty) {
    for (final s in ExamService.subjects) {
      if (subs.contains(s)) {
        out[s] = [
          for (final f in ExamService.forms)
            if (forms.contains(f)) f
        ];
      }
    }
  }
  return out;
}

/// The forms used by any subject of [a] (in the usual order).
List<String> formsOfAssignments(Map<String, List<String>> a) => [
  for (final f in ExamService.forms)
    if (a.values.any((l) => l.contains(f))) f
];

/// "Islamic (Form3, Form4) · Maths (Form4)"
String assignmentsText(Map<String, List<String>> a) => [
  for (final s in ExamService.subjects)
    if (a[s] != null && a[s]!.isNotEmpty) '$s (${a[s]!.join(', ')})'
].join(' · ');

/// What a teacher may see: ONLY the subjects and forms (classes) that were
/// filled in when the account was created (Firestore: teachers/{uid}).
/// Administrators, students and old accounts without a profile are not
/// restricted by this.
class TeacherScope {
  final bool restricted;

  /// Set by the administrator (Teachers > edit): this person sees EVERY
  /// section to take attendance, but still no exam marks of other subjects.
  final bool allSections;
  final List<String> subjects, forms;

  /// subject -> the forms in which this teacher teaches that subject.
  final Map<String, List<String>> assignments;

  /// A student account: sees only the own record (see [_LinkStudentBody]).
  final bool isStudent;
  final String studentId, sectionId;
  const TeacherScope({
    this.restricted = false,
    this.allSections = false,
    this.subjects = const [],
    this.forms = const [],
    this.assignments = const {},
    this.isStudent = false,
    this.studentId = '',
    this.sectionId = '',
  });

  /// Limited to a part of the data (a teacher or a student).
  bool get scoped => restricted || isStudent;

  static const open = TeacherScope();

  /// The subjects this person may see (in the usual order).
  List<String> get subjectList => restricted
      ? [for (final s in ExamService.subjects) if (subjects.contains(s)) s]
      : ExamService.subjects;

  /// The forms this person may see (in the usual order).
  List<String> get formList => restricted
      ? [for (final f in ExamService.forms) if (forms.contains(f)) f]
      : ExamService.forms;

  bool allowsSubject(String s) => !restricted || subjects.contains(s);
  bool allowsForm(String f) => !restricted || forms.contains(f);

  /// True when this person teaches [subject] in [form] (the exact pair).
  bool allows(String subject, String form) {
    if (!restricted) return true;
    if (assignments.isNotEmpty) {
      return assignments[subject]?.contains(form) ?? false;
    }
    return subjects.contains(subject) && forms.contains(form);
  }

  List<SectionInfo> filterSections(List<SectionInfo> l) {
    if (isStudent) return [for (final s in l) if (s.id == sectionId) s];
    if (allSections) return l;
    return restricted ? [for (final s in l) if (forms.contains(s.form)) s] : l;
  }
}

/// The scope of the signed-in person. Kept up to date by [_ScopeGate].
final ValueNotifier<TeacherScope> teacherScope =
ValueNotifier(TeacherScope.open);

/// Loads the scope (role + subjects + forms) of the signed-in person and
/// shows [child] only once it is known, so a teacher never sees, even for a
/// moment, something that is not theirs.
class _ScopeGate extends StatefulWidget {
  final Widget child;
  const _ScopeGate({required this.child});

  @override
  State<_ScopeGate> createState() => _ScopeGateState();
}

class _ScopeGateState extends State<_ScopeGate> {
  StreamSubscription<DocumentSnapshot<Map<String, dynamic>>>? _userSub;
  StreamSubscription<DocumentSnapshot<Map<String, dynamic>>>? _teacherSub;
  StreamSubscription<DocumentSnapshot<Map<String, dynamic>>>? _stuSub;
  Map<String, dynamic>? _user, _teacher, _stu;
  bool _userDone = false, _teacherDone = false, _stuDone = true;
  String _stuWatched = '';

  bool get _ready => _userDone && _teacherDone && _stuDone;

  @override
  void initState() {
    super.initState();
    final uid = FirebaseAuth.instance.currentUser?.uid;
    if (uid == null) {
      _userDone = _teacherDone = true;
      return;
    }
    final db = FirebaseFirestore.instance;
    _userSub = db.collection('users').doc(uid).snapshots().listen((d) {
      _user = d.data();
      _userDone = true;
      _update();
    }, onError: (_) {
      _user = null; // profile unreadable (rules problem): nothing is hidden
      _userDone = true;
      _update();
    });
    _teacherSub = db.collection('teachers').doc(uid).snapshots().listen((d) async {
      _teacher = d.data();
      if (_teacher == null) {
        // Added by the administrator: the record has its own id, so find it
        // by the email of this account.
        final mail = FirebaseAuth.instance.currentUser?.email ?? '';
        if (mail.isNotEmpty) {
          try {
            final t = await findTeacherByEmail(mail);
            if (t != null) {
              _teacher = {
                'allSections': t.allSections,
                'subjects': t.subjects,
                'forms': t.forms,
                'assignments': t.assignments,
              };
            }
          } catch (_) {}
        }
      }
      _teacherDone = true;
      if (mounted) _update();
    }, onError: (_) {
      _teacher = null;
      _teacherDone = true;
      _update();
    });
  }

  List<String> _list(String k) {
    final v = _teacher?[k];
    return v is List ? [for (final e in v) if (e is String) e] : <String>[];
  }

  void _update() {
    final role = _user == null ? '' : '${_user!['role']}';
    if (role == 'student') {
      final sid = '${_user!['studentId'] ?? ''}';
      if (sid != _stuWatched) {
        _stuSub?.cancel();
        _stuWatched = sid;
        _stu = null;
        if (sid.isEmpty) {
          _stuDone = true;
        } else {
          _stuDone = false;
          _stuSub = FirebaseFirestore.instance
              .collection('students')
              .doc(sid)
              .snapshots()
              .listen((d) {
            _stu = d.data();
            _stuDone = true;
            _update();
          }, onError: (_) {
            _stu = null;
            _stuDone = true;
            _update();
          });
        }
      }
    }
    if (!_ready) return;
    if (role == 'student') {
      teacherScope.value = TeacherScope(
        isStudent: true,
        studentId: _stuWatched,
        sectionId: '${_stu?['sectionId'] ?? ''}',
      );
    } else if (role == 'teacher') {
      final asg = parseTeacherAssignments(_teacher);
      teacherScope.value = TeacherScope(
          restricted: true,
          // only when the administrator ticked it for this person
          allSections: _teacher?['allSections'] == true,
          subjects: [
            for (final s in ExamService.subjects)
              if (asg.containsKey(s)) s
          ],
          forms: formsOfAssignments(asg),
          assignments: asg);
    } else {
      teacherScope.value = TeacherScope.open;
    }
    if (mounted) setState(() {});
  }

  @override
  void dispose() {
    _userSub?.cancel();
    _teacherSub?.cancel();
    _stuSub?.cancel();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    if (!_ready) {
      return const Scaffold(body: Center(child: CircularProgressIndicator()));
    }
    return widget.child;
  }
}

/// True while a new account is being created, so the home screen is not
/// shown before its profile exists.
final ValueNotifier<bool> signUpBusy = ValueNotifier(false);

/// A message for the login screen (e.g. why a sign up was undone).
final ValueNotifier<String?> loginNotice = ValueNotifier(null);

/// First sign in of a student: search the name in the list of students that
/// the school registered, and link this account to it. Only students that
/// are not linked to another account can be chosen.
class _LinkStudentBody extends StatefulWidget {
  final String uid;
  const _LinkStudentBody({required this.uid});

  @override
  State<_LinkStudentBody> createState() => _LinkStudentBodyState();
}

class _LinkStudentBodyState extends State<_LinkStudentBody> {
  final _db = FirebaseFirestore.instance;
  final _q = TextEditingController();
  late final Stream<QuerySnapshot<Map<String, dynamic>>> _stu =
  _db.collection('students').snapshots();
  late final Stream<List<SectionInfo>> _sec = _db
      .collection('sections')
      .snapshots()
      .map((s) => s.docs.map(SectionInfo.fromDoc).toList());
  bool _busy = false;
  String? _error;

  @override
  void dispose() {
    _q.dispose();
    super.dispose();
  }

  Future<void> _link(String studentId, String name, SectionInfo? sec) async {
    final ok = await showDialog<bool>(
      context: context,
      builder: (ctx) => AlertDialog(
        title: const Text('Is this you?'),
        content: Text('$name${sec == null ? '' : '\n${sec.label}'}'),
        actions: [
          TextButton(
              onPressed: () => Navigator.pop(ctx, false),
              child: const Text('No')),
          FilledButton(
              onPressed: () => Navigator.pop(ctx, true),
              child: const Text('Yes, link my account')),
        ],
      ),
    );
    if (ok != true || !mounted) return;
    setState(() {
      _busy = true;
      _error = null;
    });
    try {
      // Check first (a student can belong to one account only), then write
      // both documents together.
      final ref = _db.collection('students').doc(studentId);
      final snap = await ref.get();
      if (!snap.exists) throw Exception('This student no longer exists.');
      final owner = snap.data()?['accountUid'];
      if (owner is String && owner.isNotEmpty && owner != widget.uid) {
        throw Exception('This student is already linked to another account.');
      }
      final batch = _db.batch();
      batch.update(ref, {'accountUid': widget.uid});
      batch.set(
          _db.collection('users').doc(widget.uid),
          {
            'studentId': studentId,
            'name': name,
            if (sec != null) 'form': sec.form,
          },
          SetOptions(merge: true));
      await batch.commit();
      // The home screen reloads by itself and shows the student's data.
    } catch (e) {
      if (mounted) {
        setState(() {
          _busy = false;
          _error = _linkWhy(e);
        });
      }
    }
  }

  /// A readable reason. On the web, Firestore errors arrive "boxed", so the
  /// real error is taken out of the box.
  static String _linkWhy(Object e) {
    if (e is FirebaseException) {
      final hint = e.code == 'permission-denied'
          ? '\nThe Firestore rules do not allow this account to write to '
          '"students" or "users". Check them in the Firebase console.'
          : '';
      return '${e.code}: ${e.message ?? ''}$hint';
    }
    try {
      final inner = (e as dynamic).error;
      if (inner != null) return _linkWhy(inner as Object);
    } catch (_) {}
    return '$e'.replaceFirst('Exception: ', '');
  }

  @override
  Widget build(BuildContext context) {
    return Align(
      alignment: Alignment.topCenter,
      child: ConstrainedBox(
        constraints: const BoxConstraints(maxWidth: 560),
        child: StreamBuilder<QuerySnapshot<Map<String, dynamic>>>(
          stream: _stu,
          builder: (context, stuSnap) => StreamBuilder<List<SectionInfo>>(
            stream: _sec,
            builder: (context, secSnap) {
              final err = stuSnap.error ?? secSnap.error;
              if (err != null) {
                return Center(child: Text('Error: $err'));
              }
              if (!stuSnap.hasData || !secSnap.hasData) {
                return const Center(child: CircularProgressIndicator());
              }
              final secOf = {for (final s in secSnap.data!) s.id: s};
              final query = _q.text.trim();
              final found = query.length < 2
                  ? const <QueryDocumentSnapshot<Map<String, dynamic>>>[]
                  : [
                for (final d in stuSnap.data!.docs)
                  if (_nameMatches('${d.data()['name'] ?? ''}', query) &&
                      '${d.data()['accountUid'] ?? ''}'.isEmpty)
                    d
              ];
              return ListView(
                padding: const EdgeInsets.all(16),
                children: [
                  const Text('Find your name',
                      style:
                      TextStyle(fontSize: 22, fontWeight: FontWeight.bold)),
                  const SizedBox(height: 6),
                  Text(
                      'Type your name as the school registered it, then choose '
                          'it. This links your account to your own results.',
                      style: TextStyle(color: Colors.grey.shade700)),
                  const SizedBox(height: 14),
                  TextField(
                    controller: _q,
                    enabled: !_busy,
                    onChanged: (_) => setState(() => _error = null),
                    decoration: const InputDecoration(
                      hintText: 'Search your name',
                      prefixIcon: Icon(Icons.search),
                      border: OutlineInputBorder(),
                      isDense: true,
                    ),
                  ),
                  if (_error != null)
                    Padding(
                      padding: const EdgeInsets.only(top: 10),
                      child: Text(_error!,
                          style: const TextStyle(color: Colors.red)),
                    ),
                  const SizedBox(height: 10),
                  if (query.length < 2)
                    const Padding(
                      padding: EdgeInsets.all(16),
                      child: Text('Type at least 2 letters of your name.',
                          textAlign: TextAlign.center),
                    )
                  else if (found.isEmpty)
                    const Padding(
                      padding: EdgeInsets.all(16),
                      child: Text(
                          'No available student matches.\n'
                              'If your name is not registered, or it is already '
                              'linked to another account, ask your teacher.',
                          textAlign: TextAlign.center),
                    )
                  else
                    for (final d in found.take(30))
                      Card(
                        margin: const EdgeInsets.symmetric(vertical: 3),
                        child: ListTile(
                          enabled: !_busy,
                          leading: const CircleAvatar(
                              radius: 16, child: Icon(Icons.person, size: 18)),
                          title: Text('${d.data()['name'] ?? ''}',
                              style:
                              const TextStyle(fontWeight: FontWeight.w600)),
                          subtitle: Text(
                              secOf['${d.data()['sectionId'] ?? ''}']?.label ??
                                  ''),
                          trailing: const Icon(Icons.chevron_right),
                          onTap: () => _link(
                              d.id,
                              '${d.data()['name'] ?? ''}',
                              secOf['${d.data()['sectionId'] ?? ''}']),
                        ),
                      ),
                  if (_busy)
                    const Padding(
                      padding: EdgeInsets.all(16),
                      child: Center(child: CircularProgressIndicator()),
                    ),
                ],
              );
            },
          ),
        ),
      ),
    );
  }
}

