              profile.studentId.isNotEmpty) {
            // A student only sees the own results and attendance.
            return ValueListenableBuilder<AppSettings>(
              valueListenable: appSettings,
              builder: (context, st, _) => StudentPortal(
                  studentId: profile.studentId,
                  allowed: profile.effectiveAccess(st)),
            );
          }
          return ValueListenableBuilder<AppSettings>(
            valueListenable: appSettings,
            builder: (context, st, _) {
              final allowed =
              profile == null ? AppPages.all : profile.effectiveAccess(st);
              final items = [
                for (final i in _items)
                  if (allowed.contains(i.page)) i
              ];
              if (items.isEmpty) {
                return const Center(
                  child: Padding(
                    padding: EdgeInsets.all(24),
                    child: Text(
                        'Your account has no access to any page yet.\n'
                            'Ask the administrator to give you access.',
                        textAlign: TextAlign.center),
                  ),
                );
              }
              return Center(
                child: SingleChildScrollView(
                  padding: const EdgeInsets.all(24),
                  child: Wrap(
                    spacing: 20,
                    runSpacing: 20,
                    alignment: WrapAlignment.center,
                    children: [for (final i in items) _HomeCard(item: i)],
                  ),
                ),
              );
            },
          );
        },
      ),
    );
  }
}

class _HomeCard extends StatelessWidget {
  final _HomeItem item;
  const _HomeCard({required this.item});

  @override
  Widget build(BuildContext context) {
    return SizedBox(
      width: 250,
      height: 210,
      child: Card(
        clipBehavior: Clip.antiAlias,
        elevation: 2,
        child: InkWell(
          onTap: () => Navigator.of(context)
              .push(MaterialPageRoute(builder: item.builder)),
          child: Padding(
            padding: const EdgeInsets.all(16),
            child: Column(
              mainAxisAlignment: MainAxisAlignment.center,
              children: [
                CircleAvatar(
                  radius: 36,
                  backgroundColor: item.color.withOpacity(0.15),
                  child: Icon(item.icon, size: 38, color: item.color),
                ),
                const SizedBox(height: 14),
                Text(item.title,
                    style: const TextStyle(
                        fontSize: 20, fontWeight: FontWeight.bold)),
                const SizedBox(height: 6),
                Text(item.subtitle,
                    textAlign: TextAlign.center,
                    style:
                    const TextStyle(fontSize: 12, color: Colors.black54)),
              ],
            ),
          ),
        ),
      ),
    );
  }
}

// ======================= SCHOOL LOGO =======================

/// The places where the school logo can be shown. The keys are saved in
/// Firestore (settings/logo), so do not rename them.
class LogoPlace {
  static const login = 'login';
  static const home = 'home';
  static const exam = 'exam';
  static const sections = 'sections';
  static const attendance = 'attendance';
  static const result = 'result';

  static const all = [login, home, exam, sections, attendance, result];

  /// Places that are printed documents (they can also have a watermark).
  static const documents = [exam, sections, attendance, result];

  static const labels = {
    login: 'Login screen',
    home: 'Home screen (top bar)',
    exam: 'Exam papers (PDF and Word)',
    sections: 'Section lists (PDF and Word)',
    attendance: 'Attendance report (PDF and Word)',
    result: 'Result report (PDF, Excel and Word)',
  };
}

/// The school logo and where it is shown. Saved once for the whole school
/// (Firestore: settings/logo).
class SchoolLogo {
  final Uint8List? bytes; // PNG
  final int w, h; // pixel size of the image
  final List<String> places; // where it is shown
  final String align; // left | center | right (documents only)
  final double height; // printed height in points (documents only)
  final List<String> watermarkPlaces; // documents with a faded watermark
  final double wmOpacity; // 0.05 - 0.40 (how strong the watermark is)
  final double wmSize; // 0.30 - 0.90 (watermark width / page width)

  const SchoolLogo({
    this.bytes,
    this.w = 1,
    this.h = 1,
    this.places = LogoPlace.all,
    this.align = 'center',
    this.height = 60,
    this.watermarkPlaces = const [],
    this.wmOpacity = 0.12,
    this.wmSize = 0.6,
  });

  static const aligns = ['left', 'center', 'right'];

  /// True when a logo is saved AND it is switched on for [place].
  bool at(String place) => bytes != null && places.contains(place);

  /// True when a logo is saved AND the watermark is switched on for [place].
  bool wm(String place) => bytes != null && watermarkPlaces.contains(place);

  /// True when the image is needed in a document (logo and / or watermark).
  bool uses(String place) => at(place) || wm(place);

  factory SchoolLogo.fromMap(Map<String, dynamic> m) {
    const d = SchoolLogo();
    Uint8List? bytes;
    final b64 = m['logoBase64'];
    if (b64 is String && b64.isNotEmpty) {
      try {
        bytes = base64Decode(b64);
      } catch (_) {}
    }
    int px(String k) {
      final v = m[k];
      return v is num && v > 0 ? v.toInt() : 1;
    }

    final lp = m['places'];
    final al = m['align'];
    final ht = m['height'];
    final wp = m['watermarkPlaces'];
    final wo = m['wmOpacity'];
    final ws = m['wmSize'];
    return SchoolLogo(
      bytes: bytes,
      w: px('w'),
      h: px('h'),
      places: lp is List
          ? [
        for (final e in lp)
          if (e is String && LogoPlace.all.contains(e)) e,
      ]
          : d.places,
      align: al is String && aligns.contains(al) ? al : d.align,
      height: ht is num ? ht.toDouble().clamp(30.0, 120.0).toDouble() : d.height,
      watermarkPlaces: wp is List
          ? [
        for (final e in wp)
          if (e is String && LogoPlace.documents.contains(e)) e,
      ]
          : d.watermarkPlaces,
      wmOpacity:
      wo is num ? wo.toDouble().clamp(0.05, 0.4).toDouble() : d.wmOpacity,
      wmSize: ws is num ? ws.toDouble().clamp(0.3, 0.9).toDouble() : d.wmSize,
    );
  }
}

/// Holds the current [SchoolLogo] and keeps it in sync with Firestore.
/// It starts when the app opens (so the login screen can show the logo) and
/// is started again after sign-in, in case the rules need a signed-in user.
class SchoolLogoController extends ValueNotifier<SchoolLogo> {
  SchoolLogoController() : super(const SchoolLogo());

  StreamSubscription<DocumentSnapshot<Map<String, dynamic>>>? _sub;

  DocumentReference<Map<String, dynamic>> get _doc =>
      FirebaseFirestore.instance.collection('settings').doc('logo');

  void start() {
    _sub ??= _doc.snapshots().listen(
          (d) => value = SchoolLogo.fromMap(d.data() ?? {}),
      onError: (e) {
        debugPrint('Logo could not be loaded: $e');
        _sub?.cancel();
        _sub = null; // lets start() try again after sign-in
      },
    );
  }

  /// Saves only the given fields. The live listener then updates [value].
  Future<void> update(Map<String, Object?> fields) => _doc.set({
    ...fields,
    'updatedBy': FirebaseAuth.instance.currentUser?.uid,
    'updatedAt': FieldValue.serverTimestamp(),
  }, SetOptions(merge: true)).timeout(const Duration(seconds: 30),
      onTimeout: () {
        throw Exception('Saving timed out. Check the internet connection.');
      });

  /// Stores a new logo (any PNG / JPG; it is saved as a PNG).
  Future<void> setImage(Uint8List picked) async {
    if (picked.length > 1024 * 1024) {
      throw Exception('This image is too large. Please use one under 1 MB.');
    }
    final ({Uint8List png, int w, int h}) info;
    try {
      info = await ExamService()._toPngInfo(picked);
    } catch (_) {
      throw Exception(
          'This file is not a readable image. Please use a PNG or JPG.');
    }
    // Firestore documents are limited to about 1 MB.
    if (info.png.length > 700 * 1024) {
      throw Exception('The logo is too large. Please use a smaller image.');
    }
    await update({
      'logoBase64': base64Encode(info.png),
      'w': info.w,
      'h': info.h,
    });
  }

  Future<void> removeImage() => update({
    'logoBase64': FieldValue.delete(),
    'w': FieldValue.delete(),
    'h': FieldValue.delete(),
  });
}

final schoolLogo = SchoolLogoController();

/// The logo as a Flutter widget for [place], or [fallback] when it is off.
class AppLogo extends StatelessWidget {
  final String place;
  final double height;
  final Widget fallback;
  const AppLogo({
    super.key,
    required this.place,
    required this.height,
    this.fallback = const SizedBox.shrink(),
  });

  @override
  Widget build(BuildContext context) {
    return ValueListenableBuilder<SchoolLogo>(
      valueListenable: schoolLogo,
      builder: (context, l, _) => l.at(place)
          ? Image.memory(l.bytes!,
          height: height, fit: BoxFit.contain, gaplessPlayback: true)
          : fallback,
    );
  }
}

/// The logo as a PDF image for [place] (null = not wanted there). Create it
/// ONCE per document so a many-page PDF does not embed it again and again.
pw.MemoryImage? pdfLogoImage(String place) {
  final l = schoolLogo.value;
  return l.at(place) ? pw.MemoryImage(l.bytes!) : null;
}

/// The logo row at the top of a PDF page, aligned as set in Settings.
pw.Widget pdfLogoBlock(pw.MemoryImage img) {
  final l = schoolLogo.value;
  return pw.Container(
    width: double.infinity,
    alignment: l.align == 'left'
        ? pw.Alignment.centerLeft
        : l.align == 'right'
        ? pw.Alignment.centerRight
        : pw.Alignment.center,
    margin: const pw.EdgeInsets.only(bottom: 6),
    child: pw.Image(img, height: l.height, fit: pw.BoxFit.contain),
  );
}

/// Height (points) the logo takes at the top of a page (0 = not shown).
double logoReserve(String place) =>
    schoolLogo.value.at(place) ? schoolLogo.value.height + 6 : 0;

/// Faded logo in the middle of every page, behind the content (PDF).
/// null = no watermark wanted for [place]. Create it ONCE per document.
pw.BuildCallback? pdfWatermark(String place) {
  final l = schoolLogo.value;
  if (!l.wm(place)) return null;
  final img = pw.MemoryImage(l.bytes!);
  return (ctx) => pw.FullPage(
    ignoreMargins: true,
    child: pw.Center(
      child: pw.Opacity(
        opacity: l.wmOpacity,
        child: pw.Image(img,
            width: PdfPageFormat.a4.width * l.wmSize, fit: pw.BoxFit.contain),
      ),
    ),
  );
}

/// A4 page settings with an optional watermark [background].
pw.PageTheme pdfPageTheme(pw.EdgeInsets margin,
    {pw.BuildCallback? background, pw.ThemeData? theme}) =>
    pw.PageTheme(
      pageFormat: PdfPageFormat.a4,
      margin: margin,
      theme: theme,
      buildBackground: background,
    );

const _docxNs =
    'xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main" '
    'xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships" '
    'xmlns:wp="http://schemas.openxmlformats.org/drawingml/2006/wordprocessingDrawing" '
    'xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main" '
    'xmlns:pic="http://schemas.openxmlformats.org/drawingml/2006/picture"';

/// Paragraph (for a Word HEADER) with the faded logo centred on the page,
/// behind the text. It is 1 pt high so it does not move the content.
String docxWatermarkPara(String place,
    {required String rid, required int docPrId}) {
  final l = schoolLogo.value;
  if (!l.wm(place)) return '';
  const pageW = 595.0; // A4 width in points
  var cx = pageW * l.wmSize * 12700;
  var cy = cx * l.h / l.w;
  const maxCy = 700.0 * 12700;
  if (cy > maxCy) {
    cx = cx * maxCy / cy;
    cy = maxCy;
  }
  final amt = (l.wmOpacity * 100000).round(); // 100000 = fully visible
  return '<w:p><w:pPr><w:spacing w:before="0" w:after="0" w:line="20" w:lineRule="exact"/></w:pPr>'
      '<w:r><w:drawing>'
      '<wp:anchor distT="0" distB="0" distL="0" distR="0" simplePos="0" '
      'relativeHeight="0" behindDoc="1" locked="0" layoutInCell="1" allowOverlap="1">'
      '<wp:simplePos x="0" y="0"/>'
      '<wp:positionH relativeFrom="page"><wp:align>center</wp:align></wp:positionH>'
      '<wp:positionV relativeFrom="page"><wp:align>center</wp:align></wp:positionV>'
      '<wp:extent cx="${cx.round()}" cy="${cy.round()}"/>'
      '<wp:effectExtent l="0" t="0" r="0" b="0"/><wp:wrapNone/>'
      '<wp:docPr id="$docPrId" name="School logo watermark"/><wp:cNvGraphicFramePr/>'
      '<a:graphic><a:graphicData uri="http://schemas.openxmlformats.org/drawingml/2006/picture">'
      '<pic:pic><pic:nvPicPr><pic:cNvPr id="0" name="school_logo.png"/><pic:cNvPicPr/></pic:nvPicPr>'
      '<pic:blipFill><a:blip r:embed="$rid"><a:alphaModFix amt="$amt"/></a:blip>'
      '<a:stretch><a:fillRect/></a:stretch></pic:blipFill>'
      '<pic:spPr><a:xfrm><a:off x="0" y="0"/><a:ext cx="${cx.round()}" cy="${cy.round()}"/></a:xfrm>'
      '<a:prstGeom prst="rect"><a:avLst/></a:prstGeom></pic:spPr></pic:pic>'
      '</a:graphicData></a:graphic></wp:anchor></w:drawing></w:r></w:p>';
}

/// The relationship line that links the watermark image inside a header.
String docxWmRel(String place, String rid) => schoolLogo.value.wm(place)
    ? '<Relationship Id="$rid" Type="$_docxImageRel" Target="media/school_logo.png"/>'
    : '';

/// For Word files built from scratch (no header yet): the extra files that
/// add a header holding only the watermark. Empty when it is off.
Map<String, List<int>> docxWatermarkFiles(String place) {
  if (!schoolLogo.value.wm(place)) return const {};
  const head = '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>';
  return {
    'word/header_wm.xml': utf8.encode('$head<w:hdr $_docxNs>'
        '${docxWatermarkPara(place, rid: 'rId1', docPrId: 9300)}</w:hdr>'),
    'word/_rels/header_wm.xml.rels': utf8.encode('$head'
        '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'
        '${docxWmRel(place, 'rId1')}</Relationships>'),
  };
}

/// Link from document.xml.rels to that header.
String docxWmHeaderRel(String place) => schoolLogo.value.wm(place)
    ? '<Relationship Id="rIdWmHdr" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/header" Target="header_wm.xml"/>'
    : '';

/// Content-type line of that header.
String docxWmHeaderOverride(String place) => schoolLogo.value.wm(place)
    ? '<Override PartName="/word/header_wm.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.header+xml"/>'
    : '';

/// First child of <w:sectPr>: makes the page use that header.
String docxWmSectRef(String place) => schoolLogo.value.wm(place)
    ? '<w:headerReference w:type="default" r:id="rIdWmHdr"/>'
    : '';

const _docxImageRel =
    'http://schemas.openxmlformats.org/officeDocument/2006/relationships/image';

/// Paragraph with the logo for a Word file ('' when it is off for [place]).
/// The image must be added as word/media/school_logo.png and linked with
/// [docxLogoRel] under the same [rid].
String docxLogoPara(String place, {required String rid, required int docPrId}) {
  final l = schoolLogo.value;
  if (!l.at(place)) return '';
  var cy = (l.height * 12700).round(); // 1 pt = 12700 EMU
  var cx = (cy * l.w / l.h).round();
  const maxCx = 5486400; // 6 in
  if (cx > maxCx) {
    cy = (cy * maxCx / cx).round();
    cx = maxCx;
  }
  return '<w:p><w:pPr><w:spacing w:before="0" w:after="80"/>'
      '<w:jc w:val="${l.align}"/></w:pPr><w:r><w:drawing>'
      '<wp:inline distT="0" distB="0" distL="0" distR="0">'
      '<wp:extent cx="$cx" cy="$cy"/><wp:docPr id="$docPrId" name="School logo"/>'
      '<a:graphic><a:graphicData uri="http://schemas.openxmlformats.org/drawingml/2006/picture">'
      '<pic:pic><pic:nvPicPr><pic:cNvPr id="0" name="school_logo.png"/><pic:cNvPicPr/></pic:nvPicPr>'
      '<pic:blipFill><a:blip r:embed="$rid"/><a:stretch><a:fillRect/></a:stretch></pic:blipFill>'
      '<pic:spPr><a:xfrm><a:off x="0" y="0"/><a:ext cx="$cx" cy="$cy"/></a:xfrm>'
      '<a:prstGeom prst="rect"><a:avLst/></a:prstGeom></pic:spPr></pic:pic>'
      '</a:graphicData></a:graphic></wp:inline></w:drawing></w:r></w:p>';
}

/// The relationship line that links the logo image in a Word file.
String docxLogoRel(String place, String rid) => schoolLogo.value.at(place)
    ? '<Relationship Id="$rid" Type="$_docxImageRel" Target="media/school_logo.png"/>'
    : '';

/// A "png" content-type line, for Word files that may not have one yet.
String docxLogoPngDefault(String place) => schoolLogo.value.uses(place)
    ? '<Default Extension="png" ContentType="image/png"/>'
    : '';

// ======================= SETTINGS =======================

/// The general settings of the app. They are saved once for the whole school
/// (Firestore: settings/app), so every teacher sees the same values.
/// A missing or invalid value falls back to the default given below.
/// Mark limits of ONE exam.
class ExamLimits {
  /// Lowest / highest mark of one subject.
  final double minMark, maxMark;

  /// Lowest / highest TOTAL (sum of the subject marks) of a student.
  /// 0 = no limit. The highest is enforced when saving; a total below the
  /// lowest is shown in red.
  final double totalMin, totalMax;
  const ExamLimits({
    this.minMark = 0,
    this.maxMark = 100,
    this.totalMin = 0,
    this.totalMax = 0,
  });

  Map<String, Object?> toMap() => {
    'minMark': minMark,
    'maxMark': maxMark,
    'totalMin': totalMin,
    'totalMax': totalMax,
  };

  factory ExamLimits.fromMap(Map m, double defMax) {
    double v(String k, double def) {
      final x = m[k];
      return x is num ? x.toDouble() : def;
    }

    return ExamLimits(
      minMark: v('minMark', 0),
      maxMark: v('maxMark', defMax),
      totalMin: v('totalMin', 0),
      totalMax: v('totalMax', 0),
    );
  }

  String get summary =>
      'Subject ${_fmtMark(minMark)}-${_fmtMark(maxMark)}'
          '${totalMin > 0 || totalMax > 0 ? ' · Total ${_fmtMark(totalMin)}-${totalMax > 0 ? _fmtMark(totalMax) : 'no limit'}' : ''}';
}

class AppSettings {
  /// First day of the week in the attendance report (DateTime.monday ... sunday).
  final int weekStart;

  /// Highest subject mark of an exam that has no limits of its own yet.
  final double maxMark;

  /// The mark limits of each exam (Settings > Exams), by [SchoolService.subjectKey].
  final Map<String, ExamLimits> examLimits;

  /// Lowest average mark for the grades A, B, C, D and E (below E is an F).
  final List<double> grades;

  /// Attendance rate (in %) from which the report colour is green / orange.
  /// Below [rateWarn] it is red.
  final double rateGood, rateWarn;

  /// The exams that can be picked in Result. Empty = the default list.
  final List<String> exams;

  /// Exams that were closed (unticked) in Settings > Exams. A closed exam is
  /// hidden in Result for teachers and students. At least one exam stays open.
  final List<String> closedExams;

  /// Subjects ticked in Settings. They are shown in the header of every
  /// section (class list). Attendance does not use them.
  final List<String> sectionSubjects;

  /// Pages a Teacher / Student can open when the administrator has not set
  /// their access one by one.
  final List<String> teacherAccess, studentAccess;

  /// What is ticked when an exam dialog is opened.
  final bool uploadHeading, uploadAutoFormat, uploadNumber;

  const AppSettings({
    this.weekStart = DateTime.monday,
    this.maxMark = 100.0,
    this.examLimits = const {},
    this.grades = const [80.0, 70.0, 60.0, 50.0, 40.0],
    this.rateGood = 90.0,
    this.rateWarn = 75.0,
    this.exams = const [],
    this.closedExams = const [],
    this.sectionSubjects = const [],
    this.teacherAccess = const [AppPages.attendance, AppPages.result],
    this.studentAccess = const [AppPages.result],
    this.uploadHeading = true,
    this.uploadAutoFormat = true,
    this.uploadNumber = true,
  });

  /// Used until the first exam is added in Settings.
  static List<String> defaultExams() {
    final y = DateTime.now().year;
    return [
      for (final yr in [y, y - 1])
        for (final t in const ['Test 1', 'Mid-term', 'Test 2', 'Final'])
          '$t $yr',
    ];
  }

  /// The ticked subjects for the section sheet header, e.g. 'ENGLISH, MATHS'.
  /// They are written on the FORM line, e.g. 'FORM ONE - ENGLISH'. Empty when none ticked.
  String get subjectsLine => sectionSubjects.join(', ').toUpperCase();

  /// The exams to show (never empty).
  List<String> get examOptions => exams.isEmpty ? defaultExams() : exams;

  /// The current exam: "Mid-term <year>" or, when that is not in the list,
  /// the first exam. It is the one Result opens on (when it is open).
  String get currentExam {
    final o = examOptions;
    final pref = 'Mid-term ${DateTime.now().year}';
    return o.contains(pref) ? pref : o.first;
  }

  /// The mark limits of [exam] (the defaults when none were set).
  ExamLimits limitsFor(String exam) =>
      examLimits[SchoolService.subjectKey(exam)] ?? ExamLimits(maxMark: maxMark);

  /// The highest subject mark of any exam.
  double get largestMax => [
    maxMark,
    for (final l in examLimits.values) l.maxMark,
  ].reduce((a, b) => a > b ? a : b);

  bool isExamOpen(String e) => !closedExams.contains(e);

  /// The exams that are open (ticked).
  List<String> get openExams => [for (final e in examOptions) if (isExamOpen(e)) e];

  static const gradeLetters = ['A', 'B', 'C', 'D', 'E'];
  static const weekDays = [
    'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday',
  ];

  factory AppSettings.fromMap(Map<String, dynamic> m) {
    const d = AppSettings();

    double dbl(String k, double def) {
      final v = m[k];
      return v is num ? v.toDouble() : def;
    }

    bool flag(String k, bool def) {
      final v = m[k];
      return v is bool ? v : def;
    }

    List<String> pages(String k, List<String> def) {
      final v = m[k];
      return v is List
          ? [
        for (final e in v)
          if (e is String && AppPages.all.contains(e)) e
      ]
          : def;
    }

    final wd = m['weekStart'];
    final g = m['grades'];
    final ex = m['exams'];
    final ss = m['sectionSubjects'];
    final ce = m['closedExams'];
    final grades =
    g is List && g.length == gradeLetters.length && g.every((e) => e is num)
        ? [for (final e in g) (e as num).toDouble()]
        : d.grades;
    return AppSettings(
      weekStart: wd is num && wd >= 1 && wd <= 7 ? wd.toInt() : d.weekStart,
      maxMark: dbl('maxMark', d.maxMark),
      examLimits: m['examLimits'] is Map
          ? {
        for (final e in (m['examLimits'] as Map).entries)
          if (e.value is Map)
            '${e.key}': ExamLimits.fromMap(
                e.value as Map, dbl('maxMark', d.maxMark)),
      }
          : d.examLimits,
      grades: grades,
      rateGood: dbl('rateGood', d.rateGood),
      rateWarn: dbl('rateWarn', d.rateWarn),
      exams: ex is List
          ? [
        for (final e in ex)
          if (e is String && e.trim().isNotEmpty) e.trim(),
      ]
          : d.exams,
      closedExams: ce is List
          ? [
        for (final e in ce)
          if (e is String) e,
      ]
          : d.closedExams,
      sectionSubjects: ss is List
          ? [
        for (final e in ss)
          if (e is String && ExamService.subjects.contains(e)) e,
      ]
          : d.sectionSubjects,
      teacherAccess: pages('teacherAccess', d.teacherAccess),
      studentAccess: pages('studentAccess', d.studentAccess),
      uploadHeading: flag('uploadHeading', d.uploadHeading),
      uploadAutoFormat: flag('uploadAutoFormat', d.uploadAutoFormat),
      uploadNumber: flag('uploadNumber', d.uploadNumber),
    );
  }
}

/// Holds the current [AppSettings] and keeps them in sync with Firestore.
/// Screens read `appSettings.value`; the Settings screen changes it with
/// [update]. Until somebody is signed in, the defaults are used.
class AppSettingsController extends ValueNotifier<AppSettings> {
  AppSettingsController() : super(const AppSettings());

  StreamSubscription<DocumentSnapshot<Map<String, dynamic>>>? _sub;

  DocumentReference<Map<String, dynamic>> get _doc =>
      FirebaseFirestore.instance.collection('settings').doc('app');

  /// Starts listening to the saved settings (called when somebody signs in).
  void start() {
    _sub ??= _doc.snapshots().listen(
          (d) => value = AppSettings.fromMap(d.data() ?? {}),
      onError: (e) => debugPrint('Settings could not be loaded: $e'),
    );
  }

  /// Stops listening and goes back to the defaults (called on sign out).
  void stop() {
    _sub?.cancel();
    _sub = null;
    value = const AppSettings();
  }

  /// Saves only the given fields. The live listener then updates [value].
  Future<void> update(Map<String, Object?> fields) => _doc.set({
    ...fields,
    'updatedBy': FirebaseAuth.instance.currentUser?.uid,
    'updatedAt': FieldValue.serverTimestamp(),
  }, SetOptions(merge: true)).timeout(const Duration(seconds: 30),
      onTimeout: () {
        throw Exception('Saving timed out. Check the internet connection.');
      });
}

final appSettings = AppSettingsController();

/// One place for the general settings of the app.
class SettingsScreen extends StatefulWidget {
  const SettingsScreen({super.key});

  @override
  State<SettingsScreen> createState() => _SettingsScreenState();
}

class _SettingsScreenState extends State<SettingsScreen> {
  static const _hint = TextStyle(fontSize: 12, color: Colors.black54);

  final _service = ExamService();
  late final _good =
  TextEditingController(text: _fmtMark(appSettings.value.rateGood));
  late final _warn =
  TextEditingController(text: _fmtMark(appSettings.value.rateWarn));
  late final _grade = [
    for (final g in appSettings.value.grades)
      TextEditingController(text: _fmtMark(g)),
  ];
  final _newExam = TextEditingController();
  bool _busy = false;

  @override
  void dispose() {
    for (final c in [_good, _warn, _newExam, ..._grade]) {
      c.dispose();
    }
    super.dispose();
  }

  // ---------------- helpers ----------------

  void _toast(String m) =>
      ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text(m)));

  double? _num(TextEditingController c) =>
      double.tryParse(c.text.trim().replaceAll(',', '.'));

  Future<bool> _save(Map<String, Object?> fields, [String? okMsg]) async {
    final messenger = ScaffoldMessenger.of(context);
    setState(() => _busy = true);
    try {
      await appSettings.update(fields);
      if (okMsg != null) {
        messenger.showSnackBar(SnackBar(content: Text(okMsg)));
      }
      return true;
    } catch (e) {
      messenger.showSnackBar(SnackBar(
          content: Text('Failed: ${'$e'.replaceFirst('Exception: ', '')}')));
      return false;
    } finally {
      if (mounted) setState(() => _busy = false);
    }
  }

  Future<void> _saveRates() async {
    final good = _num(_good), warn = _num(_warn);
    if (good == null || warn == null || warn < 0 || good > 100 || warn >= good) {
      _toast('Enter two numbers from 0 to 100. '
          'The green limit must be higher than the orange limit.');
      return;
    }
    await _save(
        {'rateGood': good, 'rateWarn': warn}, 'Attendance colours saved');
  }

  Future<void> _saveResults() async {
    final top = appSettings.value.largestMax;
    final limits = [for (final c in _grade) _num(c)];
    if (limits.any((v) => v == null)) {
      _toast('Enter a number for every grade.');
      return;
    }
    final v = [for (final x in limits) x!];
    var ok = v.first <= top && v.last >= 0;
    for (var i = 1; i < v.length; i++) {
      if (v[i] >= v[i - 1]) ok = false;
    }
    if (!ok) {
      _toast('The limits must go down from A to E (for example 80, 70, 60, '
          '50, 40) and cannot be higher than the highest subject mark.');
      return;
    }
    await _save({'grades': v}, 'Results settings saved');
  }

  /// Mark limits of ONE exam: subject lowest / highest, exam total
  /// lowest / highest.
  Future<void> _editLimits(String exam) async {
    final cur = appSettings.value.limitsFor(exam);
    final low = TextEditingController(text: _fmtMark(cur.minMark));
    final top = TextEditingController(text: _fmtMark(cur.maxMark));
    final tMin = TextEditingController(text: _fmtMark(cur.totalMin));
    final tMax = TextEditingController(text: _fmtMark(cur.totalMax));
    String? err;
    final saved = await showDialog<ExamLimits>(
      context: context,
      builder: (ctx) => StatefulBuilder(
        builder: (ctx, setD) => AlertDialog(
          title: Text('Mark limits - $exam'),
          content: SizedBox(
            width: 420,
            child: SingleChildScrollView(
              child: Column(mainAxisSize: MainAxisSize.min, children: [
                const Align(
                  alignment: Alignment.centerLeft,
                  child: Text(
                      'Subject marks: the lowest and highest mark one subject '
                          'can have in this exam.',
                      style: _hint),
                ),
                const SizedBox(height: 10),
                Row(children: [
                  Expanded(child: _numField(low, 'Subject - lowest')),
                  const SizedBox(width: 10),
                  Expanded(child: _numField(top, 'Subject - highest')),
                ]),
                const SizedBox(height: 16),
                const Align(
                  alignment: Alignment.centerLeft,
                  child: Text(
                      'Exam total: the sum of all the subject marks of a '
                          'student in this exam. The highest total cannot be '
                          'exceeded when saving; a total below the lowest is '
                          'shown in red. Use 0 for no limit.',
                      style: _hint),
                ),
                const SizedBox(height: 10),
                Row(children: [
                  Expanded(child: _numField(tMin, 'Total - lowest')),
                  const SizedBox(width: 10),
                  Expanded(child: _numField(tMax, 'Total - highest')),
                ]),
                const SizedBox(height: 8),
                const Align(
                  alignment: Alignment.centerLeft,
                  child: Text('Marks that are already saved are not changed.',
                      style: _hint),
                ),
                if (err != null)
                  Padding(
                    padding: const EdgeInsets.only(top: 8),
                    child: Align(
                      alignment: Alignment.centerLeft,
                      child: Text(err!,
                          style: const TextStyle(color: Color(0xFFC62828))),
                    ),
                  ),
              ]),
            ),
          ),
          actions: [
            TextButton(
                onPressed: () => Navigator.pop(ctx),
                child: const Text('Cancel')),
            FilledButton(
              onPressed: () {
                final lo = _num(low) ?? 0;
                final hi = _num(top);
                final tl = _num(tMin) ?? 0;
                final th = _num(tMax) ?? 0;
                String? e;
                if (hi == null || hi <= 0) {
                  e = 'Enter the highest subject mark (more than 0).';
                } else if (lo < 0 || lo >= hi) {
                  e = 'The lowest subject mark must be 0 or more and below '
                      'the highest.';
                } else if (th > 0 && th < hi) {
                  e = 'The highest exam total cannot be below the highest '
                      'subject mark (${_fmtMark(hi)}). Use 0 for no limit.';
                } else if (tl < 0 || (th > 0 && tl > th)) {
                  e = 'The lowest exam total must be 0 or more and not above '
                      'the highest exam total.';
                } else if (appSettings.value.grades.first > hi &&
                    hi >= appSettings.value.largestMax) {
                  e = 'Grade A starts at '
                      '${_fmtMark(appSettings.value.grades.first)}, above this '
                      'highest mark. Change the grades first.';
                }
                if (e != null) {
                  setD(() => err = e);
                  return;
                }
                Navigator.pop(
                    ctx,
                    ExamLimits(
                        minMark: lo, maxMark: hi!, totalMin: tl, totalMax: th));
              },
              child: const Text('Save'),
            ),
          ],
        ),
      ),
    );
    for (final c in [low, top, tMin, tMax]) {
      c.dispose();
    }
    if (saved == null) return;
    await _save({
      'examLimits': {SchoolService.subjectKey(exam): saved.toMap()}
    }, 'Mark limits of "$exam" saved');
  }

  Future<void> _addExam(List<String> current) async {
    final name = _newExam.text.trim();
    if (name.isEmpty) {
      _toast('Enter the exam name, for example Mid-term 2026.');
      return;
    }
    if (current.any((e) => e.toLowerCase() == name.toLowerCase())) {
      _toast('"$name" is already in the list.');
      return;
    }
    if (await _save({'exams': [...current, name]}, '"$name" added')) {
      _newExam.clear();
    }
  }

  Future<void> _removeExam(List<String> current, String name) async {
    if (current.length <= 1) {
      _toast('Keep at least one exam.');
      return;
    }
    await _save({
      'exams': [
        for (final e in current)
          if (e != name) e,
      ]
    }, '"$name" removed');
  }

  Future<void> _resetPassword() async {
    final email = FirebaseAuth.instance.currentUser?.email;
    if (email == null) return;
    final messenger = ScaffoldMessenger.of(context);
    try {
      await FirebaseAuth.instance.sendPasswordResetEmail(email: email);
      messenger.showSnackBar(
          SnackBar(content: Text('Password reset email sent to $email')));
    } on FirebaseAuthException catch (e) {
      messenger.showSnackBar(SnackBar(content: Text(e.message ?? e.code)));
    } catch (e) {
      messenger.showSnackBar(SnackBar(content: Text('Failed: $e')));
    }
  }

