// ======================= SECTIONS & ATTENDANCE DATA =======================

class SectionInfo {
  final String id, form, name;
  const SectionInfo({required this.id, required this.form, required this.name});

  /// Short code of a section, e.g. 1A, 2C, 4B.
  static String code(String form, String name) {
    final m = RegExp(r'\d+').firstMatch(form);
    if (name.isEmpty) return form;
    return m == null ? '$form $name' : '${m[0]}$name';
  }

  String get label => code(form, name);

  /// Readable name: "1B-A" -> "1B - Section A" (a whole class stays "1C").
  String get fullName =>
      isSub ? '${code(form, classKey)} - Section $subName' : label;

  /// The class this section belongs to: "B-A" -> "B", "C" -> "C".
  String get classKey => name.split('-').first.toUpperCase();

  /// True for a part of a divided class (name like "B-A").
  bool get isSub => name.contains('-');

  /// "B-A" -> "A" (empty for a whole class).
  String get subName => isSub ? name.substring(name.indexOf('-') + 1) : '';

  factory SectionInfo.fromDoc(DocumentSnapshot<Map<String, dynamic>> d) {
    final m = d.data() ?? {};
    return SectionInfo(id: d.id, form: m['form'] ?? '', name: m['name'] ?? '');
  }
}

/// One duplicate found while uploading a student list.
class ImportDuplicate {
  final String name;

  /// The class the row in the file wanted to put the student in.
  final String className;

  /// Every class that already has a student with this name.
  final List<String> allClasses;

  /// true = same name already in the same class (row skipped);
  /// false = same name exists in another class (student was still added).
  final bool skipped;
  const ImportDuplicate({
    required this.name,
    required this.className,
    required this.allClasses,
    required this.skipped,
  });
}

/// Shows the result of an upload. When duplicates were found they are listed
/// with their classes.
Future<void> showImportResult(
    BuildContext context, {
      required int students,
      required int sections,
      required int skipped,
      required List<ImportDuplicate> dups,
      int updated = 0,
      int noPhone = 0,
    }) {
  final same = dups.where((d) => d.skipped).toList();
  final other = dups.where((d) => !d.skipped).toList();
  Widget group(String title, String hint, List<ImportDuplicate> l,
      String Function(ImportDuplicate) line) {
    if (l.isEmpty) return const SizedBox.shrink();
    return Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
      const SizedBox(height: 12),
      Text('$title (${l.length})',
          style: const TextStyle(fontWeight: FontWeight.bold)),
      Text(hint, style: const TextStyle(fontSize: 12, color: Colors.black54)),
      const SizedBox(height: 4),
      for (final d in l)
        Padding(
          padding: const EdgeInsets.symmetric(vertical: 2),
          child: Text('\u2022 ${d.name}  \u2014  ${line(d)}'),
        ),
    ]);
  }

  return showDialog<void>(
    context: context,
    builder: (ctx) => AlertDialog(
      title: const Text('Upload finished'),
      content: SizedBox(
        width: 460,
        child: SingleChildScrollView(
          child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              mainAxisSize: MainAxisSize.min,
              children: [
                Text('Added $students students and $sections new sections.\n'
                    '$skipped rows skipped (duplicates or invalid).'
                    '${updated > 0 ? '\nPhone number saved for $updated existing students.' : ''}'
                    '${noPhone > 0 ? '\n$noPhone new students have no phone number.' : ''}'),
                group(
                  'Duplicates skipped',
                  'Already in the same class, so they were not added again.',
                  same,
                      (d) => 'class ${d.className}',
                ),
                group(
                  'Same name in another class',
                  'These were added, please check they are not the same person.',
                  other,
                      (d) => 'now in ${d.className}, also in '
                      '${d.allClasses.where((c) => c != d.className).join(', ')}',
                ),
              ]),
        ),
      ),
      actions: [
        FilledButton(
            onPressed: () => Navigator.pop(ctx), child: const Text('OK')),
      ],
    ),
  );
}

class StudentInfo {
  final String id, name, sectionId;

  /// First phone number of the student (digits only). It is also the
  /// username and the password of the student's login. '' = none saved.
  final String phone;

  /// Every phone number saved for the student (the first one is [phone]).
  final List<String> phones;

  /// Login account linked to this student ('' = none yet).
  final String accountUid;
  const StudentInfo(
      {required this.id,
        required this.name,
        required this.sectionId,
        this.phone = '',
        this.phones = const [],
        this.accountUid = ''});

  /// For lists and reports: all numbers on one line, '' when there is none.
  String get phoneText =>
      phones.isNotEmpty ? phones.join(' / ') : phone;
}

List<String> _phoneList(Object? v, Object? first) {
  final l = v is List
      ? [for (final e in v) if ('$e'.trim().isNotEmpty) '$e'.trim()]
      : <String>[];
  if (l.isEmpty && '${first ?? ''}'.trim().isNotEmpty) {
    l.add('${first}'.trim());
  }
  return l;
}

/// Students sign in with their phone number. Firebase needs an email, so the
/// phone number is turned into one: 0634123456 -> 0634123456@students.school.app
const kStudentEmailDomain = 'students.school.app';

/// Digits only (spaces, +, -, brackets removed). Null when it is not a phone
/// number (fewer than 6 or more than 15 digits, or it contains letters).
String? phoneDigits(String raw) {
  final t = raw.trim();
  if (t.isEmpty || RegExp(r'[A-Za-z\u0600-\u06FF]').hasMatch(t)) return null;
  final d = t.replaceFirst(RegExp(r'\.0+$'), '').replaceAll(RegExp(r'\D'), '');
  return d.length >= 6 && d.length <= 15 ? d : null;
}

/// Every phone number in one cell, in order. A cell may hold several numbers
/// separated by , ; / | & or a new line. The FIRST one is the main number.
List<String> phonesIn(String cell) => [
  for (final part in cell.split(RegExp(r'[,;/|&\n]')))
    if (phoneDigits(part) != null) phoneDigits(part)!,
];

String studentEmailFor(String digits) => '$digits@$kStudentEmailDomain';

class StudentAccountsResult {
  int created = 0, noPhone = 0, failed = 0;
  final shared = <String>[]; // phone already used by a linked brother / sister
  String? error;
  bool cancelled = false;
}

/// Creates the login account of students: username = password = first phone
/// number. The account is created on a SECOND Firebase app, so the person
/// who is adding the students stays signed in.
class StudentAccounts {
  /// How many accounts are created at the same time. Every worker has its
  /// own Firebase app (an app can only be signed in as one person at a time).
  static const _workers = 8;

  static Future<FirebaseAuth> _auth(int i) async {
    final name = 'studentCreator$i';
    FirebaseApp app;
    try {
      app = Firebase.app(name);
    } catch (_) {
      app = await Firebase.initializeApp(
          name: name, options: DefaultFirebaseOptions.currentPlatform);
    }
    return FirebaseAuth.instanceFor(app: app);
  }

  /// [ids] = only these students; null = every student that has a phone
  /// number but no account yet.
  static Future<StudentAccountsResult> create(
      {List<String>? ids,
        void Function(int done, int total)? onProgress,
        bool Function()? cancelled}) async {
    final db = FirebaseFirestore.instance;
    final res = StudentAccountsResult();
    final List<DocumentSnapshot<Map<String, dynamic>>> docs = ids == null
        ? (await db.collection('students').get()).docs
        : [
      for (final id in ids) await db.collection('students').doc(id).get()
    ];
    final secForm = <String, String>{};
    try {
      for (final d in (await db.collection('sections').get()).docs) {
        secForm[d.id] = '${d.data()['form'] ?? ''}';
      }
    } catch (_) {}
    final todo = <DocumentSnapshot<Map<String, dynamic>>>[];
    for (final d in docs) {
      final m = d.data();
      if (m == null) continue;
      if ('${m['accountUid'] ?? ''}'.isNotEmpty) continue; // already linked
      if ('${m['phone'] ?? ''}'.isEmpty) {
        res.noPhone++;
        continue;
      }
      todo.add(d);
    }
    if (todo.isEmpty) return res;
    // Students with the same phone number (brothers / sisters) are done one
    // after the other by the same worker, so they cannot link twice.
    final groups = <String, List<DocumentSnapshot<Map<String, dynamic>>>>{};
    for (final d in todo) {
      groups.putIfAbsent('${d.data()!['phone']}', () => []).add(d);
    }
    final queue = groups.values.toList();
    final n = queue.length < _workers ? queue.length : _workers;
    final auths = await Future.wait([for (var i = 0; i < n; i++) _auth(i)]);
    var done = 0, fails = 0, next = 0;
    var stop = false;

    Future<void> worker(FirebaseAuth auth) async {
      while (!stop && next < queue.length) {
        final group = queue[next++];
        for (final d in group) {
          if (stop) break;
          if (cancelled?.call() ?? false) {
            res.cancelled = true;
            stop = true;
            break;
          }
          final m = d.data()!;
          var attempt = 0;
          while (true) {
            attempt++;
            try {
              final r = await _one(
                  auth, db, d.id, m, secForm['${m['sectionId']}'] ?? '');
              if (r == 'shared') {
                res.shared.add('${m['name']}');
              } else {
                res.created++;
              }
              fails = 0;
              break;
            } on FirebaseAuthException catch (e) {
              if (e.code == 'too-many-requests' && attempt < 3) {
                await Future.delayed(const Duration(seconds: 20));
                continue;
              }
              res.failed++;
              res.error ??= e.code == 'too-many-requests'
                  ? 'Firebase is limiting new accounts. Try again in a few minutes.'
                  : (e.message ?? e.code);
              fails++;
              break;
            } catch (e) {
              res.failed++;
              res.error ??= '$e';
              fails++;
              break;
            }
          }
          if (fails >= 3) stop = true; // something is wrong (rules, network)
          done++;
          onProgress?.call(done, todo.length);
        }
      }
    }

    await Future.wait([for (final a in auths) worker(a)]);
    onProgress?.call(done, todo.length);
    return res;
  }

  static Future<String> _one(FirebaseAuth auth, FirebaseFirestore db, String id,
      Map<String, dynamic> m, String form) async {
    final phone = '${m['phone']}';
    final email = studentEmailFor(phone);
    UserCredential cred;
    var createdNew = false;
    try {
      cred = await auth.createUserWithEmailAndPassword(
          email: email, password: phone);
      createdNew = true;
    } on FirebaseAuthException catch (e) {
      if (e.code != 'email-already-in-use') rethrow;
      try {
        cred = await auth.signInWithEmailAndPassword(
            email: email, password: phone);
      } on FirebaseAuthException {
        return 'shared'; // that email belongs to something else
      }
    }
    final user = cred.user!;
    try {
      final uref = db.collection('users').doc(user.uid);
      if (!createdNew) {
        final ex = await uref.get();
        final sid = '${ex.data()?['studentId'] ?? ''}';
        if (sid.isNotEmpty && sid != id) return 'shared'; // a sibling has it
      }
      final batch = db.batch();
      batch.update(db.collection('students').doc(id), {'accountUid': user.uid});
      batch.set(uref, {
        'role': 'student',
        'name': '${m['name'] ?? ''}',
        'email': email,
        'phone': phone,
        'studentId': id,
        if (form.isNotEmpty) 'form': form,
        'createdAt': FieldValue.serverTimestamp(),
      });
      await batch.commit();
      return 'ok';
    } catch (e) {
      if (createdNew) {
        try {
          await user.delete(); // no account without a profile
        } catch (_) {}
      }
      rethrow;
    } finally {
      try {
        await auth.signOut();
      } catch (_) {}
    }
  }
}

/// Creates the accounts with a progress window and shows the result.
Future<void> runAccountCreation(BuildContext context,
    {List<String>? ids, bool quiet = false}) async {
  final progress = ValueNotifier<(int, int)>((0, 0));
  var cancel = false;
  final nav = Navigator.of(context, rootNavigator: true);
  final messenger = ScaffoldMessenger.of(context);
  if (!quiet) {
    unawaited(showDialog<void>(
      context: context,
      barrierDismissible: false,
      builder: (ctx) => AlertDialog(
        title: const Text('Creating student logins'),
        content: ValueListenableBuilder<(int, int)>(
          valueListenable: progress,
          builder: (_, v, __) => Column(mainAxisSize: MainAxisSize.min, children: [
            LinearProgressIndicator(value: v.$2 == 0 ? null : v.$1 / v.$2),
            const SizedBox(height: 12),
            Text(v.$2 == 0
                ? 'Checking students...'
                : '${v.$1} of ${v.$2} accounts'),
            const SizedBox(height: 4),
            const Text('Username and password = first phone number.',
                style: TextStyle(fontSize: 12, color: Colors.black54)),
          ]),
        ),
        actions: [
          TextButton(onPressed: () => cancel = true, child: const Text('Stop')),
        ],
      ),
    ));
  }
  StudentAccountsResult? res;
  Object? err;
  try {
    res = await StudentAccounts.create(
        ids: ids,
        onProgress: (d, t) => progress.value = (d, t),
        cancelled: () => cancel);
  } catch (e) {
    err = e;
  }
  if (!quiet) nav.pop();
  final r = res;
  final text = err != null
      ? 'Could not create the logins: ${'$err'.replaceFirst('Exception: ', '')}'
      : '${r!.created} student login${r.created == 1 ? '' : 's'} created'
      '${r.cancelled ? ' (stopped)' : ''}'
      '${r.noPhone > 0 && ids == null ? '. ${r.noPhone} students have no phone number.' : ''}'
      '${r.shared.isNotEmpty ? '. ${r.shared.length} share a phone number with a brother or sister who already has the login.' : ''}'
      '${r.failed > 0 ? '. ${r.failed} failed: ${r.error}' : ''}';
  if (quiet || !context.mounted) {
    messenger.showSnackBar(
        SnackBar(duration: const Duration(seconds: 6), content: Text(text)));
    return;
  }
  await showDialog<void>(
    context: context,
    builder: (ctx) => AlertDialog(
      title: const Text('Student logins'),
      content: SingleChildScrollView(
        child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
          Text(text),
          if (r != null && r.shared.isNotEmpty) ...[
            const SizedBox(height: 12),
            const Text('Same phone number as a linked student:',
                style: TextStyle(fontWeight: FontWeight.bold)),
            for (final n in r.shared.take(15)) Text('\u2022 $n'),
            if (r.shared.length > 15) Text('... and ${r.shared.length - 15} more'),
          ],
        ]),
      ),
      actions: [
        FilledButton(onPressed: () => Navigator.pop(ctx), child: const Text('OK')),
      ],
    ),
  );
}

class SchoolService {
  final _db = FirebaseFirestore.instance;
  CollectionReference<Map<String, dynamic>> get _sections =>
      _db.collection('sections');
  CollectionReference<Map<String, dynamic>> get _students =>
      _db.collection('students');
  CollectionReference<Map<String, dynamic>> get _attendance =>
      _db.collection('attendance');

  String? get _uid => FirebaseAuth.instance.currentUser?.uid;

  // ---------------- Sections ----------------
  /// All sections; a teacher only gets the sections of the forms they teach
  /// (and the list updates by itself if that changes).
  Stream<List<SectionInfo>> watchSections() {
    final ctrl = StreamController<List<SectionInfo>>();
    StreamSubscription<QuerySnapshot<Map<String, dynamic>>>? sub;
    List<SectionInfo>? raw;
    void push() {
      final r = raw;
      if (r != null && !ctrl.isClosed) {
        ctrl.add(teacherScope.value.filterSections(r));
      }
    }

    ctrl.onListen = () {
      sub = _sections.snapshots().listen((s) {
        final l = s.docs.map(SectionInfo.fromDoc).toList();
        l.sort((a, b) => a.label.toLowerCase().compareTo(b.label.toLowerCase()));
        raw = l;
        push();
      }, onError: ctrl.addError);
      teacherScope.addListener(push);
    };
    ctrl.onCancel = () {
      teacherScope.removeListener(push);
      return sub?.cancel();
    };
    return ctrl.stream;
  }

  Future<void> saveSection({
    String? id,
    required String form,
    required String name,
  }) {
    final ref = id == null ? _sections.doc() : _sections.doc(id);
    return ref.set({
      'form': form,
      'name': _normSection(name),
      'updatedBy': _uid,
      'updatedAt': FieldValue.serverTimestamp(),
    }, SetOptions(merge: true));
  }

  /// Divides EACH selected class into [count] sections of its own:
  /// 1A becomes 1A-A, 1A-B, 1A-C... The students of the class are sorted by
  /// name and shared equally (the first sections get one extra student if
  /// needed). The old undivided class is removed afterwards. No other class
  /// is created or changed.
  Future<({int classes, int students})> divideClasses(
      Set<String> ids, int count) =>
      divideMany({for (final id in ids) id: count});

  /// Divides many classes at once. [plan] maps a class id to the number of
  /// sections it is divided into (classes may have different numbers).
  Future<({int classes, int students})> divideMany(
      Map<String, int> plan) async {
    final snap = await _sections.get();
    final all = snap.docs.map(SectionInfo.fromDoc).toList();
    final taken = <String>{
      for (final s in all) '${s.form}|${s.name.toUpperCase()}',
    };
    final chosen = all.where((s) => (plan[s.id] ?? 0) >= 2).toList();
    for (final c in chosen) {
      final count = plan[c.id]!;
      for (var i = 1; i <= count; i++) {
        final nm = '${c.name.toUpperCase()}-${String.fromCharCode(64 + i)}';
        if (taken.contains('${c.form}|$nm')) {
          throw Exception('${SectionInfo.code(c.form, nm)} already exists.');
        }
      }
    }

    var total = 0;
    for (final c in chosen) {
      final count = plan[c.id]!;
      // 1) the new sections of this class
      final newIds = <String>[];
      final cb = _db.batch();
      for (var i = 1; i <= count; i++) {
        final ref = _sections.doc();
        newIds.add(ref.id);
        cb.set(ref, {
          'form': c.form,
          'name': '${c.name.toUpperCase()}-${String.fromCharCode(64 + i)}',
          'updatedBy': _uid,
          'updatedAt': FieldValue.serverTimestamp(),
        });
      }
      await cb.commit();

      // 2) its students, sorted by name, shared equally
      final docs = [
        ...(await _students.where('sectionId', isEqualTo: c.id).get()).docs
      ];
      docs.sort((a, b) => '${a.data()['name'] ?? ''}'
          .toLowerCase()
          .compareTo('${b.data()['name'] ?? ''}'.toLowerCase()));
      final n = docs.length;
      final base = n ~/ count, extra = n % count;
      final moves = <(DocumentReference<Map<String, dynamic>>, String)>[];
      var idx = 0;
      for (var s = 0; s < count; s++) {
        final cnt = base + (s < extra ? 1 : 0);
        for (var j = 0; j < cnt; j++) {
          moves.add((docs[idx++].reference, newIds[s]));
        }
      }
      for (var i = 0; i < moves.length; i += 400) {
        final b = _db.batch();
        for (final m in moves.skip(i).take(400)) {
          b.update(m.$1, {'sectionId': m.$2});
        }
        await b.commit();
      }

      // 3) the old class is now empty: remove it
      await _sections.doc(c.id).delete();
      total += n;
    }
    return (classes: chosen.length, students: total);
  }

  // ---------------- Download / upload of the student lists ----------------
  /// Downloads every section with its students as a CSV file (opens in Excel).
  /// Columns: Form, Section, Student name (the same format Upload reads).
  Future<int> downloadSections() async {
    final secs = await _sections.get();
    final stu = await _students.get();
    final names = <String, List<String>>{};
    for (final d in stu.docs) {
      final m = d.data();
      (names['${m['sectionId']}'] ??= []).add('${m['name'] ?? ''}');
    }
    // Sections only (divided classes), not whole undivided classes.
    final list = secs.docs
        .map(SectionInfo.fromDoc)
        .where((s) => s.isSub)
        .toList()
      ..sort((a, b) {
        final c = a.form.compareTo(b.form);
        return c != 0
            ? c
            : a.name.toLowerCase().compareTo(b.name.toLowerCase());
      });
    if (list.isEmpty) throw Exception('There are no sections to download yet.');
    String q(String v) => '"${v.replaceAll('"', '""')}"';
    final sb = StringBuffer('\uFEFF')..write('Form,Section,Student name\r\n');
    var count = 0;
    for (final s in list) {
      final st = (names[s.id] ?? <String>[])
        ..sort((a, b) => a.toLowerCase().compareTo(b.toLowerCase()));
      if (st.isEmpty) {
        sb.write('${q(s.form)},${q(s.name)},\r\n');
      }
      for (final n in st) {
        sb.write('${q(s.form)},${q(s.name)},${q(n)}\r\n');
        count++;
      }
    }
    _downloadInBrowser(Uint8List.fromList(utf8.encode(sb.toString())),
        'Sections-${DateTime.now().year}.csv', 'text/csv');
    return count;
  }

  // ---------------- Delete everything ----------------
  /// Deletes EVERY section together with all students and attendance records.
  /// Returns the number of sections removed.
  Future<int> deleteAllSections() async {
    final secs = await _sections.get();
    final refs = <DocumentReference<Map<String, dynamic>>>[
      ...secs.docs.map((d) => d.reference),
      ...(await _students.get()).docs.map((d) => d.reference),
      ...(await _attendance.get()).docs.map((d) => d.reference),
    ];
    for (var i = 0; i < refs.length; i += 400) {
      final b = _db.batch();
      for (final r in refs.skip(i).take(400)) {
        b.delete(r);
      }
      await b.commit();
    }
    return secs.docs.length;
  }

  // ---------------- Shared data for the PDF / Word of all sections ----------------
  /// Sections + students + the header saved in the Exam tab (letterhead and
  /// general exam heading). Used by both the PDF and the Word export, so every
  /// section (also the ones created later by dividing a class) takes the
  /// Exam-tab header automatically.
  Future<
      ({
      List<SectionInfo> secs,
      Map<String, List<String>> names,
      ExamHeading heading,
      })> _loadSectionsPrintData() async {
    // Only the divided SECTIONS (1A-A, 1A-B ...) are printed / downloaded,
    // never a whole undivided class.
    final secs = (await _sections.get())
        .docs
        .map(SectionInfo.fromDoc)
        .where((s) => s.isSub)
        .toList();
    if (secs.isEmpty) {
      throw Exception('There are no sections to export yet. '
          'Divide a class into sections first.');
    }
    final names = <String, List<String>>{};
    for (final d in (await _students.get()).docs) {
      final m = d.data();
      (names['${m['sectionId']}'] ??= []).add('${m['name'] ?? ''}');
    }
    for (final l in names.values) {
      l.sort((a, b) => a.toLowerCase().compareTo(b.toLowerCase()));
    }
    secs.sort((a, b) {
      final c = a.form.compareTo(b.form);
      return c != 0 ? c : a.name.toLowerCase().compareTo(b.name.toLowerCase());
    });

    final exam = ExamService();
    ExamHeading heading;
    try {
      heading = await exam.getHeading();
    } catch (_) {
      heading = const ExamHeading();
    }
    return (secs: secs, names: names, heading: heading);
  }

  // ---------------- PDF of all sections (download + print) ----------------
  /// ONE PDF with every section (one or more pages each): Exam-tab header,
  /// numbered student list with a signature column, and invigilator lines.
  Future<({Uint8List bytes, int sections, int students})>
  buildSectionsPdf() async {
    final d = await _loadSectionsPrintData();

    // Names written in Arabic need a real font (needs internet the first time).
    pw.Font? arabic;
    try {
      arabic = await PdfGoogleFonts.notoNaskhArabicRegular();
    } catch (_) {}
    final theme = pw.ThemeData.withFont(
      base: pw.Font.times(),
      bold: pw.Font.timesBold(),
      fontFallback: [if (arabic != null) arabic],
    );

    const grey = PdfColor(0.85, 0.85, 0.85);
    pw.Widget bar(String t, {bool boxed = false, double size = 10.5}) =>
        pw.Container(
          width: double.infinity,
          alignment: pw.Alignment.center,
          padding: const pw.EdgeInsets.symmetric(vertical: 2, horizontal: 4),
          decoration: pw.BoxDecoration(
              color: grey, border: boxed ? pw.Border.all(width: 1) : null),
          child: pw.Text(t.replaceAll('–', '-'),
              style: pw.TextStyle(fontSize: size, fontWeight: pw.FontWeight.bold)),
        );

    // Subjects ticked in Settings are added to the header of every section.
    final subjectsLine = appSettings.value.subjectsLine;
    final logoImg = pdfLogoImage(LogoPlace.sections);
    final wmBg = pdfWatermark(LogoPlace.sections);
    pw.Widget headerFor(SectionInfo s, int n) {
      final h = d.heading.build('Class list', s.form);
      return pw.Column(
        crossAxisAlignment: pw.CrossAxisAlignment.stretch,
        children: [
          if (logoImg != null) pdfLogoBlock(logoImg),
          bar(h.title, boxed: true),
          bar('FORM ${ExamHeading._formWord(s.form)}'
              '${subjectsLine.isEmpty ? '' : ' - $subjectsLine'}',
              size: 16),
          bar('CLASS LIST - ${s.fullName}  ($n student${n == 1 ? '' : 's'})',
              size: 22),
          bar('${h.month.toUpperCase()} ${h.year}'),
          pw.SizedBox(height: 8),
        ],
      );
    }

    pw.Widget cell(String t, {bool head = false, double rowH = 28}) =>
        pw.Container(
          height: head ? 20 : rowH,
          alignment: pw.Alignment.center,
          color: head ? grey : null,
          child: pw.Text(t,
              style: pw.TextStyle(
                  fontSize: 12,
                  fontWeight: head ? pw.FontWeight.bold : pw.FontWeight.normal)),
        );

    /// 3 empty rows where the invigilators write their name and sign.
    pw.Widget invigilators(double rowH) => pw.Column(
      crossAxisAlignment: pw.CrossAxisAlignment.start,
      children: [
        pw.SizedBox(height: 12),
        pw.Text('INVIGILATORS',
            style:
            pw.TextStyle(fontSize: 12, fontWeight: pw.FontWeight.bold)),
        pw.SizedBox(height: 4),
        pw.Table(
          border: pw.TableBorder.all(width: 0.7),
          columnWidths: {
            0: const pw.FixedColumnWidth(30),
            1: const pw.FlexColumnWidth(3),
            2: const pw.FlexColumnWidth(2),
          },
          children: [
            pw.TableRow(children: [
              cell('#', head: true),
              cell('Invigilator name', head: true),
              cell('Signature', head: true),
            ]),
            for (var i = 1; i <= 3; i++)
              pw.TableRow(children: [
                cell('$i', rowH: rowH),
                cell('', rowH: rowH),
                cell('', rowH: rowH),
              ]),
          ],
        ),
      ],
    );

    final doc = pw.Document();
    var totalStudents = 0;
    for (final s in d.secs) {
      final st = d.names[s.id] ?? <String>[];
      totalStudents += st.length;
      // Fit the whole section on ONE A4 sheet: the rows (and fonts) shrink
      // when the class is big. Only a very large class goes on to a 2nd page.
      final n = st.length;
      final big = n > 24;
      final invRow = big ? 22.0 : 28.0;
      final fixed = 88 + 8 + // heading bars (large class-list lines) + gap
          (12 + 16 + 4 + 20 + 3 * invRow) + // invigilators block
          20 + 14 + // table header + safety
          logoReserve(LogoPlace.sections); // school logo on top
      // Page content height = 842 - 2 x 28 (margins) = 786 pt.
      final rowH =
      ((786 - fixed) / (n == 0 ? 1 : n)).clamp(15.0, 28.0).toDouble();
      // Large, easy-to-read names: as big as the row allows (9 - 16 pt).
      final fs = (rowH * 0.74).clamp(9.0, 16.0).toDouble();
      doc.addPage(pw.MultiPage(
        pageTheme: pw.PageTheme(
          theme: theme,
          pageFormat: PdfPageFormat.a4,
          margin: const pw.EdgeInsets.symmetric(horizontal: 40, vertical: 28),
          buildBackground: wmBg,
        ),
        maxPages: 500,
        footer: (ctx) => pw.Text(
            '${s.label} | Page ${ctx.pageNumber} of ${ctx.pagesCount}',
            textAlign: pw.TextAlign.center,
            style: pw.TextStyle(fontSize: 10, fontWeight: pw.FontWeight.bold)),
        build: (_) => [
          headerFor(s, st.length),
          if (st.isEmpty)
            pw.Padding(
              padding: const pw.EdgeInsets.all(12),
              child: pw.Text('No students in this section yet.'),
            )
          else
            pw.Table.fromTextArray(
              headers: const ['#', 'Student name', 'Signature'],
              data: [
                for (var i = 0; i < st.length; i++) ['${i + 1}', st[i], ''],
              ],
              headerStyle:
              pw.TextStyle(fontSize: 13, fontWeight: pw.FontWeight.bold),
              cellStyle: pw.TextStyle(fontSize: fs),
              headerDecoration: const pw.BoxDecoration(color: grey),
              headerHeight: 20,
              cellHeight: rowH,
              cellAlignments: {
                0: pw.Alignment.center,
                1: pw.Alignment.centerLeft,
                2: pw.Alignment.centerLeft,
              },
              columnWidths: {
                0: const pw.FixedColumnWidth(30),
                1: const pw.FlexColumnWidth(3),
                2: const pw.FlexColumnWidth(2),
              },
              cellPadding:
              const pw.EdgeInsets.symmetric(vertical: 0.5, horizontal: 6),
            ),
          invigilators(invRow),
        ],
      ));
    }
    return (
    bytes: await doc.save(),
    sections: d.secs.length,
    students: totalStudents,
    );
  }

  // ---------------- Word (.docx) of all sections ----------------
  /// Same content as the PDF, as an editable Word file: Exam-tab header,
  /// student list with a signature column and invigilator lines. Every
  /// section starts on a new page.
  Future<({Uint8List bytes, int sections, int students})>
  buildSectionsDocx() async {
    final d = await _loadSectionsPrintData();
    String x(String t) => ExamService._xml(t.replaceAll('–', '-'));

    const ns =
        'xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main" '
        'xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships" '
        'xmlns:wp="http://schemas.openxmlformats.org/drawingml/2006/wordprocessingDrawing" '
        'xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main" '
        'xmlns:pic="http://schemas.openxmlformats.org/drawingml/2006/picture"';
    const relBase =
        'http://schemas.openxmlformats.org/officeDocument/2006/relationships';
    const shade = '<w:shd w:val="clear" w:color="auto" w:fill="D9D9D9"/>';
    const edge = 'w:val="single" w:sz="6" w:space="0" w:color="000000"';
    const tblBorders = '<w:tblBorders><w:top $edge/><w:left $edge/>'
        '<w:bottom $edge/><w:right $edge/><w:insideH $edge/>'
        '<w:insideV $edge/></w:tblBorders>';

    String run(String t, {bool b = false, int sz = 22}) =>
        '<w:r><w:rPr>${b ? '<w:b/><w:bCs/>' : ''}<w:sz w:val="$sz"/><w:szCs w:val="$sz"/></w:rPr>'
            '<w:t xml:space="preserve">${x(t)}</w:t></w:r>';
    String para(String t,
        {bool b = true,
          String jc = 'center',
          bool pageBreak = false,
          int sz = 22,
          int sp = 20}) =>
        '<w:p><w:pPr>${pageBreak ? '<w:pageBreakBefore/>' : ''}'
            '<w:spacing w:before="$sp" w:after="$sp"/><w:jc w:val="$jc"/>'
            '<w:rPr><w:sz w:val="$sz"/><w:szCs w:val="$sz"/></w:rPr></w:pPr>'
            '${t.isEmpty ? '' : run(t, b: b, sz: sz)}</w:p>';
    String bar(String t, {bool boxed = false, int sz = 22}) =>
        '<w:tr><w:tc><w:tcPr><w:tcW w:w="10100" w:type="dxa"/>'
            '${boxed ? '<w:tcBorders><w:top $edge/><w:left $edge/><w:bottom $edge/><w:right $edge/></w:tcBorders>' : ''}'
            '$shade</w:tcPr>${para(t, sz: sz, sp: sz > 22 ? 40 : 20)}</w:tc></w:tr>';
    String tc(int w, String t,
        {bool head = false, String jc = 'left', int sz = 22, int sp = 20}) =>
        '<w:tc><w:tcPr><w:tcW w:w="$w" w:type="dxa"/>${head ? shade : ''}'
            '<w:vAlign w:val="center"/></w:tcPr>'
            '${para(t, b: head, jc: jc, sz: head ? 24 : sz, sp: sp)}</w:tc>';
    String tr(List<String> cells, {bool head = false, int h = 440}) =>
        '<w:tr><w:trPr><w:cantSplit/>${head ? '<w:tblHeader/>' : ''}'
            '<w:trHeight w:val="$h" w:hRule="atLeast"/></w:trPr>${cells.join()}</w:tr>';
    String table(String grid, String rows) =>
        '<w:tbl><w:tblPr><w:tblW w:w="10100" w:type="dxa"/>$tblBorders'
            '<w:tblLayout w:type="fixed"/></w:tblPr><w:tblGrid>$grid</w:tblGrid>$rows</w:tbl>';
    const grid3 =
        '<w:gridCol w:w="700"/><w:gridCol w:w="5400"/><w:gridCol w:w="4000"/>';

    // Subjects ticked in Settings are added to the header of every section.
    final subjectsLine = appSettings.value.subjectsLine;
    final body = StringBuffer();
    var total = 0;
    for (var i = 0; i < d.secs.length; i++) {
      final s = d.secs[i];
      final st = d.names[s.id] ?? <String>[];
      total += st.length;
      final h = d.heading.build('Class list', s.form);

      // Fit the whole section on ONE A4 sheet: row height and font shrink
      // when the class is big (page content height = 770 pt).
      final n = st.length;
      final big = n > 24;
      final invPt = big ? 22.0 : 28.0;
      final fixedPt = 88 + 8 + 19 + 8 + 18 + 19 + 3 * invPt + 30 +
          logoReserve(LogoPlace.sections);
      final rowPt =
      ((770 - fixedPt) / (n == 0 ? 1 : n)).clamp(15.0, 28.0).toDouble();
      // Large, easy-to-read names: as big as the row allows (9 - 16 pt).
      final fsz = (rowPt * 0.74 * 2).round().clamp(18, 32).toInt();
      final rowTw = (rowPt * 20).round();
      final invTw = (invPt * 20).round();

      // Every section starts on a new page (1 pt paragraph that carries the break).
      if (i > 0) body.write(para('', b: false, pageBreak: true, sz: 2, sp: 0));
      body.write(docxLogoPara(LogoPlace.sections,
          rid: 'rIdSchoolLogo', docPrId: 9200 + i));
      body.write(table(
        '<w:gridCol w:w="10100"/>',
        bar(h.title, boxed: true) +
            bar('FORM ${ExamHeading._formWord(s.form)}'
                '${subjectsLine.isEmpty ? '' : ' - $subjectsLine'}',
                sz: 32) +
            bar('CLASS LIST - ${s.fullName}  (${st.length} student${st.length == 1 ? '' : 's'})',
                sz: 44) +
            bar('${h.month.toUpperCase()} ${h.year}'),
      ));
      body.write(para('', b: false, sz: 12, sp: 0)); // gap between the tables

      if (st.isEmpty) {
        body.write(para('No students in this section yet.',
            b: false, jc: 'left'));
      } else {
        final rows = StringBuffer(tr([
          tc(700, '#', head: true, jc: 'center'),
          tc(5400, 'Student name', head: true),
          tc(4000, 'Signature', head: true),
        ], head: true, h: 380));
        for (var r = 0; r < st.length; r++) {
          rows.write(tr([
            tc(700, '${r + 1}', jc: 'center', sz: fsz, sp: 0),
            tc(5400, st[r], sz: fsz, sp: 0),
            tc(4000, '', sz: fsz, sp: 0),
          ], h: rowTw));
        }
        body.write(table(grid3, rows.toString()));
      }

      // 3 empty rows where the invigilators write their name and sign.
      body.write(para('', b: false, sz: 12, sp: 0));
      body.write(para('INVIGILATORS', jc: 'left', sz: 24));
      final inv = StringBuffer(tr([
        tc(700, '#', head: true, jc: 'center'),
        tc(5400, 'Invigilator name', head: true),
        tc(4000, 'Signature', head: true),
      ], head: true, h: 380));
      for (var k = 1; k <= 3; k++) {
        inv.write(tr([
          tc(700, '$k', jc: 'center'),
          tc(5400, ''),
          tc(4000, ''),
        ], h: invTw));
      }
      body.write(table(grid3, inv.toString()));
    }

    const xmlHead = '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>';
    final documentXml = '$xmlHead<w:document $ns><w:body>$body'
        '<w:sectPr>${docxWmSectRef(LogoPlace.sections)}<w:pgSz w:w="11906" w:h="16838"/>'
        '<w:pgMar w:top="720" w:right="900" w:bottom="720" w:left="900" '
        'w:header="400" w:footer="400" w:gutter="0"/>'
        '</w:sectPr></w:body></w:document>';
    const stylesXml = '$xmlHead<w:styles xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main">'
        '<w:docDefaults><w:rPrDefault><w:rPr>'
        '<w:rFonts w:ascii="Times New Roman" w:hAnsi="Times New Roman" w:eastAsia="Times New Roman" w:cs="Times New Roman"/>'
        '<w:sz w:val="22"/><w:szCs w:val="22"/></w:rPr></w:rPrDefault>'
        '<w:pPrDefault><w:pPr><w:spacing w:after="0" w:line="240" w:lineRule="auto"/></w:pPr></w:pPrDefault>'
        '</w:docDefaults></w:styles>';

    final files = <String, List<int>>{
      '[Content_Types].xml': utf8.encode(
          '$xmlHead<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">'
              '<Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/>'
              '<Default Extension="xml" ContentType="application/xml"/>'
              '<Default Extension="png" ContentType="image/png"/>'
              '<Default Extension="jpeg" ContentType="image/jpeg"/>'
              '<Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/>'
              '<Override PartName="/word/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.styles+xml"/>'
              '${docxWmHeaderOverride(LogoPlace.sections)}'
              '</Types>'),
      '_rels/.rels': utf8.encode(
          '$xmlHead<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'
              '<Relationship Id="rId1" Type="$relBase/officeDocument" Target="word/document.xml"/>'
              '</Relationships>'),
      'word/_rels/document.xml.rels': utf8.encode(
          '$xmlHead<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'
              '<Relationship Id="rIdStyles" Type="$relBase/styles" Target="styles.xml"/>'
              '${docxLogoRel(LogoPlace.sections, 'rIdSchoolLogo')}'
              '${docxWmHeaderRel(LogoPlace.sections)}'
              '</Relationships>'),
      'word/document.xml': utf8.encode(documentXml),
      'word/styles.xml': utf8.encode(stylesXml),
      if (schoolLogo.value.uses(LogoPlace.sections))
        'word/media/school_logo.png': schoolLogo.value.bytes!,
      ...docxWatermarkFiles(LogoPlace.sections),
    };
    final out = zip.Archive();
    files.forEach(
            (name, data) => out.addFile(zip.ArchiveFile(name, data.length, data)));
    final bytes = zip.ZipEncoder().encode(out);
    if (bytes == null) throw Exception('Could not create the Word file.');
    return (
    bytes: Uint8List.fromList(bytes),
    sections: d.secs.length,
    students: total,
    );
  }

  /// "a1" -> "A-1", "a b" -> "A-B", "b" -> "B"
  static String _normSection(String raw) {
    final t = raw.trim().toUpperCase();
    final m = RegExp(r'^([A-Z])(?:[\s\-_.]*(\d+)|[\s\-_.]+([A-Z]))$')
        .firstMatch(t);
    return m == null ? t : '${m[1]}-${m[2] ?? m[3]}';
  }

  static String? _normForm(String raw) {
    final m = RegExp(r'\d+').firstMatch(raw);
    if (m == null) return null;
    final f = 'Form${int.parse(m[0]!)}';
    return ExamService.forms.contains(f) ? f : null;
  }

  /// Reads a CSV text (comma, semicolon or tab separated).
  static List<List<String>> parseCsv(String text) {
    if (text.startsWith('\uFEFF')) text = text.substring(1);
    final firstLine = text.split('\n').first;
    var d = ',';
    var best = firstLine.split(',').length;
    for (final c in [';', '\t']) {
      final n = firstLine.split(c).length;
      if (n > best) {
        best = n;
        d = c;
      }
    }
    final rows = <List<String>>[];
    var row = <String>[];
    final cell = StringBuffer();
    var quoted = false;
    for (var i = 0; i < text.length; i++) {
      final ch = text[i];
      if (quoted) {
        if (ch == '"') {
          if (i + 1 < text.length && text[i + 1] == '"') {
            cell.write('"');
            i++;
          } else {
            quoted = false;
          }
        } else {
          cell.write(ch);
        }
      } else if (ch == '"') {
        quoted = true;
      } else if (ch == d) {
        row.add(cell.toString());
        cell.clear();
      } else if (ch == '\n' || ch == '\r') {
        if (ch == '\r' && i + 1 < text.length && text[i + 1] == '\n') i++;
        row.add(cell.toString());
        cell.clear();
        rows.add(row);
        row = <String>[];
      } else {
        cell.write(ch);
      }
    }
    if (cell.isNotEmpty || row.isNotEmpty) {
      row.add(cell.toString());
      rows.add(row);
    }
    return rows;
  }

  /// Reads the first sheet of an Excel (.xlsx) file.
  static List<List<String>> parseXlsx(Uint8List bytes) {
    final zip.Archive arc;
    try {
      arc = zip.ZipDecoder().decodeBytes(bytes);
    } catch (_) {
      throw Exception('This is not a valid .xlsx file.');
    }
    String? read(String name) {
      for (final f in arc.files) {
        if (f.isFile && f.name == name) {
          return utf8.decode(f.content as List<int>, allowMalformed: true);
        }
      }
      return null;
    }

    final shared = <String>[];
    final ss = read('xl/sharedStrings.xml');
    if (ss != null) {
      for (final si
      in RegExp(r'<si\b[^>]*>(.*?)</si>', dotAll: true).allMatches(ss)) {
        shared.add(RegExp(r'<t\b[^>]*>(.*?)</t>', dotAll: true)
            .allMatches(si[1]!)
            .map((t) => ExamService._unxml(t[1]!))
            .join());
      }
    }
    var sheet = read('xl/worksheets/sheet1.xml');
    if (sheet == null) {
      final names = [
        for (final f in arc.files)
          if (f.isFile &&
              f.name.startsWith('xl/worksheets/sheet') &&
              f.name.endsWith('.xml'))
            f.name
      ]..sort();
      if (names.isNotEmpty) sheet = read(names.first);
    }
    if (sheet == null) throw Exception('No worksheet found in this file.');

    int colOf(String ref) {
      var n = 0;
      for (final u in ref.codeUnits) {
        if (u >= 65 && u <= 90) {
          n = n * 26 + (u - 64);
        } else if (u >= 97 && u <= 122) {
          n = n * 26 + (u - 96);
        } else {
          break;
        }
      }
      return n - 1;
    }

    final rows = <List<String>>[];
    for (final r
    in RegExp(r'<row\b[^>]*>(.*?)</row>', dotAll: true).allMatches(sheet)) {
      final cells = <int, String>{};
      var maxCol = -1;
      for (final c in RegExp(r'<c\b([^>]*?)(?:/>|>(.*?)</c>)', dotAll: true)
          .allMatches(r[1]!)) {
        final attrs = c[1] ?? '';
        final inner = c[2] ?? '';
        final ref = RegExp(r'\br="([A-Za-z]+)\d+"').firstMatch(attrs)?.group(1);
        if (ref == null) continue;
        final type = RegExp(r'\bt="(\w+)"').firstMatch(attrs)?.group(1);
        String v;
        if (type == 'inlineStr') {
          v = RegExp(r'<t\b[^>]*>(.*?)</t>', dotAll: true)
              .allMatches(inner)
              .map((t) => ExamService._unxml(t[1]!))
              .join();
        } else {
          final raw = RegExp(r'<v>(.*?)</v>', dotAll: true)
              .firstMatch(inner)
              ?.group(1) ??
              '';
          if (type == 's') {
            final k = int.tryParse(raw.trim());
            v = (k != null && k >= 0 && k < shared.length) ? shared[k] : '';
          } else {
            v = ExamService._unxml(raw);
          }
        }
        final col = colOf(ref);
        cells[col] = v;
        if (col > maxCol) maxCol = col;
      }
      rows.add([for (var k = 0; k <= maxCol; k++) cells[k] ?? '']);
    }
    return rows;
  }

  static final _classCodeRe = RegExp(
      r'^(?:form\s*)?(\d{1,2})\s*[-_/ ]?\s*([A-Za-z](?:[\s\-_.]*\d+|[\s\-_.]+[A-Za-z])?)$',
      caseSensitive: false);
  static final _hasLetter = RegExp(r'[A-Za-z\u0600-\u06FF]');

  /// Understands one row of the uploaded list:
  ///  * a class cell like 1A, 2C, 4B, Form1B  +  the student name, in any
  ///    column order (e.g. "Class | Student name" or "No | Name | Class"), or
  ///  * separate columns: Form | Section | Student name.
  /// Returns null when the row is not a student row (header, empty, ...).
  static ({String form, String section, String name})? _parseRow(
      List<String> row,
      {Set<int> skipCols = const {}, int? nameCol}) {
    final cells = [for (final c in row) c.trim()];
    for (var i = 0; i < cells.length; i++) {
      final m = _classCodeRe.firstMatch(cells[i]);
      if (m == null) continue;
      final form = _normForm(m[1]!);
      if (form == null) continue;
      var name = '';
      // The header said which column is the student name: use it.
      if (nameCol != null &&
          nameCol != i &&
          nameCol < cells.length &&
          _hasLetter.hasMatch(cells[nameCol])) {
        name = cells[nameCol];
      } else {
        for (var j = 0; j < cells.length; j++) {
          // Mother-name columns (and the class cell) are never the student.
          if (j == i || skipCols.contains(j) || !_hasLetter.hasMatch(cells[j])) {
            continue;
          }
          if (cells[j].length > name.length) name = cells[j];
        }
      }
      return (form: form, section: _normSection(m[2]!), name: name);
    }
    if (cells.isEmpty) return null;
    final form = _normForm(cells[0]);
    if (form == null) return null;
    final sec = cells.length > 1 ? cells[1] : '';
    return (
    form: form,
    section: sec.isEmpty ? 'A' : _normSection(sec),
    name: cells.length > 2 ? cells[2] : '',
    );
  }

  /// Adds the students of a CSV / Excel file (columns: Form, Section,
  /// Student name). Missing sections are created; duplicates are skipped.
  Future<({int sections, int students, int skipped, int updated, int noPhone, List<ImportDuplicate> dups})>
  importFile(PlatformFile file) async {
    final bytes = file.bytes;
    if (bytes == null) throw Exception('Could not read the file.');
    final ext = (file.extension ?? '').toLowerCase();
    final table = ext == 'xlsx'
        ? parseXlsx(bytes)
        : parseCsv(utf8.decode(bytes, allowMalformed: true));

    final secSnap = await _sections.get();
    final stuSnap = await _students.get();
    final secIds = <String, String>{};
    for (final d in secSnap.docs) {
      final m = d.data();
      secIds['${m['form']}|${'${m['name'] ?? ''}'.toUpperCase()}'] = d.id;
    }
    final existing = <String>{};
    // 'sectionId|name' -> (student id, has a phone already)
    final existingDocs = <String, ({String id, bool hasPhone})>{};
    // A class that was divided (1A -> 1A-A, 1A-B...): 'form|A|name' -> student
    final secMeta = <String, ({String form, String name})>{
      for (final d in secSnap.docs)
        d.id: (
        form: '${d.data()['form'] ?? ''}',
        name: '${d.data()['name'] ?? ''}'
        ),
    };
    final classStudents = <String, ({String id, bool hasPhone})>{};
    // section id -> readable class label (1A, 2C, 1B-A ...)
    final secLabel = <String, String>{};
    for (final d in secSnap.docs) {
      final m = d.data();
      secLabel[d.id] = SectionInfo.code(
          '${m['form'] ?? ''}', '${m['name'] ?? ''}');
    }
    // student name (lower case) -> every class that already has this name
    final nameClasses = <String, Set<String>>{};
    for (final d in stuSnap.docs) {
      final m = d.data();
      final nm = '${m['name'] ?? ''}'.toLowerCase();
      existing.add('${m['sectionId']}|$nm');
      existingDocs['${m['sectionId']}|$nm'] =
      (id: d.id, hasPhone: '${m['phone'] ?? ''}'.isNotEmpty);
      final meta = secMeta['${m['sectionId']}'];
      if (meta != null && meta.name.contains('-')) {
        classStudents.putIfAbsent(
            '${meta.form}|${meta.name.split('-').first.toUpperCase()}|$nm',
                () => (id: d.id, hasPhone: '${m['phone'] ?? ''}'.isNotEmpty));
      }
      nameClasses
          .putIfAbsent(nm, () => <String>{})
          .add(secLabel['${m['sectionId']}'] ?? '?');
    }
    final dups = <ImportDuplicate>[];

    // Look at the header row: ignore the MOTHER name column(s) and remember
    // which column holds the STUDENT name.
    final motherRe = RegExp(r'mother|hooyo|\bum+\b|\bام\b|والدة|الأم',
        caseSensitive: false);
    final studentRe = RegExp(r'student|name|magac|arday|اسم|الطالب',
        caseSensitive: false);
    final skipCols = <int>{};
    int? nameCol;
    for (var i = 0; i < table.length && i < 5; i++) {
      final row = table[i];
      var found = false;
      for (var j = 0; j < row.length; j++) {
        final c = row[j].trim();
        if (c.isEmpty) continue;
        if (motherRe.hasMatch(c)) {
          skipCols.add(j);
          found = true;
        }
      }
      if (found) {
        for (var j = 0; j < row.length; j++) {
          final c = row[j].trim();
          if (!skipCols.contains(j) && studentRe.hasMatch(c)) {
            nameCol = j;
            break;
          }
        }
        break;
      }
    }

    // Phone column(s): found by the header (Phone, Mobile, Tel, Taleefon...).
    // Without such a header every cell that looks like a phone number counts.
    final phoneHeadRe = RegExp(
        r'phone|mobile|\btel\b|telephone|taleefo|contact|lambar|هاتف|جوال',
        caseSensitive: false);
    final phoneCols = <int>{};
    for (var i = 0; i < table.length && i < 5; i++) {
      for (var j = 0; j < table[i].length; j++) {
        if (phoneHeadRe.hasMatch(table[i][j])) phoneCols.add(j);
      }
      if (phoneCols.isNotEmpty) break;
    }
    List<String> phonesOfRow(List<String> row) {
      final out = <String>[];
      for (var j = 0; j < row.length; j++) {
        if (phoneCols.isNotEmpty && !phoneCols.contains(j)) continue;
        for (final p in phonesIn(row[j])) {
          if (!out.contains(p)) out.add(p);
        }
      }
      return out;
    }

    final writes = <void Function(WriteBatch)>[];
    var newSections = 0, newStudents = 0, skipped = 0;
    var updated = 0, noPhone = 0;
    for (var i = 0; i < table.length; i++) {
      final row = table[i];
      if (row.every((c) => c.trim().isEmpty)) continue;
      final parsed = _parseRow(row, skipCols: skipCols, nameCol: nameCol);
      if (parsed == null) {
        if (i > 0) skipped++; // the first row is normally the header
        continue;
      }
      final form = parsed.form;
      final section = parsed.section;
      final name = parsed.name;
      final key = '$form|$section';
      // The file says 1A but the class was divided into sections (1A-A,
      // 1A-B...): the student is already there. Do not add a second copy;
      // only fill in the missing phone number.
      if (name.isNotEmpty && !secIds.containsKey(key)) {
        final ck = '$form|${section.toUpperCase()}|${name.toLowerCase()}';
        final alt = classStudents[ck];
        if (alt != null) {
          final ph = phonesOfRow(row);
          if (!alt.hasPhone && ph.isNotEmpty) {
            updated++;
            classStudents[ck] = (id: alt.id, hasPhone: true);
            writes.add((b) => b.update(_students.doc(alt.id), {
              'phone': ph.first,
              'phones': ph,
              'username': ph.first,
              'updatedBy': _uid,
              'updatedAt': FieldValue.serverTimestamp(),
            }));
          } else {
            skipped++;
          }
          continue;
        }
      }
      String? id = secIds[key];
      if (id == null) {
        final ref = _sections.doc();
        final newId = ref.id;
        secIds[key] = newId;
        id = newId;
        newSections++;
        writes.add((b) => b.set(ref, {
          'form': form,
          'name': section,
          'updatedBy': _uid,
          'updatedAt': FieldValue.serverTimestamp(),
        }));
      }
      final String sid = id;
      if (name.isEmpty) continue; // a section with no student on this row
      final thisClass = SectionInfo.code(form, section);
      final lname = name.toLowerCase();
      final phones = phonesOfRow(row);
      final classesWithName = nameClasses.putIfAbsent(lname, () => <String>{});
      if (!existing.add('$sid|$lname')) {
        // Already in this section: only fill in a phone that is missing.
        final old = existingDocs['$sid|$lname'];
        if (old != null && !old.hasPhone && phones.isNotEmpty) {
          updated++;
          existingDocs['$sid|$lname'] = (id: old.id, hasPhone: true);
          writes.add((b) => b.update(_students.doc(old.id), {
            'phone': phones.first,
            'phones': phones,
            'username': phones.first,
            'updatedBy': _uid,
            'updatedAt': FieldValue.serverTimestamp(),
          }));
          continue;
        }
        skipped++;
        dups.add(ImportDuplicate(
          name: name,
          className: thisClass,
          allClasses: ({...classesWithName}.toList()..sort()),
          skipped: true,
        ));
        continue;
      }
      // Same name, but in a DIFFERENT class: still added, but reported.
      if (classesWithName.isNotEmpty && !classesWithName.contains(thisClass)) {
        dups.add(ImportDuplicate(
          name: name,
          className: thisClass,
          allClasses: ({...classesWithName}.toList()..sort()),
          skipped: false,
        ));
      }
      classesWithName.add(thisClass);
      newStudents++;
      if (phones.isEmpty) noPhone++;
      writes.add((b) => b.set(_students.doc(), {
        'sectionId': sid,
        'name': name,
        'phone': phones.isEmpty ? '' : phones.first,
        'phones': phones,
        // the first phone number is the username and the password
        'username': phones.isEmpty ? '' : phones.first,
        'createdBy': _uid,
        'createdAt': FieldValue.serverTimestamp(),
      }));
    }
    if (writes.isEmpty && skipped == 0) {
      throw Exception(
          'No valid rows found. The columns must be: Form, Section, Student name.');
    }
    for (var i = 0; i < writes.length; i += 400) {
      final batch = _db.batch();
      for (final w in writes.skip(i).take(400)) {
        w(batch);
      }
      await batch.commit();
    }
    return (
    sections: newSections,
    students: newStudents,
    skipped: skipped,
    updated: updated,
    noPhone: noPhone,
    dups: dups);
  }

  /// Deletes the section together with its students and attendance records.
  Future<void> deleteSection(String id) async {
    final st = await _students.where('sectionId', isEqualTo: id).get();
    final at = await _attendance.where('sectionId', isEqualTo: id).get();
    final batch = _db.batch();
    for (final d in [...st.docs, ...at.docs]) {
      batch.delete(d.reference);
    }
    batch.delete(_sections.doc(id));
    await batch.commit();
  }

  // ---------------- Students ----------------
  Stream<List<StudentInfo>> watchStudents(String sectionId) => _students
      .where('sectionId', isEqualTo: sectionId)
      .snapshots()
      .map((s) {
    final l = [
      for (final d in s.docs)
        StudentInfo(
            id: d.id,
            name: d.data()['name'] ?? '',
            sectionId: sectionId),
    ];
    l.sort((a, b) => a.name.toLowerCase().compareTo(b.name.toLowerCase()));
    return l;
  });

  /// sectionId -> number of students
  Stream<Map<String, int>> watchStudentCounts() =>
      _students.snapshots().map((s) {
        final out = <String, int>{};
        for (final d in s.docs) {
          final id = d.data()['sectionId'] as String?;
          if (id != null) out[id] = (out[id] ?? 0) + 1;
        }
        return out;
      });

  Future<void> addStudents(String sectionId, List<String> names) {
    final batch = _db.batch();
    for (final n in names) {
      batch.set(_students.doc(), {
        'sectionId': sectionId,
        'name': n,
        'createdBy': _uid,
        'createdAt': FieldValue.serverTimestamp(),
      });
    }
    return batch.commit();
  }

  /// Adds students that may have a phone number. Returns the new ids.
  Future<List<String>> addStudentsWithPhones(
      String sectionId, List<({String name, String phone})> list) async {
    final batch = _db.batch();
    final ids = <String>[];
    for (final e in list) {
      final ref = _students.doc();
      ids.add(ref.id);
      final phones = phonesIn(e.phone);
      batch.set(ref, {
        'sectionId': sectionId,
        'name': e.name,
        'phone': phones.isEmpty ? '' : phones.first,
        'phones': phones,
        'username': phones.isEmpty ? '' : phones.first,
        'createdBy': _uid,
        'createdAt': FieldValue.serverTimestamp(),
      });
    }
    await batch.commit();
    return ids;
  }

  Future<void> deleteStudent(String id) => _students.doc(id).delete();

  /// Edit: changes the name of a student.
  Future<void> renameStudent(String id, String name) =>
      _students.doc(id).update({
        'name': name.trim(),
        'updatedBy': _uid,
        'updatedAt': FieldValue.serverTimestamp(),
      });

  /// Edit: name + phone numbers. The first number is the username/password.
  Future<void> updateStudent(String id, String name, String phoneText) {
    final phones = phonesIn(phoneText);
    return _students.doc(id).update({
      'name': name.trim(),
      'phone': phones.isEmpty ? '' : phones.first,
      'phones': phones,
      'username': phones.isEmpty ? '' : phones.first,
      'updatedBy': _uid,
      'updatedAt': FieldValue.serverTimestamp(),
    });
  }

  /// Change: moves a student to another section / class of the same form.
  Future<void> moveStudent(String id, String newSectionId) =>
      _students.doc(id).update({
        'sectionId': newSectionId,
        'updatedBy': _uid,
        'updatedAt': FieldValue.serverTimestamp(),
      });

  /// Every student of every section, live (used by the Students page).
  Stream<List<StudentInfo>> watchAllStudents() =>
      _students.snapshots().map((s) => [
        for (final d in s.docs)
          StudentInfo(
              id: d.id,
              name: '${d.data()['name'] ?? ''}',
              sectionId: '${d.data()['sectionId'] ?? ''}',
              phone: '${d.data()['phone'] ?? ''}',
              phones: _phoneList(d.data()['phones'], d.data()['phone']),
              accountUid: '${d.data()['accountUid'] ?? ''}'),
      ]);

// ---------------- Attendance ----------------
  /// Subject '' means "Whole day" (the old behaviour, so old records still work).
  static String subjectKey(String subject) =>
      subject.trim().replaceAll(RegExp(r'[^A-Za-z0-9]+'), '_');

  String _attId(String sectionId, String dateKey, [String subject = '']) {
    final k = subjectKey(subject);
    return k.isEmpty ? '${sectionId}_$dateKey' : '${sectionId}_${dateKey}_$k';
  }

  static Map<String, String> _recordsOf(Object? r) =>
      r is Map ? r.map((k, v) => MapEntry('$k', '$v')) : <String, String>{};

  /// studentId -> 'present' | 'absent' | 'late'
  Future<Map<String, String>> getAttendance(String sectionId, String dateKey,
      {String subject = ''}) async {
    final d = await _attendance.doc(_attId(sectionId, dateKey, subject)).get();
    return _recordsOf(d.data()?['records']);
  }

  Future<void> saveAttendance(
      String sectionId, String dateKey, Map<String, String> records,
      {String subject = ''}) {
    return _attendance.doc(_attId(sectionId, dateKey, subject)).set({
      'sectionId': sectionId,
      'date': dateKey,
      'subject': subject.trim(),
      'records': records,
      'updatedBy': _uid,
      'updatedAt': FieldValue.serverTimestamp(),
    }).timeout(const Duration(seconds: 30), onTimeout: () {
      throw Exception('Saving timed out. Check the internet connection.');
    });
  }

  /// Every register between two dates (yyyy-MM-dd, inclusive). One range
  /// filter on one field, so no extra Firestore index is needed.
  Future<List<AttendanceDoc>> getAttendanceRange(
      String fromKey, String toKey) async {
    final q = await _attendance
        .where('date', isGreaterThanOrEqualTo: fromKey)
        .where('date', isLessThanOrEqualTo: toKey)
        .get();
    return [
      for (final d in q.docs)
        AttendanceDoc(
          id: d.id,
          sectionId: '${d.data()['sectionId'] ?? ''}',
          dateKey: '${d.data()['date'] ?? ''}',
          subject: '${d.data()['subject'] ?? ''}',
          records: _recordsOf(d.data()['records']),
        ),
    ];
  }

  /// Deletes saved registers (used by "Delete report").
  Future<void> deleteAttendanceDocs(List<String> ids) async {
    for (var i = 0; i < ids.length; i += 400) {
      final batch = _db.batch();
      for (final id in ids.skip(i).take(400)) {
        batch.delete(_attendance.doc(id));
      }
      await batch.commit();
    }
  }

  /// studentId -> student (used by the report for names).
  Future<Map<String, StudentInfo>> getAllStudents() async {
    final q = await _students.get();
    final map = {
      for (final d in q.docs)
        d.id: StudentInfo(
            id: d.id,
            name: '${d.data()['name'] ?? ''}',
            sectionId: '${d.data()['sectionId'] ?? ''}',
            phone: '${d.data()['phone'] ?? ''}',
            phones: _phoneList(d.data()['phones'], d.data()['phone'])),
    };
// A student without a phone takes the phone of the student with the same
// name in the same class (1A and 1A-A / 1A-B are the same class), as
// shown in the Students tab.
    try {
      final secs = await _sections.get();
      final info = {for (final d in secs.docs) d.id: SectionInfo.fromDoc(d)};
      String k(StudentInfo s) {
        final sec = info[s.sectionId];
        return '${sec?.form}|${sec?.classKey}|'
            '${s.name.trim().toLowerCase().replaceAll(RegExp(r'\s+'), ' ')}';
      }

      final withPhone = <String, StudentInfo>{};
      for (final s in map.values) {
        if (s.phoneText.isNotEmpty) withPhone.putIfAbsent(k(s), () => s);
      }
      for (final e in map.entries.toList()) {
        if (e.value.phoneText.isNotEmpty) continue;
        final o = withPhone[k(e.value)];
        if (o == null) continue;
        map[e.key] = StudentInfo(
            id: e.value.id,
            name: e.value.name,
            sectionId: e.value.sectionId,
            phone: o.phone,
            phones: o.phones);
      }
    } catch (_) {}
    return map;
  }
}

// ======================= SECTIONS SCREEN =======================

class SectionsScreen extends StatefulWidget {
  const SectionsScreen({super.key});

  @override
  State<SectionsScreen> createState() => _SectionsScreenState();
}

class _SectionsScreenState extends State<SectionsScreen> {
  final SchoolService _service = SchoolService();
  late final Stream<List<SectionInfo>> _secStream = _service.watchSections();
  late final Stream<Map<String, int>> _countStream =
  _service.watchStudentCounts();
  late final Stream<List<StudentInfo>> _stuStream =
  _service.watchAllStudents();
  final TextEditingController _searchCtrl = TextEditingController();
  String _query = '';

  @override
  void dispose() {
    _searchCtrl.dispose();
    super.dispose();
  }

  /// Search words (lower case). A section / class / student matches when it
  /// contains every word.
  List<String> get _tokens => _query
      .toLowerCase()
      .split(RegExp(r'\s+'))
      .where((t) => t.isNotEmpty)
      .toList();

  static bool _hit(String text, List<String> tokens) {
    final t = text.toLowerCase();
    return tokens.every(t.contains);
  }

  /// [text] with every search word marked (bold + coloured background).
  Widget _highlighted(BuildContext context, String text, List<String> tokens) {
    final base = const TextStyle(fontSize: 14, color: Colors.black87);
    final low = text.toLowerCase();
    final marks = List<bool>.filled(text.length, false);
    for (final t in tokens) {
      var i = low.indexOf(t);
      while (i >= 0) {
        for (var j = i; j < i + t.length && j < marks.length; j++) {
          marks[j] = true;
        }
        i = low.indexOf(t, i + t.length);
      }
    }
    final hl = base.copyWith(
        fontWeight: FontWeight.bold,
        backgroundColor: const Color(0xFFFFE082));
    final spans = <TextSpan>[];
    var start = 0;
    for (var i = 1; i <= text.length; i++) {
      if (i == text.length || marks[i] != marks[start]) {
        spans.add(TextSpan(
            text: text.substring(start, i), style: marks[start] ? hl : base));
        start = i;
      }
    }
    return Text.rich(TextSpan(children: spans));
  }

  Widget _searchBar() {
    return Padding(
      padding: const EdgeInsets.fromLTRB(12, 8, 12, 0),
      child: Align(
        alignment: Alignment.centerLeft,
        child: ConstrainedBox(
          constraints: const BoxConstraints(maxWidth: 480),
          child: TextField(
            controller: _searchCtrl,
            onChanged: (v) => setState(() => _query = v),
            textInputAction: TextInputAction.search,
            decoration: InputDecoration(
              isDense: true,
              filled: true,
              hintText: 'Search class, section or student',
              prefixIcon: const Icon(Icons.search),
              suffixIcon: _query.isEmpty
                  ? null
                  : IconButton(
                tooltip: 'Clear',
                icon: const Icon(Icons.close),
                onPressed: () {
                  _searchCtrl.clear();
                  setState(() => _query = '');
                },
              ),
              border: OutlineInputBorder(
                borderRadius: BorderRadius.circular(28),
                borderSide: BorderSide.none,
              ),
            ),
          ),
        ),
      ),
    );
  }

  Future<void> _delete(
      BuildContext context, SchoolService service, SectionInfo s) async {
    final ok = await showDialog<bool>(
      context: context,
      builder: (ctx) => AlertDialog(
        title: const Text('Delete section?'),
        content: Text(
            'Delete "${s.label}" with all its students and attendance records? '
                'This cannot be undone.'),
        actions: [
          TextButton(
              onPressed: () => Navigator.pop(ctx, false),
              child: const Text('Cancel')),
          FilledButton(
              onPressed: () => Navigator.pop(ctx, true),
              child: const Text('Delete')),
        ],
      ),
    );
    if (ok != true || !context.mounted) return;
    final messenger = ScaffoldMessenger.of(context);
    try {
      await service.deleteSection(s.id);
      messenger.showSnackBar(const SnackBar(content: Text('Section deleted')));
    } catch (e) {
      messenger.showSnackBar(SnackBar(content: Text('Failed: $e')));
    }
  }

  static String _students(int n) => '$n student${n == 1 ? '' : 's'}';

  /// One section (a whole class like 1C, or a part of a class like 1B-A).
  Widget _sectionTile(BuildContext context, SchoolService service,
      SectionInfo s, Map<String, int> counts,
      {bool sub = false, List<String> matches = const []}) {
    final n = counts[s.id] ?? 0;
    final open = () => Navigator.of(context).push(
      MaterialPageRoute(
        builder: (_) => SectionStudentsScreen(section: s, service: service),
      ),
    );
    final tile = ListTile(
      dense: true,
      visualDensity: VisualDensity.compact,
      contentPadding: EdgeInsets.only(left: sub ? 20 : 12, right: 0),
      leading: sub
          ? CircleAvatar(
        radius: 16,
        backgroundColor: const Color(0xFFEAD7F2),
        child: Text(s.subName.isEmpty ? s.name : s.subName,
            style: const TextStyle(
                fontSize: 13,
                fontWeight: FontWeight.bold,
                color: Color(0xFF7D3C98))),
      )
          : const CircleAvatar(
        backgroundColor: Color(0xFFEAD7F2),
        child: Icon(Icons.groups, color: Color(0xFF9B59B6)),
      ),
      title: Text(sub && s.subName.isNotEmpty ? 'Section ${s.subName}' : s.label,
          style: const TextStyle(fontWeight: FontWeight.w600)),
      subtitle: Text(matches.isEmpty
          ? _students(n)
          : '${_students(n)} · ${matches.length} '
          'match${matches.length == 1 ? '' : 'es'}'),
      onTap: () => Navigator.of(context).push(
        MaterialPageRoute(
          builder: (_) => SectionStudentsScreen(section: s, service: service),
        ),
      ),
      trailing: PopupMenuButton<String>(
        onSelected: (v) {
          if (v == 'edit') {
            showDialog(
              context: context,
              builder: (_) => SectionDialog(service: service, section: s),
            );
          } else {
            _delete(context, service, s);
          }
        },
        itemBuilder: (_) => const [
          PopupMenuItem(value: 'edit', child: Text('Edit')),
          PopupMenuItem(value: 'delete', child: Text('Delete')),
        ],
      ),
    );
    if (matches.isEmpty) return tile;
    final names = [...matches]
      ..sort((a, b) => a.toLowerCase().compareTo(b.toLowerCase()));
    final tokens = _tokens;
    return Column(
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: [
        tile,
        Container(
          margin: EdgeInsets.only(left: sub ? 20 : 12, right: 12, bottom: 8),
          padding: const EdgeInsets.symmetric(vertical: 4),
          decoration: BoxDecoration(
            color: const Color(0xFFFFF8E1),
            borderRadius: BorderRadius.circular(10),
          ),
          child: Column(
            children: [
              for (final nm in names)
                InkWell(
                  onTap: open,
                  child: Padding(
                    padding: const EdgeInsets.symmetric(
                        horizontal: 12, vertical: 6),
                    child: Row(
                      children: [
                        const Icon(Icons.person,
                            size: 18, color: Color(0xFF7D3C98)),
                        const SizedBox(width: 8),
                        Expanded(child: _highlighted(context, nm, tokens)),
                      ],
                    ),
                  ),
                ),
            ],
          ),
        ),
      ],
    );
  }

  /// Students of a class, each counted once: the whole-class record when there
  /// is one, otherwise the sum of its sections.
  static int _classTotal(List<SectionInfo> list, Map<String, int> counts) {
    final whole = list.where((s) => !s.isSub);
    final pick = whole.isNotEmpty ? whole : list;
    return pick.fold<int>(0, (a, s) => a + (counts[s.id] ?? 0));
  }

  /// A class: a plain card when it is not divided, otherwise a card that
  /// holds its sections (1B -> 1B-A, 1B-B, 1B-C).
  Widget _classCard(BuildContext context, SchoolService service, String form,
      String key, List<SectionInfo> list, Map<String, int> counts,
      {List<SectionInfo>? visible,
        Map<String, List<String>> matches = const {},
        bool searching = false}) {
    int byName(SectionInfo a, SectionInfo b) =>
        a.name.toUpperCase().compareTo(b.name.toUpperCase());
    list.sort(byName);
    final shown = [...(visible ?? list)]..sort(byName);
    if (list.length == 1 && !list.first.isSub) {
      return Card(
          child: _sectionTile(context, service, list.first, counts,
              matches: matches[list.first.id] ?? const []));
    }
// The whole class (1A) already holds every student, so its sections
// (1A-A, 1A-B ...) are not counted again and the whole-class row is hidden.
    final subs = list.where((s) => s.isSub).toList();
    final total = _classTotal(list, counts);
    return Card(
      clipBehavior: Clip.antiAlias,
      child: ExpansionTile(
        key: ValueKey('$form|$key|${searching ? 's' : ''}'),
        initiallyExpanded: true,
        shape: const Border(),
        collapsedShape: const Border(),
        leading: const CircleAvatar(
          backgroundColor: Color(0xFFD7BDE2),
          child: Icon(Icons.account_tree, color: Color(0xFF7D3C98)),
        ),
        title: Text(SectionInfo.code(form, key),
            style: const TextStyle(fontWeight: FontWeight.bold)),
        subtitle: Text('${_students(total)} · ${subs.length} sections'),
        children: [
          for (final s in shown.where((s) => s.isSub))
            _sectionTile(context, service, s, counts,
                sub: true, matches: matches[s.id] ?? const []),
        ],
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    final service = _service;
    return Scaffold(
      appBar: AppBar(
        title: const Text('Sections'),
        actions: [
          _SectionsTools(service: service),
          const SizedBox(width: 8),
        ],
      ),
      floatingActionButton: FloatingActionButton.extended(
        onPressed: () => showDialog(
          context: context,
          builder: (_) => DivideDialog(service: service),
        ),
        icon: const Icon(Icons.call_split),
        label: const Text('Divide class'),
      ),
      body: Column(
        children: [
          _searchBar(),
          Expanded(child: _content(context, service)),
        ],
      ),
    );
  }

  Widget _content(BuildContext context, SchoolService service) {
    final tokens = _tokens;
    final searching = tokens.isNotEmpty;
    return StreamBuilder<List<SectionInfo>>(
      stream: _secStream,
      builder: (context, snap) {
        if (snap.hasError) return Center(child: Text('Error: ${snap.error}'));
        if (!snap.hasData) {
          return const Center(child: CircularProgressIndicator());
        }
        final sections = snap.data!;
        if (sections.isEmpty) {
          return const Center(
            child: Padding(
              padding: EdgeInsets.all(24),
              child: Text(
                'No classes yet.\nUse the upload button to load a student list (1A, 1B, 2C...).',
                textAlign: TextAlign.center,
              ),
            ),
          );
        }
// form -> class (A, B, C...) -> its sections
        final byForm = <String, Map<String, List<SectionInfo>>>{};
        for (final s in sections) {
          (byForm[s.form] ??= {}).putIfAbsent(s.classKey, () => []).add(s);
        }
        final forms = byForm.keys.toList()..sort();
        return StreamBuilder<Map<String, int>>(
          stream: _countStream,
          builder: (context, cs) {
            final counts = cs.data ?? const <String, int>{};
// Students are only loaded while the person is searching.
            return StreamBuilder<List<StudentInfo>>(
              stream: searching ? _stuStream : null,
              builder: (context, st) {
// section id -> names of the students that match the search
                final stuHits = <String, List<String>>{};
                if (searching) {
                  for (final p in st.data ?? const <StudentInfo>[]) {
                    if (_hit('${p.name} ${p.phoneText}', tokens)) {
                      (stuHits[p.sectionId] ??= []).add(p.name);
                    }
                  }
                }
// form -> class -> sections to show
                final shownByForm =
                <String, Map<String, List<SectionInfo>>>{};
                final shownMatches = <String, List<String>>{};
                for (final f in forms) {
                  final classes = byForm[f]!;
                  final shown = <String, List<SectionInfo>>{};
                  for (final k in classes.keys) {
                    final list = classes[k]!;
                    if (!searching ||
                        _hit('${SectionInfo.code(f, k)} $f $k', tokens)) {
                      shown[k] = list; // the class itself matches: show all
                      continue;
                    }
                    final vis = <SectionInfo>[];
                    for (final s in list) {
                      final secHit = _hit(
                          '${s.label} ${s.fullName} ${s.form} ${s.name}',
                          tokens);
                      final names = stuHits[s.id];
                      if (secHit || names != null) {
                        vis.add(s);
                        if (!secHit && names != null) {
                          shownMatches[s.id] = names;
                        }
                      }
                    }
                    if (vis.isNotEmpty) shown[k] = vis;
                  }
                  if (shown.isNotEmpty) shownByForm[f] = shown;
                }
                if (searching && shownByForm.isEmpty) {
                  if (st.connectionState == ConnectionState.waiting) {
                    return const Center(child: CircularProgressIndicator());
                  }
                  return Center(
                    child: Padding(
                      padding: const EdgeInsets.all(24),
                      child: Text('No class, section or student matches '
                          '"${_query.trim()}".'),
                    ),
                  );
                }
                var found = 0, foundIn = 0;
                for (final e in shownMatches.entries) {
                  found += e.value.length;
                  foundIn++;
                }
                final columns = <Widget>[];
                for (final f in forms) {
                  if (!shownByForm.containsKey(f)) continue;
                  final classes = byForm[f]!;
                  final keys = classes.keys.toList()..sort();
                  final total = classes.values
                      .fold<int>(0, (a, l) => a + _classTotal(l, counts));
                  columns.add(_formColumn(
                    context,
                    service,
                    f,
                    keys,
                    classes,
                    counts,
                    total,
                    shown: shownByForm[f]!,
                    matches: shownMatches,
                    searching: searching,
                  ));
                }
// All forms side by side. If they do not fit the screen at the
// minimum column width, the row scrolls sideways.
                final layout = LayoutBuilder(builder: (context, box) {
                  const gap = 12.0, pad = 12.0, minW = 300.0, maxW = 420.0;
                  final n = columns.length;
                  final avail = box.maxWidth - pad * 2 - gap * (n - 1);
                  final w = (avail / n).clamp(minW, maxW).toDouble();
                  final row = Row(
                    crossAxisAlignment: CrossAxisAlignment.stretch,
                    mainAxisSize: MainAxisSize.min,
                    children: [
                      for (var i = 0; i < n; i++) ...[
                        if (i > 0) const SizedBox(width: gap),
                        SizedBox(width: w, child: columns[i]),
                      ],
                    ],
                  );
                  final h = (box.maxHeight - 12 - 88).clamp(200.0, 100000.0);
                  return SingleChildScrollView(
                    scrollDirection: Axis.horizontal,
                    padding: const EdgeInsets.fromLTRB(pad, 12, pad, 88),
                    child: SizedBox(height: h, child: row),
                  );
                });
                if (found == 0) return layout;
                return Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Padding(
                      padding: const EdgeInsets.fromLTRB(16, 10, 16, 0),
                      child: Text(
                        '$found student${found == 1 ? '' : 's'} found '
                            'in $foundIn section${foundIn == 1 ? '' : 's'}',
                        style: const TextStyle(fontWeight: FontWeight.w600),
                      ),
                    ),
                    Expanded(child: layout),
                  ],
                );
              },
            );
          },
        );
      },
    );
  }

  /// One form as a card (a column): header + all its classes and sections,
  /// scrolling vertically inside the card.
  Widget _formColumn(
      BuildContext context,
      SchoolService service,
      String form,
      List<String> keys,
      Map<String, List<SectionInfo>> classes,
      Map<String, int> counts,
      int total,
      {required Map<String, List<SectionInfo>> shown,
        Map<String, List<String>> matches = const {},
        bool searching = false}) {
    final cs = Theme.of(context).colorScheme;
    return Card(
      margin: EdgeInsets.zero,
      clipBehavior: Clip.antiAlias,
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          Container(
            color: cs.primaryContainer,
            padding: const EdgeInsets.fromLTRB(16, 12, 16, 12),
            child: Row(
              crossAxisAlignment: CrossAxisAlignment.baseline,
              textBaseline: TextBaseline.alphabetic,
              children: [
                Text(form,
                    style: TextStyle(
                        fontSize: 20,
                        fontWeight: FontWeight.bold,
                        color: cs.onPrimaryContainer)),
                const SizedBox(width: 10),
                Expanded(
                  child: Text(
                      '${_students(total)} · ${keys.length} '
                          'class${keys.length == 1 ? '' : 'es'}',
                      overflow: TextOverflow.ellipsis,
                      style: TextStyle(
                          fontSize: 13,
                          color: cs.onPrimaryContainer.withOpacity(0.75))),
                ),
              ],
            ),
          ),
          Expanded(
            child: ListView(
              padding: const EdgeInsets.all(8),
              children: [
                for (final k in keys)
                  if (shown.containsKey(k))
                    _classCard(context, service, form, k, classes[k]!, counts,
                        visible: shown[k],
                        matches: matches,
                        searching: searching),
              ],
            ),
          ),
        ],
      ),
    );
  }
}

/// Divide many classes at once: every class (of every form) has its own
/// "divide into" choice; one dropdown sets all, one per form sets a form.
class DivideDialog extends StatefulWidget {
  final SchoolService service;
  const DivideDialog({super.key, required this.service});

  @override
  State<DivideDialog> createState() => _DivideDialogState();
}

class _DivideDialogState extends State<DivideDialog> {
  List<SectionInfo> _sections = const [];
  Map<String, int> _counts = const {};
  final _plan = <String, int>{}; // class id -> number of sections (2+)
  bool _loaded = false;
  bool _busy = false;

  static const _choices = [2, 3, 4, 5, 6, 7, 8];

  @override
  void initState() {
    super.initState();
    _load();
  }

  Future<void> _load() async {
    try {
      final s = await widget.service.watchSections().first;
      final c = await widget.service.watchStudentCounts().first;
      if (mounted) {
        setState(() {
          _sections = s;
          _counts = c;
          _loaded = true;
        });
      }
    } catch (_) {
      if (mounted) setState(() => _loaded = true);
    }
  }

  List<SectionInfo> _inForm(String f) => [
    for (final s in _sections)
      if (s.form == f) s,
  ]..sort((a, b) => a.name.toUpperCase().compareTo(b.name.toUpperCase()));

  void _setMany(Iterable<SectionInfo> list, int? n) => setState(() {
    for (final s in list) {
      if (n == null) {
        _plan.remove(s.id);
      } else {
        _plan[s.id] = n;
      }
    }
  });

  Widget _picker(int? value, ValueChanged<int?> onChanged,
      {String none = '-'}) {
    return DropdownButton<int?>(
      value: value,
      isDense: true,
      underline: const SizedBox(),
      onChanged: _busy ? null : onChanged,
      items: [
        DropdownMenuItem<int?>(value: null, child: Text(none)),
        for (final n in _choices)
          DropdownMenuItem<int?>(value: n, child: Text('$n sections')),
      ],
    );
  }

  Future<void> _divide() async {
    final messenger = ScaffoldMessenger.of(context);
    final nav = Navigator.of(context);
    final chosen = [
      for (final s in _sections)
        if ((_plan[s.id] ?? 0) >= 2) s,
    ];
    if (chosen.isEmpty) {
      messenger.showSnackBar(const SnackBar(
          content: Text('Choose how many sections for at least one class.')));
      return;
    }
    final ok = await showDialog<bool>(
      context: context,
      builder: (ctx) => AlertDialog(
        title: Text('Divide ${chosen.length} '
            'class${chosen.length == 1 ? '' : 'es'}?'),
        content: const Text('The students are moved to the new sections and '
            'each undivided class is replaced.'),
        actions: [
          TextButton(
              onPressed: () => Navigator.pop(ctx, false),
              child: const Text('Cancel')),
          FilledButton(
              onPressed: () => Navigator.pop(ctx, true),
              child: const Text('Divide')),
        ],
      ),
    );
    if (ok != true || !mounted) return;
    setState(() => _busy = true);
    try {
      final r = await widget.service.divideMany(Map.of(_plan));
      nav.pop();
      messenger.showSnackBar(SnackBar(
          content: Text('Divided ${r.classes} '
              'class${r.classes == 1 ? '' : 'es'} (${r.students} students)')));
    } catch (e) {
      if (mounted) setState(() => _busy = false);
      messenger.showSnackBar(SnackBar(
          content: Text('Failed: ${'$e'.replaceFirst('Exception: ', '')}')));
    }
  }

  @override
  Widget build(BuildContext context) {
    final picked = _plan.values.where((v) => v >= 2).length;
    final bold = const TextStyle(fontWeight: FontWeight.w600);
    return AlertDialog(
      title: const Text('Divide classes'),
      content: SizedBox(
        width: 420,
        child: !_loaded
            ? const Padding(
            padding: EdgeInsets.all(24),
            child: LinearProgressIndicator())
            : _sections.isEmpty
            ? const Text('No classes yet. Upload a student list first.')
            : SingleChildScrollView(
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Row(children: [
                Expanded(
                    child: Text('All classes, all forms', style: bold)),
                _picker(null, (v) => _setMany(_sections, v),
                    none: 'Set all...'),
              ]),
              const Divider(),
              for (final f in ExamService.forms)
                if (_inForm(f).isNotEmpty) ...[
                  Row(children: [
                    Expanded(child: Text(f, style: bold)),
                    _picker(null, (v) => _setMany(_inForm(f), v),
                        none: 'Set $f...'),
                  ]),
                  for (final c in _inForm(f))
                    Row(children: [
                      Expanded(
                          child: Text(
                              '${c.label}  ·  ${_counts[c.id] ?? 0} students')),
                      _picker(_plan[c.id],
                              (v) => _setMany([c], v)),
                    ]),
                  const SizedBox(height: 8),
                ],
              const Text(
                  'Students are sorted by name and shared equally. '
                      'Old attendance records are not moved.',
                  style:
                  TextStyle(fontSize: 12, color: Colors.black54)),
            ],
          ),
        ),
      ),
      actions: [
        TextButton(
          onPressed: _busy ? null : () => Navigator.pop(context),
          child: const Text('Cancel'),
        ),
        FilledButton(
          onPressed: _busy || picked == 0 ? null : _divide,
          child: Text(picked == 0 ? 'Divide' : 'Divide $picked'),
        ),
      ],
    );
  }
}

/// Divide a form into a number of sections (or rename one section).
class SectionDialog extends StatefulWidget {
  final SchoolService service;
  final SectionInfo? section; // null = add new sections
  const SectionDialog({super.key, required this.service, this.section});

  @override
  State<SectionDialog> createState() => _SectionDialogState();
}

class _SectionDialogState extends State<SectionDialog> {
  late String _form = widget.section?.form.isNotEmpty == true &&
      ExamService.forms.contains(widget.section!.form)
      ? widget.section!.form
      : ExamService.forms.first;
  late final _name = TextEditingController(text: widget.section?.name ?? '');
  final _count = TextEditingController();
  final _selected = <String>{}; // ids of the classes to divide
  List<SectionInfo> _sections = const [];
  Map<String, int> _counts = const {};
  bool _loaded = false;
  bool _busy = false;

  @override
  void initState() {
    super.initState();
    if (widget.section == null) _loadInfo();
  }

  Future<void> _loadInfo() async {
    try {
      final s = await widget.service.watchSections().first;
      final c = await widget.service.watchStudentCounts().first;
      if (mounted) {
        setState(() {
          _sections = s;
          _counts = c;
          _loaded = true;
        });
      }
    } catch (_) {
      if (mounted) setState(() => _loaded = true);
    }
  }

  @override
  void dispose() {
    _name.dispose();
    _count.dispose();
    super.dispose();
  }

  /// The classes that exist in the chosen form (1A, 1B, 1C...).
  List<SectionInfo> get _inForm => [
    for (final s in _sections)
      if (s.form == _form) s,
  ]..sort((a, b) => a.name.toUpperCase().compareTo(b.name.toUpperCase()));

  List<SectionInfo> get _sel => [
    for (final s in _inForm)
      if (_selected.contains(s.id)) s,
  ];

  int? get _n {
    final n = int.tryParse(_count.text.trim());
    return (n == null || n < 2 || n > 20) ? null : n;
  }

  /// "1A (85) -> 1A-A, 1A-B, 1A-C (about 28 each)"
  String _line(SectionInfo s, int n) {
    final st = _counts[s.id] ?? 0;
    final parts = [
      for (var i = 1; i <= n; i++)
        SectionInfo.code(s.form, '${s.name}-${String.fromCharCode(64 + i)}'),
    ];
    return '${s.label} ($st) → ${parts.join(', ')}'
        '${st == 0 ? '' : ' (about ${(st / n).round()} each)'}';
  }

  Future<void> _save() async {
    final messenger = ScaffoldMessenger.of(context);
    final nav = Navigator.of(context);
    if (widget.section != null) {
      if (_name.text.trim().isEmpty) {
        messenger.showSnackBar(
            const SnackBar(content: Text('Enter the section name.')));
        return;
      }
      setState(() => _busy = true);
      try {
        await widget.service.saveSection(
            id: widget.section!.id, form: _form, name: _name.text);
        nav.pop();
        messenger.showSnackBar(const SnackBar(content: Text('Section saved')));
      } catch (e) {
        if (mounted) setState(() => _busy = false);
        messenger.showSnackBar(SnackBar(content: Text('Failed: $e')));
      }
      return;
    }

    final n = _n;
    if (_selected.isEmpty) {
      messenger.showSnackBar(
          const SnackBar(content: Text('Select at least one class.')));
      return;
    }
    if (n == null) {
      messenger.showSnackBar(const SnackBar(
          content: Text('Enter the number of sections (2 to 20).')));
      return;
    }
    final ok = await showDialog<bool>(
      context: context,
      builder: (ctx) => AlertDialog(
        title: const Text('Divide classes?'),
        content: Text('${_sel.map((s) => s.label).join(', ')} will be divided '
            'into $n sections each. The students are moved to the new '
            'sections and the undivided class is replaced.'),
        actions: [
          TextButton(
              onPressed: () => Navigator.pop(ctx, false),
              child: const Text('Cancel')),
          FilledButton(
              onPressed: () => Navigator.pop(ctx, true),
              child: const Text('Divide')),
        ],
      ),
    );
    if (ok != true || !mounted) return;
    setState(() => _busy = true);
    try {
      final r = await widget.service.divideClasses(_selected.toSet(), n);
      nav.pop();
      messenger.showSnackBar(SnackBar(
          content: Text('Divided ${r.classes} '
              'class${r.classes == 1 ? '' : 'es'} (${r.students} students) '
              'into $n sections each')));
    } catch (e) {
      if (mounted) setState(() => _busy = false);
      messenger.showSnackBar(SnackBar(
          content: Text('Failed: ${'$e'.replaceFirst('Exception: ', '')}')));
    }
  }

  @override
  Widget build(BuildContext context) {
    final isEdit = widget.section != null;
    final n = _n;
    final inForm = _inForm;
    final sel = _sel;
    return AlertDialog(
      title: Text(isEdit ? 'Edit section' : 'Divide class into sections'),
      content: SizedBox(
        width: 400,
        child: SingleChildScrollView(
          child: Column(
              mainAxisSize: MainAxisSize.min,
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                DropdownButtonFormField<String>(
                  value: _form,
                  decoration: const InputDecoration(
                      labelText: 'Form', border: OutlineInputBorder()),
                  items: [
                    for (final f in ExamService.forms)
                      DropdownMenuItem(value: f, child: Text(f)),
                  ],
                  onChanged: _busy
                      ? null
                      : (v) => setState(() {
                    _form = v ?? _form;
                    _selected.clear();
                  }),
                ),
                const SizedBox(height: 14),
                if (isEdit)
                  TextField(
                    controller: _name,
                    textCapitalization: TextCapitalization.characters,
                    decoration: const InputDecoration(
                      labelText: 'Section name',
                      hintText: 'A or A-B',
                      border: OutlineInputBorder(),
                    ),
                  )
                else ...[
                  Row(children: [
                    Expanded(
                      child: Text('Classes in $_form (tap to select)',
                          style: const TextStyle(fontWeight: FontWeight.w600)),
                    ),
                    if (inForm.isNotEmpty)
                      TextButton(
                        onPressed: _busy
                            ? null
                            : () => setState(() {
                          if (_selected.length == inForm.length) {
                            _selected.clear();
                          } else {
                            _selected
                              ..clear()
                              ..addAll(inForm.map((s) => s.id));
                          }
                        }),
                        child: Text(_selected.length == inForm.length
                            ? 'Clear'
                            : 'Select all'),
                      ),
                  ]),
                  const SizedBox(height: 6),
                  if (!_loaded)
                    const LinearProgressIndicator()
                  else if (inForm.isEmpty)
                    const Text(
                        'No classes in this form yet. Upload a student list '
                            'to create them.',
                        style: TextStyle(fontSize: 13, color: Colors.black54))
                  else
                    Wrap(spacing: 6, runSpacing: 6, children: [
                      for (final s in inForm)
                        FilterChip(
                          label: Text('${s.label} · ${_counts[s.id] ?? 0}'),
                          selected: _selected.contains(s.id),
                          onSelected: _busy
                              ? null
                              : (v) => setState(() {
                            if (v) {
                              _selected.add(s.id);
                            } else {
                              _selected.remove(s.id);
                            }
                          }),
                        ),
                    ]),
                  const SizedBox(height: 16),
                  TextField(
                    controller: _count,
                    keyboardType: TextInputType.number,
                    inputFormatters: [FilteringTextInputFormatter.digitsOnly],
                    onChanged: (_) => setState(() {}),
                    decoration: const InputDecoration(
                      labelText: 'Number of sections to divide each class into',
                      hintText: '3',
                      border: OutlineInputBorder(),
                    ),
                  ),
                  const SizedBox(height: 8),
                  if (n != null && sel.isNotEmpty)
                    for (final s in sel.take(6))
                      Padding(
                        padding: const EdgeInsets.only(bottom: 2),
                        child: Text(_line(s, n),
                            style: const TextStyle(
                                fontSize: 12, color: Colors.black54)),
                      ),
                  if (n != null && sel.length > 6)
                    Text('and ${sel.length - 6} more...',
                        style: const TextStyle(
                            fontSize: 12, color: Colors.black54)),
                  const SizedBox(height: 4),
                  const Text(
                      'Each selected class is divided on its own: students '
                          'are sorted by name and shared equally. No new classes '
                          'are created. Old attendance records are not moved.',
                      style: TextStyle(fontSize: 12, color: Colors.black54)),
                ],
              ]),
        ),
      ),
      actions: [
        TextButton(
          onPressed: _busy ? null : () => Navigator.pop(context),
          child: const Text('Cancel'),
        ),
        FilledButton(
          onPressed: _busy ? null : _save,
          child: Text(isEdit ? 'Save' : 'Divide'),
        ),
      ],
    );
  }
}

/// App-bar buttons of the Sections screen: upload and download student lists.
class _SectionsTools extends StatefulWidget {
  final SchoolService service;
  const _SectionsTools({required this.service});

  @override
  State<_SectionsTools> createState() => _SectionsToolsState();
}

class _SectionsToolsState extends State<_SectionsTools> {
  bool _busy = false;

  Future<void> _download() async {
    setState(() => _busy = true);
    final messenger = ScaffoldMessenger.of(context);
    try {
      final n = await widget.service.downloadSections();
      messenger.showSnackBar(
          SnackBar(content: Text('Downloaded sections with $n students')));
    } catch (e) {
      messenger.showSnackBar(
          SnackBar(content: Text('$e'.replaceFirst('Exception: ', ''))));
    } finally {
      if (mounted) setState(() => _busy = false);
    }
  }

  /// All sections as a PDF with the Exam-tab header on every section.
  Future<void> _downloadPdf() async {
    setState(() => _busy = true);
    final messenger = ScaffoldMessenger.of(context);
    try {
      final r = await widget.service.buildSectionsPdf();
      final path = await _downloadInBrowser(
          r.bytes, 'Sections-${DateTime.now().year}.pdf', 'application/pdf');
      messenger.showSnackBar(SnackBar(
          duration: const Duration(seconds: 8),
          content: Text(path == null && !kIsWeb
              ? 'Download cancelled (nothing was saved).'
              : 'PDF saved: ${r.sections} sections, ${r.students} students'
              '${path == null ? ' - check your browser Downloads folder' : '\nSaved to: $path'}')));
    } catch (e) {
      messenger.showSnackBar(
          SnackBar(content: Text('$e'.replaceFirst('Exception: ', ''))));
    } finally {
      if (mounted) setState(() => _busy = false);
    }
  }

  /// All sections as an editable Word file with the Exam-tab header.
  Future<void> _downloadDocx() async {
    setState(() => _busy = true);
    final messenger = ScaffoldMessenger.of(context);
    try {
      final r = await widget.service.buildSectionsDocx();
      final path = await _downloadInBrowser(
          r.bytes,
          'Sections-${DateTime.now().year}.docx',
          'application/vnd.openxmlformats-officedocument.wordprocessingml.document');
      messenger.showSnackBar(SnackBar(
          duration: const Duration(seconds: 8),
          content: Text(path == null && !kIsWeb
              ? 'Download cancelled (nothing was saved).'
              : 'Word saved: ${r.sections} sections, ${r.students} students'
              '${path == null ? ' - check your browser Downloads folder' : '\nSaved to: $path'}')));
    } catch (e) {
      messenger.showSnackBar(
          SnackBar(content: Text('$e'.replaceFirst('Exception: ', ''))));
    } finally {
      if (mounted) setState(() => _busy = false);
    }
  }

  /// Opens the print dialog with every section (one section per page).
  Future<void> _printAll() async {
    setState(() => _busy = true);
    final messenger = ScaffoldMessenger.of(context);
    try {
      final r = await widget.service.buildSectionsPdf();
      if (mounted) setState(() => _busy = false);
      await Printing.layoutPdf(
        name: 'Sections-${DateTime.now().year}',
        onLayout: (_) async => r.bytes,
      );
    } catch (e) {
      messenger.showSnackBar(
          SnackBar(content: Text('$e'.replaceFirst('Exception: ', ''))));
    } finally {
      if (mounted) setState(() => _busy = false);
    }
  }

  Future<void> _deleteAll() async {
    final ctrl = TextEditingController();
    final ok = await showDialog<bool>(
      context: context,
      builder: (ctx) => StatefulBuilder(
        builder: (ctx, setD) => AlertDialog(
          title: const Text('Delete ALL sections?'),
          content: SizedBox(
            width: 380,
            child: Column(mainAxisSize: MainAxisSize.min, children: [
              const Text(
                  'This deletes every section together with ALL their '
                      'students and attendance records. This cannot be undone.\n\n'
                      'Tip: download the PDF or Word file first to keep a copy.\n\n'
                      'Type DELETE to confirm.'),
              const SizedBox(height: 12),
              TextField(
                controller: ctrl,
                autofocus: true,
                onChanged: (_) => setD(() {}),
                decoration: const InputDecoration(border: OutlineInputBorder()),
              ),
            ]),
          ),
          actions: [
            TextButton(
                onPressed: () => Navigator.pop(ctx, false),
                child: const Text('Cancel')),
            FilledButton(
              style: FilledButton.styleFrom(backgroundColor: Colors.red),
              onPressed: ctrl.text.trim().toUpperCase() == 'DELETE'
                  ? () => Navigator.pop(ctx, true)
                  : null,
              child: const Text('Delete all'),
            ),
          ],
        ),
      ),
    );
    ctrl.dispose();
    if (ok != true || !mounted) return;
    setState(() => _busy = true);
    final messenger = ScaffoldMessenger.of(context);
    try {
      final n = await widget.service.deleteAllSections();
      messenger.showSnackBar(SnackBar(content: Text('Deleted $n sections')));
    } catch (e) {
      messenger.showSnackBar(SnackBar(content: Text('Failed: $e')));
    } finally {
      if (mounted) setState(() => _busy = false);
    }
  }

  Future<void> _upload() async {
    final go = await showDialog<bool>(
      context: context,
      builder: (ctx) => AlertDialog(
        title: const Text('Upload student list'),
        content: const SizedBox(
          width: 400,
          child: Text(
            'Choose an Excel (.xlsx) or CSV file for ALL classes. '
                'Use these columns: the class, the student name and the phone number:\n\n'
                'Class  |  Student name  |  Phone\n'
                '1A  |  Ali Hassan  |  0634123456\n'
                '1B  |  Amina Yusuf  |  0634765432\n'
                '2C  |  Omar Abdi  |  0634111222\n'
                '4B  |  Hodan Warsame  |  0634333444\n\n'
                'Separate Form | Section | Student name columns also work.\n\n'
                'Add a Phone column (Phone, Mobile or Tel) to save the phone '
                'numbers. Several numbers in one cell can be separated by a '
                'comma. The FIRST phone number becomes the student\'s '
                'username and password.\n\n'
                'Every class in the file (1A, 1B, 2C, 4B...) is created '
                'automatically if it does not exist yet. '
                'Students that are already in a section are skipped.',
          ),
        ),
        actions: [
          TextButton(
              onPressed: () => Navigator.pop(ctx, false),
              child: const Text('Cancel')),
          FilledButton.icon(
            onPressed: () => Navigator.pop(ctx, true),
            icon: const Icon(Icons.attach_file),
            label: const Text('Choose file'),
          ),
        ],
      ),
    );
    if (go != true || !mounted) return;
    final res = await FilePicker.platform.pickFiles(
      withData: true,
      type: FileType.custom,
      allowedExtensions: ['xlsx', 'csv', 'txt'],
    );
    if (res == null || res.files.isEmpty || !mounted) return;
    setState(() => _busy = true);
    final messenger = ScaffoldMessenger.of(context);
    try {
      final r = await widget.service.importFile(res.files.first);
      if (r.dups.isNotEmpty) {
        if (mounted) {
          await showImportResult(context,
              students: r.students,
              sections: r.sections,
              skipped: r.skipped,
              updated: r.updated,
              noPhone: r.noPhone,
              dups: r.dups);
        }
      } else {
        messenger.showSnackBar(SnackBar(
          duration: const Duration(seconds: 6),
          content: Text('Added ${r.students} students and ${r.sections} new '
              'sections. ${r.skipped} rows skipped (duplicates or invalid).'
              '${r.updated > 0 ? ' Phone number added to ${r.updated} existing students.' : ''}'
              '${r.noPhone > 0 ? ' ${r.noPhone} new students have no phone number (they cannot log in).' : ''}'),
        ));
      }
// every uploaded student with a phone number gets the login now
      if (mounted) {
        await runAccountCreation(context);
      }
    } catch (e) {
      messenger.showSnackBar(SnackBar(
          content: Text('Upload failed: ${'$e'.replaceFirst('Exception: ', '')}')));
    } finally {
      if (mounted) setState(() => _busy = false);
    }
  }

  @override
  Widget build(BuildContext context) {
    if (_busy) {
      return const Padding(
        padding: EdgeInsets.symmetric(horizontal: 12),
        child: Center(
          child: SizedBox(
              width: 20,
              height: 20,
              child: CircularProgressIndicator(strokeWidth: 2)),
        ),
      );
    }
    return Row(mainAxisSize: MainAxisSize.min, children: [
      IconButton(
        tooltip: 'Upload student list (Excel / CSV)',
        icon: const Icon(Icons.upload_file),
        onPressed: _upload,
      ),
      PopupMenuButton<String>(
        tooltip: 'Download sections',
        icon: const Icon(Icons.download),
        onSelected: (v) => v == 'docx' ? _downloadDocx() : _downloadPdf(),
        itemBuilder: (_) => const [
          PopupMenuItem(value: 'pdf', child: Text('Download sections (PDF)')),
          PopupMenuItem(value: 'docx', child: Text('Download sections (Word)')),
        ],
      ),
      IconButton(
        tooltip: 'Print sections',
        icon: const Icon(Icons.print),
        onPressed: _printAll,
      ),
      IconButton(
        tooltip: 'Delete all sections',
        icon: const Icon(Icons.delete_sweep),
        onPressed: _deleteAll,
      ),
    ]);
  }
}

/// Students of one section.
class SectionStudentsScreen extends StatelessWidget {
  final SectionInfo section;
  final SchoolService service;
  const SectionStudentsScreen(
      {super.key, required this.section, required this.service});

  Future<void> _add(BuildContext context) async {
    final c = TextEditingController();
    final names = await showDialog<List<String>>(
      context: context,
      builder: (ctx) => AlertDialog(
        title: const Text('Add students'),
        content: SizedBox(
          width: 380,
          child: TextField(
            controller: c,
            autofocus: true,
            minLines: 4,
            maxLines: 10,
            keyboardType: TextInputType.multiline,
            textCapitalization: TextCapitalization.words,
            decoration: const InputDecoration(
              labelText: 'Student names',
              helperText: 'One name per line',
              border: OutlineInputBorder(),
            ),
          ),
        ),
        actions: [
          TextButton(
              onPressed: () => Navigator.pop(ctx),
              child: const Text('Cancel')),
          FilledButton(
            onPressed: () => Navigator.pop(ctx, [
              for (final l in c.text.split('\n'))
                if (l.trim().isNotEmpty) l.trim(),
            ]),
            child: const Text('Add'),
          ),
        ],
      ),
    );
    c.dispose();
    if (names == null || names.isEmpty || !context.mounted) return;
    final messenger = ScaffoldMessenger.of(context);
    try {
      await service.addStudents(section.id, names);
      messenger.showSnackBar(SnackBar(
          content: Text(
              'Added ${names.length} student${names.length == 1 ? '' : 's'}')));
    } catch (e) {
      messenger.showSnackBar(SnackBar(content: Text('Failed: $e')));
    }
  }

  Future<void> _edit(BuildContext context, StudentInfo s) async {
    final c = TextEditingController(text: s.name);
    final name = await showDialog<String>(
      context: context,
      builder: (ctx) => AlertDialog(
        title: const Text('Edit student'),
        content: SizedBox(
          width: 380,
          child: TextField(
            controller: c,
            autofocus: true,
            textCapitalization: TextCapitalization.words,
            decoration: const InputDecoration(
              labelText: 'Student name',
              border: OutlineInputBorder(),
            ),
            onSubmitted: (v) => Navigator.pop(ctx, v.trim()),
          ),
        ),
        actions: [
          TextButton(
              onPressed: () => Navigator.pop(ctx), child: const Text('Cancel')),
          FilledButton(
              onPressed: () => Navigator.pop(ctx, c.text.trim()),
              child: const Text('Save')),
        ],
      ),
    );
    c.dispose();
    if (name == null || name.isEmpty || name == s.name || !context.mounted) {
      return;
    }
    final messenger = ScaffoldMessenger.of(context);
    try {
      await service.renameStudent(s.id, name);
      messenger.showSnackBar(const SnackBar(content: Text('Student updated')));
    } catch (e) {
      messenger.showSnackBar(SnackBar(content: Text('Failed: $e')));
    }
  }

  /// Move the student to another section / class of the SAME form.
  Future<void> _change(BuildContext context, StudentInfo s) async {
    final messenger = ScaffoldMessenger.of(context);
    List<SectionInfo> all;
    try {
      all = await service.watchSections().first;
    } catch (e) {
      messenger.showSnackBar(SnackBar(content: Text('Failed: $e')));
      return;
    }
    final targets = all
        .where((x) => x.form == section.form && x.id != section.id)
        .toList();
    if (!context.mounted) return;
    if (targets.isEmpty) {
      messenger.showSnackBar(SnackBar(
          content: Text(
              'There is no other section or class in ${section.form}.')));
      return;
    }
    final to = await showDialog<SectionInfo>(
      context: context,
      builder: (ctx) => SimpleDialog(
        title: Text('Move "${s.name}" to...'),
        children: [
          for (final t in targets)
            SimpleDialogOption(
              onPressed: () => Navigator.pop(ctx, t),
              child: Text(t.fullName, style: const TextStyle(fontSize: 16)),
            ),
        ],
      ),
    );
    if (to == null || !context.mounted) return;
    final ok = await showDialog<bool>(
      context: context,
      builder: (ctx) => AlertDialog(
        title: const Text('Change section?'),
        content: Text(
            'Move "${s.name}" from ${section.fullName} to ${to.fullName}?'),
        actions: [
          TextButton(
              onPressed: () => Navigator.pop(ctx, false),
              child: const Text('Cancel')),
          FilledButton(
              onPressed: () => Navigator.pop(ctx, true),
              child: const Text('Move')),
        ],
      ),
    );
    if (ok != true) return;
    try {
      await service.moveStudent(s.id, to.id);
      messenger.showSnackBar(
          SnackBar(content: Text('Moved to ${to.fullName}')));
    } catch (e) {
      messenger.showSnackBar(SnackBar(content: Text('Failed: $e')));
    }
  }

  Future<void> _remove(BuildContext context, StudentInfo s) async {
    final ok = await showDialog<bool>(
      context: context,
      builder: (ctx) => AlertDialog(
        title: const Text('Remove student?'),
        content: Text('Remove "${s.name}" from ${section.label}?'),
        actions: [
          TextButton(
              onPressed: () => Navigator.pop(ctx, false),
              child: const Text('Cancel')),
          FilledButton(
              onPressed: () => Navigator.pop(ctx, true),
              child: const Text('Remove')),
        ],
      ),
    );
    if (ok != true || !context.mounted) return;
    final messenger = ScaffoldMessenger.of(context);
    try {
      await service.deleteStudent(s.id);
    } catch (e) {
      messenger.showSnackBar(SnackBar(content: Text('Failed: $e')));
    }
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text(section.fullName)),
      floatingActionButton: FloatingActionButton.extended(
        onPressed: () => _add(context),
        icon: const Icon(Icons.person_add),
        label: const Text('Add students'),
      ),
      body: StreamBuilder<List<StudentInfo>>(
        stream: service.watchStudents(section.id),
        builder: (context, snap) {
          if (snap.hasError) return Center(child: Text('Error: ${snap.error}'));
          if (!snap.hasData) {
            return const Center(child: CircularProgressIndicator());
          }
          final students = snap.data!;
          if (students.isEmpty) {
            return const Center(
              child: Padding(
                padding: EdgeInsets.all(24),
                child: Text('No students in this section yet.',
                    textAlign: TextAlign.center),
              ),
            );
          }
          return Align(
            alignment: Alignment.topCenter,
            child: ConstrainedBox(
              constraints: const BoxConstraints(maxWidth: 720),
              child: Column(children: [
                _subjectHeader(context, students.length),
                Expanded(
                  child: ListView.builder(
                    padding: const EdgeInsets.fromLTRB(16, 8, 16, 96),
                    itemCount: students.length,
                    itemBuilder: (context, i) {
                      final s = students[i];
                      return Card(
                        child: ListTile(
                          leading: CircleAvatar(child: Text('${i + 1}')),
                          title: Text(s.name),
                          trailing: Row(
                            mainAxisSize: MainAxisSize.min,
                            children: [
                              IconButton(
                                tooltip: 'Edit name',
                                icon: const Icon(Icons.edit_outlined),
                                onPressed: () => _edit(context, s),
                              ),
                              IconButton(
                                tooltip: 'Change section / class',
                                icon: const Icon(Icons.swap_horiz),
                                onPressed: () => _change(context, s),
                              ),
                              IconButton(
                                tooltip: 'Remove student',
                                icon: const Icon(Icons.delete_outline),
                                onPressed: () => _remove(context, s),
                              ),
                            ],
                          ),
                        ),
                      );
                    },
                  ),
                ),
              ]),
            ),
          );
        },
      ),
    );
  }

  /// Header of the section: its name, student count and the subjects ticked
  /// in Settings.
  Widget _subjectHeader(BuildContext context, int count) {
    final cs = Theme.of(context).colorScheme;
    return ValueListenableBuilder<AppSettings>(
      valueListenable: appSettings,
      builder: (context, st, _) => Container(
        width: double.infinity,
        margin: const EdgeInsets.fromLTRB(16, 12, 16, 0),
        padding: const EdgeInsets.all(12),
        decoration: BoxDecoration(
          color: cs.primaryContainer.withOpacity(0.5),
          borderRadius: BorderRadius.circular(12),
        ),
        child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
          Text('${section.fullName} · $count '
              'student${count == 1 ? '' : 's'}',
              style: const TextStyle(fontWeight: FontWeight.w700)),
          const SizedBox(height: 6),
          if (st.sectionSubjects.isEmpty)
            const Text('No subjects ticked. Tick them in Settings.',
                style: TextStyle(fontSize: 12, color: Colors.black54))
          else
            Wrap(spacing: 6, runSpacing: 6, children: [
              for (final sub in st.sectionSubjects)
                Chip(
                  label: Text(sub),
                  visualDensity: VisualDensity.compact,
                  materialTapTargetSize: MaterialTapTargetSize.shrinkWrap,
                ),
            ]),
        ]),
      ),
    );
  }
}

// ======================= STUDENTS SCREEN =======================

/// The Students page: every student of every section in one list, with
/// search, filters, add, edit, move, remove and upload (Excel / CSV).
/// It uses the same data as the Sections page (Firestore: students and
/// sections), so both pages always show the same students.
class StudentsScreen extends StatefulWidget {
  const StudentsScreen({super.key});

  @override
  State<StudentsScreen> createState() => _StudentsScreenState();
}

class _StudentsScreenState extends State<StudentsScreen> {
  final _service = SchoolService();
  final _search = TextEditingController();
  late final Stream<List<SectionInfo>> _sectionsStream =
  _service.watchSections();
  late final Stream<List<StudentInfo>> _studentsStream =
  _service.watchAllStudents();
  String _form = 'All';
  String _classKey = ''; // e.g. "1B" (all sections of the class), '' = every class
  bool _showList = false; // false = totals page, true = list of students
  bool _busy = false;

  @override
  void dispose() {
    _search.dispose();
    super.dispose();
  }

  void _toast(String m, {int seconds = 4}) {
    if (!mounted) return;
    ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(duration: Duration(seconds: seconds), content: Text(m)));
  }

  String _err(Object e) => '$e'.replaceFirst('Exception: ', '');

// ---------------- Add ----------------
  Future<void> _add(List<SectionInfo> secs, List<StudentInfo> all,
      String? presetId) async {
    if (secs.isEmpty) {
      _toast('There are no sections yet. Upload a student list first.');
      return;
    }
    final c = TextEditingController();
    var sectionId =
    secs.any((s) => s.id == presetId) ? presetId! : secs.first.id;
    final res = await showDialog<({String sectionId, List<String> names})>(
      context: context,
      builder: (ctx) => StatefulBuilder(
        builder: (ctx, setD) => AlertDialog(
          title: const Text('Add students'),
          content: SizedBox(
            width: 380,
            child: SingleChildScrollView(
              child: Column(mainAxisSize: MainAxisSize.min, children: [
                DropdownButtonFormField<String>(
                  value: sectionId,
                  decoration: const InputDecoration(
                      labelText: 'Class / section',
                      border: OutlineInputBorder()),
                  items: [
                    for (final s in secs)
                      DropdownMenuItem(value: s.id, child: Text(s.fullName)),
                  ],
                  onChanged: (v) => setD(() => sectionId = v ?? sectionId),
                ),
                const SizedBox(height: 12),
                TextField(
                  controller: c,
                  autofocus: true,
                  minLines: 4,
                  maxLines: 10,
                  keyboardType: TextInputType.multiline,
                  textCapitalization: TextCapitalization.words,
                  decoration: const InputDecoration(
                    labelText: 'Student names',
                    helperText: 'One student per line. Add the phone after a '
                        'comma: Ali Hassan, 0634123456',
                    helperMaxLines: 3,
                    border: OutlineInputBorder(),
                  ),
                ),
              ]),
            ),
          ),
          actions: [
            TextButton(
                onPressed: () => Navigator.pop(ctx),
                child: const Text('Cancel')),
            FilledButton(
              onPressed: () => Navigator.pop(ctx, (
              sectionId: sectionId,
              names: [
                for (final l in c.text.split('\n'))
                  if (l.trim().isNotEmpty) l.trim(),
              ],
              )),
              child: const Text('Add'),
            ),
          ],
        ),
      ),
    );
    c.dispose();
    if (res == null || res.names.isEmpty || !mounted) return;
// Skip names that are already in that section (and repeated lines).
    final seen = <String>{
      for (final s in all)
        if (s.sectionId == res.sectionId) s.name.trim().toLowerCase(),
    };
    ({String name, String phone}) parseLine(String l) {
      final m = RegExp(r'^(.*?)\s*[,;|\t]\s*(.+)$').firstMatch(l);
      return m == null
          ? (name: l.trim(), phone: '')
          : (name: m[1]!.trim(), phone: m[2]!);
    }

    final fresh = [
      for (final l in res.names)
        if (parseLine(l).name.isNotEmpty &&
            seen.add(parseLine(l).name.toLowerCase()))
          parseLine(l),
    ];
    final skipped = res.names.length - fresh.length;
    if (fresh.isEmpty) {
      _toast('Nothing added: ${skipped == 1 ? 'that student is' : 'those students are'} already in the section.');
      return;
    }
    try {
      final newIds = await _service.addStudentsWithPhones(res.sectionId, fresh);
      _toast('Added ${fresh.length} student${fresh.length == 1 ? '' : 's'}'
          '${skipped > 0 ? ' ($skipped already there, skipped)' : ''}');
// every student with a phone number gets the login right away
      if (mounted && fresh.any((x) => phonesIn(x.phone).isNotEmpty)) {
        await runAccountCreation(context, ids: newIds, quiet: true);
      }
    } catch (e) {
      _toast('Failed: ${_err(e)}');
    }
  }

  /// Fixes a list that was uploaded twice: a student of a divided class
  /// (1A-A) without a phone and the same name in the whole class (1A) with a
  /// phone. The phone moves to the original student, the copy is deleted.
  Future<void> _mergeDuplicates(
      List<SectionInfo> secs, List<StudentInfo> all) async {
    final secById = {for (final s in secs) s.id: s};
    String norm(String n) =>
        n.trim().toLowerCase().replaceAll(RegExp(r'\s+'), ' ');
    String key(StudentInfo s) {
      final sec = secById[s.sectionId]!;
      return '${sec.form}|${sec.classKey}|${norm(s.name)}';
    }

    final sources = <String, List<StudentInfo>>{};
    for (final s in all) {
      final sec = secById[s.sectionId];
      if (sec != null && !sec.isSub && s.phoneText.isNotEmpty) {
        sources.putIfAbsent(key(s), () => []).add(s);
      }
    }
    final pairs = <({StudentInfo from, StudentInfo to})>[];
    final used = <String>{};
    for (final s in all) {
      final sec = secById[s.sectionId];
      if (sec == null || !sec.isSub || s.phoneText.isNotEmpty) continue;
      final c = sources[key(s)];
      if (c == null) continue;
      final free = [for (final x in c) if (!used.contains(x.id)) x];
      if (free.length != 1) continue; // unclear: leave both students alone
      used.add(free.first.id);
      pairs.add((from: free.first, to: s));
    }
    if (pairs.isEmpty) {
      _toast('No duplicate students found.');
      return;
    }
    final ok = await showDialog<bool>(
      context: context,
      builder: (ctx) => AlertDialog(
        title: const Text('Merge duplicate students?'),
        content: Text('${pairs.length} students exist twice: once in a '
            'divided section (like 1A - Section A, no phone) and once in the '
            'whole class (like 1A, with a phone).\n\n'
            'The phone number will be copied to the student in the section, '
            'and the copy in the whole class will be deleted. This cannot be '
            'undone.'),
        actions: [
          TextButton(
              onPressed: () => Navigator.pop(ctx, false),
              child: const Text('Cancel')),
          FilledButton(
              onPressed: () => Navigator.pop(ctx, true),
              child: Text('Merge ${pairs.length}')),
        ],
      ),
    );
    if (ok != true || !mounted) return;
    setState(() => _busy = true);
    try {
      final db = FirebaseFirestore.instance;
      final col = db.collection('students');
      for (var i = 0; i < pairs.length; i += 200) {
        final batch = db.batch();
        for (final p in pairs.skip(i).take(200)) {
          final phones = p.from.phones.isNotEmpty
              ? p.from.phones
              : [p.from.phone];
          batch.update(col.doc(p.to.id), {
            'phone': phones.first,
            'phones': phones,
            'username': phones.first,
// keep the login if the copy already had one
            if (p.from.accountUid.isNotEmpty) 'accountUid': p.from.accountUid,
            'updatedAt': FieldValue.serverTimestamp(),
          });
          if (p.from.accountUid.isNotEmpty) {
            batch.set(db.collection('users').doc(p.from.accountUid),
                {'studentId': p.to.id}, SetOptions(merge: true));
          }
          batch.delete(col.doc(p.from.id));
        }
        await batch.commit();
      }
      _toast('Merged ${pairs.length} students.');
    } catch (e) {
      _toast('Failed: ${_err(e)}');
    } finally {
      if (mounted) setState(() => _busy = false);
    }
  }

  void _open(StudentInfo s, SectionInfo sec) {
    Navigator.of(context).push(MaterialPageRoute(
        builder: (_) => StudentDetailScreen(student: s, section: sec)));
  }

// ---------------- Edit / move / remove ----------------
  Future<void> _edit(StudentInfo s) async {
    final c = TextEditingController(text: s.name);
    final ph = TextEditingController(text: s.phone);
    final res = await showDialog<({String name, String phone})>(
      context: context,
      builder: (ctx) => AlertDialog(
        title: const Text('Edit student'),
        content: SizedBox(
          width: 380,
          child: Column(mainAxisSize: MainAxisSize.min, children: [
            TextField(
              controller: c,
              autofocus: true,
              textCapitalization: TextCapitalization.words,
              decoration: const InputDecoration(
                labelText: 'Student name',
                border: OutlineInputBorder(),
              ),
            ),
            const SizedBox(height: 12),
            TextField(
              controller: ph,
              keyboardType: TextInputType.phone,
              decoration: const InputDecoration(
                labelText: 'Phone number(s)',
                helperText:
                'Separate several numbers with a comma. The first one '
                    'is the username and password.',
                helperMaxLines: 3,
                border: OutlineInputBorder(),
              ),
            ),
          ]),
        ),
        actions: [
          TextButton(
              onPressed: () => Navigator.pop(ctx),
              child: const Text('Cancel')),
          FilledButton(
              onPressed: () => Navigator.pop(
                  ctx, (name: c.text.trim(), phone: ph.text.trim())),
              child: const Text('Save')),
        ],
      ),
    );
    c.dispose();
    ph.dispose();
    if (res == null || res.name.isEmpty || !mounted) return;
    final newPhone = phonesIn(res.phone).isEmpty ? '' : phonesIn(res.phone).first;
    if (res.name == s.name && newPhone == s.phone) return;
    try {
      await _service.updateStudent(s.id, res.name, res.phone);
      _toast('Student updated');
      if (mounted && newPhone.isNotEmpty) {
        await runAccountCreation(context, ids: [s.id], quiet: true);
      }
    } catch (e) {
      _toast('Failed: ${_err(e)}');
    }
  }

  /// Moves the student to another section / class of the SAME form (the
  /// same rule as on the Sections page).
  Future<void> _move(
      StudentInfo s, SectionInfo from, List<SectionInfo> secs) async {
    final targets = [
      for (final x in secs)
        if (x.form == from.form && x.id != from.id) x,
    ];
    if (targets.isEmpty) {
      _toast('There is no other section or class in ${from.form}.');
      return;
    }
    final to = await showDialog<SectionInfo>(
      context: context,
      builder: (ctx) => SimpleDialog(
        title: Text('Move "${s.name}" to...'),
        children: [
          for (final t in targets)
            SimpleDialogOption(
              onPressed: () => Navigator.pop(ctx, t),
              child: Text(t.fullName, style: const TextStyle(fontSize: 16)),
            ),
        ],
      ),
    );
    if (to == null || !mounted) return;
    final ok = await showDialog<bool>(
      context: context,
      builder: (ctx) => AlertDialog(
        title: const Text('Change section?'),
        content: Text(
            'Move "${s.name}" from ${from.fullName} to ${to.fullName}?'),
        actions: [
          TextButton(
              onPressed: () => Navigator.pop(ctx, false),
              child: const Text('Cancel')),
          FilledButton(
              onPressed: () => Navigator.pop(ctx, true),
              child: const Text('Move')),
        ],
      ),
    );
    if (ok != true || !mounted) return;
    try {
      await _service.moveStudent(s.id, to.id);
      _toast('Moved to ${to.fullName}');
    } catch (e) {
      _toast('Failed: ${_err(e)}');
    }
  }

  Future<void> _remove(StudentInfo s, SectionInfo sec) async {
    final ok = await showDialog<bool>(
      context: context,
      builder: (ctx) => AlertDialog(
        title: const Text('Remove student?'),
        content: Text('Remove "${s.name}" from ${sec.fullName}?'),
        actions: [
          TextButton(
              onPressed: () => Navigator.pop(ctx, false),
              child: const Text('Cancel')),
          FilledButton(
              onPressed: () => Navigator.pop(ctx, true),
              child: const Text('Remove')),
        ],
      ),
    );
    if (ok != true || !mounted) return;
    try {
      await _service.deleteStudent(s.id);
      _toast('Removed ${s.name}');
    } catch (e) {
      _toast('Failed: ${_err(e)}');
    }
  }

// ---------------- Upload / download ----------------
  Future<void> _upload() async {
    final go = await showDialog<bool>(
      context: context,
      builder: (ctx) => AlertDialog(
        title: const Text('Upload student list'),
        content: const SizedBox(
          width: 400,
          child: Text(
            'Choose an Excel (.xlsx) or CSV file. '
                'Use these columns: the class, the student name and the phone number:\n\n'
                'Class  |  Student name  |  Phone\n'
                '1A  |  Ali Hassan  |  0634123456\n'
                '1B  |  Amina Yusuf  |  0634765432\n'
                '2C  |  Omar Abdi  |  0634111222\n\n'
                'Separate Form | Section | Student name columns also work.\n\n'
                'Add a Phone column (Phone, Mobile or Tel) to save the phone '
                'numbers. The FIRST phone number becomes the student\'s '
                'username and password.\n\n'
                'A class that does not exist yet (1A, 2C, 4B...) is created '
                'automatically. Students that are already in a section are '
                'skipped, so it is safe to upload the same file again.\n\n'
                'Tip: use the download button to get an empty template.',
          ),
        ),
        actions: [
          TextButton(
              onPressed: () => Navigator.pop(ctx, false),
              child: const Text('Cancel')),
          FilledButton.icon(
            onPressed: () => Navigator.pop(ctx, true),
            icon: const Icon(Icons.attach_file),
            label: const Text('Choose file'),
          ),
        ],
      ),
    );
    if (go != true || !mounted) return;
    final res = await FilePicker.platform.pickFiles(
      withData: true,
      type: FileType.custom,
      allowedExtensions: ['xlsx', 'csv', 'txt'],
    );
    if (res == null || res.files.isEmpty || !mounted) return;
    setState(() => _busy = true);
    try {
      final r = await _service.importFile(res.files.first);
      if (r.dups.isNotEmpty) {
        if (mounted) {
          await showImportResult(context,
              students: r.students,
              sections: r.sections,
              skipped: r.skipped,
              updated: r.updated,
              noPhone: r.noPhone,
              dups: r.dups);
        }
      } else {
        _toast(
            'Added ${r.students} students and ${r.sections} new sections. '
                '${r.skipped} rows skipped (duplicates or invalid).'
                '${r.updated > 0 ? ' Phone number added to ${r.updated} existing students.' : ''}'
                '${r.noPhone > 0 ? ' ${r.noPhone} new students have no phone number (they cannot log in).' : ''}',
            seconds: 8);
      }
// every uploaded student with a phone number gets the login now
      if (mounted) {
        await runAccountCreation(context);
      }
    } catch (e) {
      _toast('Upload failed: ${_err(e)}');
    } finally {
      if (mounted) setState(() => _busy = false);
    }
  }

  static String _csvCell(String v) =>
      RegExp(r'[",\r\n]').hasMatch(v) ? '"${v.replaceAll('"', '""')}"' : v;

  Future<void> _saveCsv(String fileName, String text) async {
    try {
// The BOM lets Excel show Arabic / Somali names correctly.
      final bytes = Uint8List.fromList(utf8.encode('\uFEFF$text'));
      final path = await _downloadInBrowser(bytes, fileName, 'text/csv');
      _toast(
          path == null && !kIsWeb
              ? 'Download cancelled (nothing was saved).'
              : 'Saved $fileName${path == null ? '' : '\nSaved to: $path'}',
          seconds: 8);
    } catch (e) {
      _toast('Download failed: ${_err(e)}');
    }
  }

  Future<void> _exportList(
      List<StudentInfo> shown, Map<String, SectionInfo> secById) {
    final b = StringBuffer('Class,Student name,Phone\r\n');
    for (final s in shown) {
      b.write('${_csvCell(secById[s.sectionId]?.label ?? '')},'
          '${_csvCell(s.name)},${_csvCell(s.phone)}\r\n');
    }
    return _saveCsv('Students-${DateTime.now().year}.csv', b.toString());
  }

  Future<void> _template() =>
      _saveCsv('Students-template.csv', 'Class,Student name,Phone\r\n');

// ---------------- Screen ----------------
  Widget _frame(Widget body,
      {List<Widget> actions = const [], Widget? fab}) =>
      Scaffold(
        appBar: AppBar(title: const Text('Students'), actions: actions),
        floatingActionButton: fab,
        body: body,
      );

  @override
  Widget build(BuildContext context) {
    return StreamBuilder<List<SectionInfo>>(
      stream: _sectionsStream,
      builder: (context, secSnap) {
        if (secSnap.hasError) {
          return _frame(Center(child: Text('Error: ${secSnap.error}')));
        }
        return StreamBuilder<List<StudentInfo>>(
          stream: _studentsStream,
          builder: (context, stuSnap) {
            if (stuSnap.hasError) {
              return _frame(Center(child: Text('Error: ${stuSnap.error}')));
            }
            if (!secSnap.hasData || !stuSnap.hasData) {
              return _frame(
                  const Center(child: CircularProgressIndicator()));
            }
            return _page(secSnap.data!, stuSnap.data!);
          },
        );
      },
    );
  }

// Totals page: whole school, each form and each class. Tap a form or a
// class (or "Show all students") to open the list of students.
  Widget _summary(List<SectionInfo> secs, List<StudentInfo> visible) {
    final cs = Theme.of(context).colorScheme;
    final secById = {for (final s in secs) s.id: s};
    final formCount = <String, int>{};
    final classCount = <String, int>{}; // e.g. "1B" (its sections add up)
    final classForm = <String, String>{};
    for (final st in visible) {
      final sec = secById[st.sectionId];
      if (sec == null) continue;
      formCount[sec.form] = (formCount[sec.form] ?? 0) + 1;
      final cKey = SectionInfo.code(sec.form, sec.classKey);
      classCount[cKey] = (classCount[cKey] ?? 0) + 1;
    }
    for (final sec in secs) {
      final cKey = SectionInfo.code(sec.form, sec.classKey);
      classCount.putIfAbsent(cKey, () => 0);
      classForm[cKey] = sec.form;
    }
    final noPhone = visible.where((x) => x.phoneText.isEmpty).length;
    final forms = [
      for (final f in ExamService.forms)
        if (secs.any((s) => s.form == f)) f,
    ];

    void open(String form, String classKey) => setState(() {
      _showList = true;
      _form = form;
      _classKey = classKey;
    });

    Widget stat(IconData icon, String text) =>
        Row(mainAxisSize: MainAxisSize.min, children: [
          Icon(icon, size: 18, color: cs.primary),
          const SizedBox(width: 6),
          Text(text, style: const TextStyle(fontSize: 14)),
        ]);

    return LayoutBuilder(builder: (context, box) {
      final cardW = box.maxWidth < 372 ? box.maxWidth - 32 : 340.0;
      final btnW = (cardW - 28 - 8) / 2;
      return ListView(
        padding: const EdgeInsets.fromLTRB(16, 0, 16, 96),
        children: [
          Align(
            alignment: Alignment.centerLeft,
            child: TextButton.icon(
              onPressed: () => open('All', ''),
              icon: const Icon(Icons.groups_2_outlined),
              label: const Text('Show all students',
                  style: TextStyle(fontWeight: FontWeight.w600)),
            ),
          ),
          const Divider(height: 1),
          const SizedBox(height: 10),
          Align(
            alignment: Alignment.centerLeft,
            child: Container(
              padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 10),
              decoration: BoxDecoration(
                  color: cs.surface,
                  borderRadius: BorderRadius.circular(8),
                  border: Border.all(color: cs.outlineVariant)),
              child: Wrap(spacing: 16, runSpacing: 6, children: [
                stat(Icons.school_outlined, '${classCount.length} Classes'),
                stat(Icons.people_alt_outlined, '${visible.length} Students'),
                if (noPhone > 0)
                  stat(Icons.phone_disabled_outlined, '$noPhone without phone'),
              ]),
            ),
          ),
          const SizedBox(height: 12),
          Wrap(spacing: 12, runSpacing: 12, children: [
            for (final f in forms)
              SizedBox(
                width: cardW,
                child: Card(
                  margin: EdgeInsets.zero,
                  clipBehavior: Clip.antiAlias,
                  child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                    InkWell(
                      onTap: () => open(f, ''),
                      child: Container(
                        color: cs.primaryContainer.withOpacity(0.35),
                        padding: const EdgeInsets.symmetric(
                            horizontal: 14, vertical: 14),
                        child: Row(children: [
                          Text(f, style: const TextStyle(fontSize: 14.5)),
                          const SizedBox(width: 6),
                          Text('(${formCount[f] ?? 0})',
                              style: const TextStyle(
                                  fontSize: 12, color: Colors.black54)),
                          const Spacer(),
                          const Icon(Icons.chevron_right, size: 20),
                        ]),
                      ),
                    ),
                    Padding(
                      padding: const EdgeInsets.all(14),
                      child: Wrap(spacing: 8, runSpacing: 8, children: [
                        for (final k in (classCount.keys
                            .where((k) => classForm[k] == f)
                            .toList()
                          ..sort()))
                          SizedBox(
                            width: btnW,
                            child: OutlinedButton(
                              onPressed: () => open(f, k),
                              style: OutlinedButton.styleFrom(
                                  padding: const EdgeInsets.symmetric(
                                      horizontal: 12, vertical: 12),
                                  alignment: Alignment.centerLeft),
                              child: Row(children: [
                                Text(k),
                                const SizedBox(width: 6),
                                Text('(${classCount[k]})',
                                    style: const TextStyle(
                                        fontSize: 12, color: Colors.black54)),
                                const Spacer(),
                                const Icon(Icons.chevron_right, size: 18),
                              ]),
                            ),
                          ),
                      ]),
                    ),
                  ]),
                ),
              ),
          ]),
        ],
      );
    });
  }

  Widget _page(List<SectionInfo> secs, List<StudentInfo> all) {
    final cs = Theme.of(context).colorScheme;
    final secById = {for (final s in secs) s.id: s};
// Only students of the sections this person may see.
// A student who is also saved in a section of his class (1A and 1A-A)
// is ONE student: count him once per class (same name = same student,
// the upload already refuses the same name twice in one class).
    final uniq = <String, StudentInfo>{};
    for (final s in all) {
      final sec = secById[s.sectionId];
      if (sec == null) continue;
      final key = '${SectionInfo.code(sec.form, sec.classKey)}|'
          '${s.name.trim().toLowerCase().replaceAll(RegExp(r'\s+'), ' ')}';
      final old = uniq[key];
      if (old == null) {
        uniq[key] = s;
        continue;
      }
// keep the better copy: the one in the whole class, then the one with a phone
      final oldSub = secById[old.sectionId]!.isSub;
      final newSub = sec.isSub;
      if ((oldSub && !newSub) ||
          (oldSub == newSub && old.phoneText.isEmpty && s.phoneText.isNotEmpty)) {
        uniq[key] = s;
      }
    }
    final visible = uniq.values.toList();
    final forms = [
      for (final f in ExamService.forms)
        if (secs.any((s) => s.form == f)) f,
    ];
    final form = forms.contains(_form) ? _form : 'All';
    final classKey = _classKey;
    final q = _search.text.trim().toLowerCase();
    final listMode = _showList || q.isNotEmpty;
    final filterTitle = classKey.isNotEmpty
        ? 'Class $classKey'
        : (form != 'All' ? form : 'All students');

    final shown = [
      for (final s in visible)
        if ((form == 'All' || secById[s.sectionId]!.form == form) &&
            (classKey.isEmpty ||
                SectionInfo.code(secById[s.sectionId]!.form,
                    secById[s.sectionId]!.classKey) ==
                    classKey) &&
            (q.isEmpty ||
                s.name.toLowerCase().contains(q) ||
                s.phoneText.replaceAll(' ', '').contains(q.replaceAll(' ', '')) ||
                secById[s.sectionId]!.label.toLowerCase().contains(q) ||
                secById[s.sectionId]!.fullName.toLowerCase().contains(q)))
          s,
    ]..sort((a, b) {
      final c = secById[a.sectionId]!
          .label
          .toLowerCase()
          .compareTo(secById[b.sectionId]!.label.toLowerCase());
      return c != 0
          ? c
          : a.name.toLowerCase().compareTo(b.name.toLowerCase());
    });

    final presetMatches = classKey.isEmpty
        ? <SectionInfo>[]
        : secs
        .where((x) => SectionInfo.code(x.form, x.classKey) == classKey)
        .toList();
    final String? presetId =
    presetMatches.isEmpty ? null : presetMatches.first.id;

    return _frame(
      Align(
        alignment: Alignment.topCenter,
        child: ConstrainedBox(
          constraints: BoxConstraints(maxWidth: listMode ? 760 : 1100),
          child: Column(children: [
            Padding(
              padding: const EdgeInsets.fromLTRB(16, 12, 16, 4),
              child: TextField(
                controller: _search,
                onChanged: (_) => setState(() {}),
                decoration: InputDecoration(
                  hintText: 'Search name, class (e.g. 2C) or phone',
                  prefixIcon: const Icon(Icons.search),
                  suffixIcon: _search.text.isEmpty
                      ? null
                      : IconButton(
                    icon: const Icon(Icons.clear),
                    onPressed: () => setState(_search.clear),
                  ),
                  border: const OutlineInputBorder(),
                  isDense: true,
                ),
              ),
            ),
            if (_showList)
              Padding(
                padding: const EdgeInsets.fromLTRB(8, 4, 16, 0),
                child: Row(children: [
                  TextButton.icon(
                    onPressed: () => setState(() {
                      _showList = false;
                      _form = 'All';
                      _classKey = '';
                      _search.clear();
                    }),
                    icon: const Icon(Icons.arrow_back, size: 18),
                    label: const Text('Back to classes'),
                  ),
                  const Spacer(),
                  Text(filterTitle,
                      style: const TextStyle(
                          fontSize: 14, fontWeight: FontWeight.w700)),
                ]),
              ),
            if (listMode)
              Padding(
                padding: const EdgeInsets.fromLTRB(16, 8, 16, 4),
                child: Align(
                  alignment: Alignment.centerLeft,
                  child: Text(
                      shown.length == visible.length
                          ? '${visible.length} student'
                          '${visible.length == 1 ? '' : 's'}'
                          '${shown.where((x) => x.phoneText.isEmpty).isEmpty ? '' : '  ·  ${shown.where((x) => x.phoneText.isEmpty).length} without phone'}'
                          : '${shown.length} of ${visible.length} students'
                          '${shown.where((x) => x.phoneText.isEmpty).isEmpty ? '' : '  ·  ${shown.where((x) => x.phoneText.isEmpty).length} without phone'}',
                      style:
                      const TextStyle(fontSize: 12, color: Colors.black54)),
                ),
              ),
            Expanded(
              child: !listMode
                  ? _summary(secs, visible)
                  : shown.isEmpty
                  ? Center(
                child: Padding(
                  padding: const EdgeInsets.all(24),
                  child: Text(
                      visible.isEmpty
                          ? 'No students yet.\nTap the upload button to add '
                          'a student list, or tap Add.'
                          : 'Nobody matches your search.',
                      textAlign: TextAlign.center),
                ),
              )
                  : ListView.builder(
                padding: const EdgeInsets.fromLTRB(16, 4, 16, 96),
                itemCount: shown.length,
                itemBuilder: (context, i) {
                  final s = shown[i];
                  final sec = secById[s.sectionId]!;
                  return Card(
                    child: ListTile(
                      onTap: () => _open(s, sec),
                      leading: CircleAvatar(
                        backgroundColor: cs.primaryContainer,
                        child: Text('${i + 1}'),
                      ),
                      title: Text(s.name),
                      subtitle: Column(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: [
                          Text(sec.fullName,
                              style: TextStyle(
                                  color: cs.primary,
                                  fontWeight: FontWeight.w600)),
                          Row(children: [
                            Icon(Icons.phone,
                                size: 13,
                                color: s.phoneText.isEmpty
                                    ? Colors.orange.shade800
                                    : Colors.black54),
                            const SizedBox(width: 4),
                            Flexible(
                              child: Text(
                                  s.phoneText.isEmpty
                                      ? 'No phone number'
                                      : s.phoneText,
                                  overflow: TextOverflow.ellipsis,
                                  style: TextStyle(
                                      fontSize: 12.5,
                                      color: s.phoneText.isEmpty
                                          ? Colors.orange.shade800
                                          : Colors.black87)),
                            ),
                          ]),
                        ],
                      ),
                      trailing: PopupMenuButton<String>(
                        tooltip: 'Manage student',
                        onSelected: (v) {
                          if (v == 'details') {
                            _open(s, sec);
                          } else if (v == 'edit') {
                            _edit(s);
                          } else if (v == 'move') {
                            _move(s, sec, secs);
                          } else {
                            _remove(s, sec);
                          }
                        },
                        itemBuilder: (_) => const [
                          PopupMenuItem(
                              value: 'details',
                              child: ListTile(
                                  leading: Icon(Icons.badge_outlined),
                                  title: Text('View details & attendance'),
                                  dense: true,
                                  contentPadding: EdgeInsets.zero)),
                          PopupMenuItem(
                              value: 'edit',
                              child: ListTile(
                                  leading: Icon(Icons.edit_outlined),
                                  title: Text('Edit name / phone'),
                                  dense: true,
                                  contentPadding: EdgeInsets.zero)),
                          PopupMenuItem(
                              value: 'move',
                              child: ListTile(
                                  leading: Icon(Icons.swap_horiz),
                                  title: Text('Change section / class'),
                                  dense: true,
                                  contentPadding: EdgeInsets.zero)),
                          PopupMenuItem(
                              value: 'remove',
                              child: ListTile(
                                  leading: Icon(Icons.delete_outline),
                                  title: Text('Remove student'),
                                  dense: true,
                                  contentPadding: EdgeInsets.zero)),
                        ],
                      ),
                    ),
                  );
                },
              ),
            ),
          ]),
        ),
      ),
      actions: [
        if (_busy)
          const Padding(
            padding: EdgeInsets.symmetric(horizontal: 12),
            child: Center(
              child: SizedBox(
                  width: 20,
                  height: 20,
                  child: CircularProgressIndicator(strokeWidth: 2)),
            ),
          )
        else ...[
          IconButton(
            tooltip: 'Create login accounts for all students',
            icon: const Icon(Icons.key),
            onPressed: () => runAccountCreation(context),
          ),
          IconButton(
            tooltip: 'Merge duplicate students',
            icon: const Icon(Icons.merge_type),
            onPressed: () => _mergeDuplicates(secs, all),
          ),
          IconButton(
            tooltip: 'Upload student list (Excel / CSV)',
            icon: const Icon(Icons.upload_file),
            onPressed: _upload,
          ),
          PopupMenuButton<String>(
            tooltip: 'Download',
            icon: const Icon(Icons.download),
            onSelected: (v) =>
            v == 'template' ? _template() : _exportList(shown, secById),
            itemBuilder: (_) => const [
              PopupMenuItem(
                  value: 'list', child: Text('Download this list (CSV)')),
              PopupMenuItem(
                  value: 'template', child: Text('Download empty template')),
            ],
          ),
        ],
        const SizedBox(width: 8),
      ],
      fab: FloatingActionButton.extended(
        onPressed: () =>
            _add(secs, all, presetId),
        icon: const Icon(Icons.person_add),
        label: const Text('Add'),
      ),
    );
  }
}

// ======================= STUDENT PORTAL (what a student sees) =======================
/// A student account sees ONLY the own data: profile, exam results and
/// attendance. No lists of classes or of other students.
class StudentPortal extends StatelessWidget {
  final String studentId;
  final List<String> allowed; // pages the administrator gave this student
  const StudentPortal(
      {super.key, required this.studentId, required this.allowed});

  @override
  Widget build(BuildContext context) {
    final tabs = <(String, IconData, Widget)>[
      if (allowed.contains(AppPages.result))
        ('Results', Icons.emoji_events, _StudentResultsBody(studentId: studentId)),
      if (allowed.contains(AppPages.attendance))
        ('Attendance', Icons.fact_check,
        _StudentAttendanceBody(studentId: studentId)),
    ];
    final header = Padding(
      padding: const EdgeInsets.fromLTRB(16, 12, 16, 4),
      child: _StudentProfileCard(studentId: studentId),
    );
    if (tabs.isEmpty) {
      return ListView(children: [
        Center(child: ConstrainedBox(constraints: const BoxConstraints(maxWidth: 760), child: header)),
        const Padding(
          padding: EdgeInsets.all(24),
          child: Text(
              'Your account has no access to results or attendance yet.\n'
                  'Ask the administrator to give you access.',
              textAlign: TextAlign.center),
        ),
      ]);
    }
    return DefaultTabController(
      length: tabs.length,
      child: Align(
        alignment: Alignment.topCenter,
        child: ConstrainedBox(
          constraints: const BoxConstraints(maxWidth: 760),
          child: Column(children: [
            header,
            TabBar(tabs: [
              for (final t in tabs) Tab(icon: Icon(t.$2), text: t.$1),
            ]),
            Expanded(child: TabBarView(children: [for (final t in tabs) t.$3])),
          ]),
        ),
      ),
    );
  }
}

class _StudentProfileCard extends StatelessWidget {
  final String studentId;
  const _StudentProfileCard({required this.studentId});

  @override
  Widget build(BuildContext context) {
    final cs = Theme.of(context).colorScheme;
    return StreamBuilder<DocumentSnapshot<Map<String, dynamic>>>(
      stream: FirebaseFirestore.instance
          .collection('students')
          .doc(studentId)
          .snapshots(),
      builder: (context, snap) {
        final m = snap.data?.data();
        if (m == null) {
          return const Card(
              child: Padding(
                  padding: EdgeInsets.all(16),
                  child: Text('Loading your details...')));
        }
        final name = '${m['name'] ?? ''}';
        final phone = '${m['phone'] ?? ''}';
        return FutureBuilder<DocumentSnapshot<Map<String, dynamic>>>(
          future: FirebaseFirestore.instance
              .collection('sections')
              .doc('${m['sectionId']}')
              .get(),
          builder: (context, sec) {
            final si = sec.data != null && sec.data!.exists
                ? SectionInfo.fromDoc(sec.data!)
                : null;
            return Card(
              margin: EdgeInsets.zero,
              child: Padding(
                padding: const EdgeInsets.all(14),
                child: Row(children: [
                  CircleAvatar(
                    radius: 28,
                    backgroundColor: cs.primaryContainer,
                    child: Text(name.isEmpty ? '?' : name[0].toUpperCase(),
                        style: TextStyle(
                            fontSize: 24,
                            fontWeight: FontWeight.bold,
                            color: cs.onPrimaryContainer)),
                  ),
                  const SizedBox(width: 14),
                  Expanded(
                    child: Column(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: [
                          Text(name,
                              style: const TextStyle(
                                  fontSize: 18, fontWeight: FontWeight.w700)),
                          if (si != null)
                            Text('${si.form}  ·  ${si.fullName}',
                                style: TextStyle(
                                    color: cs.primary,
                                    fontWeight: FontWeight.w600)),
                          if (phone.isNotEmpty)
                            Text('Phone: $phone',
                                style: const TextStyle(
                                    fontSize: 12.5, color: Colors.black54)),
                        ]),
                  ),
                ]),
              ),
            );
          },
        );
      },
    );
  }
}

/// The exam results of the signed-in student (only the open exams).
class _StudentResultsBody extends StatefulWidget {
  final String studentId;
  const _StudentResultsBody({required this.studentId});

  @override
  State<_StudentResultsBody> createState() => _StudentResultsBodyState();
}

class _StudentResultsBodyState extends State<_StudentResultsBody> {
  late Future<Map<String, ResultMarks>> _f = _load();

  Future<Map<String, ResultMarks>> _load() async {
    final col = FirebaseFirestore.instance.collection('results');
// also the marks entered on this student's twin record (class <-> section)
    final twin = (await ResultService().twinMap())[widget.studentId];
    QuerySnapshot<Map<String, dynamic>> q;
    try {
      q = await col
          .where('studentId', whereIn: [widget.studentId, if (twin != null) twin])
          .get();
    } catch (_) {
      q = await col.where('studentId', isEqualTo: widget.studentId).get();
    }
    final byExam = <String, List<Map<String, dynamic>>>{};
    for (final d in q.docs) {
      byExam.putIfAbsent('${d.data()['exam'] ?? ''}', () => []).add(d.data());
    }
    return {
      for (final e in byExam.entries) e.key: ResultMarks(ResultService._merge(e.value)),
    };
  }

  @override
  Widget build(BuildContext context) {
    return FutureBuilder<Map<String, ResultMarks>>(
      future: _f,
      builder: (context, snap) {
        if (snap.hasError) {
          return Center(child: Text('Could not load your results: ${snap.error}'));
        }
        if (!snap.hasData) {
          return const Center(child: CircularProgressIndicator());
        }
// Show every exam this student has marks for, unless the administrator
// CLOSED it. (Before, an exam was also hidden when its name was not in the
// Settings > Exams list, e.g. after the list was edited or renamed.)
        final data = snap.data!;
        final order = appSettings.value.examOptions;
        final withMarks = [
          for (final e in data.keys)
            if (e.isNotEmpty && data[e]!.marks.isNotEmpty) e,
        ];
        final exams = [
          for (final e in withMarks)
            if (appSettings.value.isExamOpen(e)) e,
        ]..sort((a, b) {
          int i(String x) {
            final k = order.indexOf(x);
            return k < 0 ? 1 << 20 : k;
          }
          final c = i(a).compareTo(i(b));
          return c != 0 ? c : a.compareTo(b);
        });
        final closedCount = withMarks.length - exams.length;
        return RefreshIndicator(
          onRefresh: () async {
            setState(() => _f = _load());
            await _f;
          },
          child: ListView(
            physics: const AlwaysScrollableScrollPhysics(),
            padding: const EdgeInsets.fromLTRB(16, 12, 16, 32),
            children: [
              if (exams.isEmpty)
                Padding(
                  padding: const EdgeInsets.all(24),
                  child: Center(
                      child: Text(
                          closedCount > 0
                              ? 'Your results are not open yet.\nThe administrator has not opened this exam.'
                              : 'No results published yet.',
                          textAlign: TextAlign.center)),
                ),
              if (exams.isNotEmpty) _transcript(exams, data),
            ],
          ),
        );
      },
    );
  }

  Widget _transcript(List<String> exams, Map<String, ResultMarks> data) {
    final cs = Theme.of(context).colorScheme;
    final subs = <String>[
      for (final s in ExamService.subjects)
        if (exams.any((e) => data[e]!.marks.containsKey(s))) s,
      for (final s in {for (final e in exams) ...data[e]!.marks.keys})
        if (!ExamService.subjects.contains(s)) s,
    ];
    final avgs = [for (final e in exams) data[e]!.average!];
    final overall = avgs.fold(0.0, (a, b) => a + b) / avgs.length;
    final overallG = _gradeOf(overall);
    final multi = exams.length > 1;

    double? subAvg(String sub) {
      final v = [
        for (final e in exams)
          if (data[e]!.marks[sub] != null) data[e]!.marks[sub]!
      ];
      return v.isEmpty ? null : v.fold(0.0, (a, b) => a + b) / v.length;
    }

    String best = '';
    double bestV = -1;
    for (final sub in subs) {
      final v = subAvg(sub);
      if (v != null && v > bestV) {
        bestV = v;
        best = sub;
      }
    }
    String f1(double v) => _fmtMark(double.parse(v.toStringAsFixed(1)));

    const bold = TextStyle(fontWeight: FontWeight.w700);
    final head = Color.lerp(cs.primary, Colors.black, 0.25)!;

    Widget cell(Widget child, {Alignment al = Alignment.center}) => Padding(
      padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 9),
      child: Align(alignment: al, child: child),
    );
    Widget label(String t, {bool strong = true}) => cell(
        Text(t,
            style: TextStyle(
                fontWeight: strong ? FontWeight.w700 : FontWeight.w500)),
        al: Alignment.centerLeft);
    Widget pill(String text, Color c) => Container(
      constraints: const BoxConstraints(minWidth: 44),
      padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 4),
      decoration: BoxDecoration(
        color: c.withAlpha(30),
        borderRadius: BorderRadius.circular(20),
      ),
      child: Text(text,
          textAlign: TextAlign.center,
          style: TextStyle(fontWeight: FontWeight.w800, color: c)),
    );
    Widget markPill(double v) => pill(_fmtMark(v), _gradeColor(_gradeOf(v)));
    Widget gradeBadge(String g, {double size = 34}) => Container(
      width: size,
      height: size,
      alignment: Alignment.center,
      decoration: BoxDecoration(
        shape: BoxShape.circle,
        color: _gradeColor(g).withAlpha(36),
        border: Border.all(color: _gradeColor(g), width: 1.5),
      ),
      child: Text(g,
          style: TextStyle(
              fontSize: size * 0.46,
              fontWeight: FontWeight.w900,
              color: _gradeColor(g))),
    );
    Widget tile(String title, Widget value) => Expanded(
      child: Container(
        margin: const EdgeInsets.symmetric(horizontal: 4),
        padding: const EdgeInsets.symmetric(vertical: 12, horizontal: 8),
        decoration: BoxDecoration(
          color: cs.surface,
          borderRadius: BorderRadius.circular(14),
          border: Border.all(color: cs.outlineVariant),
        ),
        child: Column(children: [
          Text(title,
              style: TextStyle(fontSize: 11.5, color: cs.onSurfaceVariant)),
          const SizedBox(height: 6),
          value,
        ]),
      ),
    );
    Widget trend(int i) {
      if (i == 0) return const SizedBox.shrink();
      final d = avgs[i] - avgs[i - 1];
      if (d.abs() < 0.05) return const SizedBox.shrink();
      final up = d > 0;
      final c = up ? kGreen : kRed;
      return Row(mainAxisSize: MainAxisSize.min, children: [
        Icon(up ? Icons.arrow_upward : Icons.arrow_downward, size: 12, color: c),
        Text(f1(d.abs()),
            style: TextStyle(fontSize: 11, fontWeight: FontWeight.w700, color: c)),
      ]);
    }

// grading key, e.g. "A 80+ · B 70+ · ... · F below 40"
    final limits = appSettings.value.grades;
    final key = [
      for (var i = 0; i < limits.length; i++)
        '${AppSettings.gradeLetters[i]} ${_fmtMark(limits[i])}+',
      'F below ${_fmtMark(limits.last)}',
    ].join('  ·  ');

    return Card(
      margin: EdgeInsets.zero,
      clipBehavior: Clip.antiAlias,
      child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
// ---- banner ----
        Container(
          padding: const EdgeInsets.fromLTRB(18, 16, 18, 16),
          decoration: BoxDecoration(
            gradient: LinearGradient(
              colors: [cs.primary, head],
              begin: Alignment.topLeft,
              end: Alignment.bottomRight,
            ),
          ),
          child: Row(children: [
            Container(
              padding: const EdgeInsets.all(10),
              decoration: BoxDecoration(
                  color: Colors.white.withAlpha(40), shape: BoxShape.circle),
              child: const Icon(Icons.workspace_premium,
                  color: Colors.white, size: 28),
            ),
            const SizedBox(width: 14),
            Expanded(
              child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                const Text('Academic Transcript',
                    style: TextStyle(
                        color: Colors.white,
                        fontSize: 19,
                        fontWeight: FontWeight.w800)),
                const SizedBox(height: 2),
                Text(
                    '${exams.length} exam${exams.length == 1 ? '' : 's'}  ·  '
                        '${subs.length} subject${subs.length == 1 ? '' : 's'}',
                    style: const TextStyle(color: Colors.white70, fontSize: 13)),
              ]),
            ),
          ]),
        ),
// ---- summary ----
        Padding(
          padding: const EdgeInsets.fromLTRB(12, 14, 12, 4),
          child: Row(children: [
            tile('Overall average',
                Text(f1(overall),
                    style: const TextStyle(fontSize: 22, fontWeight: FontWeight.w800))),
            tile('Overall grade', gradeBadge(overallG, size: 38)),
            tile(
              'Best subject',
              Column(children: [
                Text(best.isEmpty ? '-' : best,
                    maxLines: 1,
                    overflow: TextOverflow.ellipsis,
                    style: const TextStyle(fontSize: 15, fontWeight: FontWeight.w800)),
                if (best.isNotEmpty)
                  Text(f1(bestV),
                      style: TextStyle(
                          fontSize: 12,
                          fontWeight: FontWeight.w700,
                          color: _gradeColor(_gradeOf(bestV)))),
              ]),
            ),
          ]),
        ),
// ---- table ----
        Padding(
          padding: const EdgeInsets.fromLTRB(12, 10, 12, 4),
          child: LayoutBuilder(builder: (context, c) {
            const firstW = 120.0;
            final cols = exams.length + (multi ? 1 : 0);
            final colW = ((c.maxWidth - firstW) / cols).clamp(96.0, 220.0);
            final tableW = firstW + colW * cols;
            final fit = tableW <= c.maxWidth;
            TableColumnWidth w() =>
                fit ? const FlexColumnWidth() : FixedColumnWidth(colW);
            return ClipRRect(
              borderRadius: BorderRadius.circular(12),
              child: DecoratedBox(
                decoration: BoxDecoration(
                  border: Border.all(color: cs.outlineVariant),
                  borderRadius: BorderRadius.circular(12),
                ),
                child: SingleChildScrollView(
                  scrollDirection: Axis.horizontal,
                  child: SizedBox(
                    width: fit ? c.maxWidth : tableW,
                    child: Table(
                      columnWidths: {
                        0: const FixedColumnWidth(firstW),
                        for (var i = 1; i <= cols; i++) i: w(),
                      },
                      defaultVerticalAlignment: TableCellVerticalAlignment.middle,
                      children: [
                        TableRow(
                            decoration: BoxDecoration(color: cs.primary.withAlpha(28)),
                            children: [
                              label('Subject'),
                              for (final e in exams)
                                cell(Text(e,
                                    textAlign: TextAlign.center, style: bold)),
                              if (multi) cell(const Text('Average', style: bold)),
                            ]),
                        for (var r = 0; r < subs.length; r++)
                          TableRow(
                              decoration: BoxDecoration(
                                color: r.isOdd
                                    ? cs.surfaceContainerHighest.withAlpha(70)
                                    : Colors.transparent,
                              ),
                              children: [
                                label(subs[r], strong: false),
                                for (final e in exams)
                                  cell(data[e]!.marks[subs[r]] == null
                                      ? Text('-',
                                      style: TextStyle(color: cs.onSurfaceVariant))
                                      : markPill(data[e]!.marks[subs[r]]!)),
                                if (multi)
                                  cell(subAvg(subs[r]) == null
                                      ? const Text('-')
                                      : markPill(double.parse(
                                      subAvg(subs[r])!.toStringAsFixed(1)))),
                              ]),
                        TableRow(
                            decoration: BoxDecoration(
                                color: cs.primary.withAlpha(18),
                                border: Border(
                                    top: BorderSide(color: cs.primary, width: 1.5))),
                            children: [
                              label('Total'),
                              for (final e in exams)
                                cell(Text(_fmtMark(data[e]!.total), style: bold)),
                              if (multi) cell(const SizedBox.shrink()),
                            ]),
                        TableRow(
                            decoration: BoxDecoration(color: cs.primary.withAlpha(18)),
                            children: [
                              label('Average'),
                              for (var i = 0; i < exams.length; i++)
                                cell(Column(mainAxisSize: MainAxisSize.min, children: [
                                  Text(f1(avgs[i]), style: bold),
                                  trend(i),
                                ])),
                              if (multi)
                                cell(Text(f1(overall), style: bold)),
                            ]),
                        TableRow(
                            decoration: BoxDecoration(color: cs.primary.withAlpha(18)),
                            children: [
                              label('Grade'),
                              for (var i = 0; i < exams.length; i++)
                                cell(gradeBadge(_gradeOf(avgs[i]))),
                              if (multi) cell(gradeBadge(overallG)),
                            ]),
                      ],
                    ),
                  ),
                ),
              ),
            );
          }),
        ),
        Padding(
          padding: const EdgeInsets.fromLTRB(16, 6, 16, 16),
          child: Text('Grading: $key',
              style: TextStyle(fontSize: 11.5, color: cs.onSurfaceVariant)),
        ),
      ]),
    );
  }

  Widget _examCard(String exam, ResultMarks r) {
    final avg = r.average!;
    final g = _gradeOf(avg);
    return Card(
      child: Padding(
        padding: const EdgeInsets.all(16),
        child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
          Row(children: [
            Expanded(
              child: Text(exam,
                  style: const TextStyle(
                      fontSize: 16, fontWeight: FontWeight.w700)),
            ),
            Container(
              padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 4),
              decoration: BoxDecoration(
                color: _gradeColor(g).withAlpha(36),
                borderRadius: BorderRadius.circular(20),
              ),
              child: Text('Grade $g',
                  style: TextStyle(
                      fontWeight: FontWeight.w800, color: _gradeColor(g))),
            ),
          ]),
          const Divider(height: 20),
          for (final sub in ExamService.subjects)
            if (r.marks[sub] != null)
              Padding(
                padding: const EdgeInsets.symmetric(vertical: 4),
                child: Row(children: [
                  Expanded(child: Text(sub)),
                  Text(_fmtMark(r.marks[sub]!),
                      style: const TextStyle(fontWeight: FontWeight.w700)),
                ]),
              ),
          const Divider(height: 20),
          Row(children: [
            const Expanded(child: Text('Total')),
            Text(_fmtMark(r.total),
                style: const TextStyle(fontWeight: FontWeight.w700)),
          ]),
          const SizedBox(height: 4),
          Row(children: [
            const Expanded(child: Text('Average')),
            Text(_fmtMark(double.parse(avg.toStringAsFixed(1))),
                style: const TextStyle(fontWeight: FontWeight.w700)),
          ]),
        ]),
      ),
    );
  }
}

/// The attendance of the signed-in student: rate and day-by-day history.
class _StudentAttendanceBody extends StatefulWidget {
  final String studentId;
  const _StudentAttendanceBody({required this.studentId});

  @override
  State<_StudentAttendanceBody> createState() => _StudentAttendanceBodyState();
}

class _StudentAttendanceBodyState extends State<_StudentAttendanceBody> {
  late Future<List<_AttEntry>> _f = _load();
  String _filter = 'all';

  Future<List<_AttEntry>> _load() async {
    final q = await FirebaseFirestore.instance
        .collection('attendance')
        .where(FieldPath(['records', widget.studentId]),
        whereIn: ['present', 'absent', 'late'])
        .get();
    return [
      for (final d in q.docs)
        _AttEntry(
          '${d.data()['date'] ?? ''}',
          '${d.data()['subject'] ?? ''}'.trim(),
          '${(d.data()['records'] as Map?)?[widget.studentId] ?? ''}',
        ),
    ]..sort((a, b) {
      final c = b.dateKey.compareTo(a.dateKey);
      return c != 0 ? c : a.subject.compareTo(b.subject);
    });
  }

  DateTime? _parse(String k) {
    try {
      return DateFormat('yyyy-MM-dd').parseStrict(k);
    } catch (_) {
      return null;
    }
  }

  @override
  Widget build(BuildContext context) {
    return FutureBuilder<List<_AttEntry>>(
      future: _f,
      builder: (context, snap) {
        if (snap.hasError) {
          return Center(
              child: Text('Could not load your attendance: ${snap.error}'));
        }
        if (!snap.hasData) {
          return const Center(child: CircularProgressIndicator());
        }
        final all = snap.data!;
        final t = _Tally();
        var late = 0;
        for (final e in all) {
          t.add(e.mark);
          if (e.mark == 'late') late++;
        }
        final shown = [
          for (final e in all)
            if (_filter == 'all' || e.mark == _filter) e,
        ];
        final rows = <Widget>[];
        String? lastMonth;
        for (final e in shown) {
          final d = _parse(e.dateKey);
          final month =
          d == null ? 'Unknown date' : DateFormat('MMMM yyyy').format(d);
          if (month != lastMonth) {
            lastMonth = month;
            rows.add(Padding(
              padding: const EdgeInsets.fromLTRB(16, 12, 16, 2),
              child: Text(month,
                  style: const TextStyle(
                      fontWeight: FontWeight.w700, color: Colors.black54)),
            ));
          }
          final c = e.mark == 'absent'
              ? kRed
              : e.mark == 'late'
              ? kLate
              : kGreen;
          rows.add(ListTile(
            dense: true,
            leading: Icon(e.mark == 'absent' ? Icons.cancel : Icons.check_circle,
                color: c),
            title: Text(d == null
                ? e.dateKey
                : DateFormat('EEE, MMM d, yyyy').format(d)),
            subtitle: Text(e.subject.isEmpty ? 'Whole day' : e.subject),
            trailing: Text(
                e.mark.isEmpty ? '' : e.mark[0].toUpperCase() + e.mark.substring(1),
                style: TextStyle(color: c, fontWeight: FontWeight.w700)),
          ));
        }
        return RefreshIndicator(
          onRefresh: () async {
            setState(() => _f = _load());
            await _f;
          },
          child: ListView(
            physics: const AlwaysScrollableScrollPhysics(),
            padding: const EdgeInsets.fromLTRB(16, 12, 16, 32),
            children: [
              Card(
                child: Padding(
                  padding: const EdgeInsets.all(16),
                  child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Row(children: [
                          const Text('Attendance rate',
                              style: TextStyle(
                                  fontSize: 16, fontWeight: FontWeight.bold)),
                          const Spacer(),
                          Text(_pct(t.rate),
                              style: TextStyle(
                                  fontSize: 26,
                                  fontWeight: FontWeight.bold,
                                  color: _rateColor(t.rate))),
                        ]),
                        const SizedBox(height: 10),
                        _StackBar(t, height: 10),
                        const SizedBox(height: 12),
                        Wrap(spacing: 8, runSpacing: 8, children: [
                          _pill('Present', t.p, kGreen),
                          _pill('Absent', t.a, kRed),
                          if (late > 0) _pill('of which late', late, kLate),
                          _pill('Days marked', t.total, Colors.blueGrey),
                        ]),
                      ]),
                ),
              ),
              Card(
                child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Padding(
                        padding: const EdgeInsets.fromLTRB(16, 12, 16, 4),
                        child: Wrap(spacing: 8, children: [
                          for (final f in const ['all', 'present', 'absent', 'late'])
                            ChoiceChip(
                              label: Text(f[0].toUpperCase() + f.substring(1)),
                              selected: _filter == f,
                              onSelected: (_) => setState(() => _filter = f),
                            ),
                        ]),
                      ),
                      if (rows.isEmpty)
                        const Padding(
                          padding: EdgeInsets.all(24),
                          child: Center(child: Text('No attendance records.')),
                        ),
                      ...rows,
                    ]),
              ),
            ],
          ),
        );
      },
    );
  }

  Widget _pill(String label, int n, Color c) => Chip(
    visualDensity: VisualDensity.compact,
    side: BorderSide(color: c),
    backgroundColor: c.withOpacity(0.12),
    label: Text('$label: $n',
        style: TextStyle(fontWeight: FontWeight.w600, color: c)),
  );
}

// ======================= STUDENT DETAIL SCREEN =======================
/// Everything about one student: profile + full attendance history.
class StudentDetailScreen extends StatefulWidget {
  final StudentInfo student;
  final SectionInfo section;
  const StudentDetailScreen(
      {super.key, required this.student, required this.section});

  @override
  State<StudentDetailScreen> createState() => _StudentDetailScreenState();
}

class _AttEntry {
  final String dateKey, subject, mark;
  const _AttEntry(this.dateKey, this.subject, this.mark);
  bool get present => mark == 'present' || mark == 'late';
}

class _StudentDetailScreenState extends State<StudentDetailScreen> {
  late final Stream<DocumentSnapshot<Map<String, dynamic>>> _docStream =
  FirebaseFirestore.instance
      .collection('students')
      .doc(widget.student.id)
      .snapshots();
  late Future<List<_AttEntry>> _attFuture = _loadAttendance();
  String _filter = 'all'; // all | present | absent | late

  /// Every register (any section, any date) that has a mark for this
  /// student. Queries one field path, so no extra Firestore index is needed.
  Future<List<_AttEntry>> _loadAttendance() async {
    final q = await FirebaseFirestore.instance
        .collection('attendance')
        .where(FieldPath(['records', widget.student.id]),
        whereIn: ['present', 'absent', 'late'])
        .get();
    final list = <_AttEntry>[
      for (final d in q.docs)
        _AttEntry(
          '${d.data()['date'] ?? ''}',
          '${d.data()['subject'] ?? ''}'.trim(),
          '${(d.data()['records'] as Map?)?[widget.student.id] ?? ''}',
        ),
    ]..sort((a, b) {
      final c = b.dateKey.compareTo(a.dateKey);
      return c != 0 ? c : a.subject.compareTo(b.subject);
    });
    return list;
  }

  DateTime? _parse(String k) {
    try {
      return DateFormat('yyyy-MM-dd').parseStrict(k);
    } catch (_) {
      return null;
    }
  }

  String _fmtDate(Timestamp? t) =>
      t == null ? '–' : DateFormat('MMM d, yyyy  HH:mm').format(t.toDate());

  Widget _info(IconData icon, String label, String value) => ListTile(
    dense: true,
    leading: Icon(icon, size: 20),
    title: Text(label,
        style: const TextStyle(fontSize: 12, color: Colors.black54)),
    subtitle: Text(value,
        style: const TextStyle(
            fontSize: 15,
            fontWeight: FontWeight.w600,
            color: Colors.black87)),
  );

  Widget _profile(ColorScheme cs) {
    final sec = widget.section;
    return StreamBuilder<DocumentSnapshot<Map<String, dynamic>>>(
      stream: _docStream,
      builder: (context, snap) {
        final m = snap.data?.data() ?? {};
        final linked = (m['accountUid'] is String) &&
            (m['accountUid'] as String).isNotEmpty;
        final name = '${m['name'] ?? widget.student.name}';
        return Card(
          child: Padding(
            padding: const EdgeInsets.symmetric(vertical: 12),
            child: Column(children: [
              CircleAvatar(
                radius: 34,
                backgroundColor: cs.primaryContainer,
                child: Text(
                  name.trim().isEmpty ? '?' : name.trim()[0].toUpperCase(),
                  style: TextStyle(
                      fontSize: 28,
                      fontWeight: FontWeight.bold,
                      color: cs.onPrimaryContainer),
                ),
              ),
              const SizedBox(height: 8),
              Padding(
                padding: const EdgeInsets.symmetric(horizontal: 16),
                child: Text(name,
                    textAlign: TextAlign.center,
                    style: const TextStyle(
                        fontSize: 20, fontWeight: FontWeight.bold)),
              ),
              const SizedBox(height: 4),
              Text(sec.fullName,
                  style: TextStyle(
                      color: cs.primary, fontWeight: FontWeight.w600)),
              const Divider(height: 24),
              _info(Icons.school_outlined, 'Form', sec.form),
              _info(Icons.class_outlined, 'Class', SectionInfo.code(sec.form, sec.classKey)),
              _info(Icons.groups_outlined, 'Section',
                  sec.isSub ? 'Section ${sec.subName}' : 'Whole class (no sections)'),
              _info(Icons.phone_outlined, 'Phone number(s)',
                  (m['phones'] is List && (m['phones'] as List).isNotEmpty)
                      ? (m['phones'] as List).join('  ·  ')
                      : 'Not saved'),
              _info(Icons.person_outline, 'Username / password',
                  '${m['phone'] ?? ''}'.isEmpty
                      ? 'No phone number, cannot log in'
                      : '${m['phone']}  (same for both)'),
              _info(Icons.link, 'Student account',
                  linked ? 'Linked to a login account' : 'Not linked'),
              if (!linked && '${m['phone'] ?? ''}'.isNotEmpty)
                Padding(
                  padding: const EdgeInsets.fromLTRB(16, 0, 16, 8),
                  child: Align(
                    alignment: Alignment.centerLeft,
                    child: FilledButton.tonalIcon(
                      onPressed: () => runAccountCreation(context,
                          ids: [widget.student.id], quiet: true),
                      icon: const Icon(Icons.key),
                      label: const Text('Create login account'),
                    ),
                  ),
                ),
              _info(Icons.event_available_outlined, 'Added',
                  _fmtDate(m['createdAt'] as Timestamp?)),
              if (m['updatedAt'] != null)
                _info(Icons.update, 'Last updated',
                    _fmtDate(m['updatedAt'] as Timestamp?)),
              _info(Icons.tag, 'Student ID', widget.student.id),
            ]),
          ),
        );
      },
    );
  }

  Widget _summary(List<_AttEntry> all) {
    final t = _Tally();
    var late = 0;
    for (final e in all) {
      t.add(e.mark);
      if (e.mark == 'late') late++;
    }
    final color = _rateColor(t.rate);
    return Card(
      child: Padding(
        padding: const EdgeInsets.all(16),
        child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
          Row(children: [
            const Icon(Icons.fact_check_outlined),
            const SizedBox(width: 8),
            const Text('Attendance',
                style: TextStyle(fontSize: 16, fontWeight: FontWeight.bold)),
            const Spacer(),
            Text(_pct(t.rate),
                style: TextStyle(
                    fontSize: 26, fontWeight: FontWeight.bold, color: color)),
          ]),
          const SizedBox(height: 10),
          _StackBar(t, height: 10),
          const SizedBox(height: 12),
          Wrap(spacing: 8, runSpacing: 8, children: [
            _chip('Present', t.p, kGreen),
            _chip('Absent', t.a, kRed),
            if (late > 0) _chip('of which late', late, kLate),
            _chip('Days marked', t.total, Colors.blueGrey),
          ]),
        ]),
      ),
    );
  }

  Widget _chip(String label, int n, Color c) => Chip(
    visualDensity: VisualDensity.compact,
    side: BorderSide(color: c),
    backgroundColor: c.withOpacity(0.12),
    label: Text('$label: $n',
        style: TextStyle(fontWeight: FontWeight.w600, color: c)),
  );

  Widget _history(List<_AttEntry> all) {
    final shown = [
      for (final e in all)
        if (_filter == 'all' ||
            (_filter == 'present' && e.mark == 'present') ||
            (_filter == 'late' && e.mark == 'late') ||
            (_filter == 'absent' && e.mark == 'absent'))
          e,
    ];
    final children = <Widget>[
      Padding(
        padding: const EdgeInsets.fromLTRB(16, 12, 16, 4),
        child: Row(children: [
          const Icon(Icons.history),
          const SizedBox(width: 8),
          const Text('Attendance history',
              style: TextStyle(fontSize: 16, fontWeight: FontWeight.bold)),
        ]),
      ),
      Padding(
        padding: const EdgeInsets.symmetric(horizontal: 12),
        child: Wrap(spacing: 8, children: [
          for (final f in const ['all', 'present', 'absent', 'late'])
            ChoiceChip(
              label: Text(f[0].toUpperCase() + f.substring(1)),
              selected: _filter == f,
              onSelected: (_) => setState(() => _filter = f),
            ),
        ]),
      ),
    ];
    if (shown.isEmpty) {
      children.add(const Padding(
        padding: EdgeInsets.all(24),
        child: Center(child: Text('No attendance records.')),
      ));
    }
    String? lastMonth;
    for (final e in shown) {
      final d = _parse(e.dateKey);
      final month = d == null ? 'Unknown date' : DateFormat('MMMM yyyy').format(d);
      if (month != lastMonth) {
        lastMonth = month;
        children.add(Padding(
          padding: const EdgeInsets.fromLTRB(16, 12, 16, 2),
          child: Text(month,
              style: const TextStyle(
                  fontWeight: FontWeight.w700, color: Colors.black54)),
        ));
      }
      final c = e.mark == 'absent'
          ? kRed
          : e.mark == 'late'
          ? kLate
          : kGreen;
      children.add(ListTile(
        dense: true,
        leading: Icon(
            e.mark == 'absent' ? Icons.cancel : Icons.check_circle,
            color: c),
        title: Text(d == null
            ? e.dateKey
            : DateFormat('EEE, MMM d, yyyy').format(d)),
        subtitle: Text(e.subject.isEmpty ? 'Whole day' : e.subject),
        trailing: Text(
            e.mark.isEmpty ? '' : e.mark[0].toUpperCase() + e.mark.substring(1),
            style: TextStyle(color: c, fontWeight: FontWeight.w700)),
      ));
    }
    return Card(
        child: Column(
            crossAxisAlignment: CrossAxisAlignment.start, children: children));
  }

  @override
  Widget build(BuildContext context) {
    final cs = Theme.of(context).colorScheme;
    return Scaffold(
      appBar: AppBar(title: const Text('Student details'), actions: [
        IconButton(
          tooltip: 'Refresh attendance',
          icon: const Icon(Icons.refresh),
          onPressed: () => setState(() => _attFuture = _loadAttendance()),
        ),
      ]),
      body: Align(
        alignment: Alignment.topCenter,
        child: ConstrainedBox(
          constraints: const BoxConstraints(maxWidth: 760),
          child: ListView(
            padding: const EdgeInsets.fromLTRB(16, 12, 16, 32),
            children: [
              _profile(cs),
              FutureBuilder<List<_AttEntry>>(
                future: _attFuture,
                builder: (context, snap) {
                  if (snap.hasError) {
                    return Card(
                        child: Padding(
                            padding: const EdgeInsets.all(16),
                            child: Text(
                                'Could not load attendance: ${snap.error}')));
                  }
                  if (!snap.hasData) {
                    return const Padding(
                        padding: EdgeInsets.all(32),
                        child: Center(child: CircularProgressIndicator()));
                  }
                  return Column(children: [
                    _summary(snap.data!),
                    _history(snap.data!),
                  ]);
                },
              ),
            ],
          ),
        ),
      ),
    );
  }
}

// ======================= ATTENDANCE SCREEN =======================

const kLate = Color(0xFFF39C12);

/// One saved register: one section, one day, one subject ('' = whole day).
class AttendanceDoc {
  final String id, sectionId, dateKey, subject;
  final Map<String, String> records; // studentId -> present | absent
  const AttendanceDoc({
    required this.id,
    required this.sectionId,
    required this.dateKey,
    required this.subject,
    required this.records,
  });
}

/// Present / absent counter. (Old 'late' marks count as present.)
class _Tally {
  int p = 0, a = 0;
  int get total => p + a;

  /// Attendance rate = present / marked. Null when nothing is marked.
  double? get rate => total == 0 ? null : p / total;

  void add(String? mark) {
    if (mark == 'present' || mark == 'late') {
      p++;
    } else if (mark == 'absent') {
      a++;
    }
  }
}

Color _rateColor(double? r) {
  if (r == null) return Colors.grey;
  final s = appSettings.value; // limits are set in Settings
  if (r >= s.rateGood / 100) return kGreen;
  if (r >= s.rateWarn / 100) return kLate;
  return kRed;
}

String _pct(double? r) => r == null ? '–' : '${(r * 100).round()}%';

/// Thin stacked bar: green present, red absent, grey not marked.
class _StackBar extends StatelessWidget {
  final _Tally t;
  final int unmarked;
  final double height;
  const _StackBar(this.t, {this.unmarked = 0, this.height = 8});

  @override
  Widget build(BuildContext context) {
    final total = t.total + unmarked;
    return ClipRRect(
      borderRadius: BorderRadius.circular(height / 2),
      child: SizedBox(
        height: height,
        child: total == 0
            ? ColoredBox(color: Colors.grey.shade300)
            : Row(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
          if (t.p > 0)
            Expanded(flex: t.p, child: const ColoredBox(color: kGreen)),
          if (t.a > 0)
            Expanded(flex: t.a, child: const ColoredBox(color: kRed)),
          if (unmarked > 0)
            Expanded(
                flex: unmarked,
                child: ColoredBox(color: Colors.grey.shade300)),
        ]),
      ),
    );
  }
}

class AttendanceScreen extends StatefulWidget {
  const AttendanceScreen({super.key});

  @override
  State<AttendanceScreen> createState() => _AttendanceScreenState();
}

class _AttendanceScreenState extends State<AttendanceScreen> {
  final _service = SchoolService();
  String? _sectionId;
// Selected subjects. Empty = "All subjects" (whole-day register).
// One or more subjects = the same marks are saved for each of them.
  final Set<String> _subjects = {};

  List<String> get _subjectOrder {
    final all = teacherScope.value.subjectList;
    final sel = _subjects.toList();
    sel.sort((a, b) => all.indexOf(a).compareTo(all.indexOf(b)));
    return sel;
  }

  String get _subjectLabel =>
      _subjects.isEmpty ? 'All subjects' : _subjectOrder.join(', ');
  DateTime _date = DateTime.now();
  Map<String, String> _marks = {};
  bool _loading = false;
  bool _saving = false;
  bool _dirty = false;
  bool _onlyUnmarked = false;
  int _token = 0; // ignores answers of an older section / date / subject

  String get _dateKey => DateFormat('yyyy-MM-dd').format(_date);

  Future<void> _load() async {
    final id = _sectionId;
    if (id == null) return;
    final t = ++_token;
    setState(() {
      _loading = true;
      _dirty = false;
    });
    try {
// Empty selection = whole day. Several subjects: merge their registers.
// A student absent in ANY chosen subject is shown absent for all of them.
      final keys = _subjects.isEmpty ? <String>[''] : _subjectOrder;
      final merged = <String, String>{};
      for (final k in keys) {
        final m = await _service.getAttendance(id, _dateKey, subject: k);
        for (final e in m.entries) {
          if (merged[e.key] == 'absent') continue;
          merged[e.key] = e.value;
        }
      }
      if (!mounted || t != _token) return;
      setState(() {
// the Late option was removed: old late marks count as present
        _marks = {
          for (final e in merged.entries)
            e.key: e.value == 'late' ? 'present' : e.value,
        };
        _loading = false;
      });
    } catch (e) {
      if (!mounted || t != _token) return;
      setState(() {
        _marks = {};
        _loading = false;
      });
      ScaffoldMessenger.of(context)
          .showSnackBar(SnackBar(content: Text('Could not load: $e')));
    }
  }

  /// Asks before throwing away marks that were not saved yet.
  Future<bool> _okToLeave() async {
    if (!_dirty) return true;
    final r = await showDialog<bool>(
      context: context,
      builder: (c) => AlertDialog(
        title: const Text('Discard unsaved changes?'),
        content: const Text('The marks you changed have not been saved.'),
        actions: [
          TextButton(
              onPressed: () => Navigator.pop(c, false),
              child: const Text('Keep editing')),
          FilledButton(
              onPressed: () => Navigator.pop(c, true),
              child: const Text('Discard')),
        ],
      ),
    );
    return r ?? false;
  }

  Future<void> _setDate(DateTime d) async {
    if (!await _okToLeave() || !mounted) return;
    setState(() => _date = d);
    _load();
  }

  Future<void> _pickDate() async {
    final d = await showDatePicker(
      context: context,
      initialDate: _date,
      firstDate: DateTime(2020),
      lastDate: DateTime.now().add(const Duration(days: 365)),
    );
    if (d != null) _setDate(d);
  }

  Future<void> _save(List<StudentInfo> students) async {
    final id = _sectionId;
    if (id == null) return;
    setState(() => _saving = true);
    final messenger = ScaffoldMessenger.of(context);
    try {
      final records = {
        for (final s in students)
          if (_marks[s.id] != null) s.id: _marks[s.id]!,
      };
      final keys = _subjects.isEmpty ? <String>[''] : _subjectOrder;
      for (final k in keys) {
        await _service.saveAttendance(id, _dateKey, records, subject: k);
      }
      if (!mounted) return;
      setState(() {
        _saving = false;
        _dirty = false;
      });
      messenger.showSnackBar(SnackBar(
          content: Text(
              'Saved · ${records.length} of ${students.length} students marked')));
    } catch (e) {
      if (mounted) setState(() => _saving = false);
      messenger.showSnackBar(SnackBar(content: Text('Failed: $e')));
    }
  }

  /// Dialog with checkboxes: "All subjects" or any number of subjects.
  Future<void> _pickSubjects() async {
    final all = teacherScope.value.subjectList;
    final temp = {..._subjects};
    final result = await showDialog<Set<String>>(
      context: context,
      builder: (c) => StatefulBuilder(
        builder: (c, setD) => AlertDialog(
          title: const Text('Subjects'),
          contentPadding: const EdgeInsets.fromLTRB(8, 12, 8, 0),
          content: SizedBox(
            width: 360,
            child: ListView(shrinkWrap: true, children: [
              CheckboxListTile(
                value: temp.isEmpty,
                title: const Text('All subjects'),
                controlAffinity: ListTileControlAffinity.leading,
                onChanged: (_) => setD(temp.clear),
              ),
              const Divider(height: 1),
              for (final s in all)
                CheckboxListTile(
                  value: temp.contains(s),
                  title: Text(s),
                  controlAffinity: ListTileControlAffinity.leading,
                  onChanged: (v) =>
                      setD(() => v == true ? temp.add(s) : temp.remove(s)),
                ),
            ]),
          ),
          actions: [
            TextButton(
                onPressed: () => Navigator.pop(c),
                child: const Text('Cancel')),
            FilledButton(
                onPressed: () => Navigator.pop(c, temp),
                child: const Text('Done')),
          ],
        ),
      ),
    );
    if (result == null || !mounted) return;
    if (result.length == _subjects.length && result.containsAll(_subjects)) {
      return;
    }
    if (!await _okToLeave() || !mounted) return;
    setState(() {
      _subjects
        ..clear()
        ..addAll(result);
    });
    _load();
  }

  void _openReport() {
    Navigator.of(context).push(MaterialPageRoute(
      builder: (_) =>
          AttendanceReportScreen(sectionId: _sectionId, date: _date),
    ));
  }

// ---------------- widgets ----------------

  Widget _controls() => Padding(
    padding: const EdgeInsets.fromLTRB(16, 12, 16, 8),
    child: Column(children: [
      Row(children: [
        Expanded(
          flex: 5,
          child: StreamBuilder<List<SectionInfo>>(
            stream: _service.watchSections(),
            builder: (context, snap) {
              final sections = snap.data ?? const <SectionInfo>[];
              final valid = sections.any((s) => s.id == _sectionId);
              return DropdownButtonFormField<String>(
                value: valid ? _sectionId : null,
                isExpanded: true,
                decoration: const InputDecoration(
                  labelText: 'Section',
                  border: OutlineInputBorder(),
                  isDense: true,
                ),
                items: [
                  for (final s in sections)
                    DropdownMenuItem(value: s.id, child: Text(s.label)),
                ],
                onChanged: (v) async {
                  if (v == null || v == _sectionId) return;
                  if (!await _okToLeave() || !mounted) return;
                  setState(() => _sectionId = v);
                  _load();
                },
              );
            },
          ),
        ),
        const SizedBox(width: 10),
        Expanded(
          flex: 5,
          child: InkWell(
            borderRadius: BorderRadius.circular(4),
            onTap: _pickSubjects,
            child: InputDecorator(
              decoration: const InputDecoration(
                labelText: 'Subjects',
                border: OutlineInputBorder(),
                isDense: true,
                suffixIcon: Icon(Icons.arrow_drop_down),
              ),
              child: Text(_subjectLabel,
                  maxLines: 1, overflow: TextOverflow.ellipsis),
            ),
          ),
        ),
      ]),
      const SizedBox(height: 10),
      Row(children: [
        IconButton(
          tooltip: 'Previous day',
          visualDensity: VisualDensity.compact,
          onPressed: () =>
              _setDate(DateTime(_date.year, _date.month, _date.day - 1)),
          icon: const Icon(Icons.chevron_left),
        ),
        Expanded(
          child: OutlinedButton.icon(
            onPressed: _pickDate,
            icon: const Icon(Icons.calendar_today, size: 18),
            label: Text(DateFormat('EEE, MMM d, yyyy').format(_date),
                overflow: TextOverflow.ellipsis),
            style:
            OutlinedButton.styleFrom(minimumSize: const Size(0, 44)),
          ),
        ),
        IconButton(
          tooltip: 'Next day',
          visualDensity: VisualDensity.compact,
          onPressed: () =>
              _setDate(DateTime(_date.year, _date.month, _date.day + 1)),
          icon: const Icon(Icons.chevron_right),
        ),
        const SizedBox(width: 4),
        FilledButton.tonalIcon(
          onPressed: _openReport,
          icon: const Icon(Icons.insights, size: 20),
          label: const Text('Report'),
          style: FilledButton.styleFrom(minimumSize: const Size(0, 44)),
        ),
      ]),
    ]),
  );

  Widget _stat(IconData icon, String label, int n, Color c) => Padding(
    padding: const EdgeInsets.only(right: 14),
    child: Row(mainAxisSize: MainAxisSize.min, children: [
      Icon(icon, size: 16, color: c),
      const SizedBox(width: 4),
      Text('$label ',
          style: TextStyle(fontSize: 13, color: Colors.grey.shade700)),
      Text('$n',
          style:
          const TextStyle(fontSize: 13, fontWeight: FontWeight.w700)),
    ]),
  );

  Widget _markButton(StudentInfo s, String value, IconData icon, Color c,
      String label) {
    final selected = _marks[s.id] == value;
    return Tooltip(
      message: label,
      child: InkWell(
        borderRadius: BorderRadius.circular(10),
        onTap: _saving
            ? null
            : () => setState(() {
          if (selected) {
            _marks.remove(s.id);
          } else {
            _marks[s.id] = value;
          }
          _dirty = true;
        }),
        child: AnimatedContainer(
          duration: const Duration(milliseconds: 120),
          width: 46,
          height: 38,
          margin: const EdgeInsets.only(left: 6),
          decoration: BoxDecoration(
            color: selected ? c : Colors.transparent,
            border: Border.all(color: selected ? c : Colors.grey.shade400),
            borderRadius: BorderRadius.circular(10),
          ),
          child: Icon(icon,
              size: 20, color: selected ? Colors.white : Colors.grey.shade600),
        ),
      ),
    );
  }

  Widget _list(List<StudentInfo> students) {
    final t = _Tally();
    for (final s in students) {
      t.add(_marks[s.id]);
    }
    final unmarked = students.length - t.total;
    final shown = [
      for (var i = 0; i < students.length; i++)
        if (!_onlyUnmarked || _marks[students[i].id] == null) i,
    ];

    return Column(children: [
// ---- summary ----
      Padding(
        padding: const EdgeInsets.fromLTRB(16, 0, 16, 6),
        child: Card(
          margin: EdgeInsets.zero,
          child: Padding(
            padding: const EdgeInsets.fromLTRB(12, 10, 4, 10),
            child: Column(children: [
              Row(children: [
                Expanded(
                  child: Wrap(runSpacing: 4, children: [
                    _stat(Icons.check_circle, 'Present', t.p, kGreen),
                    _stat(Icons.cancel, 'Absent', t.a, kRed),
                    _stat(Icons.help, 'Left', unmarked, Colors.grey),
                  ]),
                ),
                FilledButton.tonalIcon(
                  onPressed: _saving
                      ? null
                      : () => setState(() {
                    for (final s in students) {
                      _marks[s.id] = 'present';
                    }
                    _dirty = true;
                  }),
                  icon: const Icon(Icons.done_all, size: 18),
                  label: const Text('All present'),
                  style: FilledButton.styleFrom(
                      visualDensity: VisualDensity.compact),
                ),
                PopupMenuButton<String>(
                  tooltip: 'More',
                  enabled: !_saving,
                  icon: const Icon(Icons.more_vert),
                  onSelected: (v) => setState(() {
                    if (v == 'present') {
                      for (final s in students) {
                        _marks[s.id] = 'present';
                      }
                    } else if (v == 'rest') {
                      for (final s in students) {
                        _marks.putIfAbsent(s.id, () => 'present');
                      }
                    } else {
                      _marks.clear();
                    }
                    _dirty = true;
                  }),
                  itemBuilder: (_) => const [
                    PopupMenuItem(
                        value: 'rest', child: Text('Mark the rest present')),
                    PopupMenuItem(value: 'clear', child: Text('Clear all')),
                  ],
                ),
              ]),
              Padding(
                padding: const EdgeInsets.only(right: 8, top: 2),
                child: _StackBar(t, unmarked: unmarked, height: 6),
              ),
            ]),
          ),
        ),
      ),
      Padding(
        padding: const EdgeInsets.fromLTRB(16, 0, 16, 2),
        child: Row(children: [
          Text(
              '${students.length} students · $_subjectLabel',
              style: TextStyle(fontSize: 12, color: Colors.grey.shade700)),
          const Spacer(),
          FilterChip(
            label: const Text('Not marked only'),
            selected: _onlyUnmarked,
            visualDensity: VisualDensity.compact,
            labelStyle: const TextStyle(fontSize: 12),
            onSelected: (v) => setState(() => _onlyUnmarked = v),
          ),
        ]),
      ),
// ---- students: name + 3 one-tap buttons on a single line ----
      Expanded(
        child: shown.isEmpty
            ? const Center(child: Text('Everyone is marked 🎉'))
            : ListView.builder(
          padding: const EdgeInsets.fromLTRB(16, 4, 16, 8),
          itemCount: shown.length,
          itemBuilder: (context, k) {
            final i = shown[k];
            final s = students[i];
            final mark = _marks[s.id];
            final c = mark == 'present'
                ? kGreen
                : mark == 'absent'
                ? kRed
                : Colors.grey.shade400;
            return Card(
              margin: const EdgeInsets.symmetric(vertical: 3),
              child: Padding(
                padding: const EdgeInsets.symmetric(
                    horizontal: 12, vertical: 8),
                child: Row(children: [
                  CircleAvatar(
                    radius: 13,
                    backgroundColor: c,
                    child: Text('${i + 1}',
                        style: const TextStyle(
                            fontSize: 11, color: Colors.white)),
                  ),
                  const SizedBox(width: 10),
                  Expanded(
                    child: Text(s.name,
                        maxLines: 2,
                        overflow: TextOverflow.ellipsis,
                        style: const TextStyle(
                            fontSize: 14.5, fontWeight: FontWeight.w600)),
                  ),
                  _markButton(
                      s, 'present', Icons.check, kGreen, 'Present'),
                  _markButton(s, 'absent', Icons.close, kRed, 'Absent'),
                ]),
              ),
            );
          },
        ),
      ),
      SafeArea(
        top: false,
        child: Padding(
          padding: const EdgeInsets.fromLTRB(16, 4, 16, 12),
          child: SizedBox(
            width: double.infinity,
            child: FilledButton.icon(
              onPressed: (_saving || _loading) ? null : () => _save(students),
              icon: _saving
                  ? const SizedBox(
                  width: 16,
                  height: 16,
                  child: CircularProgressIndicator(strokeWidth: 2))
                  : const Icon(Icons.save),
              label: Text(_dirty ? 'Save changes' : 'Save attendance'),
            ),
          ),
        ),
      ),
    ]);
  }

  @override
  Widget build(BuildContext context) {
    final Widget body;
    if (_sectionId == null) {
      body = const Center(
        child: Padding(
          padding: EdgeInsets.all(24),
          child: Text('Choose a section, subject and date to take attendance.',
              textAlign: TextAlign.center),
        ),
      );
    } else if (_loading) {
      body = const Center(child: CircularProgressIndicator());
    } else {
      body = StreamBuilder<List<StudentInfo>>(
        stream: _service.watchStudents(_sectionId!),
        builder: (context, snap) {
          if (snap.hasError) return Center(child: Text('Error: ${snap.error}'));
          if (!snap.hasData) {
            return const Center(child: CircularProgressIndicator());
          }
          if (snap.data!.isEmpty) {
            return const Center(
              child: Padding(
                padding: EdgeInsets.all(24),
                child: Text(
                    'This section has no students yet.\nAdd them in Sections first.',
                    textAlign: TextAlign.center),
              ),
            );
          }
          return _list(snap.data!);
        },
      );
    }
    return Scaffold(
      appBar: AppBar(title: const Text('Attendance')),
      body: Align(
        alignment: Alignment.topCenter,
        child: ConstrainedBox(
          constraints: const BoxConstraints(maxWidth: 720),
          child: Column(children: [
            _controls(),
            Expanded(child: body),
          ]),
        ),
      ),
    );
  }
}

// ======================= ATTENDANCE REPORT =======================

enum _Period { day, week, month }

class _ReportData {
  final List<AttendanceDoc> docs;
  final Map<String, StudentInfo> students;
  const _ReportData(this.docs, this.students);
}

/// One line of a breakdown card (a day, a subject or a section).
class _RepRow {
  final String label;
  final _Tally t;
  const _RepRow(this.label, this.t);
}

/// Everything the report shows, computed once for the screen and the exports.
class _Analysis {
  final _Tally overall;
  final int registers;
  final List<_RepRow> dayRows, subjectRows, sectionRows;
  final List<MapEntry<String, _Tally>> attention;
  final List<(IconData, String, Color)> insights;
  const _Analysis(this.overall, this.registers, this.dayRows, this.subjectRows,
      this.sectionRows, this.attention, this.insights);
}

/// Plain text version of the report, used for PDF / Word / print.
class _ExTable {
  final String title;
  final List<String> head;
  final List<List<String>> rows;
  final List<int> weights; // relative column widths
  const _ExTable(this.title, this.head, this.rows, this.weights);
}

class _ExDoc {
  final String period, filters, fileKey;
  final List<String> insights;
  final List<_ExTable> tables;
  final ({Uint8List data, int w, int h, String kind})? logo; // school letterhead
  const _ExDoc({
    this.logo,
    required this.period,
    required this.filters,
    required this.fileKey,
    required this.insights,
    required this.tables,
  });
}

class AttendanceReportScreen extends StatefulWidget {
  final String? sectionId;
  final DateTime? date;
  const AttendanceReportScreen({super.key, this.sectionId, this.date});

  @override
  State<AttendanceReportScreen> createState() => _AttendanceReportScreenState();
}

class _AttendanceReportScreenState extends State<AttendanceReportScreen> {
  static const _all = '__all__';
  static const _none = '__none__'; // "Whole day" registers (no subject)

  final _service = SchoolService();
  _Period _period = _Period.week;
  late DateTime _anchor;
  late String _section;
// Selected subjects. Empty = all subjects. May also contain `_none`
// ("Whole day" registers). One or many can be ticked.
  final Set<String> _subjects = {};
  late Future<_ReportData> _future;
  _ReportData? _data; // last loaded data (for the exports)
  List<SectionInfo> _secs = const [];
  bool _busy = false;
  ({Uint8List data, int w, int h, String kind})? _logo;
  bool _logoLoaded = false;

  /// The school letterhead saved in the Exam tab (null = none / unreadable).
  Future<({Uint8List data, int w, int h, String kind})?> _loadLogo() async {
    if (_logoLoaded) return _logo;
    try {
      final exam = ExamService();
      final lh = await exam.getLetterhead();
      if (lh != null) {
        final kind = exam._sniff(lh);
        if (kind != null) {
          final sz = await exam._imageSize(lh);
          _logo = (data: lh, w: sz.w, h: sz.h, kind: kind);
        } else {
          final p = await exam._toPngInfo(lh);
          _logo = (data: p.png, w: p.w, h: p.h, kind: 'png');
        }
      }
    } catch (_) {
      _logo = null; // unreadable letterhead: export without the image
    }
    _logoLoaded = true;
    return _logo;
  }

  @override
  void initState() {
    super.initState();
    final d = widget.date ?? DateTime.now();
    _anchor = DateTime(d.year, d.month, d.day);
    _section = widget.sectionId ?? _all;
    _future = _fetch();
  }

  static DateTime _addDays(DateTime d, int n) =>
      DateTime(d.year, d.month, d.day + n);

  (DateTime, DateTime) get _range {
    final d = _anchor;
    switch (_period) {
      case _Period.day:
        return (d, d);
      case _Period.week:
        final start = _addDays(
            d, -((d.weekday - appSettings.value.weekStart + 7) % 7));
        return (start, _addDays(start, 6));
      case _Period.month:
        return (DateTime(d.year, d.month, 1), DateTime(d.year, d.month + 1, 0));
    }
  }

  String _key(DateTime d) => DateFormat('yyyy-MM-dd').format(d);

  Future<_ReportData> _fetch() async {
    final (from, to) = _range;
    final res = await Future.wait([
      _service.getAttendanceRange(_key(from), _key(to)),
      _service.getAllStudents(),
    ]);
    return _ReportData(
        res[0] as List<AttendanceDoc>, res[1] as Map<String, StudentInfo>);
  }

  void _reload() => setState(() => _future = _fetch());

  void _shift(int dir) {
    setState(() {
      switch (_period) {
        case _Period.day:
          _anchor = _addDays(_anchor, dir);
        case _Period.week:
          _anchor = _addDays(_anchor, 7 * dir);
        case _Period.month:
          _anchor = DateTime(_anchor.year, _anchor.month + dir, 1);
      }
    });
    _reload();
  }

  Future<void> _pickDate() async {
    final d = await showDatePicker(
      context: context,
      initialDate: _anchor,
      firstDate: DateTime(2020),
      lastDate: DateTime.now().add(const Duration(days: 365)),
    );
    if (d == null) return;
    setState(() => _anchor = DateTime(d.year, d.month, d.day));
    _reload();
  }

  String get _periodLabel {
    final (from, to) = _range;
    switch (_period) {
      case _Period.day:
        return DateFormat('EEE, MMM d, yyyy').format(from);
      case _Period.week:
        return '${DateFormat('MMM d').format(from)} – '
            '${DateFormat('MMM d, yyyy').format(to)}';
      case _Period.month:
        return DateFormat('MMMM yyyy').format(from);
    }
  }

  /// Sections this person may see (a teacher: the forms they teach).
  Set<String> _allowedIds = {};

  bool _match(AttendanceDoc d) =>
      (!teacherScope.value.restricted ||
          (_allowedIds.contains(d.sectionId) &&
              (d.subject.isEmpty ||
                  teacherScope.value.allSections ||
                  teacherScope.value.allowsSubject(d.subject)))) &&
          (_section == _all || d.sectionId == _section) &&
          (_subjects.isEmpty ||
              _subjects.contains(d.subject.isEmpty ? _none : d.subject));

  /// Selected subjects in display order (Whole day first, then the list).
  List<String> get _subjectOrder {
    final all = [_none, ...teacherScope.value.subjectList];
    final sel = _subjects.toList();
    sel.sort((a, b) {
      int ix(String s) {
        final i = all.indexOf(s);
        return i < 0 ? 999 : i;
      }

      return ix(a).compareTo(ix(b));
    });
    return sel;
  }

  String get _subjectLabel => _subjects.isEmpty
      ? 'All subjects'
      : _subjectOrder.map((s) => s == _none ? 'Whole day' : s).join(', ');

  /// Dialog with checkboxes: "All subjects" or any number of subjects.
  Future<void> _pickSubjects() async {
    final all = teacherScope.value.subjectList;
    final temp = {..._subjects};
    final result = await showDialog<Set<String>>(
      context: context,
      builder: (c) => StatefulBuilder(
        builder: (c, setD) => AlertDialog(
          title: const Text('Subjects'),
          contentPadding: const EdgeInsets.fromLTRB(8, 12, 8, 0),
          content: SizedBox(
            width: 360,
            child: ListView(shrinkWrap: true, children: [
              CheckboxListTile(
                value: temp.isEmpty,
                title: const Text('All subjects'),
                controlAffinity: ListTileControlAffinity.leading,
                onChanged: (_) => setD(temp.clear),
              ),
              const Divider(height: 1),
              CheckboxListTile(
                value: temp.contains(_none),
                title: const Text('Whole day'),
                controlAffinity: ListTileControlAffinity.leading,
                onChanged: (v) =>
                    setD(() => v == true ? temp.add(_none) : temp.remove(_none)),
              ),
              for (final s in all)
                CheckboxListTile(
                  value: temp.contains(s),
                  title: Text(s),
                  controlAffinity: ListTileControlAffinity.leading,
                  onChanged: (v) =>
                      setD(() => v == true ? temp.add(s) : temp.remove(s)),
                ),
            ]),
          ),
          actions: [
            TextButton(
                onPressed: () => Navigator.pop(c),
                child: const Text('Cancel')),
            FilledButton(
                onPressed: () => Navigator.pop(c, temp),
                child: const Text('Done')),
          ],
        ),
      ),
    );
    if (result == null || !mounted) return;
    setState(() {
      _subjects
        ..clear()
        ..addAll(result);
    });
  }

// ---------------- widgets ----------------

  Widget _filters(List<SectionInfo> sections) {
    final validSection = _section == _all || sections.any((s) => s.id == _section);
    return Padding(
      padding: const EdgeInsets.fromLTRB(16, 12, 16, 6),
      child: Column(children: [
// Daily / Weekly / Monthly and the date navigator share ONE line on
// wide screens; on a narrow phone they stack so nothing is squeezed.
        LayoutBuilder(builder: (context, box) {
          final periodButtons = SegmentedButton<_Period>(
            showSelectedIcon: false,
            segments: const [
              ButtonSegment(value: _Period.day, label: Text('Daily')),
              ButtonSegment(value: _Period.week, label: Text('Weekly')),
              ButtonSegment(value: _Period.month, label: Text('Monthly')),
            ],
            selected: {_period},
            onSelectionChanged: (v) {
              setState(() => _period = v.first);
              _reload();
            },
          );
          final dateNav = Row(children: [
            IconButton(
              tooltip: 'Previous',
              visualDensity: VisualDensity.compact,
              onPressed: () => _shift(-1),
              icon: const Icon(Icons.chevron_left),
            ),
            Expanded(
              child: OutlinedButton.icon(
                onPressed: _pickDate,
                icon: const Icon(Icons.calendar_today, size: 18),
                label: Text(_periodLabel, overflow: TextOverflow.ellipsis),
                style: OutlinedButton.styleFrom(minimumSize: const Size(0, 44)),
              ),
            ),
            IconButton(
              tooltip: 'Next',
              visualDensity: VisualDensity.compact,
              onPressed: () => _shift(1),
              icon: const Icon(Icons.chevron_right),
            ),
          ]);
          if (box.maxWidth >= 640) {
            return Row(children: [
              Expanded(flex: 5, child: periodButtons),
              const SizedBox(width: 8),
              Expanded(flex: 6, child: dateNav),
            ]);
          }
          return Column(children: [
            SizedBox(width: double.infinity, child: periodButtons),
            const SizedBox(height: 10),
            dateNav,
          ]);
        }),
        const SizedBox(height: 10),
        Row(children: [
          Expanded(
            child: DropdownButtonFormField<String>(
              value: validSection ? _section : _all,
              isExpanded: true,
              decoration: const InputDecoration(
                labelText: 'Section',
                border: OutlineInputBorder(),
                isDense: true,
              ),
              items: [
                const DropdownMenuItem(
                    value: _all, child: Text('All sections')),
                for (final s in sections)
                  DropdownMenuItem(value: s.id, child: Text(s.label)),
              ],
              onChanged: (v) => setState(() => _section = v ?? _all),
            ),
          ),
          const SizedBox(width: 10),
          Expanded(
            child: InkWell(
              borderRadius: BorderRadius.circular(4),
              onTap: _pickSubjects,
              child: InputDecorator(
                decoration: const InputDecoration(
                  labelText: 'Subjects',
                  border: OutlineInputBorder(),
                  isDense: true,
                  suffixIcon: Icon(Icons.arrow_drop_down),
                ),
                child: Text(_subjectLabel,
                    maxLines: 1, overflow: TextOverflow.ellipsis),
              ),
            ),
          ),
        ]),
      ]),
    );
  }

  Widget _kpi(String label, int n, int total, Color c) => Expanded(
    child: Column(children: [
      Text('$n',
          style: TextStyle(
              fontSize: 20, fontWeight: FontWeight.w800, color: c)),
      Text(label, style: TextStyle(fontSize: 12, color: Colors.grey.shade700)),
      Text(total == 0 ? '' : '${(n * 100 / total).round()}%',
          style: TextStyle(fontSize: 11, color: Colors.grey.shade600)),
    ]),
  );

  Widget _overview(_Tally t, int registers) {
    final r = t.rate;
    final c = _rateColor(r);
    return Card(
      margin: EdgeInsets.zero,
      child: Padding(
        padding: const EdgeInsets.all(16),
        child: Column(children: [
          Row(children: [
            SizedBox(
              width: 86,
              height: 86,
              child: Stack(alignment: Alignment.center, children: [
                SizedBox(
                  width: 86,
                  height: 86,
                  child: CircularProgressIndicator(
                    value: r ?? 0,
                    strokeWidth: 9,
                    color: c,
                    backgroundColor: Colors.grey.shade200,
                  ),
                ),
                Text(_pct(r),
                    style: const TextStyle(
                        fontSize: 22, fontWeight: FontWeight.w800)),
              ]),
            ),
            const SizedBox(width: 16),
            Expanded(
              child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                const Text('Attendance rate',
                    style:
                    TextStyle(fontSize: 16, fontWeight: FontWeight.w700)),
                const SizedBox(height: 2),
                Text(
                    '$registers register${registers == 1 ? '' : 's'} · '
                        '${t.total} marks',
                    style:
                    TextStyle(fontSize: 12.5, color: Colors.grey.shade700)),
                const SizedBox(height: 2),
                Text('Present, out of all marked',
                    style:
                    TextStyle(fontSize: 11.5, color: Colors.grey.shade600)),
              ]),
            ),
          ]),
          const SizedBox(height: 14),
          _StackBar(t, height: 10),
          const SizedBox(height: 12),
          Row(children: [
            _kpi('Present', t.p, t.total, kGreen),
            _kpi('Absent', t.a, t.total, kRed),
          ]),
        ]),
