Firestore:
  rules_version = '2';
  service cloud.firestore { match /databases/{db}/documents {
    match /exams/{doc} { allow read, write: if request.auth != null; }
    match /files/{doc} { allow read, write: if request.auth != null; }
    match /settings/logo { allow read: if true; allow write: if request.auth != null; }
    match /settings/{doc} { allow read, write: if request.auth != null; }
    match /sections/{doc} { allow read, write: if request.auth != null; }
    match /students/{doc} { allow read, write: if request.auth != null; }
    match /teachers/{doc} { allow read, write: if request.auth != null; }
    match /users/{doc} { allow read, write: if request.auth != null; }
    match /attendance/{doc} { allow read, write: if request.auth != null; }
    match /assignments/{doc} { allow read, write: if request.auth != null; }
    match /assignmentFiles/{doc} { allow read, write: if request.auth != null; }
    match /results/{doc} { allow read, write: if request.auth != null; } } }

(Firebase Storage is no longer used.)
------------------------------------------------------------------------------ */